window.AdAstraGlossary=[{"id": "aberrazione-cromatica", "name": "Aberrazione cromatica", "definition": "Nei sistemi rifrangenti la dipendenza della rifrazione dalla lunghezza d’onda può far formare immagini di colori differenti in posizioni diverse.", "example": "Colori diversi possono avere fuochi differenti", "source": "https://www.treccani.it/enciclopedia/aberrazione/", "lesson": "lezione-7-3.html", "related": ["rifrattore", "acromatico", "fuoco"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Quando i colori non arrivano insieme al fuoco", "paragraphs": ["Una lente devia la luce in modo leggermente diverso secondo la lunghezza d’onda. Un obiettivo semplice può quindi portare colori diversi a fuoco a distanze diverse. In una stella brillante il risultato può essere un alone colorato, pur cercando la regolazione più nitida. Non significa che la stella possieda realmente una corona viola o che il sensore abbia fotografato gas presente attorno a essa."]}, {"title": "Una proprietà da correggere nel progetto", "paragraphs": ["L’effetto non richiede necessariamente un graffio o un difetto di fabbricazione: dipende dalla dispersione dei materiali e dalla geometria ottica. Combinazioni appropriate di lenti e vetri permettono di ridurlo. Un acromatico e un apocromatico mirano a livelli di correzione differenti, da valutare nella banda e nell’uso previsto. La semplice presenza di tre lenti non sostituisce una descrizione delle prestazioni del sistema completo."]}, {"title": "Non ogni bordo colorato ha questa origine", "paragraphs": ["Vicino all’orizzonte l’atmosfera può separare i colori e produrre dispersione anche con uno strumento riflettore. Elaborazione, saturazione e riflessi possono introdurre altri aloni. Se il bordo blu e quello rosso compaiono ai lati opposti di un pianeta basso, non è corretto attribuirli automaticamente all’obiettivo. La diagnosi richiede osservazione della forma, posizione nel campo, altezza del bersaglio e configurazione dello strumento."]}, {"title": "Che cosa cambia per l’osservatore", "paragraphs": ["Un filtro può modificare le bande che passano e attenuare un alone, ma non ricostruisce tutta l’informazione di un sistema perfettamente corretto. La fotografia rende visibili difetti poco evidenti all’occhio perché sensore e trattamento pesano le bande in altro modo. Per valutare un’ottica confronta immagini a fuoco, esposizione e condizioni simili. La qualità non si riduce a un’etichetta commerciale né all’assenza di colore in una miniatura ridotta."]}], "facts": ["Colori diversi possono avere fuochi differenti", "Dispersione atmosferica e cromatismo dell’obiettivo sono distinti"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/aberrazione/"}]}, {"id": "aberrazione-della-luce", "name": "Aberrazione della luce", "definition": "Il moto dell’osservatore modifica la direzione apparente da cui riceve la luce; l’aberrazione astronomica è distinta dai difetti ottici.", "example": "Aberrazione astronomica ≠ aberrazione ottica", "source": "https://www.treccani.it/enciclopedia/aberrazione/", "lesson": "lezione-1-6.html", "related": ["parallasse", "astrometria", "orbita"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La direzione dipende anche dal ricevitore", "paragraphs": ["L’aberrazione della luce riguarda il rapporto fra propagazione del segnale e movimento dell’osservatore. L’analogia della pioggia che sembra arrivare inclinata mentre corriamo può introdurre l’idea, ma non sostituisce la descrizione fisica della luce. Il risultato è una variazione della direzione apparente, non lo spostamento reale della stella sulla propria orbita e non una deformazione introdotta da una lente mal costruita."]}, {"title": "Il contributo annuo", "paragraphs": ["Il moto orbitale terrestre produce un contributo che varia nell’anno. La figura apparente dipende dalla direzione della sorgente rispetto al piano del moto. Anche altri movimenti dell’osservatore possono contribuire. Per un’osservazione introduttiva gli effetti sono piccoli, ma nell’astrometria precisa si distinguono insieme ad altre correzioni. Una coppia di coordinate di catalogo non si trasforma in direzione apparente soltanto aggiungendo un valore fisso uguale per ogni stella e data."]}, {"title": "Diversa dalla parallasse", "paragraphs": ["La parallasse usa il cambiamento della posizione dell’osservatore e dipende dalla distanza della sorgente. L’aberrazione coinvolge invece il suo stato di moto. Entrambe possono produrre variazioni annue, ma non sono lo stesso fenomeno. Usare tutta la variazione osservata come se fosse parallasse porterebbe a una distanza sbagliata. È proprio la distinzione fra contributi diversi a rendere la misura astrometrica più sottile di un confronto visivo fra due punti."]}, {"title": "La lezione per le carte", "paragraphs": ["Una mappa didattica può usare coordinate di catalogo e dichiararlo, senza promettere la precisione di un sistema di puntamento professionale. Se presenta invece coordinate apparenti deve spiegare quali trasformazioni applica. La parola aberrazione ha anche significati in ottica: cromatismo, sfericità e altri difetti non vanno confusi con questo effetto astronomico. Il contesto è parte della definizione e aiuta a evitare che un’unica etichetta colleghi fenomeni soltanto omonimi."]}], "facts": ["Aberrazione astronomica ≠ aberrazione ottica", "Variazione annua non significa automaticamente parallasse"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/aberrazione/"}]}, {"id": "aberrazione-sferica", "name": "Aberrazione sferica", "definition": "L’aberrazione sferica si presenta quando raggi a diverse distanze dall’asse di un sistema non convergono nello stesso fuoco nella configurazione considerata.", "example": "Può essere presente anche a una sola lunghezza d’onda", "source": "https://www.treccani.it/enciclopedia/aberrazione/", "lesson": "lezione-7-3.html", "related": ["fuoco", "diffrazione", "riflettore"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Non tutti i raggi si incontrano nello stesso punto", "paragraphs": ["Un’immagine ideale di una sorgente lontana richiede una geometria ottica appropriata. Se i raggi che attraversano zone diverse dell’apertura convergono in posizioni assiali differenti, il risultato si allarga. Il nome richiama superfici sferiche e la loro geometria, ma il comportamento dipende dal sistema complessivo. Non basta guardare se una lente sembri rotonda dall’esterno per stabilire il difetto."]}, {"title": "Non richiede un colore diverso", "paragraphs": ["A differenza dell’aberrazione cromatica, qui il problema può essere presente anche considerando una sola lunghezza d’onda. È quindi sbagliato attribuire ogni perdita di nitidezza alla separazione dei colori. La forma delle superfici, le distanze e le combinazioni di elementi possono correggere il sistema. Uno specchio non introduce il cromatismo di una lente semplice, ma non è per questo automaticamente esente da aberrazione sferica o da altri difetti."]}, {"title": "Il controllo attraverso l’immagine", "paragraphs": ["Le figure intra ed extrafocali di una stella possono fornire indizi, ma la loro interpretazione richiede esperienza e condizioni adeguate. Turbolenza, acclimatazione, ostruzione e progetto del telescopio modificano l’aspetto. Non è corretto giudicare ogni differenza fra i due lati del fuoco come una prova definitiva di ottica inutilizzabile. Una descrizione divulgativa può insegnare che esistono cause diverse senza trasformare un test schematico in una diagnosi universale."]}, {"title": "Il compromesso dell’apertura", "paragraphs": ["Ridurre l’apertura può limitare alcuni contributi dei raggi periferici, ma riduce anche luce raccolta e potere risolutivo ideale. Non è una riparazione gratuita. L’obiettivo di un progetto ottico è bilanciare proprietà e correzioni in condizioni definite. Per il lettore è utile collegare il termine a una domanda concreta: il sistema concentra correttamente la luce? La risposta deve separare figura di diffrazione, errori di progetto o realizzazione e disturbi introdotti dall’ambiente."]}], "facts": ["Può essere presente anche a una sola lunghezza d’onda", "Non ogni immagine poco nitida ha la stessa causa"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/aberrazione/"}]}, {"id": "accrescimento", "name": "Accrescimento", "definition": "In astrofisica l’accrescimento è l’aumento della massa di un corpo attraverso l’acquisizione di materia dall’ambiente o da una compagna.", "example": "Accrescimento = acquisizione di materia", "source": "https://www.treccani.it/enciclopedia/accrescimento/", "lesson": "lezione-4-5.html", "related": ["stella", "buco-nero", "quasar"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Crescere raccogliendo materia", "paragraphs": ["Una protostella può acquisire materiale dalla nube e dal disco circostanti; un oggetto compatto può ricevere gas da una stella compagna o dall’ambiente. Queste situazioni diverse condividono l’idea di accrescimento, ma non identiche condizioni fisiche. Non si tratta soltanto di aumentare il diametro visibile. La massa, il momento angolare e l’energia del materiale devono essere considerati insieme."]}, {"title": "Perché compare un disco", "paragraphs": ["Se il materiale possiede momento angolare, non cade tutto direttamente lungo raggi verso il centro. Può organizzarsi in una struttura rotante, nella quale processi fisici permettono trasporto di materia e ridistribuzione del momento angolare. Il disco non è una superficie solida. Un disegno di anelli concentrici è una semplificazione e non dimostra che ogni sistema abbia esattamente la stessa forma o lo stesso spessore."]}, {"title": "Luce senza uscire dal buco nero", "paragraphs": ["La materia in accrescimento può riscaldarsi e irradiare energia prima di attraversare l’orizzonte di un buco nero. La sorgente luminosa osservata è quindi esterna a quel confine. Non vediamo luce che fugge dall’interno. Il rendimento e lo spettro dipendono dal regime e dal sistema. Getti e venti possono accompagnare alcuni processi, ma non vanno disegnati come accessori obbligatori di ogni corpo che cresce."]}, {"title": "Dalla formazione stellare alle galassie attive", "paragraphs": ["Lo stesso termine attraversa scale molto differenti: nascita delle stelle, interazioni binarie e nuclei galattici. Per comprenderlo bisogna sempre chiedere chi riceve la materia, da dove arriva e come perdiamo o trasformiamo energia. Una fotografia di getti protostellari non è l’immagine di un quasar in piccolo. Il collegamento divulgativo sta nel principio fisico, mentre dimensioni, tempi e meccanismi specifici richiedono spiegazioni proprie."]}], "facts": ["Accrescimento = acquisizione di materia", "La luce del materiale esterno non proviene dall’interno dell’orizzonte"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/accrescimento/"}]}, {"id": "acromatico", "name": "Acromatico", "definition": "Un sistema acromatico è progettato per ridurre l’aberrazione cromatica, facendo coincidere opportunamente il fuoco di determinate lunghezze d’onda.", "example": "Acromatico non significa immagine senza colori", "source": "https://www.treccani.it/vocabolario/acromatico/", "lesson": "lezione-7-3.html", "related": ["aberrazione-cromatica", "apocromatico", "rifrattore"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Correggere una lente con un’altra", "paragraphs": ["Un obiettivo composto può usare materiali con dispersioni diverse e poteri ottici opportuni per ridurre la separazione dei fuochi dei colori. Il classico doppietto acromatico è un esempio di questa strategia. Non si tratta di togliere i colori della scena: il sistema continua a formare un’immagine policromatica. “Acromatico” descrive qui la correzione ottica, non una fotografia in bianco e nero."]}, {"title": "La correzione ha un intervallo e dei residui", "paragraphs": ["Fare coincidere il fuoco di determinate bande non significa eliminare perfettamente ogni differenza a tutte le lunghezze d’onda. Può rimanere uno spettro secondario visibile su soggetti brillanti. Apertura, focale, progetto e uso previsto influenzano quanto il residuo sia evidente. Non è corretto trasformare l’etichetta in una promessa assoluta o affermare che ogni acromatico abbia prestazioni identiche soltanto perché possiede due lenti."]}, {"title": "Un esempio pratico", "paragraphs": ["Durante l’osservazione di una stella molto luminosa può comparire un alone colorato, mentre su un soggetto meno brillante l’immagine resta piacevole e informativa. In fotografia il sensore può rendere il residuo più evidente. L’esperienza dipende anche da fuoco, esposizione, altezza dell’oggetto e trattamento. Un confronto serio mantiene queste condizioni controllate invece di giudicare due strumenti attraverso immagini elaborate in modi completamente diversi."]}, {"title": "Come leggere una scheda tecnica", "paragraphs": ["Il termine non descrive la montatura, il motore o la stabilità del treppiede. Un buon obiettivo può essere penalizzato da un supporto instabile; un sistema più corretto può essere sovradimensionato rispetto all’uso previsto. Valuta campo, correzione, peso e destinatario del progetto. L’obiettivo didattico non è costruire una gerarchia di nomi, ma collegare una proprietà fisica alle conseguenze osservabili e capire perché un’ottica possa essere adatta a un impiego e meno a un altro."]}], "facts": ["Acromatico non significa immagine senza colori", "La correzione riguarda bande e condizioni definite"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/vocabolario/acromatico/"}]}, {"id": "adattamento-al-buio", "name": "Adattamento al buio", "definition": "L’occhio diventa progressivamente più sensibile alla luce debole quando rimane in un ambiente poco illuminato: questo processo è l’adattamento al buio.", "example": "Tempo al buio e assenza di abbagliamento aiutano l’osservazione", "source": "https://www.treccani.it/enciclopedia/occhio/", "lesson": "lezione-7-1.html", "related": ["luce", "magnitudine-apparente", "binocolo"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il cielo non si è acceso all’improvviso", "paragraphs": ["All’inizio di una serata può sembrare che manchino molte stelle. Dopo un po’, senza cambiare luogo o strumento, il cielo si arricchisce. Una parte del cambiamento avviene dentro di noi: la pupilla si dilata e la retina modifica la propria sensibilità. Non è quindi il telescopio a raccogliere più luce col passare dei minuti. Anche l’occhio ha bisogno di preparazione, proprio come l’attrezzatura sul tavolo."]}, {"title": "Due risposte con tempi differenti", "paragraphs": ["La dilatazione pupillare è relativamente rapida; l’adattamento dei recettori retinici richiede più tempo. I bastoncelli contribuiscono soprattutto alla visione in condizioni molto deboli, mentre i coni sono importanti per colori e dettagli nella visione diurna. Una ventina di minuti può già fare differenza e il miglioramento può proseguire oltre mezz’ora. Non esiste però un cronometro identico per tutti: contano illuminazione precedente, condizioni individuali e luminosità del bersaglio."]}, {"title": "Una luce rossa deve essere anche debole", "paragraphs": ["Per consultare una carta serve soltanto la luce necessaria a leggerla. Il colore rosso aiuta, ma non rende innocua qualsiasi intensità: una lampada abbagliante o uno schermo acceso possono compromettere l’adattamento. Riduci la luminosità, orienta il fascio sul quaderno e rispetta chi osserva accanto a te. Preparare prima cavi e accessori evita di dover cercare tutto con una torcia potente proprio quando il gruppo è pronto."]}, {"title": "Che cosa annotare nel diario", "paragraphs": ["Confronta la visibilità di una regione prima e dopo un intervallo al buio, mantenendo quanto possibile lo stesso cielo e la stessa direzione. Non trasformare il confronto in una prova della luminosità assoluta del sito: nel frattempo possono cambiare nubi, foschia e altezza degli astri. Per Luna e pianeti brillanti la priorità non è sempre la massima sensibilità alla luce debole. L’adattamento serve soprattutto a cogliere dettagli e oggetti poco contrastati."]}], "facts": ["Tempo al buio e assenza di abbagliamento aiutano l’osservazione", "Rosso non significa automaticamente poco luminoso"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/occhio/"}, {"title": "NASA/JPL Night Sky Network · osservazione e adattamento", "url": "https://nightsky.jpl.nasa.gov/documents/353/0ScopeManual.pdf"}]}, {"id": "afelio", "name": "Afelio", "definition": "L’afelio è il punto di un’orbita attorno al Sole in cui la distanza dal Sole è massima.", "example": "Afelio: massima distanza dal Sole", "source": "https://www.treccani.it/enciclopedia/afelio/", "lesson": "lezione-3-6.html", "related": ["orbita", "perielio", "eclittica"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il punto più lontano dal Sole", "paragraphs": ["In un’orbita ellittica il Sole occupa un fuoco, non il centro geometrico. Percorrendo l’ellisse, il corpo incontra quindi distanze diverse: l’afelio è il punto più lontano e il perielio quello più vicino. Il termine riguarda specificamente il Sole. Per un’orbita terrestre si usano invece apogeo e perigeo. La distinzione nel nome ricorda quale sia il corpo di riferimento."]}, {"title": "Come entra nella geometria", "paragraphs": ["Nel modello di un’ellisse, semiasse maggiore ed eccentricità determinano le distanze estreme. Senza introdurre formule complesse, immaginiamo un’orbita con distanza minima di 2 e massima di 4 unità: il semiasse maggiore vale 3 unità, la media dei due estremi. Non è però la distanza istantanea in qualsiasi punto. Le unità devono essere dichiarate e il corpo centrale non va disegnato nel centro soltanto per rendere la figura simmetrica."]}, {"title": "Velocità e tempo trascorso", "paragraphs": ["Un corpo su un’orbita ellittica ideale si muove più lentamente nei pressi dell’afelio che al perielio. Percorre quindi porzioni uguali di traiettoria in tempi differenti. Questo è coerente con la seconda legge di Keplero, espressa attraverso aree uguali spazzate in tempi uguali. Una semplice animazione a velocità costante lungo un’ellisse molto allungata non riproduce correttamente il moto orbitale."]}, {"title": "L’equivoco delle stagioni", "paragraphs": ["Per la Terra l’estate boreale si verifica vicino al periodo in cui passa all’afelio, non perché sia più vicina al Sole. L’alternanza stagionale è governata principalmente dall’inclinazione dell’asse, che cambia altezza del Sole e durata del giorno nei due emisferi. La distanza ha effetti sull’energia ricevuta, ma non spiega da sola la successione opposta delle stagioni. Un disegno didattico molto eccentrico deve dichiarare che la forma è accentuata rispetto all’orbita terrestre."]}], "facts": ["Afelio: massima distanza dal Sole", "La Terra non ha l’estate boreale perché è più vicina al Sole"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/afelio/"}]}, {"id": "afocale", "name": "Afocale", "definition": "Un sistema afocale trasforma un fascio parallelo in un altro fascio parallelo; nella fotografia afocale una fotocamera con obiettivo riprende attraverso l’oculare.", "example": "Afocale: fotocamera con obiettivo davanti all’oculare", "source": "https://www.treccani.it/vocabolario/afocale/", "lesson": "astrofotografia.html", "related": ["fuoco", "oculare", "focale"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La luce esce ancora come da un soggetto lontano", "paragraphs": ["Un sistema afocale, nel caso ideale appropriato, riceve raggi paralleli e li restituisce paralleli. Un telescopio regolato per l’osservazione di un oggetto lontano con un occhio rilassato può realizzare questa condizione attraverso obiettivo e oculare. Non significa che al suo interno non si formi alcuna immagine. La parola descrive il comportamento complessivo del sistema, non l’assenza di ottica o di regolazione."]}, {"title": "Il telefono davanti all’oculare", "paragraphs": ["Nella ripresa afocale si mantiene l’obiettivo della fotocamera e lo si colloca davanti all’oculare. La fotocamera riceve l’immagine presentata dallo strumento e la forma sul proprio sensore. È diverso dal fuoco diretto, dove il sensore viene posto nel piano dell’immagine del telescopio senza il proprio obiettivo fotografico. Confondere i due assetti rende difficile interpretare ingrandimento, campo e possibili vignettature."]}, {"title": "Allineare le pupille", "paragraphs": ["L’obiettivo della fotocamera deve essere posizionato e centrato correttamente rispetto all’oculare. Uno spostamento può ridurre il campo illuminato, creare un cerchio tagliato o rendere instabile l’immagine. Un adattatore adeguato aiuta, ma non garantisce automaticamente la compatibilità di ogni telefono, lente e oculare. Anche autofocus, esposizione e vibrazioni del tocco possono influenzare molto il risultato, soprattutto alle scale più spinte."]}, {"title": "Un’esperienza utile, con aspettative corrette", "paragraphs": ["La Luna è un soggetto che permette di capire il metodo, ma la luminosità delle sue regioni varia e richiede una regolazione dell’esposizione. Il fatto di vedere il disco nell’anteprima non dimostra che il fuoco sia ottimale. Conviene confrontare dettagli e stabilità, non soltanto quanto il soggetto riempia lo schermo. Per il Sole non si improvvisa: serve sempre una configurazione solare correttamente filtrata e adatta, indipendentemente dal metodo di ripresa."]}], "facts": ["Afocale: fotocamera con obiettivo davanti all’oculare", "Fuoco diretto: sensore nel piano immagine del telescopio"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/vocabolario/afocale/"}]}, {"id": "airglow", "name": "Airglow", "definition": "L’airglow è una debole emissione naturale dell’atmosfera, presente anche quando non si osserva un’aurora.", "example": "Una componente naturale della luminosità del cielo", "source": "https://www.treccani.it/vocabolario/airglow/", "lesson": "lezione-8-3.html", "related": ["aurora-polare", "atmosfera", "spettro"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il cielo naturale non è completamente spento", "paragraphs": ["Anche lontano dalle città il fondo del cielo possiede una luminosità naturale. Una sua componente è l’airglow, dovuto a processi nell’atmosfera che producono emissione. La parola inglese non identifica un oggetto distante fra le stelle. Ricorda piuttosto che il mezzo attraverso cui osserviamo può essere esso stesso una sorgente, anche in una notte senza Luna e senza illuminazione artificiale vicina."]}, {"title": "Come nasce il segnale", "paragraphs": ["Processi fotochimici e ricombinazioni possono contribuire alle emissioni atmosferiche, con intensità e distribuzioni variabili. Non si tratta semplicemente di nuvole illuminate dal suolo. Una banda fotografica può rendere visibile una struttura tenue che l’occhio non distingue facilmente. Il fatto che una certa riga sia emessa da ossigeno non basta però a classificare ogni immagine dello stesso colore: diversi fenomeni possono coinvolgere specie e transizioni comuni."]}, {"title": "Distinto dall’aurora", "paragraphs": ["Aurora e airglow non sono due nomi intercambiabili per qualsiasi chiarore verde. Il meccanismo, la dinamica e il contesto osservativo vanno interpretati. Fotografie grandangolari possono mostrare bande, mentre condizioni artificiali o elaborazioni possono introdurre dominanti e gradienti. Per un’identificazione utile si conservano luogo, data, ora, direzione, impostazioni e immagini originali, confrontando l’evoluzione invece di affidarsi soltanto alla tonalità di una versione elaborata."]}, {"title": "Una componente del fondo nelle misure", "paragraphs": ["Il fondo naturale conta quando si fotografano soggetti deboli e quando si valuta la qualità del cielo. Non tutta la luminosità misurata può essere attribuita alle lampade di una città. Anche Luna, stelle non risolte, luce zodiacale e condizioni atmosferiche contribuiscono, secondo la direzione e la banda. Separare le componenti evita di trasformare una fotografia suggestiva in una misura improvvisata dell’inquinamento luminoso o di attribuire automaticamente una classe di buio a un luogo."]}], "facts": ["Una componente naturale della luminosità del cielo", "Airglow ≠ aurora ≠ chiarore artificiale"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/vocabolario/airglow/"}]}, {"id": "albedo", "name": "Albedo", "definition": "L’albedo descrive la capacità di un corpo o di una superficie di riflettere la radiazione, secondo una definizione e una banda da specificare.", "example": "Albedo geometrica e albedo di Bond sono quantità differenti", "source": "https://www.treccani.it/enciclopedia/albedo/", "lesson": "lezione-3-2.html", "related": ["pianeta", "magnitudine-apparente", "stella"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La luce che torna indietro", "paragraphs": ["Una superficie investita dalla luce ne assorbe una parte e ne rinvia una parte. L’albedo quantifica un aspetto di questa riflessione. Un materiale chiaro può restituire più radiazione di uno scuro, ma il risultato dipende anche dalla lunghezza d’onda, dalla struttura e dalla geometria. Non è una lampada interna del pianeta: parla del comportamento della luce ricevuta da una sorgente esterna."]}, {"title": "Le definizioni non sono tutte equivalenti", "paragraphs": ["L’albedo di Bond riguarda la frazione complessiva della radiazione incidente che viene riflessa, integrando direzioni e lunghezze d’onda pertinenti. L’albedo geometrica confronta invece la brillantezza a fase piena con un riferimento diffusore ideale. Sono quantità diverse: un numero non può sostituire l’altro soltanto perché entrambi si chiamano albedo. Una scheda tecnica dovrebbe specificare la definizione, la banda e gli eventuali limiti del dato."]}, {"title": "Perché un pianeta può brillare molto", "paragraphs": ["La luce ricevuta da un pianeta dipende anche dalle distanze e dalla porzione illuminata visibile. Un oggetto con alta albedo non è necessariamente il più luminoso nel nostro cielo. Venere può apparire molto brillante grazie a una combinazione di riflessione atmosferica, dimensione apparente, distanza e fase. Una fotografia elaborata non permette di misurare direttamente l’albedo confrontando soltanto quanto sono bianchi i pixel."]}, {"title": "Il legame con il bilancio energetico", "paragraphs": ["La parte di radiazione non riflessa può contribuire all’energia assorbita dal corpo. Tuttavia la temperatura non si deduce dalla sola albedo: contano distanza dalla stella, emissione termica, atmosfera, distribuzione dell’energia e altre sorgenti. Due mondi con riflettività simile possono avere condizioni molto differenti. La parola è quindi una tessera del bilancio fisico, non una scorciatoia per stabilire abitabilità o clima da un singolo numero."]}], "facts": ["Albedo geometrica e albedo di Bond sono quantità differenti", "Brillantezza apparente dipende anche da distanza e fase"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/albedo/"}, {"title": "JPL · definizioni di albedo", "url": "https://ssd.jpl.nasa.gov/glossary/albedo.html"}]}, {"id": "almucantarat", "name": "Almucantarat", "definition": "Un almucantarat è un cerchio di uguale altezza sulla sfera celeste locale: tutti i suoi punti hanno la stessa altezza rispetto all’orizzonte.", "example": "Almucantarat = cerchio di altezza costante", "source": "https://www.treccani.it/enciclopedia/almucantarat/", "lesson": "lezione-1-6.html", "related": ["altezza-angolare", "orizzonte", "zenit"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un nome difficile per un’idea semplice", "paragraphs": ["Immagina di mantenere lo sguardo inclinato di 30° sopra l’orizzonte e di girare lentamente attorno a te. Le direzioni incontrate appartengono a un cerchio di uguale altezza. Questo è l’almucantarat. Il termine non aggiunge una nuova coordinata: descrive un insieme di punti con lo stesso valore di una coordinata già nota. Per scegliere uno dei punti serve anche la direzione orizzontale, cioè l’azimut."]}, {"title": "Il riferimento resta l’osservatore", "paragraphs": ["Il piano del cerchio è parallelo all’orizzonte locale e il suo centro sta sulla verticale. Non coincide generalmente con un parallelo di declinazione, che si riferisce invece ai poli e all’equatore celesti. Una stella può attraversare cerchi di altezza diversa durante la notte, pur conservando praticamente la propria declinazione di catalogo. Confondere questi due reticoli è una delle cause di simulazioni stagionali geometricamente sbagliate."]}, {"title": "Come compare sulla carta", "paragraphs": ["In una mappa circolare centrata sullo zenit, i cerchi concentrici possono rappresentare altezze costanti. Il bordo può essere 0°, poi si procede verso 30°, 60° e il centro a 90°. La distanza fra i cerchi sulla pagina dipende dalla proiezione: non si misura direttamente l’angolo con un righello. Una legenda deve dichiarare il significato, altrimenti il lettore può scambiarli per orbite o per distanze spaziali."]}, {"title": "Un aiuto alla pianificazione", "paragraphs": ["Sapere che due bersagli hanno la stessa altezza aiuta a confrontare la loro posizione rispetto agli ostacoli e al percorso atmosferico, senza renderli necessariamente ugualmente visibili. Brillantezza, estensione, direzione delle luci e condizioni locali restano diverse. L’almucantarat è quindi un riferimento geometrico utile: organizza il campo visivo e permette di descrivere una direzione, ma non promette identiche condizioni osservative per ogni oggetto che attraversa quel cerchio."]}], "facts": ["Almucantarat = cerchio di altezza costante", "Non è generalmente un parallelo di declinazione"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/almucantarat/"}]}, {"id": "altezza-angolare", "name": "Altezza angolare", "definition": "Angolo fra la direzione di un astro e il piano dell’orizzonte locale. Si misura in gradi, non in metri.", "example": "All’orizzonte vale 0°; allo zenit 90°. Un’altezza negativa indica una direzione sotto l’orizzonte geometrico.", "source": "https://www.treccani.it/enciclopedia/coordinate/", "lesson": "lezione-1-1.html", "related": ["azimut", "zenit"], "checked": "2026-10-30", "sections": [{"title": "Quanto devi alzare lo sguardo", "paragraphs": ["L’altezza angolare indica l’angolo fra una direzione del cielo e il piano dell’orizzonte locale. Immagina di seguire un astro con lo sguardo: partendo dall’orizzonte, sollevi la testa fino a incontrarlo. L’angolo percorso non è la sua quota in chilometri. Una stella lontanissima e un aereo vicino possono avere la stessa altezza angolare pur trovandosi a distanze completamente diverse. Il riferimento è l’osservatore: cambia con il luogo e, per gli astri, generalmente con l’ora."]}, {"title": "La scala dell’orizzonte", "paragraphs": ["Sul piano dell’orizzonte l’altezza vale 0°. Sopra la testa, allo zenit, vale +90°; sotto l’orizzonte è negativa, fino a −90° nella direzione del nadir. A 45° un oggetto è a metà dell’angolo fra orizzonte e zenit, non a metà della sua distanza fisica. Per descrivere una direzione completa serve anche l’azimut: “40° di altezza verso est” contiene due informazioni che non possono sostituirsi. La misura usa un piano ideale, mentre montagne, alberi e tetti definiscono un profilo visibile irregolare."]}, {"title": "Dalla carta alla serata", "paragraphs": ["Un bersaglio alto tende a essere osservato attraverso un percorso atmosferico più favorevole di uno rasente all’orizzonte. Vicino all’orizzonte aumentano spesso attenuazione, dispersione dei colori e disturbi atmosferici. Non esiste però un’altezza magica che garantisca una buona immagine: meteo, turbolenza, ostacoli e luce diffusa restano importanti. Nella pianificazione conviene quindi controllare l’altezza durante l’intera finestra disponibile, anziché limitarsi a verificare se un oggetto sia formalmente sorto."]}, {"title": "Che cosa una misura non dice", "paragraphs": ["L’altezza non coincide con la declinazione. La prima appartiene al sistema locale; la seconda si riferisce all’equatore celeste. Un oggetto che passa allo zenit da un luogo non è allo zenit per tutti gli osservatori terrestri. Inoltre la rifrazione atmosferica può modificare l’altezza apparente: vicino all’orizzonte la differenza conta nel calcolo di sorgere e tramonto. Una carta didattica deve dichiarare se mostra direzioni geometriche o apparenti, senza attribuire precisione da strumento di misura a un disegno prospettico."]}], "facts": ["Orizzonte 0° · zenit +90° · nadir −90°", "Un angolo descrive una direzione, non una distanza"], "sources": [{"title": "Treccani · riferimento della voce", "url": "https://www.treccani.it/enciclopedia/coordinate/"}, {"title": "USNO · altezza e azimut", "url": "https://aa.usno.navy.mil/faq/alt_az"}], "editorialStatus": "scheda-estesa"}, {"id": "altitudine", "name": "Altitudine", "definition": "L’altitudine è la quota di un luogo rispetto al livello medio del mare; non è l’altezza angolare di un astro sopra l’orizzonte.", "example": "Altitudine del luogo: metri", "source": "https://www.treccani.it/enciclopedia/altitudine/", "lesson": "lezione-7-6.html", "related": ["altezza-angolare", "atmosfera", "seeing"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Due altezze che misurano cose diverse", "paragraphs": ["Un prato può trovarsi a mille metri di altitudine e una stella a trenta gradi di altezza. Il primo numero descrive la posizione del luogo sulla Terra; il secondo la direzione dello sguardo. Metri e gradi non sono intercambiabili. Nelle applicazioni in lingua inglese, inoltre, altitude può indicare proprio l’altezza angolare dell’astro: leggere unità e contesto impedisce di interpretare la quota dell’osservatore come una coordinata celeste."]}, {"title": "Perché si cercano siti elevati", "paragraphs": ["Salire può ridurre la quantità di atmosfera sovrastante e, in alcune condizioni, lasciare sotto di sé strati umidi o inquinati. Questo non trasforma ogni vetta in un osservatorio ideale. La turbolenza, le correnti locali, le nubi e le luci circostanti restano determinanti. Un sito più basso ma riparato da vento e illuminazione diretta può essere più utile per una serata divulgativa di un crinale molto esposto."]}, {"title": "La montagna cambia anche la preparazione", "paragraphs": ["Abbigliamento, accessibilità, vento e possibilità di riporre gli strumenti contano quanto il panorama. Le condizioni notturne possono essere molto diverse da quelle dell’arrivo pomeridiano. Nel progetto di una serata conviene distinguere la qualità astronomica del cielo dalla praticabilità del posto. Un orizzonte libero non giustifica l’installazione su un terreno instabile, né la necessità di raggiungere una quota elevata è un requisito per iniziare a osservare."]}, {"title": "Il dato da riportare", "paragraphs": ["Nel diario indica località, quota approssimata se nota e ostacoli verso le direzioni osservate. Se un programma chiede l’elevazione del sito, controlla che richieda metri e non un angolo. Alcuni calcoli di eventi vicini all’orizzonte possono dipendere anche dalla quota e dalla rifrazione atmosferica. Le coordinate della città, da sole, non descrivono però il profilo di montagne o edifici davanti al tuo punto preciso di osservazione."]}], "facts": ["Altitudine del luogo: metri", "Altezza dell’astro: gradi sopra l’orizzonte"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/altitudine/"}]}, {"id": "ammasso-aperto", "name": "Ammasso aperto", "definition": "Gruppo fisico di stelle con una distribuzione generalmente meno concentrata di quella di un ammasso globulare.", "example": "Le Pleiadi sono un ammasso aperto: il gruppo non è soltanto un disegno prospettico.", "source": "https://www.treccani.it/enciclopedia/sistemi-stellari_(Enciclopedia-del-Novecento)/", "lesson": "lezione-5-2.html", "related": ["ammasso-globulare", "costellazione"], "checked": "2026-10-30", "sections": [{"title": "Un gruppo nato dalla stessa storia", "paragraphs": ["Un ammasso aperto è un insieme fisico di stelle, normalmente legato a un episodio di formazione comune in una nube di gas. Non è soltanto una vicinanza apparente nel cielo. Le stelle possono avere masse e luminosità diverse, e non devono per forza apparire dello stesso colore. Per riconoscere l’appartenenza, gli astronomi confrontano anche distanze, moti e altre proprietà: l’immagine da sola può includere stelle estranee lungo la stessa linea di vista."]}, {"title": "Perché si chiama aperto", "paragraphs": ["Il nome richiama la distribuzione generalmente meno compatta di quella degli ammassi globulari. Il gruppo può essere irregolare e lasciare ampi spazi apparenti fra le stelle. Non è una sfera con un bordo solido. Molti ammassi aperti si trovano nel disco della Galassia; l’ambiente e le interazioni gravitazionali possono modificarli e disperderne progressivamente i membri. La forma di oggi racconta soltanto una parte della loro evoluzione."]}, {"title": "Che cosa insegna un confronto fra stelle", "paragraphs": ["Avere un gruppo di origine comune permette di confrontare stelle che condividono approssimativamente età e composizione iniziale. Le differenze di massa fanno procedere l’evoluzione a ritmi diversi. La posizione dei membri in un diagramma colore–luminosità offre quindi informazioni che non emergono contando semplicemente i punti della fotografia. Le eccezioni, le stelle doppie e i membri incerti richiedono un’analisi, non una classificazione fatta solo a occhio."]}, {"title": "Le Pleiadi come punto di partenza", "paragraphs": ["Le Pleiadi sono un esempio particolarmente adatto a comprendere la differenza fra un campo ampio e un forte ingrandimento. Se il gruppo occupa una porzione estesa del cielo, un campo troppo stretto ne taglia la figura. Binocolo, occhio nudo e telescopio offrono letture diverse, nessuna identica a una lunga fotografia. Non bisogna inoltre confondere le stelle dell’ammasso con la nebulosità di polvere visibile in molte riprese: stelle e materiale diffuso sono componenti da interpretare separatamente."]}], "facts": ["Gruppo fisico, non soltanto figura prospettica", "Appartenenza verificata anche con moti e distanze", "Il campo dello strumento deve contenere il soggetto"], "sources": [{"title": "Treccani · riferimento della voce", "url": "https://www.treccani.it/enciclopedia/sistemi-stellari_(Enciclopedia-del-Novecento)/"}, {"title": "NASA · ammassi aperti e Pleiadi", "url": "https://www.nasa.gov/universe/stars/star-clusters/open-clusters/"}], "editorialStatus": "scheda-estesa", "aliases": ["ammassi aperti"]}, {"id": "ammasso-di-galassie", "name": "Ammasso di galassie", "definition": "Un ammasso di galassie è una grande struttura gravitazionale che comprende numerose galassie, gas caldo e materia oscura.", "example": "Ammasso stellare ≠ ammasso di galassie", "source": "https://www.treccani.it/enciclopedia/galassia_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-6-4.html", "related": ["galassia", "ammasso-globulare", "gravitazione"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Cambiare scala senza perdere il significato", "paragraphs": ["Un ammasso stellare contiene stelle; un ammasso di galassie contiene intere galassie. La parola comune non deve nascondere il salto di scala. Dentro ciascuna galassia si trovano a loro volta stelle, gas e altri sistemi. Immagina quindi di allargare progressivamente la mappa: prima una regione stellare, poi una galassia, infine il suo ambiente cosmico. Non sono tre nomi differenti per lo stesso raggruppamento luminoso."]}, {"title": "La fotografia non mostra tutta la massa", "paragraphs": ["Nelle immagini ottiche riconosciamo soprattutto le galassie e la luce delle loro stelle. Il gas molto caldo tra le galassie viene studiato anche attraverso i raggi X; la distribuzione della massa si ricostruisce con più metodi, compresi i moti e la lente gravitazionale. La materia oscura non è una macchia nera fotografabile fra due galassie. Un’immagine composita deve spiegare che cosa rappresentano i colori dei diversi strumenti."]}, {"title": "Apparire vicini non basta", "paragraphs": ["Due galassie sovrapposte sulla carta possono trovarsi a distanze diverse. Per identificare i membri di un ammasso servono dati aggiuntivi, non soltanto il numero di ovali in una fotografia. Le misure spettroscopiche e lo studio della struttura aiutano a distinguere appartenenza e proiezione. Anche la presenza di una galassia molto brillante al centro apparente non autorizza a immaginare tutte le altre su orbite circolari ordinate come pianeti attorno al Sole."]}, {"title": "Una rete, non una collezione di isole immobili", "paragraphs": ["Gli ammassi fanno parte della distribuzione a grande scala e possono interagire e fondersi. Gruppi, ammassi e superammassi non sono semplicemente contenitori identici di dimensione crescente: occorre distinguere anche il loro stato dinamico. Nel laboratorio, associa quindi la fotografia di un campo di galassie alla scala corretta, poi chiediti quali informazioni mancano. La classificazione visiva è un primo passo; la dimostrazione del legame fisico richiede osservazioni e modelli."]}], "facts": ["Ammasso stellare ≠ ammasso di galassie", "Luce visibile e massa totale non coincidono"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/galassia_(Dizionario-delle-Scienze-Fisiche)/"}, {"title": "NASA · strutture a grande scala", "url": "https://science.nasa.gov/universe/galaxies/large-scale-structures/"}], "aliases": ["ammassi di galassie"]}, {"id": "ammasso-globulare", "name": "Ammasso globulare", "definition": "Sistema stellare denso, approssimativamente sferoidale, con forte concentrazione di stelle verso il centro.", "example": "Non confondere un ammasso di stelle con un ammasso di galassie: cambia ciò che viene raggruppato.", "source": "https://www.treccani.it/enciclopedia/sistemi-stellari_(Enciclopedia-del-Novecento)/", "lesson": "lezione-5-3.html", "related": ["galassia", "ammasso-aperto"], "checked": "2026-10-30", "sections": [{"title": "Molte stelle in un sistema compatto", "paragraphs": ["Un ammasso globulare è un sistema di stelle gravitazionalmente legato, con forma complessiva spesso approssimativamente sferoidale e una concentrazione centrale evidente. Le stelle restano oggetti distinti: la fotografia può fonderne la luce perché la separazione apparente è piccola. L’aspetto di una nube luminosa non significa che l’oggetto sia composto principalmente da gas come una nebulosa."]}, {"title": "Una popolazione preziosa per la storia galattica", "paragraphs": ["Gli ammassi globulari della Via Lattea comprendono tipicamente popolazioni stellari antiche e occupano un volume più ampio del solo disco galattico. Aiutano a ricostruire formazione ed evoluzione della Galassia. “Antico” non significa però che ogni stella del gruppo sia identica o che tutti gli ammassi abbiano esattamente la stessa età e composizione. Le osservazioni moderne mostrano storie e popolazioni più articolate della figura ideale di un unico insieme uniforme."]}, {"title": "Che cosa cambia all’oculare", "paragraphs": ["In uno strumento piccolo un globulare può apparire come un batuffolo concentrato. Con maggiore apertura, condizioni adatte e ingrandimento utile si possono distinguere più stelle, soprattutto nelle regioni esterne. La risoluzione reale dipende anche da seeing, altezza e contrasto. Non è corretto promettere che una certa immagine fotografica sarà riprodotta dall’oculare: sensore, integrazione e trattamento dei dati possono far emergere componenti non equivalenti alla percezione visuale."]}, {"title": "Le distinzioni che evitano errori", "paragraphs": ["Un ammasso di stelle non è un ammasso di galassie. Nel primo i membri sono stelle di un sistema; nel secondo si raggruppano intere galassie, su scale molto maggiori. Anche una galassia ellittica vista da lontano può apparire tondeggiante: la forma non basta a stabilire la natura dell’oggetto. Per un riconoscimento didattico servono una fotografia pertinente, una scala o un contesto e gli indizi fisici necessari, non soltanto una macchia tonda da abbinare a una parola."]}], "facts": ["È un sistema di stelle, non un ammasso di galassie", "La luce centrale può non risolversi in singoli punti", "Forma apparente e natura fisica non sono sinonimi"], "sources": [{"title": "Treccani · riferimento della voce", "url": "https://www.treccani.it/enciclopedia/sistemi-stellari_(Enciclopedia-del-Novecento)/"}], "editorialStatus": "scheda-estesa", "media": {"file": "assets/lezioni/47tuc-globulare.jpg", "caption": "47 Tucanae: un ammasso globulare. La concentrazione apparente non ne fa una galassia.", "credit": "ESO/M.-R. Cioni/VISTA Magellanic Cloud survey; Cambridge Astronomical Survey Unit", "source": "https://www.eso.org/public/images/eso1302a/", "license": "CC BY 4.0"}, "aliases": ["ammassi globulari"]}, {"id": "ampiezza", "name": "Ampiezza", "definition": "L’ampiezza quantifica l’entità di una variazione o oscillazione; bisogna dichiarare se indica lo scostamento dal valore centrale oppure la differenza fra massimo e minimo.", "example": "Scostamento dal centro e variazione picco-picco differiscono", "source": "https://www.treccani.it/enciclopedia/ampiezza/", "lesson": "lezione-4-2.html", "related": ["fotometria", "magnitudine-apparente", "radiazione"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Quanto varia una grandezza", "paragraphs": ["Se una misura cambia nel tempo, il suo periodo racconta ogni quanto si ripete e l’ampiezza quanto si allontana da un riferimento. Sono informazioni diverse. Nel caso di un’oscillazione si può usare lo scostamento massimo dalla posizione centrale; per una curva di luce si usa spesso l’intervallo fra estremi. Senza precisare la convenzione, due numeri apparentemente diversi possono descrivere lo stesso segnale."]}, {"title": "Un esempio da leggere senza formule avanzate", "paragraphs": ["Un valore che oscilla fra 8 e 12 ha centro 10. Lo scostamento massimo dal centro è 2, mentre la variazione picco-picco è 4. Dire soltanto “ampiezza quattro” non chiarisce quale definizione sia stata scelta. Se si misura una stella in magnitudini, il rapporto fra flussi non coincide numericamente con la differenza fra i valori: la scala fotometrica ha una propria definizione."]}, {"title": "Il caso delle stelle variabili", "paragraphs": ["Una curva di luce mostra variazioni dovute a processi intrinseci o a geometrie come le eclissi. L’ampiezza osservata può dipendere dalla banda, dal sistema e dalla presenza di luce aggiuntiva. Non misura automaticamente la variazione del raggio stellare. Anche una periodicità regolare non identifica da sola il meccanismo: colore, spettro e altri dati aiutano a distinguere pulsazione, occultazione e fenomeni differenti."]}, {"title": "Segnale reale o rumore", "paragraphs": ["Una piccola variazione può essere confrontabile con l’incertezza della misura. Prima di assegnarle un significato fisico occorre valutare fondo, calibrazione e ripetibilità. Una curva disegnata con grandi escursioni per renderla leggibile deve dichiarare la scala verticale. Amplificare graficamente un cambiamento è legittimo se aiuta a leggerlo, ma non deve suggerire che il fenomeno sia enorme. Un asse con unità e intervallo espliciti trasforma una figura evocativa in un’informazione interpretabile."]}], "facts": ["Scostamento dal centro e variazione picco-picco differiscono", "Periodo: ogni quanto · ampiezza: quanto varia"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/ampiezza/"}]}, {"id": "anello-planetario", "name": "Anello planetario", "definition": "Un anello planetario è un insieme di particelle che orbitano attorno a un pianeta, non una lastra solida fissata al suo equatore.", "example": "Gli anelli sono popolazioni di particelle in orbita", "source": "https://www.treccani.it/enciclopedia/saturno/", "lesson": "lezione-3-4.html", "related": ["pianeta", "orbita", "sistema-solare"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un disco apparente fatto di molte orbite", "paragraphs": ["Saturno offre l’esempio più riconoscibile, ma tutti e quattro i pianeti giganti del Sistema solare hanno sistemi di anelli. La loro visibilità e composizione non sono uguali. Il disegno di un unico bordo continuo è una semplificazione: ogni particella segue il proprio moto gravitazionale. L’insieme produce fasce luminose o deboli, lacune e strutture che una fotografia sufficientemente dettagliata può rivelare."]}, {"title": "Ghiaccio, polvere e dimensioni diverse", "paragraphs": ["Negli anelli principali di Saturno è importante il ghiaccio d’acqua, mentre altri sistemi possono essere molto scuri e ricchi di polvere. Non conviene trasferire automaticamente colore e brillantezza saturniani agli altri pianeti. Le particelle non devono avere tutte la stessa grandezza e una divisione scura non è necessariamente uno spazio completamente vuoto. Anche qui il contrasto dell’immagine può far apparire netta una differenza che in realtà riguarda la densità del materiale."]}, {"title": "Perché la forma cambia nell’oculare", "paragraphs": ["Un sistema quasi piano, osservato inclinato, appare come un’ellisse. Quando la linea di vista si avvicina al piano degli anelli, la loro apertura apparente diminuisce. Non è il pianeta che schiaccia improvvisamente gli anelli: cambia la prospettiva durante i moti orbitali. Un’animazione didattica deve conservare la geometria del piano e distinguere l’inclinazione reale dall’angolo sotto cui lo vediamo dalla Terra."]}, {"title": "La prova che puoi fare sul quaderno", "paragraphs": ["Disegna Saturno in serate diverse e annota apertura apparente, ombra degli anelli e condizioni dell’osservazione. Una singola differenza di nitidezza può dipendere dal seeing o dal fuoco, quindi non attribuirla subito a un cambiamento fisico. Le immagini ravvicinate delle sonde mostrano dettagli irraggiungibili con molti strumenti amatoriali. Nel confronto conserva sempre la provenienza: vedere la stessa struttura generale non significa poter distinguere le medesime particelle o le stesse lacune."]}], "facts": ["Gli anelli sono popolazioni di particelle in orbita", "La prospettiva modifica la loro apertura apparente"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/saturno/"}, {"title": "NASA · Saturno e i suoi anelli", "url": "https://science.nasa.gov/saturn/facts/"}], "aliases": ["anelli planetari"]}, {"id": "angolo-orario", "name": "Angolo orario", "definition": "L’angolo orario esprime quanto una direzione celeste si trova a est o a ovest del meridiano locale, secondo la convenzione adottata.", "example": "Angolo orario 1 h = 15°", "source": "https://www.treccani.it/enciclopedia/coordinate/", "lesson": "lezione-1-3.html", "related": ["ascensione-retta", "declinazione", "giorno-siderale"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un riferimento legato al tuo meridiano", "paragraphs": ["Il meridiano celeste locale passa per zenit e poli celesti. L’angolo orario colloca il cerchio orario dell’astro rispetto a quel riferimento. Nella convenzione astronomica usuale cresce verso ovest e si può esprimere in ore angolari. Zero corrisponde al passaggio sul meridiano superiore. Non è la stessa cosa dell’ascensione retta, che usa un’origine di catalogo anziché il meridiano del luogo."]}, {"title": "Le ore che misurano angoli", "paragraphs": ["Un giro corrisponde a 24 h, quindi un’ora angolare equivale a 15°. Non basta leggere il quadrante dell’orologio civile per conoscere l’angolo orario di una stella. Occorrono il tempo siderale locale e l’ascensione retta nel riferimento coerente. Nell’uso classico si sottrae l’ascensione retta dal tempo siderale locale e si tratta il risultato come un angolo periodico. La convenzione del segno deve sempre essere esplicita."]}, {"title": "Il moto lungo un parallelo celeste", "paragraphs": ["Per una stella ideale con declinazione fissa, cambiare angolo orario la fa percorrere lungo il proprio cerchio di declinazione. Non la porta verso l’equatore celeste e non cambia la sua appartenenza alla regione circumpolare per il medesimo luogo. Altezza e azimut variano perché il cerchio è osservato rispetto all’orizzonte. Questo è il controllo geometrico fondamentale per un laboratorio che simula il moto diurno."]}, {"title": "Un esempio pratico", "paragraphs": ["Una stella appena a ovest del meridiano ha già superato il transito superiore, nella convenzione positiva verso ovest. Questo può aiutare a valutare l’evoluzione della sua altezza e la pianificazione della ripresa, ma non sostituisce tutti i vincoli dello strumento. Vicino ai poli celesti il percorso ha caratteristiche diverse da quello di un astro equatoriale. Un diagramma deve conservare latitudine, declinazione e segno dell’angolo, altrimenti un’animazione piacevole può raccontare un cielo impossibile."]}], "facts": ["Angolo orario 1 h = 15°", "Cambia il posto sul parallelo celeste, non la declinazione"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/coordinate/"}], "archiveReferences": ["Marco Monaci, Corso di Astronomia, pagina PDF 21: confronto fra tempo siderale, angolo orario e ascensione retta."]}, {"id": "anno-giuliano", "name": "Anno giuliano", "definition": "L’anno giuliano astronomico è un intervallo convenzionale di 365,25 giorni, ciascuno di 86.400 secondi, usato per esprimere durate e altre grandezze.", "example": "1 anno giuliano = 31.557.600 secondi esatti", "source": "https://www.treccani.it/enciclopedia/anno/", "lesson": "lezione-2-1.html", "related": ["anno-luce", "ora-civile", "effemeridi"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Una misura stabilita, non un evento da aspettare", "paragraphs": ["Per misurare intervalli lunghi serve un’unità riproducibile. L’anno giuliano astronomico risponde a questa esigenza: vale esattamente 31.557.600 secondi. Non si deve osservare quando la Terra completa un’orbita per conoscerne la durata. È una convenzione, come usare una certa lunghezza come metro di riferimento. La precisione del numero deriva dalla definizione dell’unità e non dalla perfetta regolarità del movimento terrestre."]}, {"title": "Il quarto di giorno non è una data del calendario", "paragraphs": ["365,25 significa 365 giorni e sei ore. Se conti quattro intervalli di questa durata ottieni 1.461 giorni. Non significa che ogni anno civile abbia sei ore aggiunte a dicembre, né che il calendario gregoriano sia costituito soltanto da gruppi di quattro anni identici. Le regole dei bisestili servono a un problema diverso: mantenere il calendario sufficientemente vicino al ciclo delle stagioni nel lungo periodo."]}, {"title": "L’anno luce usa questa convenzione", "paragraphs": ["Nella definizione moderna dell’anno luce si considera il percorso della luce nel vuoto durante un anno giuliano. Perciò è possibile ottenere una distanza numerica ben definita moltiplicando una velocità costante per un intervallo convenzionale esatto. Un anno luce resta una lunghezza, non la durata di un viaggio qualsiasi. Scrivere la convenzione evita di confondere l’anno tropico o il calendario personale con l’unità usata nel calcolo."]}, {"title": "Come leggere un dato astronomico", "paragraphs": ["Quando un catalogo esprime un moto in secondi d’arco per anno, la documentazione specifica il riferimento temporale pertinente. Non si deve sostituire automaticamente l’anno civile di 365 o 366 giorni. Allo stesso modo un’epoca di catalogo non è l’ora locale dell’osservazione. Per il lettore basta ricordare la distinzione: una cosa è l’unità con cui misuriamo il tempo, un’altra è il fenomeno astronomico o la data che intendiamo descrivere."]}], "facts": ["1 anno giuliano = 31.557.600 secondi esatti", "Convenzione temporale ≠ anno civile"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/anno/"}, {"title": "JPL · parametri e unità astronomiche", "url": "https://ssd.jpl.nasa.gov/astro_par.html"}]}, {"id": "anno-luce", "name": "Anno luce", "definition": "Unità di distanza: il cammino percorso dalla luce nel vuoto durante un anno.", "example": "Dire che un oggetto è lontano quattro anni luce indica una distanza, non la sua età.", "source": "https://www.treccani.it/enciclopedia/anno-luce/", "lesson": "lezione-6-3.html", "related": ["parsec", "parallasse"], "checked": "2026-10-30", "sections": [{"title": "Una distanza nascosta in una parola di tempo", "paragraphs": ["L’anno luce misura una distanza, non una durata. È il cammino che la luce percorre nel vuoto in un anno convenzionale. La parola “anno” compare perché usiamo un intervallo di tempo per costruire l’unità: allo stesso modo potremmo descrivere un sentiero dicendo quanta strada percorriamo camminando per un’ora. In astronomia, però, la velocità e l’intervallo adottati nella definizione sono specificati con precisione.", "Un anno luce equivale a 9.460.730.472.580,8 chilometri: circa 9.461 miliardi di chilometri. La notazione compatta è 9,461 × 10¹² km. Non significa 9.461 milioni: la differenza è di un fattore mille. Usare l’anno luce permette di parlare delle stelle senza scrivere continuamente numeri molto lunghi."]}, {"title": "Come si ottiene il numero", "paragraphs": ["La velocità della luce nel vuoto è esattamente 299.792,458 km al secondo. Per questa definizione si adotta l’anno giuliano: 365,25 giorni di 86.400 secondi ciascuno, cioè 31.557.600 secondi. Il calcolo consiste soltanto nel moltiplicare la strada percorsa in un secondo per il numero di secondi dell’anno. Non richiede radici o logaritmi.", "299.792,458 km/s × 31.557.600 s = 9.460.730.472.580,8 km. I secondi compaiono una volta al denominatore e una al numeratore: si cancellano, lasciando una lunghezza. Un anno giuliano non è il calendario di un particolare anno civile e non indica l’alternanza degli anni bisestili. È un intervallo convenzionale di durata fissa."]}, {"title": "Guardare lontano significa ricevere luce partita prima", "paragraphs": ["Immaginiamo una stella a quattro anni luce, sufficientemente vicina perché basti la geometria ordinaria. La luce che riceviamo oggi ha impiegato circa quattro anni per arrivare. Non stiamo vedendo la stella nel suo stato simultaneo all’osservazione terrestre: riceviamo un segnale partito prima. Questo non significa che la stella abbia quattro anni di età, né che abbia impiegato quattro anni a formarsi.", "La distinzione torna utile già nel Sistema solare. Il tempo di propagazione della luce dal Sole alla Terra, alla distanza di un’unità astronomica, è circa 499 secondi: poco più di otto minuti. Un’immagine è quindi sempre una notizia arrivata da una certa distanza. Il ritardo non è prodotto dal telescopio: esiste anche quando guardiamo a occhio nudo."]}, {"title": "Quale unità scegliere e dove fermare l’analogia", "paragraphs": ["Per le distanze fra pianeti è comoda l’unità astronomica; per le stelle vicine l’anno luce offre un ordine di grandezza intuitivo. Nei cataloghi si usa spesso il parsec: un parsec corrisponde a circa 3,26 anni luce ed è legato alla misura della parallasse. Nessuna di queste unità indica da sola la durata di un viaggio umano, che dipenderebbe dalla velocità e dalla traiettoria del mezzo.", "Per le galassie molto lontane occorre un’ulteriore cautela. L’Universo si espande durante il viaggio della luce, e distanza attuale, distanza ricavata dalla luminosità e tempo trascorso dall’emissione non sono quantità intercambiabili. L’idea “un anno luce uguale un anno di ritardo” funziona come prima lettura locale; non va trasformata in una regola cosmologica universale."]}], "facts": ["1 anno luce = 9.460.730.472.580,8 km", "Valore arrotondato: circa 9.461 miliardi di km", "Calcolo: velocità della luce × 31.557.600 secondi"], "sources": [{"title": "Treccani · anno luce", "url": "https://www.treccani.it/enciclopedia/anno-luce/"}, {"title": "NASA/JPL · parametri e anno giuliano", "url": "https://ssd.jpl.nasa.gov/astro_par.html"}, {"title": "IAU · unità e misure astronomiche", "url": "https://iauarchive.eso.org/public/themes/measuring/"}, {"title": "NASA · distanze cosmiche", "url": "https://science.nasa.gov/universe/cosmic-distances/"}], "archiveReferences": ["Marco Monaci, Corso di Astronomia, pagina PDF 27: definizione, conversione approssimata e confronto con il parsec. Consultazione nell’archivio personale; non riproduzione del testo."], "editorialStatus": "scheda-estesa", "aliases": ["anno-luce", "anni luce"]}, {"id": "anno-siderale", "name": "Anno siderale", "definition": "L’anno siderale descrive il periodo della rivoluzione terrestre rispetto a un riferimento legato alle stelle lontane: circa 365 giorni, 6 ore e 9 minuti.", "example": "Siderale: riferimento stellare", "source": "https://www.treccani.it/enciclopedia/anno/", "lesson": "lezione-2-1.html", "related": ["giorno-siderale", "punto-equinoziale", "anno-giuliano"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La domanda è: rispetto a che cosa?", "paragraphs": ["Dire che la Terra torna al punto di partenza richiede di scegliere un riferimento. Se confrontiamo la sua rivoluzione con le direzioni delle stelle lontane, otteniamo l’anno siderale. Non è il ritorno dello stesso giorno sul calendario e non è un giro della Terra su se stessa. Quel giro riguarda il giorno siderale. La somiglianza dei nomi indica il riferimento stellare, non l’identità dei due movimenti."]}, {"title": "Un piccolo scarto che racconta un altro movimento", "paragraphs": ["L’anno siderale è un po’ più lungo dell’anno tropico medio. Gli equinozi, usati per collegare l’anno alle stagioni, non conservano una direzione fissa rispetto al cielo stellato: interviene la precessione. Per questo una rivoluzione confrontata con le stelle e un ciclo stagionale non terminano esattamente insieme. Il fenomeno è lento, ma la differenza diventa importante quando si costruiscono calendari o si confrontano osservazioni molto lontane nel tempo."]}, {"title": "Un esempio da immaginare senza formule", "paragraphs": ["Su un pavimento circolare segna un riferimento fisso e, poco prima, una seconda tacca che si sposta lentamente in verso opposto al tuo cammino. Tornare alla tacca mobile richiede meno strada che tornare a quella fissa. L’esempio illustra soltanto il confronto tra riferimenti, non riproduce in scala i movimenti terrestri. Aiuta però a capire perché due definizioni corrette di anno possano dare intervalli leggermente differenti."]}, {"title": "Quanto dettaglio serve nel diario", "paragraphs": ["Per organizzare una serata usi date e orari civili, non conti anni siderali. Il concetto serve a interpretare il rapporto tra stelle, stagioni e coordinate. Anche il valore numerico è da presentare con una precisione adatta al contesto e con il riferimento temporale delle formule più accurate. Non è necessario imparare tutti i secondi: è più utile saper spiegare quale ritorno viene misurato e perché non coincide con il ciclo stagionale."]}], "facts": ["Siderale: riferimento stellare", "Rivoluzione annuale e rotazione diurna sono fenomeni distinti"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/anno/"}, {"title": "Archivio INAF Torino · Lattanzi, pagina 59, riferimento storico da leggere criticamente", "url": "https://www.oato.inaf.it/biblioteca/pdf/TechRep078_Lattanzi.pdf"}], "archiveReferences": ["Lattanzi, pagina 59: letto il confronto fra anno siderale e tropico; formule storiche non adottate come valori esatti attuali."]}, {"id": "anno-tropico", "name": "Anno tropico", "definition": "L’anno tropico collega il moto apparente del Sole al ciclo delle stagioni; il suo valore medio è circa 365,2422 giorni.", "example": "Anno tropico medio ≈ 365,2422 giorni", "source": "https://www.treccani.it/enciclopedia/anno/", "lesson": "lezione-2-2.html", "related": ["punto-equinoziale", "eclittica", "anno-siderale"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "L’anno delle stagioni", "paragraphs": ["Il calendario deve riportare la primavera nello stesso periodo dell’anno, non soltanto contare rivoluzioni rispetto a stelle lontane. Il riferimento tropico risponde a questa esigenza. Nella descrizione introduttiva lo colleghiamo al ritorno del Sole alla stessa fase del ciclo stagionale. Una definizione di precisione distingue però il valore medio dagli intervalli tra singoli equinozi o solstizi: questi non sono tutti identici al secondo."]}, {"title": "Perché non dura esattamente 365 giorni", "paragraphs": ["Il valore medio supera i 365 giorni di poco meno di sei ore. Se il calendario ignorasse sempre questa frazione, le date scivolerebbero progressivamente rispetto alle stagioni. Gli anni bisestili correggono gran parte dello scarto, con regole che nel calendario gregoriano non si riducono a una sola aggiunta ogni quattro anni senza eccezioni. Il calendario è una costruzione civile che cerca un buon accordo con il ciclo astronomico."]}, {"title": "Il riferimento si muove lentamente", "paragraphs": ["Gli equinozi dipendono dall’orientamento dell’equatore terrestre rispetto all’orbita. Questo orientamento cambia lentamente per precessione: il punto equinoziale non resta fisso contro le stelle. Ecco perché l’anno tropico medio è leggermente più breve di quello siderale. Non significa che la Terra imbocchi due orbite differenti secondo il calendario scelto. Stiamo misurando lo stesso sistema con due criteri diversi per stabilire quando il ciclo è concluso."]}, {"title": "Una conseguenza per chi osserva", "paragraphs": ["Le costellazioni serali tornano grosso modo nella stessa stagione da un anno al successivo, ma le coordinate e le corrispondenze esatte richiedono riferimenti dichiarati nei confronti su tempi lunghi. Non occorre introdurre questa complessità per orientare una carta stasera. Serve invece a capire perché le stagioni non siano definite dalla distanza istantanea Terra–Sole e perché una parola comune, anno, possa indicare intervalli astronomici distinti."]}], "facts": ["Anno tropico medio ≈ 365,2422 giorni", "Il calendario segue il ciclo stagionale, con approssimazioni e regole"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/anno/"}]}, {"id": "apertura", "name": "Apertura", "definition": "Nell’uso astronomico comune l’apertura indica il diametro utile che raccoglie luce; non va confusa con focale e ingrandimento.", "example": "Diametro doppio → area geometrica quattro volte maggiore", "source": "https://www.treccani.it/enciclopedia/apertura_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-7-3.html", "related": ["focale", "diffrazione", "telescopio"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il diametro che incontra il cielo", "paragraphs": ["Un telescopio da 100 mm possiede un’apertura nominale di quel diametro. La misura descrive la pupilla d’ingresso o l’apertura utile secondo il sistema, non necessariamente l’ingombro esterno del tubo. Un paraluce o una cella possono essere più larghi senza raccogliere più luce. Per confronti accurati contano anche eventuali ostruzioni, trasmissione e parti effettivamente utilizzate nel percorso ottico."]}, {"title": "La superficie cresce più del diametro", "paragraphs": ["Per aperture circolari libere, raddoppiare il diametro quadruplica l’area. Un 100 mm ha quindi quattro volte l’area geometrica di un 50 mm, non due. Questa proporzione riguarda la raccolta ideale, a condizioni equivalenti. Non dice che ogni oggetto apparirà quattro volte più luminoso all’occhio con qualsiasi oculare: ingrandimento, pupilla d’uscita, trasmissione e natura estesa o puntiforme del soggetto entrano nell’esperienza."]}, {"title": "Il legame con la risoluzione", "paragraphs": ["A parità di lunghezza d’onda, l’apertura maggiore riduce la scala angolare della figura di diffrazione. Può quindi permettere di separare dettagli più fini. L’atmosfera e la qualità del sistema possono però impedire di raggiungere quel limite. Una fotografia mossa non diventa nitida soltanto perché proviene da un diametro maggiore. La possibilità teorica e il risultato della serata sono due livelli da distinguere."]}, {"title": "Apertura relativa e fotografia", "paragraphs": ["Il rapporto focale si ottiene dividendo la focale per l’apertura utile: con 500 mm e 100 mm si ha f/5. È un rapporto, non un ingrandimento. In un obiettivo fotografico il diaframma può modificare l’apertura utilizzata, mentre il diametro esterno resta uguale. Un confronto serio specifica quindi quale apertura è stata realmente impiegata e considera anche campo, peso e supporto necessari per sfruttarla."]}], "facts": ["Diametro doppio → area geometrica quattro volte maggiore", "500 mm / 100 mm = f/5"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/apertura_(Dizionario-delle-Scienze-Fisiche)/"}]}, {"id": "apocromatico", "name": "Apocromatico", "definition": "Un obiettivo apocromatico mira a una correzione cromatica più estesa rispetto a un acromatico classico, con proprietà da verificare nel progetto concreto.", "example": "Tripletto ed apocromatico non sono sinonimi automatici", "source": "https://www.treccani.it/vocabolario/apocromatico/", "lesson": "lezione-7-3.html", "related": ["acromatico", "aberrazione-cromatica", "rifrattore"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Far lavorare insieme più colori", "paragraphs": ["Nella tradizione ottica l’apocromatismo riguarda una correzione più ampia dei fuochi cromatici, tipicamente descritta attraverso tre lunghezze d’onda e il controllo di ulteriori residui. Il senso pratico è concentrare meglio la luce policromatica. Non basta però ripetere il numero di colori: la prestazione è una proprietà dell’intero progetto, dei materiali, delle tolleranze e dell’intervallo di lunghezze d’onda considerato."]}, {"title": "Non è soltanto il numero di lenti", "paragraphs": ["Tripletto indica tre elementi nel gruppo, mentre apocromatico indica un obiettivo di correzione. Le due parole non sono sinonimi automatici. Esistono configurazioni diverse e i nomi commerciali possono riassumere caratteristiche differenti. Anche la sigla ED descrive una proprietà dei materiali utilizzati, non un certificato universale dell’immagine finale. Per un confronto concreto servono dati o prove pertinenti, non soltanto la scritta sul tubo."]}, {"title": "Il vantaggio cercato in fotografia", "paragraphs": ["Le stelle mettono in evidenza aloni e differenze di fuoco tra bande. Una buona correzione aiuta a ottenere immagini più concentrate e colori meglio controllati, entro i limiti del sistema. Restano però curvatura di campo, campionamento, fuoco, inseguimento e atmosfera. Se ai bordi le stelle sono deformate, il problema non è necessariamente cromatico; può richiedere un correttore appropriato e una distanza del sensore corretta."]}, {"title": "Scegliere in funzione dell’esperienza", "paragraphs": ["Un obiettivo più sofisticato non rende automatico il lavoro sul campo. Bisogna ancora montarlo, equilibrarlo, proteggerlo dalla condensa e mettere a fuoco. Il peso e la focale possono richiedere un supporto più impegnativo. Un laboratorio serio mostra quindi l’ottica dentro una catena completa, senza attribuire alla sola parola apocromatico la capacità di cancellare ogni errore. La scelta migliore è quella coerente con il campo, la portabilità e il tipo di immagini desiderate."]}], "facts": ["Tripletto ed apocromatico non sono sinonimi automatici", "Correzione cromatica ≠ correzione di ogni difetto"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/vocabolario/apocromatico/"}]}, {"id": "apogeo", "name": "Apogeo", "definition": "L’apogeo è il punto di un’orbita geocentrica in cui il corpo si trova alla massima distanza dalla Terra.", "example": "Apogeo: massima distanza dalla Terra", "source": "https://www.treccani.it/enciclopedia/apogeo/", "lesson": "lezione-2-4.html", "related": ["orbita", "perigeo", "afelio"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La Terra come riferimento", "paragraphs": ["Per descrivere un’orbita intorno alla Terra si chiamano apogeo e perigeo i punti di distanza rispettivamente massima e minima. Non sono sinonimi di afelio e perielio, che si riferiscono al Sole. La Luna, per esempio, ha un’orbita la cui distanza terrestre varia. Questi nomi identificano posizioni nella traiettoria, non due stati differenti della superficie lunare."]}, {"title": "Dimensione apparente", "paragraphs": ["A maggiore distanza lo stesso corpo sottende un angolo minore. La Luna vicina all’apogeo appare quindi più piccola che vicino al perigeo, a parità di confronto e con le dovute condizioni. Una fotografia confrontabile deve mantenere la stessa scala ottica e un trattamento coerente. Due immagini ritagliate e ridimensionate per riempire il riquadro non permettono di misurare direttamente la differenza osservata."]}, {"title": "Il legame con alcune eclissi", "paragraphs": ["La dimensione apparente della Luna rispetto al Sole entra nella distinzione fra eclissi totale e anulare, insieme all’allineamento e alla posizione dell’osservatore. Non basta però dire apogeo per prevedere un’eclissi: occorrono fase, vicinanza ai nodi e geometria completa. L’orbita reale subisce perturbazioni e i valori di distanza e data si ricavano da effemeridi, non da un cerchio fisso disegnato una volta per tutte."]}, {"title": "L’equivoco dell’orizzonte", "paragraphs": ["La Luna che sembra enorme vicino all’orizzonte non è per questo al perigeo, né quella alta in cielo è automaticamente all’apogeo. L’illusione lunare riguarda la percezione e il contesto visivo. Per confrontare dimensioni fisiche apparenti si usano immagini e misure calibrate. Separare distanza orbitale, altezza sull’orizzonte e percezione evita di attribuire a una sola causa fenomeni che appartengono a livelli differenti della spiegazione."]}], "facts": ["Apogeo: massima distanza dalla Terra", "Luna bassa sull’orizzonte ≠ necessariamente Luna più vicina"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/apogeo/"}]}, {"id": "apside", "name": "Apside", "definition": "In un’orbita ellittica i due apsidi sono i punti di minima e massima distanza dal fuoco occupato dal corpo centrale nel modello a due corpi.", "example": "Perielio/afelio: rispetto al Sole", "source": "https://www.treccani.it/enciclopedia/apside/", "lesson": "lezione-3-6.html", "related": ["orbita", "perielio", "afelio"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "I due estremi della distanza", "paragraphs": ["Un corpo su un’ellisse non mantiene sempre la stessa distanza dal corpo attorno a cui orbita. Un apside corrisponde all’avvicinamento maggiore e l’altro all’allontanamento maggiore. Il segmento che li congiunge individua la linea degli apsidi. Per leggere bene il disegno bisogna collocare il corpo centrale in un fuoco, non automaticamente nel centro geometrico dell’ellisse: altrimenti si rappresenta in modo sbagliato proprio la variazione che si vuole spiegare."]}, {"title": "Nomi specifici secondo il sistema", "paragraphs": ["Per un’orbita attorno al Sole si parla di perielio e afelio; per un’orbita attorno alla Terra di perigeo e apogeo. Sono nomi della stessa distinzione geometrica applicata a riferimenti diversi. Una cometa può avere un perielio senza passare vicino alla Terra. Un perigeo lunare non implica invece una particolare fase: distanza dalla Terra e posizione rispetto all’illuminazione solare descrivono aspetti differenti del moto."]}, {"title": "La velocità non è uniforme", "paragraphs": ["Nel modello kepleriano il corpo si muove più rapidamente vicino al punto di minima distanza e più lentamente vicino a quello di massima distanza. Per questo un’animazione non dovrebbe distribuire posizioni a tempi uguali come semplici punti equidistanti lungo l’ellisse. Il disegno può usare un’orbita molto allungata per rendere il fenomeno evidente, ma deve dichiarare che l’eccentricità è dimostrativa e non quella di tutti i pianeti."]}, {"title": "Il limite del modello semplice", "paragraphs": ["Le perturbazioni possono modificare l’orbita e l’orientamento della linea degli apsidi. Le effemeridi reali non si ricavano quindi da una singola ellisse immutabile per ogni epoca. Nel limite di un’orbita circolare, la distanza è uguale in ogni punto e non esiste una direzione privilegiata degli apsidi. Prima di memorizzare un nuovo nome, chiediti dunque quale distanza varia, da quale corpo viene misurata e quali ipotesi usa la rappresentazione."]}], "facts": ["Perielio/afelio: rispetto al Sole", "Perigeo/apogeo: rispetto alla Terra"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/apside/"}]}, {"id": "ascensione-retta", "name": "Ascensione retta", "definition": "Coordinata equatoriale che individua la posizione lungo l’equatore celeste, con origine nel punto equinoziale di primavera.", "example": "Si esprime abitualmente da 0 a 24 ore: sono unità angolari; 1 ora corrisponde a 15°.", "source": "https://www.treccani.it/enciclopedia/coordinate/", "lesson": "lezione-1-6.html", "related": ["declinazione", "equatore-celeste", "punto-equinoziale"], "checked": "2026-10-30", "sections": [{"title": "La posizione lungo l’equatore celeste", "paragraphs": ["L’ascensione retta, indicata con la lettera greca α, è una delle coordinate usate per assegnare un indirizzo alle direzioni del cielo. Si misura lungo l’equatore celeste fino al cerchio orario che passa per l’astro. Per completare l’indirizzo si aggiunge la declinazione, cioè quanto la direzione è a nord o a sud dell’equatore. In questa descrizione non stiamo collocando l’astro alla sua distanza reale: due coordinate angolari individuano una linea di vista."]}, {"title": "Perché si scrive in ore", "paragraphs": ["Un giro completo corrisponde a 24 ore di ascensione retta, equivalenti a 360°. Di conseguenza 1 h corrisponde a 15° e 6 h a 90°. Sono unità angolari, non la durata necessaria a raggiungere una stella e neppure l’ora civile alla quale osservarla. Se un catalogo riporta “AR 6 h, Dec +30°”, l’astro non compare necessariamente alle sei del mattino. Per ricavare quando e dove cercarlo servono anche data, luogo e sistema di riferimento."]}, {"title": "L’origine della coordinata", "paragraphs": ["Nel sistema equatoriale classico l’origine è il punto equinoziale di primavera, dove il percorso apparente annuo del Sole attraversa l’equatore celeste passando dal lato sud al lato nord. Si chiama anche punto vernale o punto gamma. È una direzione di riferimento, non una stella da individuare all’oculare. I moderni cataloghi possono usare riferimenti come ICRS: non è corretto trattare ogni coppia di numeri come riferita automaticamente allo stesso equinozio o alla stessa epoca."]}, {"title": "Un riferimento stabile, con condizioni precise", "paragraphs": ["Per una stella lontana, coordinate di catalogo riferite allo stesso sistema ed epoca sono sostanzialmente le stesse per osservatori in città differenti. Cambia invece la sua posizione rispetto ai loro orizzonti. Ciò non significa che le coordinate siano eterne: moto proprio, precessione nel riferimento appropriato e altri effetti entrano nei confronti precisi. Per oggetti vicini conta anche il punto di osservazione. La regola pratica è conservare insieme ai numeri l’indicazione del riferimento e distinguere le coordinate di catalogo da quelle apparenti o topocentriche."]}], "facts": ["24 h = 360° · 1 h = 15°", "AR e declinazione costituiscono una coppia", "Le ore di AR non sono ore dell’orologio civile"], "sources": [{"title": "Treccani · riferimento della voce", "url": "https://www.treccani.it/enciclopedia/coordinate/"}, {"title": "USNO · ICRS e sistemi di riferimento", "url": "https://aa.usno.navy.mil/faq/ICRS_doc"}], "editorialStatus": "scheda-estesa", "aliases": ["AR", "ascensioni rette"]}, {"id": "asterismo", "name": "Asterismo", "definition": "Un asterismo è una figura riconoscibile formata da stelle viste in una certa disposizione apparente; può occupare parte di una costellazione o attraversarne più di una.", "example": "Grande Carro: parte dell’Orsa Maggiore", "source": "https://www.treccani.it/vocabolario/asterismo/", "lesson": "lezione-1-4.html", "related": ["costellazione", "sfera-celeste", "ammasso-aperto"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La figura che la mente riconosce", "paragraphs": ["Un triangolo, una cintura, un carro: prima dei nomi tecnici riconosciamo relazioni fra punti luminosi. In astronomia osservativa moderna chiamiamo asterismo una figura stellare riconoscibile che non coincide necessariamente con una costellazione ufficiale. Il termine ha avuto anche altri usi storici; il vocabolario Treccani ne ricorda l’antico impiego come sinonimo di costellazione. Qui adottiamo la distinzione divulgativa fra figura apparente e regione del cielo."]}, {"title": "Due esempi per fissare il concetto", "paragraphs": ["Il Grande Carro occupa una parte dell’Orsa Maggiore. Il Triangolo Estivo unisce invece Vega, Deneb e Altair, appartenenti a Lira, Cigno e Aquila. Un asterismo può quindi stare dentro una costellazione oppure attraversarne più di una. Le costellazioni moderne sono regioni con confini definiti, non soltanto le linee che uniscono alcune stelle. Una carta deve rendere distinguibili il contorno della regione e i collegamenti della figura."]}, {"title": "Vicinanza sul cielo e distanza nello spazio", "paragraphs": ["Le stelle di un asterismo possono avere distanze, età e moti molto diversi. Le linee aiutano il riconoscimento ma non indicano cavi, orbite comuni o appartenenza automatica a un ammasso. Un piccolo modello con punti posti a profondità differenti mostra come una figura possa cambiare spostando il punto di vista. Non significa però che dall’altra parte della Terra le costellazioni si deformino sensibilmente: per stelle lontane lo spostamento terrestre è minuscolo rispetto alle distanze."]}, {"title": "Usarlo per orientarsi", "paragraphs": ["Un asterismo luminoso offre un primo appiglio per trovare stelle e regioni meno evidenti. Serve ancora una carta coerente con luogo, data e ora per collegare il disegno all’orizzonte. Le indicazioni stagionali sono finestre pratiche, non proprietà che accendono e spengono le stelle a una data fissa. Nel diario puoi disegnare pochi punti ben riconosciuti e annotare come la figura era orientata rispetto a un riferimento locale."]}], "facts": ["Grande Carro: parte dell’Orsa Maggiore", "Triangolo Estivo: attraversa tre costellazioni"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/vocabolario/asterismo/"}, {"title": "OpenStax · cielo e costellazioni", "url": "https://openstax.org/books/astronomy-2e/pages/2-1-the-sky-above"}], "aliases": ["asterismi"]}, {"id": "asteroide", "name": "Asteroide", "definition": "Gli asteroidi sono piccoli corpi del Sistema solare, prevalentemente rocciosi o metallici, con proprietà e orbite molto diverse.", "example": "La fascia principale si trova fra Marte e Giove", "source": "https://www.treccani.it/enciclopedia/asteroide/", "lesson": "lezione-3-5.html", "related": ["cometa", "meteoroide", "orbita"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Piccoli mondi, non semplici sassi identici", "paragraphs": ["La parola richiama l’aspetto stellare con cui molti di questi corpi appaiono nei telescopi, non una loro natura di stelle. Gli asteroidi comprendono oggetti di dimensioni, composizioni e strutture diverse. Alcuni sono blocchi relativamente compatti, altri aggregati di frammenti. Il loro studio racconta collisioni e trasformazioni della materia del Sistema solare. Una fotografia ravvicinata di un singolo asteroide non rappresenta l’aspetto di tutti gli altri."]}, {"title": "Dove si trovano", "paragraphs": ["Molti percorrono la fascia principale fra Marte e Giove, ma non tutti risiedono lì. Esistono popolazioni su altre orbite e oggetti che si avvicinano alla regione terrestre. La fascia non è una parete compatta di rocce come in certe scene cinematografiche: le distanze fra i corpi sono enormi rispetto alle loro dimensioni. Nei disegni la densità e la grandezza dei simboli vengono spesso aumentate per rendere visibile la popolazione."]}, {"title": "Asteroide, cometa e frammento", "paragraphs": ["Le categorie aiutano a descrivere composizione e attività, ma la storia dei piccoli corpi può produrre casi di transizione. Una cometa attiva mostra materiale liberato dal nucleo; un meteoroide è invece un corpo più piccolo nello spazio interplanetario. La meteora è il fenomeno atmosferico e la meteorite il campione che raggiunge il suolo. Non si può sostituire un termine con l’altro soltanto perché una fotografia mostra una forma irregolare."]}, {"title": "Come si riconosce il movimento", "paragraphs": ["In un campo stellare un asteroide può comparire come un punto che cambia posizione rispetto allo sfondo fra riprese successive. Per identificarlo servono tempi, coordinate e confronti con effemeridi, non il solo aspetto. La luminosità varia con distanza, geometria, rotazione e superficie. Un oggetto vicino alla Terra non è automaticamente in collisione: l’eventuale rischio richiede una determinazione orbitale e le sue incertezze, non un soprannome allarmante."]}], "facts": ["La fascia principale si trova fra Marte e Giove", "Vicino alla Terra non significa in collisione"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/asteroide/"}, {"title": "NASA · asteroidi e piccoli corpi", "url": "https://science.nasa.gov/asteroids-comets-meteors/facts/"}], "aliases": ["asteroidi"]}, {"id": "astrofotografia", "name": "Astrofotografia", "definition": "L’astrofotografia comprende tecniche di ripresa ed elaborazione che registrano la luce degli oggetti e dei fenomeni astronomici.", "example": "Ripresa, elaborazione e interpretazione sono passaggi distinti", "source": "https://www.treccani.it/vocabolario/astrofotografia/", "lesson": "astrofotografia.html", "related": ["sensore", "astroinseguitore", "fotometria"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Conservare luce oltre lo sguardo", "paragraphs": ["Una fotografia del cielo non è soltanto il ricordo di una serata. Un sensore può accumulare segnale durante esposizioni e osservazioni ripetute, permettendo di rivelare strutture poco evidenti all’occhio. Questo non significa che ogni immagine elaborata coincida con ciò che vedremmo nell’oculare. Tempo di raccolta, filtri, risposta del sensore e trattamento dei dati contribuiscono al risultato e devono essere spiegati quando influenzano la lettura della figura."]}, {"title": "Non esiste una ricetta unica", "paragraphs": ["Un paesaggio stellato, i dettagli lunari, un pianeta e una nebulosa richiedono scelte differenti. Cambiano dimensioni apparenti, luminosità, tempi e necessità di inseguimento. Per una fotografia da treppiede contano il moto apparente delle stelle e la focale; per una lunga integrazione del cielo profondo contano anche precisione meccanica, calibrazione e condizioni del fondo cielo. Un limite di esposizione presentato come universale non può descrivere tutte queste situazioni."]}, {"title": "Dalla ripresa alla spiegazione", "paragraphs": ["Preparazione, messa a fuoco, acquisizione, controllo e archiviazione formano un percorso. Quando si combinano più immagini bisogna distinguere l’aumento del segnale utile dalla comparsa di artefatti. Sottrarre difetti strumentali non autorizza a inventare strutture del soggetto. Anche una composizione artistica può avere valore, purché sia dichiarata: un cielo trasferito sopra un paesaggio non va presentato come documentazione diretta di un evento avvenuto in quel luogo."]}, {"title": "Il primo archivio personale", "paragraphs": ["Per cominciare registra data, ora, luogo, bersaglio, attrezzatura e impostazioni essenziali. Conserva gli originali insieme alla versione elaborata e annota i passaggi principali. Un confronto fra serate diventa così comprensibile anche dopo mesi. Le fotografie del diario possono essere semplici: la loro forza sta nella continuità e nella possibilità di riconoscere che cosa è cambiato. Una scheda ordinata racconta più di un’immagine spettacolare priva di provenienza e contesto."]}], "facts": ["Ripresa, elaborazione e interpretazione sono passaggi distinti", "Conserva originali e dati della serata"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/vocabolario/astrofotografia/"}, {"title": "NASA · guida all’astrofotografia", "url": "https://science.nasa.gov/wp-content/uploads/2023/09/Astrophotography_Guide.pdf"}]}, {"id": "astroinseguitore", "name": "Astroinseguitore", "definition": "Un astroinseguitore fotografico compensa il moto diurno con una rotazione attorno a un asse disposto parallelamente a quello terrestre.", "example": "Allineamento polare prima dell’inquadratura", "source": "https://www.treccani.it/enciclopedia/montatura/", "lesson": "lezione-7-3.html", "related": ["montatura-equatoriale", "polo-celeste", "focale"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il movimento che rende possibile la posa", "paragraphs": ["Su un treppiede fisso le stelle cambiano posizione nell’immagine durante l’esposizione. Un inseguitore ruota il corredo per compensare questo moto apparente. Nei dispositivi compatti a un asse il principio è quello equatoriale: l’asse va orientato verso il polo celeste appropriato. La parola descrive una funzione, non una tecnologia unica: esistono soluzioni elettroniche e meccaniche, con capacità e procedure differenti."]}, {"title": "La catena dei supporti", "paragraphs": ["Una configurazione frequente comprende treppiede, base di regolazione polare, corpo dell’inseguitore, testa per l’inquadratura e fotocamera con obiettivo. Ogni collegamento deve usare adattatori e serraggi compatibili. La testa superiore sceglie il campo fotografato; la base orienta l’asse. Spostare la base a ogni nuovo bersaglio distrugge l’allineamento. Un contrappeso può essere necessario secondo il modello e il carico, ma non va aggiunto arbitrariamente a qualsiasi dispositivo."]}, {"title": "Il limite non è soltanto il peso", "paragraphs": ["Un teleobiettivo lungo esercita leve e richiede precisione maggiore di un grandangolo. Vento, rigidità del treppiede, equilibrio, qualità meccanica e allineamento incidono sul risultato. Una portata nominale non equivale a una garanzia di pose perfette con qualsiasi focale. Aumentando la scala dell’immagine diventano più visibili errori che in una fotografia grandangolare sarebbero accettabili. La durata utile della posa va verificata nel proprio assetto."]}, {"title": "Viaggio, paesaggio e cielo profondo", "paragraphs": ["L’inseguitore può offrire un corredo trasportabile per Via Lattea, campi stellari e alcuni soggetti del cielo profondo. In una ripresa inseguita il paesaggio terrestre si muove rispetto al sensore: cielo e primo piano richiedono scelte coerenti, eventualmente esposizioni separate dichiarate. Un dispositivo con puntamento automatico o un piccolo telescopio integrato risponde a esigenze diverse. Il confronto utile riguarda campo, controllo, ingombro e risultato desiderato, non soltanto la presenza di un motore."]}], "facts": ["Allineamento polare prima dell’inquadratura", "Portata, focale e leva vanno considerate insieme"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/montatura/"}, {"title": "Sky-Watcher · esempio di inseguitore a un asse", "url": "https://www.skywatcherusa.com/products/star-adventurer-photo-package"}], "aliases": ["astroinseguitori"]}, {"id": "astrometria", "name": "Astrometria", "definition": "L’astrometria misura posizioni e movimenti dei corpi celesti in sistemi di riferimento definiti.", "example": "Coordinate + riferimento + epoca + incertezza", "source": "https://www.treccani.it/vocabolario/astrometria/", "lesson": "lezione-9-4.html", "related": ["parallasse", "ascensione-retta", "declinazione"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Dalla posizione apparente alla misura", "paragraphs": ["Dire che una stella è vicino a una casa aiuta a ritrovarla durante una serata. L’astrometria richiede invece coordinate e riferimenti che permettano il confronto fra osservazioni. Posizione, data, sistema di riferimento e incertezza fanno parte dello stesso dato. Non basta assegnare due numeri molto dettagliati a un punto su una fotografia: le cifre devono corrispondere a una misura calibrata."]}, {"title": "La fotografia ha una geometria", "paragraphs": ["Un sensore registra pixel, non direttamente ascensione retta e declinazione. Per collegare le due descrizioni si confrontano stelle riconosciute con un catalogo e si determina una trasformazione, considerando scala, orientamento e distorsioni. La soluzione astrometrica consente di associare direzioni ai punti dell’immagine. Non crea automaticamente una distanza tridimensionale né rende esatta ogni parte di una ripresa con difetti o pochi riferimenti."]}, {"title": "Il tempo rivela altri movimenti", "paragraphs": ["Ripetendo misure si possono studiare moto proprio, parallasse e traiettorie di oggetti del Sistema solare. Questi contributi non sono intercambiabili. La parallasse nasce dal cambiamento del punto di vista; il moto proprio descrive un cambiamento apparente della direzione legato al moto della sorgente rispetto al riferimento. Per separarli occorre una serie di dati appropriata, non soltanto confrontare due immagini senza conoscere tempi e geometrie."]}, {"title": "Perché serve anche al divulgatore", "paragraphs": ["Una carta interattiva scientificamente coerente deve mantenere le coordinate corrette e trasformarle nel riferimento locale in base a luogo e tempo. La costellazione non può essere spostata a piacere per riempire il riquadro. Le illustrazioni artistiche restano legittime se dichiarate, ma una mappa quantitativa richiede una catena verificabile fra catalogo, calcolo e proiezione. Questa distinzione permette di usare immagini evocative senza trasformarle in false misure del cielo."]}], "facts": ["Coordinate + riferimento + epoca + incertezza", "Pixel dell’immagine e coordinate celesti richiedono una trasformazione"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/vocabolario/astrometria/"}, {"title": "USNO · riferimento ICRS", "url": "https://aa.usno.navy.mil/faq/ICRS_doc"}]}, {"id": "astronomia", "name": "Astronomia", "definition": "L’astronomia studia i corpi e i fenomeni celesti attraverso osservazioni, modelli e confronto delle loro proprietà ed evoluzione.", "example": "Osservazione, interpretazione e previsione vanno distinte", "source": "https://www.treccani.it/enciclopedia/astronomia/", "lesson": "lezione-1-1.html", "related": ["astrometria", "fotometria", "spettro"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Dallo stupore a una domanda controllabile", "paragraphs": ["Riconoscere una costellazione può essere il primo passo, ma la curiosità diventa conoscenza quando distingue che cosa è stato visto da come lo interpretiamo. L’astronomia collega osservazioni e modelli fisici per descrivere il cielo. Non richiede di spegnere lo stupore: richiede di non usarlo come sostituto delle prove. Una serata ben annotata può avere valore didattico anche senza produrre una scoperta nuova."]}, {"title": "Molte finestre, un quadro da confrontare", "paragraphs": ["Posizioni e moti appartengono all’astrometria; flussi e variazioni sono studiati con la fotometria; gli spettri aiutano a ricostruire condizioni fisiche e composizione. Le discipline non sono compartimenti impermeabili. Una galassia osservata in radio e nel visibile rivela componenti differenti, che devono essere interpretate insieme. La distinzione storica netta fra astronomia descrittiva e astrofisica non riassume il lavoro moderno, in cui osservazione e teoria sono strettamente collegate."]}, {"title": "Modelli utili, limiti espliciti", "paragraphs": ["Un’orbita ellittica a due corpi, una sfera celeste e una stella ideale sono strumenti per capire. Non riproducono ogni dettaglio della realtà. Un laboratorio divulgativo è corretto se conserva la geometria essenziale, dichiara le ipotesi e spiega dove l’approssimazione smette di funzionare. Aggiungere cifre o effetti grafici non aumenta automaticamente il rigore. Un modello semplice controllato può insegnare più di una scena complessa ma arbitraria."]}, {"title": "Il ruolo di un portale divulgativo", "paragraphs": ["Un percorso pubblico aiuta a leggere immagini, termini e notizie con autonomia crescente. Le fonti vanno contestualizzate, soprattutto quando contengono dati storici o materiali aziendali. La divulgazione non è una copia abbreviata di un manuale universitario, ma neppure un elenco di curiosità prive di nessi. Esempi, osservazioni pratiche e domande ben poste permettono al lettore di costruire un quadro coerente, mantenendo separati risultato misurato, interpretazione e possibilità ancora aperta."]}], "facts": ["Osservazione, interpretazione e previsione vanno distinte", "Un modello semplice deve dichiarare le proprie ipotesi"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/astronomia/"}]}, {"id": "atmosfera", "name": "Atmosfera", "definition": "L’atmosfera è l’involucro gassoso di un corpo; in astronomia osservativa è anche il mezzo attraverso cui riceviamo gran parte dei segnali dal cielo.", "example": "Atmosfera: proprietà variabili con quota e condizioni", "source": "https://www.treccani.it/enciclopedia/atmosfera/", "lesson": "lezione-8-4.html", "related": ["seeing", "radiazione", "pianeta"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un ambiente, non una pellicola uniforme", "paragraphs": ["L’atmosfera terrestre varia con quota, luogo e tempo. Pressione, temperatura e composizione non restano identiche lungo il percorso della luce. Non esiste un bordo netto oltre il quale ogni particella scompare improvvisamente. Nei disegni la fascia colorata attorno alla Terra è spesso ingrandita per essere visibile: non va letta come una misura in scala del suo spessore rispetto al pianeta."]}, {"title": "La luce attraversa un filtro complesso", "paragraphs": ["Gas e particelle assorbono, diffondono e rifrangono radiazione. Alcune bande raggiungono bene il suolo, altre vengono bloccate: per questo osservare dall’esterno dell’atmosfera apre finestre differenti. La diffusione della luce solare contribuisce al cielo diurno e al crepuscolo. L’attenuazione vicino all’orizzonte può rendere difficile vedere una stella geometricamente già sorta, anche in assenza di una montagna davanti al bersaglio."]}, {"title": "Trasparenza e stabilità non sono sinonimi", "paragraphs": ["Una notte limpida può avere aria turbolenta che deforma le immagini ad alto ingrandimento. Una notte con velo atmosferico può invece mostrare in certi momenti dettagli relativamente fermi. Il primo confronto riguarda la trasmissione, il secondo il seeing. Umidità e temperatura delle superfici possono inoltre produrre condensa sugli strumenti: è un problema del corredo, distinto dalla posizione astronomica dell’oggetto."]}, {"title": "Atmosfere di mondi diversi", "paragraphs": ["Altri pianeti possiedono involucri con composizioni, pressioni e dinamiche molto differenti. La presenza di un’atmosfera non dimostra automaticamente abitabilità. Anche il Sole e le stelle hanno regioni esterne chiamate atmosfere, in un contesto fisico diverso da quello di un pianeta roccioso. Quando una lezione usa la parola deve precisare di quale corpo e di quale regione parla, invece di immaginare ovunque una copia dell’aria terrestre."]}], "facts": ["Atmosfera: proprietà variabili con quota e condizioni", "Trasparenza e seeing descrivono aspetti diversi"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/atmosfera/"}]}, {"id": "atomo", "name": "Atomo", "definition": "Un atomo è una struttura composta da un nucleo e da elettroni; il numero di protoni identifica l’elemento chimico.", "example": "Il numero di protoni identifica l’elemento", "source": "https://www.treccani.it/enciclopedia/atomo/", "lesson": "lezione-4-3.html", "related": ["plasma", "spettro", "fotone"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La materia ha una struttura", "paragraphs": ["Un nucleo contiene protoni e, normalmente, neutroni; gli elettroni appartengono alla struttura elettronica che lo circonda. Il numero di protoni distingue un elemento dall’altro. Il nome storico richiama l’indivisibilità, ma l’atomo non è privo di componenti. In una spiegazione astronomica serve soprattutto capire che la materia può interagire con la luce attraverso stati energetici specifici, anziché comportarsi come una sostanza indistinta."]}, {"title": "Non è un Sistema solare in miniatura", "paragraphs": ["Il disegno di elettroni su orbite circolari attorno al nucleo è un modello storico utile in certi passaggi introduttivi, non una fotografia dei loro percorsi. La descrizione quantistica non assegna semplicemente a ciascun elettrone una piccola traiettoria planetaria. Le scale del nucleo e della struttura elettronica sono inoltre molto diverse: una figura leggibile le altera inevitabilmente. Questa semplificazione va dichiarata per evitare analogie troppo letterali."]}, {"title": "Righe e livelli energetici", "paragraphs": ["Un atomo può assorbire o emettere un fotone in relazione a una transizione energetica consentita. Le differenze corrispondenti contribuiscono a righe riconoscibili nello spettro. Per identificare una sorgente si confrontano insiemi di righe, intensità e condizioni, non soltanto un colore fotografico. Lo stesso elemento può presentare segnali differenti secondo lo stato di ionizzazione e l’ambiente: assenza di una riga non significa automaticamente assenza dell’elemento."]}, {"title": "Quando diventa uno ione", "paragraphs": ["Se un atomo perde o acquista elettroni assume carica netta ed è uno ione. L’identità dell’elemento non cambia finché non cambia il numero dei protoni. Questo distingue ionizzazione e trasformazione nucleare. Nelle stelle la fusione coinvolge nuclei, mentre le righe che registriamo spesso raccontano interazioni in regioni esterne. Separare nucleo, elettroni e ambiente permette di capire perché la luce sia un archivio di informazioni sulla materia lontana."]}], "facts": ["Il numero di protoni identifica l’elemento", "Ionizzazione ≠ trasformazione del nucleo"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/atomo/"}]}, {"id": "attivita-solare", "name": "Attività solare", "definition": "L’attività solare comprende fenomeni legati soprattutto all’evoluzione del campo magnetico del Sole, come macchie, brillamenti ed espulsioni di materiale.", "example": "Ciclo medio di attività: circa undici anni", "source": "https://www.treccani.it/enciclopedia/sole/", "lesson": "lezione-2-3.html", "related": ["sole", "vento-solare", "aurora-polare"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Una stella che cambia aspetto", "paragraphs": ["La superficie visibile del Sole non presenta sempre la stessa distribuzione di macchie. Regioni magnetiche emergono, si trasformano e ruotano fuori dalla vista. Altri fenomeni diventano evidenti osservando differenti parti dello spettro. Un’immagine in luce visibile e una nell’ultravioletto non mostrano due Soli diversi: rendono accessibili regioni e processi diversi della stessa stella. Per confrontarle occorre leggere strumento, banda e momento della ripresa."]}, {"title": "Il ciclo non è un calendario rigido", "paragraphs": ["Il numero di macchie e altri indicatori variano lungo un ciclo di attività dell’ordine di undici anni. Durata e intensità dei cicli non sono perfettamente costanti. Un massimo indica una fase statisticamente più attiva, non la garanzia di un evento importante in una serata scelta. Anche vicino al minimo possono verificarsi fenomeni significativi. Una previsione specifica richiede dati aggiornati e non si deduce dal solo numero dell’anno."]}, {"title": "Fenomeni collegati, ma differenti", "paragraphs": ["Un brillamento è un rapido aumento dell’emissione; un’espulsione di massa coronale riguarda una grande quantità di plasma e campo magnetico che si propaga nello spazio. Possono essere associati, ma non sono sinonimi. Gli effetti verso la Terra dipendono anche da direzione e caratteristiche dell’evento e dall’interazione con l’ambiente magnetico terrestre. La presenza di una grande macchia non promette automaticamente un’aurora visibile da una certa città."]}, {"title": "Osservare con metodo e strumenti adatti", "paragraphs": ["Nel diario solare sono importanti data, ora, orientamento dell’immagine e sistema di filtraggio utilizzato. Le immagini di archivio devono restare dichiarate tali, senza suggerire che descrivano l’attività di oggi. Per osservare direttamente il Sole servono procedure e filtri specifici adeguati allo strumento; non bastano occhiali scuri o un generico filtro fotografico. Comprendere il fenomeno sullo schermo precede qualsiasi esercizio pratico di puntamento e non ne sostituisce le precauzioni."]}], "facts": ["Ciclo medio di attività: circa undici anni", "Brillamento ed espulsione di massa coronale non sono sinonimi"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/sole/"}]}, {"id": "aurora-polare", "name": "Aurora polare", "definition": "L’aurora è un’emissione dell’alta atmosfera prodotta dall’interazione con particelle energetiche, collegata alla dinamica dell’ambiente magnetico terrestre.", "example": "Emissione atmosferica, non semplice riflesso", "source": "https://www.treccani.it/enciclopedia/aurora-polare/", "lesson": "lezione-8-3.html", "related": ["plasma", "atmosfera", "airglow"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "L’atmosfera emette, non riflette soltanto", "paragraphs": ["Archi, cortine e raggi aurorali nascono quando particelle energetiche trasferiscono energia a componenti dell’alta atmosfera. I successivi processi di emissione producono luce. Non è la luce solare colorata che si riflette su nuvole ordinarie. Il collegamento fra attività del Sole, vento solare e ambiente magnetico terrestre è essenziale, ma non si riduce a una traiettoria diretta identica per ogni particella."]}, {"title": "Il ruolo del campo magnetico", "paragraphs": ["La dinamica delle particelle cariche è organizzata dal campo magnetico e dalle condizioni della magnetosfera. Le aurore sono frequenti in regioni legate agli ovali aurorali, che cambiano in forma ed estensione. Non basta quindi tracciare un cerchio immutabile attorno al polo geografico. Eventi intensi possono rendere osservabili emissioni anche a latitudini più basse, ma la visibilità locale non è garantita da un unico indice generale."]}, {"title": "Colori e percezione", "paragraphs": ["I colori dipendono da specie coinvolte, transizioni e condizioni alle diverse quote. Le fotografie possono registrare tonalità molto più evidenti di quelle percepite dall’occhio in una debole emissione. Un chiarore rosso in una foto non certifica da solo un’aurora: esistono altri fenomeni atmosferici e sorgenti artificiali. Contano direzione, evoluzione, contesto e confronto con dati osservativi appropriati, conservando possibilmente gli originali della ripresa."]}, {"title": "Prevedere senza promettere", "paragraphs": ["Gli avvisi di attività geomagnetica aiutano a pianificare, ma nubi, luce lunare, ostacoli e intensità reale determinano che cosa si vedrà. Una lezione deve distinguere previsione, segnalazione e osservazione personale. I numeri storici di frequenza o quote riportati da una singola fonte non descrivono tutti gli eventi. L’esperienza più utile è collegare una testimonianza ben documentata al processo fisico, senza presentare ogni cielo colorato come prova di uno spettacolo eccezionale."]}], "facts": ["Emissione atmosferica, non semplice riflesso", "Foto e visione a occhio nudo possono apparire molto diverse"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/aurora-polare/"}]}, {"id": "autoguida", "name": "Autoguida", "definition": "In astrofotografia l’autoguida misura gli spostamenti di una stella o di un campo e invia correzioni alla montatura per ridurre gli errori di inseguimento.", "example": "Autoguida ≠ GoTo ≠ allineamento polare", "source": "https://www.treccani.it/vocabolario/autoguida/", "lesson": "astrofotografia.html", "related": ["astroinseguitore", "montatura-equatoriale", "seeing"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un controllo durante la posa", "paragraphs": ["L’inseguimento cerca di compensare il moto apparente del cielo. L’autoguida aggiunge un controllo: una camera osserva un riferimento e un programma valuta se occorre correggere il movimento della montatura. È una retroazione, come controllare una traiettoria mentre la si percorre. Non è il puntamento automatico di un nuovo bersaglio e non coincide con l’allineamento polare, che prepara l’orientamento dell’asse prima o durante la messa in servizio."]}, {"title": "Quale luce viene misurata", "paragraphs": ["Il riferimento può essere raccolto da un piccolo strumento di guida o da un dispositivo che preleva parte del fascio del telescopio principale. Una seconda ottica non è quindi l’unica soluzione possibile. Se la guida e la camera principale si muovono l’una rispetto all’altra, la guida può sembrare buona mentre l’immagine presenta comunque difetti. I collegamenti meccanici contano quanto il grafico delle correzioni visualizzato dal programma."]}, {"title": "Correggere non significa inseguire ogni oscillazione", "paragraphs": ["La posizione misurata varia anche per turbolenza atmosferica e rumore. Reagire a ogni minima variazione può introdurre correzioni inutili. Parametri, tempi e calibrazione dipendono dal sistema: non esiste un valore magico valido per ogni montatura. Il seeing non viene cancellato spostando lo strumento in continuazione. Inoltre una guida su un solo riferimento non elimina automaticamente la rotazione di campo dovuta a un assetto o a una geometria non adeguati."]}, {"title": "Prima la base, poi l’automatismo", "paragraphs": ["Supporto stabile, montaggio corretto, bilanciamento quando previsto e cura dei cavi restano fondamentali. Un astroinseguitore può offrire correzioni su un solo asse o non supportare affatto la guida: bisogna leggere il manuale del modello. Per valutare il risultato guarda le stelle della ripresa principale, non soltanto il punteggio del software. L’autoguida è un aiuto alla meccanica e alla misura, non una promessa di esposizioni illimitate o di immagini sempre perfette."]}], "facts": ["Autoguida ≠ GoTo ≠ allineamento polare", "Il risultato si verifica nelle immagini della camera principale"], "sources": [{"title": "Treccani · significato generale di guida automatica; applicazione astronomica spiegata nel testo", "url": "https://www.treccani.it/vocabolario/autoguida/"}], "archiveReferences": ["Fulvio Mete, pagina 68: letto il setup di guida; non adottate come universali la necessità di una seconda ottica né la correzione del seeing."]}, {"id": "azimut", "name": "Azimut", "definition": "Coordinata che indica la direzione sul piano dell’orizzonte. Va sempre dichiarata la convenzione di origine e verso.", "example": "In AD ASTRA: nord 0°, est 90°, sud 180°, ovest 270°. Alcuni testi astronomici adottano invece il sud come origine.", "source": "https://www.treccani.it/enciclopedia/azimut/", "lesson": "lezione-1-6.html", "related": ["altezza-angolare", "orizzonte"], "checked": "2026-10-30", "sections": [{"title": "La direzione lungo l’orizzonte", "paragraphs": ["L’azimut risponde a una domanda molto concreta: verso quale parte dell’orizzonte devo girarmi per cercare un oggetto? È una coordinata angolare. Per definirla immaginiamo il piano dell’orizzonte dell’osservatore e il cerchio verticale che passa per l’astro e per lo zenit. L’azimut individua la direzione in cui quel cerchio incontra l’orizzonte. Non misura quanto l’astro è lontano dalla Terra.", "In AD ASTRA l’origine è il nord geografico e il valore cresce verso est: nord 0°, est 90°, sud 180°, ovest 270°. Un giro completo riporta a nord, perciò 360° e 0° indicano la stessa direzione. Nord-est si trova a 45°; sud-est a 135°. I valori intermedi permettono di descrivere una direzione più precisamente del solo punto cardinale."]}, {"title": "Due numeri per indicare dove guardare", "paragraphs": ["L’azimut si accompagna all’altezza angolare, che misura quanto una direzione sale sopra il piano dell’orizzonte. Dire “azimut 90°, altezza 40°” significa guardare verso est e alzare lo sguardo di 40°. Non significa che l’astro si trovi a quaranta metri, né che sia a una particolare distanza nello spazio. Due oggetti molto lontani fra loro possono apparire quasi sulla stessa linea di vista.", "Puoi provare il concetto senza strumenti: scegli un riferimento lontano, individua il suo lato dell’orizzonte e poi valuta quanto è alto. Ruotare il corpo cambia il rapporto fra est, destra e sinistra, ma non sposta i punti cardinali del luogo. Per questo una descrizione come “alla tua destra” richiede di sapere dove sei rivolto; un azimut dichiarato evita quell’ambiguità."]}, {"title": "Perché luogo e ora sono indispensabili", "paragraphs": ["Il sistema altazimutale è legato all’osservatore. Spostandoti sulla superficie terrestre cambiano la verticale locale e l’orizzonte rispetto alle stelle. Inoltre la rotazione terrestre modifica nel tempo le direzioni osservate. Azimut e altezza non sono quindi un indirizzo di catalogo permanente: per riprodurre una vista servono luogo, data e ora.", "Le coordinate equatoriali organizzano invece le direzioni rispetto all’equatore e ai poli celesti. Una carta locale può essere calcolata da quelle coordinate, ma il risultato altazimutale vale per l’osservatore e per l’istante scelti. È il motivo per cui una carta serale di Roma non va trattata come una fotografia universale del cielo osservabile contemporaneamente da ogni città."]}, {"title": "Convenzioni, bussola e casi limite", "paragraphs": ["La convenzione va sempre dichiarata. Alcuni testi astronomici, soprattutto storici, fanno partire l’azimut da sud: usare il numero senza controllare il riferimento può invertire una direzione. La bussola, inoltre, indica il riferimento magnetico locale, non automaticamente il nord geografico. La differenza si chiama declinazione magnetica; oggetti metallici vicini possono introdurre ulteriori errori.", "Allo zenit l’azimut non ha un valore univoco: tutte le direzioni orizzontali conducono alla stessa verticale quando l’altezza raggiunge 90°. Un programma serio deve trattare questo caso, invece di mostrare un numero arbitrario come se fosse significativo. Infine l’orizzonte geometrico non è il profilo degli ostacoli: una collina può nascondere un astro con altezza positiva. Conoscere le coordinate è il punto di partenza dell’osservazione, non una garanzia di visibilità."]}], "facts": ["Convenzione AD ASTRA: N 0° · E 90° · S 180° · O 270°", "Azimut e altezza sono angoli, non distanze", "Allo zenit l’azimut è indefinito"], "sources": [{"title": "Treccani · azimut", "url": "https://www.treccani.it/enciclopedia/azimut/"}, {"title": "Treccani · sistemi di coordinate e convenzioni", "url": "https://www.treccani.it/enciclopedia/coordinate/"}, {"title": "US Naval Observatory · coordinate locali", "url": "https://aa.usno.navy.mil/faq/alt_az"}, {"title": "US Naval Observatory · riferimento al nord vero", "url": "https://aa.usno.navy.mil/data/AltAz"}], "archiveReferences": ["Marco Monaci, Corso di Astronomia, pagina PDF 17: dipendenza dall’osservatore e azimut indefinito allo zenit. La discussione del sistema equatoriale nella stessa pagina contiene semplificazioni da non trasferire senza controllo."], "editorialStatus": "scheda-estesa"}, {"id": "banda-fotometrica", "name": "Banda fotometrica", "definition": "Una banda fotometrica identifica una risposta spettrale definita entro cui si misura la luce di un oggetto astronomico.", "example": "La banda fa parte della misura", "source": "https://www.treccani.it/enciclopedia/fotometro/", "lesson": "lezione-4-3.html", "related": ["fotometria", "spettro", "magnitudine-apparente"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "La luminosità dipende anche da quale luce misuri", "paragraphs": ["Due stelle possono avere un rapporto di brillantezza diverso se osservate in una banda blu o in una rossa. La loro emissione non è distribuita nello stesso modo lungo lo spettro. La banda fotometrica rende esplicita la parte di luce considerata e il sistema con cui viene misurata. Senza questa indicazione, una magnitudine può sembrare in contraddizione con un’altra che in realtà si riferisce a una misura differente."]}, {"title": "Una curva di risposta, non una finestra ideale", "paragraphs": ["Un filtro non trasmette necessariamente tutto allo stesso modo fra due estremi netti. La risposta complessiva comprende anche sensore, ottica e, da terra, atmosfera. I sistemi standard permettono confronti attraverso procedure di calibrazione. Non basta che due filtri abbiano lo stesso colore commerciale perché i dati siano immediatamente equivalenti. Anche una fotografia RGB gradevole non diventa automaticamente una misura fotometrica standard senza gli opportuni controlli."]}, {"title": "Il colore come differenza misurata", "paragraphs": ["Un indice di colore confronta magnitudini in due bande definite. Non è semplicemente la tonalità visualizzata sul monitor dopo aver regolato saturazione e bilanciamento del bianco. Può fornire indizi sulle proprietà della sorgente, ma anche l’assorbimento lungo la linea di vista modifica la luce ricevuta. Per interpretarlo occorre quindi distinguere il segnale osservato dalle caratteristiche intrinseche che vogliamo ricostruire attraverso modelli e altri dati."]}, {"title": "Come leggere una scheda o un catalogo", "paragraphs": ["Accanto a una magnitudine cerca la sigla della banda, il sistema e l’eventuale incertezza. In un confronto fra osservazioni mantieni queste informazioni insieme al valore. Se il sito riporta un numero semplificato per aiutare a trovare un bersaglio, non trattarlo come una misura personale di precisione. Nel diario una descrizione visuale resta preziosa, ma non va confusa con il risultato calibrato di uno strumento che ha raccolto luce in una specifica banda fotometrica."]}], "facts": ["La banda fa parte della misura", "Colore fotografico elaborato ≠ indice fotometrico calibrato"], "sources": [{"title": "Treccani · fondamento terminologico; applicazione alle immagini astronomiche spiegata nel testo", "url": "https://www.treccani.it/enciclopedia/fotometro/"}]}, {"id": "banda-passante", "name": "Banda passante", "definition": "La banda passante è l’intervallo spettrale o di frequenze che un dispositivo lascia passare secondo una risposta e un criterio di misura dichiarati.", "example": "La curva di trasmissione conta più del solo nome del filtro", "source": "https://www.treccani.it/enciclopedia/fotometria/", "lesson": "astrofotografia.html", "related": ["banda-fotometrica", "spettro", "nebulosa-a-emissione"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Scegliere una parte del segnale", "paragraphs": ["In fotografia astronomica un filtro seleziona alcune lunghezze d’onda e ne attenua altre. Una banda ampia raccoglie una porzione estesa dello spettro; una stretta concentra la selezione attorno a una regione più limitata. Il filtro non inventa i fotoni mancanti e non rende tutti gli oggetti più luminosi. Cambia invece il rapporto fra contributi trasmessi, con vantaggi o svantaggi che dipendono dal soggetto e dalle condizioni."]}, {"title": "La larghezza deve essere definita", "paragraphs": ["Una curva reale di trasmissione non è un rettangolo perfetto. Per descriverne la larghezza si può usare, per esempio, la distanza fra i punti in cui la trasmissione raggiunge metà del massimo. Questo criterio è diverso da indicare ogni lunghezza d’onda alla quale passa una quantità qualunque di luce. Anche la trasmissione massima e l’attenuazione fuori banda contano: due filtri con la stessa larghezza nominale possono comportarsi diversamente."]}, {"title": "Un esempio sulle nebulose", "paragraphs": ["Una nebulosa a emissione produce anche righe caratteristiche. Se il filtro trasmette una di queste regioni e attenua parte del fondo, il contrasto registrato può migliorare. Una galassia o una stella emette invece una distribuzione più ampia, sulla quale lo stesso filtro può tagliare molto segnale utile. La scelta non dipende quindi soltanto da quanto il cielo sia illuminato, ma da quale informazione si vuole raccogliere e con quale sistema."]}, {"title": "Dal grafico alla ripresa reale", "paragraphs": ["Lunghezza d’onda centrale, larghezza, angolo d’incidenza e caratteristiche dello strumento possono influire sulla resa. Leggi la documentazione invece di affidarti al solo nome del filtro. Nelle immagini in falsi colori, bande diverse possono essere assegnate a colori visibili per distinguere strutture: l’assegnazione va dichiarata. Il laboratorio deve aiutare a capire la selezione della luce, non promettere che un accessorio cancelli l’inquinamento luminoso o sostituisca un cielo adatto all’osservazione."]}], "facts": ["La curva di trasmissione conta più del solo nome del filtro", "Una selezione stretta non è adatta indistintamente a tutti i bersagli"], "sources": [{"title": "Treccani · fondamento terminologico; applicazione alle immagini astronomiche spiegata nel testo", "url": "https://www.treccani.it/enciclopedia/fotometria/"}]}, {"id": "baricentro", "name": "Baricentro", "definition": "In astronomia il baricentro viene usato come centro di massa del sistema: la sua posizione dipende dalla distribuzione delle masse.", "example": "Masse uguali → centro a metà", "source": "https://www.treccani.it/enciclopedia/baricentro/", "lesson": "lezione-3-6.html", "related": ["massa", "gravitazione", "orbita"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un centro pesato, non sempre il punto a metà", "paragraphs": ["Per due masse uguali il centro di massa si trova a metà del segmento che le separa. Se una massa è maggiore, il centro si sposta verso di essa. Il nome baricentro coincide con centro di gravità nelle condizioni appropriate di campo uniforme; nel linguaggio astronomico si usa comunemente per il centro di massa. È importante non trasferire senza precisazioni una costruzione geometrica omogenea a un sistema di corpi con masse differenti."]}, {"title": "Un esempio semplice", "paragraphs": ["Considera due corpi separati da 100 unità di distanza, uno tre volte più massiccio dell’altro. Il centro di massa si trova a 25 unità dal corpo maggiore e a 75 da quello minore: il prodotto massa per distanza è uguale dai due lati. Non è quindi nel punto medio. Le unità possono essere metri o chilometri, purché siano le stesse e il modello descriva masse puntiformi o centri di corpi appropriati."]}, {"title": "Due corpi in movimento", "paragraphs": ["Nel modello isolato a due corpi entrambi orbitano attorno al centro di massa comune. Dire che un pianeta gira attorno a una stella è spesso un’approssimazione molto utile, ma non implica che la stella resti perfettamente immobile. Il suo movimento può fornire indizi sulla presenza di una compagna. Massa, inclinazione e geometria osservativa entrano però nell’interpretazione: un’oscillazione misurata non restituisce sempre ogni parametro senza ambiguità."]}, {"title": "Dallo spazio al proprio strumento", "paragraphs": ["La stessa attenzione alla distribuzione dei carichi aiuta a capire un corredo sul supporto. Una fotocamera lontana dall’asse può esercitare una leva importante anche se pesa poco. Bilanciare non significa soltanto sommare chilogrammi, e il baricentro del sistema cambia aggiungendo accessori. Nel laboratorio un pezzo va quindi collocato dove esiste un collegamento plausibile, senza supporre che una figura sospesa resti stabile perché graficamente centrata nel riquadro."]}], "facts": ["Masse uguali → centro a metà", "Il centro si avvicina alla massa maggiore"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/baricentro/"}]}, {"id": "barlow", "name": "Barlow", "definition": "La lente di Barlow è un accessorio ottico che aumenta la focale equivalente del sistema e, nell’uso visuale con lo stesso oculare, l’ingrandimento.", "example": "Ingrandimento = focale equivalente ÷ focale dell’oculare", "source": "https://www.treccani.it/enciclopedia/lente/", "lesson": "lezione-7-4.html", "related": ["focale", "ingrandimento", "oculare"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Che cosa cambia nella catena ottica", "paragraphs": ["Una Barlow inserita nella configurazione prevista modifica il fascio prima della formazione dell’immagine finale. Con un oculare dato permette di ottenere un ingrandimento maggiore rispetto all’uso senza accessorio. Il principio non consiste nell’aumentare il diametro del telescopio. La raccolta di luce e il limite di risoluzione legato all’apertura non diventano quelli di uno strumento più grande soltanto perché il soggetto appare più esteso."]}, {"title": "Un esempio con divisioni semplici", "paragraphs": ["Un telescopio di focale 600 millimetri con un oculare da 20 millimetri fornisce 30 ingrandimenti: si divide 600 per 20. In una configurazione che realizzi davvero un fattore due, la focale equivalente diventa 1.200 millimetri e lo stesso oculare fornisce 60 ingrandimenti. I numeri spiegano il cambiamento di scala; non garantiscono che a 60 volte i dettagli siano sempre più nitidi o più facili da osservare."]}, {"title": "Il fattore dipende dalla configurazione", "paragraphs": ["Per molte Barlow l’amplificazione varia con la distanza dal piano dell’immagine. Il valore scritto sul barilotto si riferisce a una configurazione prevista dal produttore. Prolunghe e posizioni diverse possono modificarlo; altri amplificatori hanno comportamenti differenti. Anche il raggiungimento del fuoco e la compatibilità meccanica vanno controllati. Nel laboratorio i pezzi illustrano l’ordine funzionale, ma non devono suggerire che ogni accessorio si possa collegare in qualsiasi punto senza verifica."]}, {"title": "Quando aiuta e quando no", "paragraphs": ["La Barlow può essere utile per osservazioni a maggiore scala o per determinate riprese lunari e planetarie. Non corregge il seeing, una cattiva collimazione o un sostegno instabile. Un’immagine già sfocata diventa soprattutto più grande, non più informativa. Prima di aggiungerla confronta il risultato sullo stesso soggetto e annota la configurazione. Cercare il massimo ingrandimento dichiarato ha meno valore che trovare una scala adatta a bersaglio, atmosfera e strumento."]}], "facts": ["Ingrandimento = focale equivalente ÷ focale dell’oculare", "Più grande non significa automaticamente più dettagliato"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/lente/"}, {"title": "UAI · Osservare i pianeti, accessori ottici", "url": "https://www.uai.it/sito/wp-content/uploads/2022/03/Osservare-i-pianeti-Falorni-Tanga-LQ.pdf"}], "archiveReferences": ["Fulvio Mete, pagina 32: letto il principio di amplificazione; non adottati ingrandimenti massimi come soglie universali né raccomandazioni commerciali datate."]}, {"id": "bayer-designazione", "name": "Bayer, designazione di", "definition": "La designazione di Bayer identifica molte stelle con una lettera, spesso greca, associata al nome latino della costellazione nella forma grammaticale prevista.", "example": "La lettera è un identificatore, non una magnitudine", "source": "https://www.treccani.it/enciclopedia/johann-bayer/", "lesson": "lezione-9-4.html", "related": ["stella", "costellazione", "astrometria"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un nome che colloca la stella sulla carta", "paragraphs": ["Accanto a un nome proprio puoi trovare una lettera seguita dall’indicazione della costellazione. È un modo storico e ancora utile per identificare stelle riconoscibili sulle carte. La lettera non è una coordinata e non indica da sola una proprietà fisica. Il riferimento alla costellazione serve a distinguere designazioni simili: la stessa lettera può comparire in molte regioni del cielo senza identificare la stessa sorgente."]}, {"title": "Non è una classifica perfetta della luminosità", "paragraphs": ["La scelta delle lettere è collegata storicamente anche alla brillantezza, ma non costituisce un ordinamento rigoroso valido senza eccezioni. Non si deve insegnare che alfa sia sempre la stella apparentemente più luminosa della costellazione o che ogni lettera successiva implichi un valore preciso di magnitudine. Le convenzioni storiche e le differenze fra sistemi di nomenclatura richiedono di usare il nome come identificatore, non come misura da sostituire ai dati."]}, {"title": "Nomi propri e cataloghi convivono", "paragraphs": ["Una stella può avere più identificazioni nei diversi cataloghi e un nome proprio standardizzato. Il confronto richiede una corrispondenza affidabile, soprattutto in sistemi multipli o campi affollati. Un’applicazione che cambia etichetta non ha necessariamente cambiato oggetto. Per riconoscere la stessa sorgente guarda coordinate, contesto e identificativi, invece di supporre che ogni nome incontrato rappresenti una nuova stella. Le sigle dei cataloghi hanno inoltre logiche differenti da quelle delle lettere storiche."]}, {"title": "Non confonderla con la matrice fotografica", "paragraphs": ["Il termine Bayer compare anche nella descrizione della disposizione di filtri colorati su molti sensori, ma quello è un altro concetto e un altro riferimento storico. Una lezione deve distinguere i due usi, senza collegare la classificazione delle stelle al funzionamento della camera. Nel glossario e nei pop-up conviene quindi scrivere il titolo completo della voce. Il lettore capisce così se sta cercando un oggetto sulla mappa o leggendo la struttura del dispositivo che lo fotografa."]}], "facts": ["La lettera è un identificatore, non una magnitudine", "La nomenclatura stellare è distinta dalla matrice colore del sensore"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/johann-bayer/"}]}, {"id": "bias", "name": "Bias", "definition": "Nella calibrazione delle immagini astronomiche, un fotogramma di bias caratterizza il livello elettronico di riferimento e la struttura associata alla lettura, senza segnale luminoso del soggetto.", "example": "Il bias è un riferimento strumentale", "source": "https://www.treccani.it/vocabolario/ricerca/bias/", "lesson": "astrofotografia.html", "related": ["calibrazione", "sensore", "ccd"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un’immagine senza cielo contiene ancora valori", "paragraphs": ["Una camera non restituisce necessariamente zero quando non riceve luce. L’elettronica introduce un livello di riferimento e altri contributi. Un fotogramma di bias viene normalmente acquisito senza luce al tempo più breve previsto dalla procedura per quel sistema. Non rappresenta una fotografia del rumore cosmico né una mappa delle stelle invisibili. È un dato strumentale da interpretare insieme a impostazioni e comportamento della camera."]}, {"title": "Il riferimento si stima, non si conosce magicamente", "paragraphs": ["Più fotogrammi possono essere combinati per stimare meglio la componente ripetibile e limitarne le variazioni casuali. Il risultato viene spesso chiamato master bias. Non significa che ogni oscillazione casuale delle riprese successive sia stata prevista e cancellata. La sottrazione di un riferimento stimato ha a sua volta un’incertezza. L’immagine può diventare più corretta rispetto al livello strumentale senza diventare priva di rumore."]}, {"title": "Un passaggio coerente con gli altri riferimenti", "paragraphs": ["I dark comprendono contributi della lettura oltre al segnale sviluppato durante l’esposizione. Una procedura deve evitare di sottrarre due volte lo stesso livello. Alcune camere o configurazioni richiedono strategie diverse, e i flat hanno esigenze proprie. Per questo non si deve imporre una ricetta unica basata solo sui nomi dei file. Il programma di calibrazione e la documentazione del dispositivo vanno letti come parti dello stesso flusso operativo."]}, {"title": "La parola ha significati più ampi", "paragraphs": ["In elettronica e nella misura bias può indicare polarizzazione o scostamento; in altri contesti descrive un errore sistematico o una distorsione del giudizio. La voce qui riguarda specificamente i dati di camera. Nel diario tecnico registra impostazioni, condizioni e procedura usata. Un diagramma didattico può mostrare un livello aggiunto e la sua sottrazione ideale, ma deve distinguere quel caso costruito dal comportamento reale di tutti i pixel e da tutti i difetti dell’immagine."]}], "facts": ["Il bias è un riferimento strumentale", "Correggere il livello non elimina ogni componente casuale"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/vocabolario/ricerca/bias/"}]}, {"id": "big-bang", "name": "Big Bang", "definition": "Il modello del Big Bang descrive l’evoluzione dell’Universo da una fase molto calda e densa, seguita da espansione e raffreddamento.", "example": "Espansione cosmica ≠ esplosione da un centro nel cielo", "source": "https://www.treccani.it/enciclopedia/big-bang/", "lesson": "lezione-6-5.html", "related": ["universo", "redshift", "radiazione"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Una storia ricostruita, non un’esplosione nel cielo", "paragraphs": ["Il nome può far immaginare una bomba che disperde frammenti in uno spazio già vuoto. Questa immagine è fuorviante. Il modello cosmologico descrive l’evoluzione dello spazio e del suo contenuto; non individua una direzione del cielo da cui sarebbe partito tutto. Guardando galassie lontane non osserviamo schegge lanciate da un centro locale, né la Via Lattea occupa un punto privilegiato dell’espansione generale."]}, {"title": "Le tracce che devono concordare", "paragraphs": ["Espansione cosmica, radiazione cosmica di fondo e abbondanze degli elementi leggeri forniscono informazioni differenti che vengono confrontate nello stesso quadro fisico. Una teoria non è sostenuta soltanto da una figura suggestiva o dal colore rosso di una galassia. Anche la ricostruzione della formazione delle strutture deve accordarsi con i dati. Il valore del modello sta nella capacità di collegare osservazioni indipendenti, non nel raccontare una scena che nessuno ha fotografato dall’esterno."]}, {"title": "Un limite da dichiarare", "paragraphs": ["Risalire a condizioni sempre più antiche porta verso energie e densità per cui le conoscenze sono meno complete. Descrivere bene molte fasi dell’evoluzione non equivale a possedere una risposta verificata su un eventuale prima o sull’origine ultima di tutto. L’estrapolazione matematica a una singolarità non è una fotografia di un oggetto infinitamente denso. Distinguere risultati osservativi, modelli e questioni aperte rende la spiegazione più solida, senza svuotarla di meraviglia."]}, {"title": "Come leggere un’illustrazione cosmologica", "paragraphs": ["Una sequenza dal plasma alle galassie rappresenta tempi differenti, non una strada nello spazio che potremmo percorrere in quella forma. Le dimensioni dei disegni e la durata delle tappe sono spesso compresse. La radiazione di fondo non è una parete materiale al bordo dell’Universo: è luce antica osservabile in molte direzioni. Prima di interpretare un diagramma chiediti quindi se l’asse descrive tempo, distanza o una combinazione illustrativa delle due grandezze."]}], "facts": ["Espansione cosmica ≠ esplosione da un centro nel cielo", "Le prove e i limiti del modello vanno distinti"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/big-bang/"}, {"title": "NASA · quadro cosmologico", "url": "https://science.nasa.gov/universe/the-big-bang/"}]}, {"id": "bilanciamento", "name": "Bilanciamento", "definition": "Il bilanciamento distribuisce il carico rispetto agli assi della montatura per limitarne gli squilibri, secondo le indicazioni previste per quel sistema.", "example": "Peso e braccio della leva contribuiscono allo squilibrio", "source": "https://www.treccani.it/vocabolario/ricerca/bilanciamento/", "lesson": "strumentazione.html", "related": ["baricentro", "montatura-equatoriale", "autoguida"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il peso conta insieme alla distanza", "paragraphs": ["Una camera leggera posta lontano da un asse può produrre uno squilibrio significativo. Non basta sommare i chilogrammi dei componenti: conta anche dove si trovano. Il concetto è quello della leva. Spostare un contrappeso lungo la sua barra cambia l’effetto senza modificarne la massa. Nel montaggio reale intervengono però geometria, accessori e limiti meccanici, quindi un disegno con due pesi uguali non descrive ogni configurazione."]}, {"title": "Non è la stessa cosa che mettere in bolla", "paragraphs": ["La messa in bolla riguarda il riferimento del supporto; il bilanciamento riguarda i carichi sugli assi; l’allineamento polare riguarda la direzione dell’asse equatoriale. Queste operazioni possono far parte della preparazione, ma non sono sinonimi né si sostituiscono a vicenda. Un telescopio può stare su un supporto orizzontale ed essere sbilanciato; può essere bilanciato e avere l’asse polare orientato nella direzione sbagliata."]}, {"title": "La configurazione completa è quella che userai", "paragraphs": ["Oculare, diagonale, camera, cercatore e cavi possono spostare il baricentro. Preparare un assetto senza gli accessori effettivi e aggiungerli dopo può cambiare il risultato. Le operazioni pratiche devono seguire il manuale, mantenendo il carico sostenuto quando si agisce su frizioni o bloccaggi. Non è prudente dedurre da una simulazione che si possa lasciare libero un tubo pesante mentre si cerca il punto di equilibrio."]}, {"title": "Un principio da adattare, non una ricetta universale", "paragraphs": ["Alcuni sistemi richiedono procedure specifiche e non tutti impiegano contrappesi tradizionali. La capacità dichiarata non significa che ogni carico entro quel numero abbia lo stesso comportamento fotografico: lunghezza, vento e disposizione degli accessori influiscono. Il bilanciamento può favorire un funzionamento regolare, ma non corregge giochi, cedimenti o errori d’inseguimento da solo. Nel diario tecnico annota l’assetto completo e verifica il risultato nelle osservazioni, senza inseguire una presunta regola identica per tutte le montature."]}], "facts": ["Peso e braccio della leva contribuiscono allo squilibrio", "Bilanciamento ≠ messa in bolla ≠ allineamento polare"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/vocabolario/ricerca/bilanciamento/"}]}, {"id": "binaria-a-eclisse", "name": "Binaria a eclisse", "definition": "Una binaria a eclisse è un sistema di due stelle la cui geometria consente occultazioni reciproche apparenti, producendo variazioni periodiche della luce ricevuta.", "example": "Una variazione apparente può avere origine geometrica", "source": "https://www.treccani.it/enciclopedia/binario_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-4-1.html", "related": ["stella", "baricentro", "fotometria"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Due stelle, un segnale che diminuisce", "paragraphs": ["Le due componenti orbitano attorno al loro centro di massa. Se il piano orbitale è orientato favorevolmente rispetto alla linea di vista, una può passare davanti all’altra. La luce totale che riceviamo diminuisce perché una parte della superficie luminosa viene nascosta. Non significa necessariamente che la stella si spenga o riduca la propria produzione energetica: la variazione può essere soprattutto una conseguenza della geometria del sistema."]}, {"title": "Una curva racconta più di un’immagine", "paragraphs": ["Misurando il flusso nel tempo si ottiene una curva di luce. Possono comparire due minimi differenti lungo un ciclo, secondo le proprietà delle componenti e la geometria. Profondità e durata contengono informazioni, ma non vanno interpretate isolatamente come un’unica misura diretta della massa. Le curve reali possono includere altri effetti. Nel laboratorio una diminuzione schematica serve a introdurre l’occultazione, non a rappresentare ogni dettaglio di una binaria osservata."]}, {"title": "Le categorie possono sovrapporsi", "paragraphs": ["Una binaria a eclisse può anche essere studiata attraverso variazioni delle righe spettrali. A eclisse, spettroscopica e visuale descrivono modi di riconoscere o osservare il sistema, non sempre famiglie fisiche incompatibili. Un puzzle di nomenclatura deve quindi evitare di costringere la stessa sorgente in una sola categoria assoluta. Prima di scegliere l’etichetta chiediti quale dato viene mostrato: due immagini separate, una curva di luce oppure uno spettro variabile."]}, {"title": "Che cosa possiamo ricavare", "paragraphs": ["Combinare fotometria, spettroscopia e modello orbitale consente di vincolare proprietà come dimensioni, masse e orientamento, con limiti e incertezze. Il risultato non deriva da una semplice somiglianza fra un disegno e una fotografia. La periodicità richiede osservazioni ripetute e confronti affidabili. Anche un calo di luce di una sorgente sconosciuta può avere altre cause: l’eclisse è un’interpretazione da verificare, non un nome da assegnare automaticamente a qualunque segnale che scende e risale."]}], "facts": ["Una variazione apparente può avere origine geometrica", "Le classificazioni osservative delle binarie possono sovrapporsi"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/binario_(Dizionario-delle-Scienze-Fisiche)/"}, {"title": "OpenStax · masse e sistemi binari", "url": "https://openstax.org/books/astronomy-2e/pages/18-2-measuring-stellar-masses"}], "aliases": ["binarie a eclisse", "binaria ad eclisse", "binarie ad eclisse"]}, {"id": "binaria-astrometrica", "name": "Binaria astrometrica", "definition": "Una binaria astrometrica è studiata attraverso il movimento apparente di una componente o del centro di luce che segnala l’influenza orbitale di una compagna.", "example": "Centro di luce e centro di massa possono differire", "source": "https://www.treccani.it/enciclopedia/binario_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-4-1.html", "related": ["astrometria", "parallasse", "baricentro"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Una traccia nella posizione", "paragraphs": ["Misure precise e ripetute possono mostrare che la posizione di una sorgente non segue soltanto l’andamento previsto da moto proprio e parallasse. Una componente orbitale può essere un indizio della presenza di una compagna. Non occorre vedere due stelle separate nella stessa immagine. L’astrometria studia proprio posizioni e movimenti angolari, ma ogni scarto deve essere valutato insieme alla qualità della misura e alle alternative possibili."]}, {"title": "Il punto luminoso non è sempre il centro di massa", "paragraphs": ["Se entrambe le stelle contribuiscono alla luce e non vengono risolte, il centro della distribuzione luminosa può comportarsi diversamente dal baricentro. Luminosità e massa non sono la stessa proprietà. Un modello che faccia coincidere sempre il punto più brillante con il centro di massa introduce un errore concettuale. La ricostruzione deve specificare quale posizione viene misurata e quale combinazione delle componenti produce il segnale osservato."]}, {"title": "Separare diversi movimenti", "paragraphs": ["La parallasse annuale, il moto proprio e un’orbita possono sovrapporsi nelle misure. Una linea ondulata disegnata sullo schermo non identifica da sola la causa. Serve una sequenza temporale sufficiente e un modello confrontato con i dati. L’animazione didattica può mostrare i contributi uno alla volta, poi combinarli, mantenendo le scale dichiarate. Il lettore vede così perché una fotografia singola non permette la stessa analisi di un insieme di misure ripetute."]}, {"title": "Che cosa si può concludere", "paragraphs": ["Il segnale astrometrico può fornire vincoli sull’orbita e, con informazioni aggiuntive, sulle proprietà del sistema. Non rivela automaticamente la natura della compagna senza considerare altri dati. Spettroscopia e fotometria possono completare l’interpretazione. Nel laboratorio associa quindi l’etichetta al tipo di misura mostrato e conserva una fase di verifica: riconoscere un metodo non significa avere già dimostrato ogni dettaglio fisico della sorgente che il metodo permette di studiare."]}], "facts": ["Centro di luce e centro di massa possono differire", "Parallasse, moto proprio e orbita vanno separati"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/binario_(Dizionario-delle-Scienze-Fisiche)/"}, {"title": "ESA/Gaia · identificazione astrometrica delle binarie", "url": "https://www.esa.int/ESA_Multimedia/Videos/2022/06/How_Gaia_detects_binary_stars/(lang)"}], "aliases": ["binarie astrometriche"]}, {"id": "binaria-spettroscopica", "name": "Binaria spettroscopica", "definition": "Una binaria spettroscopica viene riconosciuta o studiata attraverso variazioni delle righe spettrali associate al moto orbitale delle componenti.", "example": "La spettroscopia può rivelare una coppia non risolta", "source": "https://www.treccani.it/enciclopedia/binario_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-4-3.html", "related": ["effetto-doppler", "velocita-radiale", "binaria-visuale"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Due stelle possono apparire come un solo punto", "paragraphs": ["La separazione angolare può essere troppo piccola per risolvere le componenti nella fotografia disponibile. Lo spettro conserva però informazioni sul loro moto relativo. Variazioni periodiche delle posizioni delle righe possono indicare la presenza di un sistema orbitale. Non bisogna quindi disegnare due grandi dischi separati e presentarli come la fotografia effettiva della misura: il disegno ricostruisce un’interpretazione che nasce da dati differenti."]}, {"title": "Una o due serie di righe", "paragraphs": ["A seconda di luminosità, spettro e qualità dei dati, si possono riconoscere le righe di entrambe le componenti oppure soprattutto quelle di una. Il mancato riconoscimento della seconda serie non dimostra che la compagna sia un buco nero. Potrebbe semplicemente contribuire poco al segnale osservato o essere difficile da distinguere in quelle condizioni. L’identificazione fisica richiede più controlli di una singola immagine con due righe tracciate a mano."]}, {"title": "La geometria influisce sul segnale", "paragraphs": ["Quando una componente si avvicina e poi si allontana lungo la linea di vista, la sua velocità radiale cambia. L’ampiezza osservata dipende anche dall’inclinazione dell’orbita. Un sistema guardato quasi lungo l’asse non fornisce lo stesso andamento di uno visto quasi di taglio. Per ricavare masse e dimensioni occorre distinguere ciò che viene misurato direttamente dalle informazioni che richiedono altre osservazioni o ipotesi sul sistema."]}, {"title": "Un laboratorio che mostra i dati giusti", "paragraphs": ["Accanto alle stelle schematiche fai muovere le stesse caratteristiche spettrali in modo coerente con le frecce di velocità radiale. Non cambiare arbitrariamente il numero delle righe per ottenere un effetto più vistoso. La curva deve dichiarare tempo e velocità, con un riferimento del sistema. Se compaiono anche eclissi, spiega che aggiungono informazione geometrica: la categoria spettroscopica non esclude quella a eclisse, ma descrive un altro modo di osservare la stessa coppia."]}], "facts": ["La spettroscopia può rivelare una coppia non risolta", "Una compagna poco visibile non è automaticamente un buco nero"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/binario_(Dizionario-delle-Scienze-Fisiche)/"}, {"title": "ESA/Gaia · diversi metodi di riconoscimento", "url": "https://www.esa.int/ESA_Multimedia/Videos/2022/06/How_Gaia_detects_binary_stars/(lang)"}], "aliases": ["binarie spettroscopiche"]}, {"id": "binaria-visuale", "name": "Binaria visuale", "definition": "Una binaria visuale è un sistema stellare fisicamente legato nel quale le componenti possono essere risolte come sorgenti separate con osservazioni adatte.", "example": "Doppia apparente non significa automaticamente binaria fisica", "source": "https://www.treccani.it/enciclopedia/binario_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-4-1.html", "related": ["stella", "baricentro", "binaria-astrometrica"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Vedere due stelle e riconoscere un sistema", "paragraphs": ["Un telescopio può separare due punti luminosi vicini. Questo è il primo dato osservativo, ma non dimostra automaticamente un legame gravitazionale: una doppia apparente può essere un allineamento di sorgenti a distanze differenti. La parola binaria aggiunge il significato fisico di sistema. Il laboratorio deve quindi distinguere la semplice vicinanza sulla fotografia dalla ricostruzione del moto e delle proprietà che permette di attribuire le stelle allo stesso sistema."]}, {"title": "La separazione cambia con la prospettiva", "paragraphs": ["L’orbita osservata è una proiezione sul piano del cielo. Un’ellisse apparente non si legge come se la guardassimo sempre perpendicolarmente dall’alto. Anche la distanza del sistema influisce sulla separazione angolare. Una coppia fisicamente ampia ma molto lontana può risultare difficile da risolvere. Per questo l’immagine deve indicare se mostra dimensioni apparenti oppure una ricostruzione spaziale, senza passare dall’una all’altra mantenendo gli stessi numeri come se fossero equivalenti."]}, {"title": "L’osservazione può richiedere pazienza", "paragraphs": ["Seguire il moto orbitale può richiedere intervalli lunghi rispetto a una singola serata. Le posizioni ripetute permettono di studiare il sistema con un contesto più ricco di una fotografia isolata. Una simulazione può accelerare il movimento, ma non deve far credere che ogni coppia ruoti visibilmente durante pochi minuti all’oculare. Il cambiamento di dettaglio dovuto al seeing non è un rapido moto orbitale delle componenti."]}, {"title": "L’utilità del sistema binario", "paragraphs": ["Moto, dimensione orbitale e distanza, con un modello adeguato, forniscono informazioni sulle masse. Non serve collocare una stella immobile al centro per spiegare il principio: entrambe partecipano al moto attorno al centro di massa. La stessa coppia può offrire anche dati spettroscopici o fotometrici. Le etichette osservative non devono quindi diventare scatole incompatibili: visuale descrive la possibilità di separare le sorgenti, non tutto ciò che possiamo conoscere del sistema."]}], "facts": ["Doppia apparente non significa automaticamente binaria fisica", "La traiettoria sul cielo è una proiezione dell’orbita"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/binario_(Dizionario-delle-Scienze-Fisiche)/"}], "aliases": ["binarie visuali"]}, {"id": "binning", "name": "Binning", "definition": "Il binning combina misure di pixel vicini in elementi più grandi, riducendo il numero di campioni dell’immagine; il modo in cui avviene dipende da camera e software.", "example": "Binning 2×2: quattro campioni diventano un elemento", "source": "https://www.treccani.it/enciclopedia/campionamento/", "lesson": "astrofotografia.html", "related": ["pixel", "ccd", "cmos"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Raggruppare la griglia", "paragraphs": ["In un binning due per due si combinano gruppi di quattro pixel disposti in due righe e due colonne. Un’immagine di quattromila per tremila campioni diventa, in questo semplice esempio, di duemila per millecinquecento elementi. Non cambia il campo ottico già inquadrato: cambia la griglia che lo descrive. La dimensione angolare rappresentata da ciascun elemento cresce e alcuni dettagli fini possono non essere più separabili nella rappresentazione risultante."]}, {"title": "Non tutte le combinazioni sono uguali", "paragraphs": ["Si possono sommare cariche prima della lettura in alcune architetture oppure combinare valori dopo altri passaggi della catena elettronica o nel software. Somma e media producono anche scale numeriche differenti. Per questo una voce binning nel menu non dimostra da sola un certo miglioramento del rumore. Il manuale del modello e della modalità usata è il riferimento corretto, evitando regole assolute ricavate soltanto dalla sigla CCD o CMOS."]}, {"title": "Segnale e rumore richiedono un confronto coerente", "paragraphs": ["Raggruppare misure può rendere più evidente un segnale su una scala maggiore, ma riduce il dettaglio spaziale e non raccoglie fotoni che non siano già arrivati durante la posa. Il confronto deve mantenere chiari scala, area e passaggi di lettura. Non è corretto giudicare il beneficio guardando due immagini visualizzate con ingrandimenti o contrasti diversi senza dirlo. Anche saturazione e informazione cromatica richiedono attenzione secondo l’architettura del sensore."]}, {"title": "Quando il concetto è utile", "paragraphs": ["Il binning può avere impieghi nella lettura di una camera, nella guida, nella preparazione di un’immagine o nell’analisi di dati. Non va confuso con il ritaglio del sensore o con un aumento della focale. Nel laboratorio mostra prima la griglia originale e poi i gruppi combinati, con la stessa scena sottostante. Il lettore deve vedere quale informazione spaziale viene accorpata, invece di ricevere la promessa generica che un pulsante renda ogni fotografia più sensibile e più dettagliata insieme."]}], "facts": ["Binning 2×2: quattro campioni diventano un elemento", "Il comportamento dipende dal punto della catena in cui avviene"], "sources": [{"title": "Treccani · fondamento terminologico; applicazione alle immagini astronomiche spiegata nel testo", "url": "https://www.treccani.it/enciclopedia/campionamento/"}, {"title": "Oxford Instruments/Andor · binning e architetture di camera", "url": "https://andor.oxinst.com/learning/view/article/binning-in-the-neo-and-zl41-wave-scmos-cameras"}]}, {"id": "binocolo", "name": "Binocolo", "definition": "Un binocolo usa due canali ottici accoppiati per osservare con entrambi gli occhi immagini ingrandite e raddrizzate.", "example": "10×50: dieci ingrandimenti, obiettivi da 50 mm", "source": "https://www.treccani.it/enciclopedia/binocolo/", "lesson": "lezione-7-2.html", "related": ["obiettivo", "oculare", "ingrandimento"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Due occhi, un campo da esplorare", "paragraphs": ["Il binocolo offre un passaggio naturale fra sguardo libero e telescopio. Due sistemi ottici lavorano insieme e devono presentare immagini correttamente allineate. Prismi o altri elementi raddrizzano il campo e influenzano l’ingombro. L’impressione comoda della visione binoculare non significa però che le distanze tridimensionali delle stelle diventino percepibili come quelle di oggetti vicini: il cielo resta una distribuzione di direzioni lontane."]}, {"title": "Leggere due numeri", "paragraphs": ["In una sigla come 10×50, il primo numero indica l’ingrandimento e il secondo il diametro nominale degli obiettivi in millimetri. Dieci non è una lunghezza focale e cinquanta non è il campo in gradi. La pupilla d’uscita geometrica si ottiene dividendo 50 per 10: circa 5 mm. L’effettiva esperienza dipende anche dalla pupilla dell’occhio, dalle condizioni luminose e dalle proprietà reali dello strumento."]}, {"title": "Regolazioni prima del cielo", "paragraphs": ["Si regola la distanza fra i canali per adattarla agli occhi e si mette a fuoco, usando la compensazione diottrica secondo il progetto del modello. Immagini doppie persistenti possono indicare un problema di allineamento e non vanno accettate come normale ingrandimento. Anche la postura conta: appoggiare le braccia o usare un supporto appropriato può ridurre tremori che nascondono stelle deboli o piccoli dettagli."]}, {"title": "Il supporto è parte dell’osservazione", "paragraphs": ["Un cavalletto richiede un adattatore compatibile e una testa che permetta movimenti comodi. Non si serrano le lenti contro un sostegno e non si assume che ogni binocolo abbia lo stesso attacco. Per guardare alto, una soluzione inadatta può rendere scomoda la posizione del collo. La scelta coinvolge quindi apertura, peso, campo e ergonomia. Per il Sole si applicano protezioni specifiche davanti a entrambe le aperture: l’uso ordinario non è sicuro."]}], "facts": ["10×50: dieci ingrandimenti, obiettivi da 50 mm", "Pupilla d’uscita geometrica: 50 / 10 = 5 mm"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/binocolo/"}], "aliases": ["binocoli"]}, {"id": "binocolo-tetto", "name": "Binocolo a prismi a tetto", "definition": "Un binocolo a prismi a tetto impiega sistemi prismatici con superfici disposte secondo una geometria detta a tetto, spesso in una struttura esterna più allineata e compatta.", "example": "Il nome riguarda la geometria dei prismi", "source": "https://www.treccani.it/enciclopedia/binocolo/", "lesson": "lezione-7-2.html", "related": ["binocolo", "binocolo-porro", "catadiottrico"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il tetto è una geometria ottica", "paragraphs": ["Il nome non indica una copertura aggiunta sopra il binocolo. Descrive una disposizione di superfici del prisma che contribuisce al percorso e al raddrizzamento dell’immagine. Esistono schemi diversi nella stessa famiglia. Molti strumenti hanno obiettivi e oculari più allineati rispetto alla sagoma classica di un Porro, ma la sola fotografia esterna non basta a ricostruire ogni riflessione e ogni trattamento del sistema."]}, {"title": "La compattezza non è una misura di qualità", "paragraphs": ["Un involucro sottile può essere comodo nel trasporto e nell’uso, ma non garantisce automaticamente una trasmissione o una risoluzione superiore. Precisione delle superfici, trattamenti e progetto complessivo influiscono sul risultato. Anche le esigenze di correzione proprie di alcuni sistemi a tetto devono essere affrontate dal costruttore. Non è utile stabilire una gerarchia assoluta fra tetto e Porro senza confrontare modelli, condizioni e compito osservativo."]}, {"title": "L’occhio deve poter lavorare comodamente", "paragraphs": ["Ingrandimento, diametro degli obiettivi, campo, estrazione pupillare e possibilità di regolazione contano per entrambi gli schemi. Un osservatore con occhiali può avere esigenze diverse da un altro, e una cerniera deve consentire la distanza interpupillare appropriata. Prima di giudicare la nitidezza verifica quindi che la regolazione sia corretta. Il tipo dei prismi non sostituisce la prova di comfort e non elimina il bisogno di un supporto quando il movimento delle mani disturba l’immagine."]}, {"title": "Una figura esplorabile utile", "paragraphs": ["Nella fotografia selezionabile distingui ciò che è realmente visibile da ciò che viene ricostruito in sezione. Obiettivi, oculari e comando di fuoco possono essere indicati sul corpo; il percorso interno richiede invece uno schema coerente e dichiarato. Non si devono collocare prismi immaginari dove rimane spazio nel disegno. Per accessori e attacco al treppiede segui il modello specifico: due sagome simili possono avere interfacce differenti e non accettare lo stesso adattatore."]}], "facts": ["Il nome riguarda la geometria dei prismi", "Compattezza e qualità ottica sono proprietà differenti"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/binocolo/"}, {"title": "ZEISS · confronto dei sistemi prismatici", "url": "https://blogs.zeiss.com/sports-optics/hunting/en/about-binoculars/"}], "aliases": ["binocoli a prismi a tetto"]}, {"id": "binocolo-porro", "name": "Binocolo a prismi di Porro", "definition": "Un binocolo a prismi di Porro usa una disposizione di prismi per raddrizzare l’immagine e ripiegare il percorso ottico, spesso con obiettivi e oculari lateralmente sfalsati.", "example": "Porro descrive il sistema prismatico", "source": "https://www.treccani.it/enciclopedia/cannocchiale-e-binocolo_(Enciclopedia-dei-ragazzi)/", "lesson": "lezione-7-2.html", "related": ["binocolo", "binocolo-tetto", "riflessione"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Riconoscere il percorso, non soltanto la sagoma", "paragraphs": ["L’obiettivo forma l’immagine e il sistema prismatico ne modifica orientamento e percorso prima dell’oculare. Nelle configurazioni più riconoscibili, gli assi degli obiettivi e quelli degli oculari risultano sfalsati. Esistono però varianti, quindi la forma esterna è un indizio e non una descrizione completa dell’ottica interna. Una sezione didattica deve mostrare riflessioni coerenti, invece di collegare due lenti con un tubo decorativo che non spiega come arriva la luce."]}, {"title": "I numeri stampati hanno un altro significato", "paragraphs": ["Una scritta come dieci per cinquanta indica dieci ingrandimenti e obiettivi di cinquanta millimetri, non il numero o il tipo dei prismi. La configurazione Porro non determina da sola campo reale, qualità del bordo o comfort. Due strumenti con gli stessi numeri possono avere prestazioni differenti per progetto, trattamenti e costruzione. Il glossario serve a distinguere queste proprietà, senza trasformare una categoria ottica in una garanzia commerciale."]}, {"title": "L’uso astronomico richiede stabilità", "paragraphs": ["La facilità di orientamento e l’ampiezza del campo possono rendere il binocolo un ottimo primo strumento. La tremolazione delle mani può però nascondere dettagli che l’ottica sarebbe in grado di mostrare. Un supporto adeguato o un appoggio stabile aiuta, rispettando attacchi e portata. L’adattatore non deve essere rappresentato avvitato a una lente: deve collegarsi all’interfaccia prevista, mentre i due percorsi ottici rimangono liberi e correttamente orientati."]}, {"title": "Che cosa valutare nella prova", "paragraphs": ["Regola distanza interpupillare e fuoco secondo le istruzioni, poi confronta una regione riconoscibile del cielo. Doppie immagini persistenti non si risolvono forzando l’osservazione e non autorizzano regolazioni interne improvvisate. Nel diario annota ingrandimenti, supporto e condizioni, non soltanto il nome dello schema. Le fotografie esplorabili dovrebbero identificare obiettivi, oculari, cerniera e comando di fuoco nel punto in cui compaiono davvero, con etichette che non nascondano le parti osservate."]}], "facts": ["Porro descrive il sistema prismatico", "La sigla 10×50 descrive ingrandimenti e diametro degli obiettivi"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/cannocchiale-e-binocolo_(Enciclopedia-dei-ragazzi)/"}, {"title": "Fondazione Scienza e Tecnica · esempio e geometria del sistema Porro", "url": "https://www.fstfirenze.it/binocolo-da-campo/"}], "aliases": ["binocoli a prismi di Porro"]}, {"id": "bolide", "name": "Bolide", "definition": "Un bolide è una meteora particolarmente vistosa; l’uso del termine e le soglie adottate possono variare fra contesti osservativi.", "example": "Bolide non significa automaticamente meteorite al suolo", "source": "https://www.treccani.it/enciclopedia/bolide/", "lesson": "lezione-8-1.html", "related": ["meteora", "meteoroide", "meteorite"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Una meteora che attira l’attenzione", "paragraphs": ["Una scia molto brillante può illuminare il paesaggio, mostrare variazioni rapide o frammentarsi. Nel linguaggio osservativo viene spesso chiamata bolide. Il termine non prova che il corpo iniziale fosse un grande asteroide, né certifica un impatto al suolo. Treccani lo collega ai fenomeni meteorici vistosi; per un rapporto scientifico conviene aggiungere durata, luminosità stimata e caratteristiche invece di affidarsi alla sola etichetta."]}, {"title": "Luce, suono e tempi diversi", "paragraphs": ["Un evento può essere accompagnato da rumori, ma la luce e le onde acustiche raggiungono l’osservatore con tempi differenti. Un suono registrato nello stesso filmato non va associato automaticamente senza controlli di distanza e temporizzazione. Anche saturazione del sensore, riflessi e compressione video possono alterare l’impressione di colore o dimensione. La grandezza apparente della macchia luminosa non misura direttamente il diametro del meteoroide."]}, {"title": "La traccia non è il campione", "paragraphs": ["Una scia persistente può restare visibile dopo il passaggio luminoso. Non è un corpo che continua a volare acceso nello stesso punto. Se materiale sopravvive e raggiunge il suolo, si parla di meteoriti, ma molte osservazioni non permettono di stabilirlo. Per ricostruire una traiettoria servono osservazioni coordinate e strumenti di misura. Indicare una direzione a occhio non identifica da sola una zona di caduta precisa."]}, {"title": "Come rendere utile una segnalazione", "paragraphs": ["Conserva l’originale del filmato, annota luogo, data completa, ora con fuso e direzione. Se non conosci l’orientamento, usa riferimenti riconoscibili del paesaggio e dichiaralo. Non aggiungere una ricostruzione grafica presentandola come registrazione diretta. La distinzione fra osservato e interpretato rende la testimonianza più preziosa e permette a chi studia questi eventi di confrontarla con altri dati, senza dover prima separare dettagli inventati da quelli realmente visti."]}], "facts": ["Bolide non significa automaticamente meteorite al suolo", "Luminosità apparente ≠ diametro fisico del corpo"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/bolide/"}]}, {"id": "brillamento-solare", "name": "Brillamento solare", "definition": "Un brillamento solare è una rapida liberazione di energia nell’atmosfera del Sole che produce un aumento dell’emissione elettromagnetica.", "example": "Brillamento ≠ espulsione di massa coronale", "source": "https://www.treccani.it/enciclopedia/brillamento-solare/", "lesson": "lezione-2-3.html", "related": ["attivita-solare", "vento-solare", "spettro"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un cambiamento rapido in una regione attiva", "paragraphs": ["Il Sole emette continuamente energia, ma alcune regioni possono mostrare aumenti rapidi e intensi dell’emissione. I brillamenti sono collegati al rilascio di energia magnetica. Non vanno immaginati come combustione di ossigeno, né come normali fiamme terrestri ingrandite. La parola esplosione rende l’idea della rapidità, ma da sola non spiega i processi del plasma e del campo magnetico che alimentano il fenomeno."]}, {"title": "Non tutte le immagini mostrano lo stesso aspetto", "paragraphs": ["Un brillamento viene studiato in diverse bande dello spettro. Le immagini ultraviolette o nei raggi X possono evidenziare regioni che non appaiono nello stesso modo in luce visibile. I colori pubblicati sono spesso assegnati per rappresentare una banda non percepibile direttamente dall’occhio. Una didascalia deve indicarlo: l’immagine resta basata su osservazioni autentiche, ma non equivale alla vista che offrirebbe un telescopio visuale generico."]}, {"title": "La distinzione dalle espulsioni di massa", "paragraphs": ["Un’espulsione di massa coronale riguarda plasma e campo magnetico che si allontanano dal Sole. Un brillamento riguarda soprattutto un evento energetico riconosciuto attraverso la radiazione. I due fenomeni possono accompagnarsi, ma non ogni osservazione dell’uno dimostra automaticamente l’altro. Per gli effetti sulla Terra servono ulteriori informazioni sulla propagazione e sulla geometria. La notizia di un brillamento non costituisce da sola una previsione affidabile di aurore nel tuo luogo."]}, {"title": "Osservare il cambiamento con dati coerenti", "paragraphs": ["Per confrontare due immagini controlla orari, strumenti, bande e scale di visualizzazione. Un contrasto più forte dovuto all’elaborazione non dimostra una crescita fisica dell’evento. Le sequenze ufficiali permettono di seguirne l’evoluzione con un contesto migliore di un singolo fotogramma. Nell’attività divulgativa conviene usare questi archivi con provenienza chiara; il fenomeno non giustifica osservazioni solari improvvisate o l’impiego di filtri non specificamente adatti al sistema ottico utilizzato."]}], "facts": ["Brillamento ≠ espulsione di massa coronale", "Banda e orario sono essenziali per leggere la sequenza"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/brillamento-solare/"}, {"title": "INAF · spiegazione del fenomeno", "url": "https://sorvegliatispaziali.inaf.it/brillamento/"}]}, {"id": "brillanza-superficiale", "name": "Brillanza superficiale", "definition": "La brillanza superficiale descrive quanto segnale riceviamo per una certa area apparente di un oggetto esteso, nella banda considerata.", "example": "Magnitudine totale ≠ brillanza per area apparente", "source": "https://www.treccani.it/enciclopedia/brillanza/", "lesson": "lezione-5-1.html", "related": ["magnitudine-apparente", "fotometria", "galassia"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "La luce può essere molto diluita", "paragraphs": ["Una galassia può avere una magnitudine totale promettente e risultare difficile da vedere. La sua luce è distribuita su un’area del cielo, mentre quella di una stella non risolta appare concentrata in una piccola immagine. Immagina la stessa quantità di segnale distribuita su una macchia piccola o su una molto più grande: nel secondo caso ogni porzione deve emergere dal fondo con meno contrasto."]}, {"title": "Un’unità che richiede attenzione", "paragraphs": ["In astronomia ottica si usano spesso magnitudini per secondo d’arco quadrato. Il secondo d’arco misura un angolo; il suo quadrato identifica un’area apparente, non una superficie in metri sulla galassia. Come per le magnitudini, un numero minore indica una maggiore brillantezza nella stessa convenzione. Non confrontare direttamente una magnitudine totale con un valore per unità di area: descrivono quantità diverse, anche se condividono parte del nome."]}, {"title": "La media non descrive ogni dettaglio", "paragraphs": ["Una galassia può avere un nucleo relativamente evidente e un alone molto più tenue. Una brillanza media dipende anche dall’area o dal contorno scelto per la misura e può nascondere questa differenza. Nel catalogo leggi quindi se il valore riguarda il centro, una media o una specifica regione. Anche banda di misura e metodo contano: un numero isolato non basta per prevedere esattamente ciò che ogni osservatore riuscirà a distinguere."]}, {"title": "Il contrasto guida la serata", "paragraphs": ["Luce diffusa, trasparenza, altezza dell’oggetto, ingrandimento ed esperienza influenzano l’osservazione di sorgenti estese. Aumentare l’ingrandimento distribuisce l’immagine su un campo apparente maggiore e non crea luce aggiuntiva. Può rendere riconoscibili alcune forme, ma non è sempre vantaggioso. Nel diario descrivi quali parti hai visto e in quali condizioni. Un nucleo appena percepibile non autorizza a riportare tutti i bracci presenti in una fotografia a lunga esposizione."]}], "facts": ["Magnitudine totale ≠ brillanza per area apparente", "Una galassia non ha necessariamente brillanza uniforme"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/brillanza/"}, {"title": "NASA/IPAC NED · definizioni delle brillanze galattiche", "url": "https://ned.ipac.caltech.edu/level5/CATALOGS/sbog.html"}]}, {"id": "buco-nero", "name": "Buco nero", "definition": "Un buco nero è una regione dello spaziotempo delimitata da un orizzonte degli eventi, dal cui interno nessun segnale può raggiungere osservatori esterni lontani.", "example": "Modello non rotante: raggio ≈ 3 km per massa solare", "source": "https://www.treccani.it/enciclopedia/buco-nero/", "lesson": "lezione-10-3.html", "related": ["stella", "quasar", "gravitazione"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un confine fisico, non un aspirapolvere", "paragraphs": ["L’orizzonte degli eventi distingue una regione da cui non è possibile inviare segnali verso l’esterno. Non è una superficie solida e non è il bordo di una cavità scavata nello spazio. Un buco nero non esercita a grande distanza un’attrazione speciale superiore a quella di un altro corpo con la stessa massa. Sostituire idealmente il Sole con un oggetto compatto della medesima massa non farebbe precipitare immediatamente la Terra, anche se l’ambiente luminoso cambierebbe radicalmente."]}, {"title": "Massa e dimensione dell’orizzonte", "paragraphs": ["Per un buco nero non rotante e privo di carica, il raggio dell’orizzonte è circa 3 km per ogni massa solare. Dieci masse solari corrispondono quindi a circa 30 km di raggio e 60 km di diametro. È la dimensione del confine, non quella di un corpo solido. La proporzione descrive un modello specifico: la rotazione modifica la geometria e non va ignorata nelle descrizioni precise."]}, {"title": "Come ne ricostruiamo la presenza", "paragraphs": ["Si studiano moti di stelle, radiazione del materiale circostante e segnali gravitazionali prodotti da sistemi compatti. Le immagini ottenute con interferometria radio mostrano strutture luminose attorno a una regione scura, non luce proveniente dall’interno dell’orizzonte. La scala dell’ombra osservata non coincide semplicemente con il diametro geometrico dell’orizzonte. Occorre distinguere il dato ricostruito dal modello usato per interpretarlo."]}, {"title": "Che cosa resta aperto", "paragraphs": ["Le soluzioni classiche possono contenere una singolarità, ma descriverla come un punto fisico direttamente osservato di densità infinita supera ciò che misuriamo. Una teoria completa dell’interno richiede ancora sviluppi. Anche le cifre storiche nelle enciclopedie vanno confrontate con fonti aggiornate: questa scheda usa Treccani per il quadro terminologico e NASA per la descrizione fisica, senza trasferire le vecchie stime della massa del centro galattico presenti nella voce storica."]}], "facts": ["Modello non rotante: raggio ≈ 3 km per massa solare", "Orizzonte, ombra e materia luminosa non sono la stessa struttura"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/buco-nero/"}, {"title": "NASA · buchi neri", "url": "https://science.nasa.gov/universe/black-holes/"}], "aliases": ["buchi neri"]}, {"id": "calendario", "name": "Calendario", "definition": "Un calendario organizza i giorni e gli anni secondo regole civili o culturali, spesso costruite per mantenere un rapporto con cicli astronomici.", "example": "Il mese civile non è una lunazione", "source": "https://www.treccani.it/enciclopedia/anno/", "lesson": "lezione-2-1.html", "related": ["anno-tropico", "ora-civile", "effemeridi"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Organizzare il tempo non è misurare un solo moto", "paragraphs": ["Il giorno, il mese lunare e l’anno stagionale non contengono un numero intero l’uno dell’altro. Un calendario deve quindi scegliere quali cicli seguire e come gestire le frazioni. I mesi del calendario gregoriano non corrispondono tutti a una lunazione e il loro inizio non coincide regolarmente con la Luna nuova. La data civile è una convenzione utile alla vita comune, non il nome automatico di una fase lunare."]}, {"title": "Il bisestile mantiene un accordo approssimato", "paragraphs": ["Nel calendario gregoriano gli anni divisibili per quattro sono generalmente bisestili, ma gli anni secolari fanno eccezione salvo quelli divisibili per quattrocento. Così il 2000 è stato bisestile e il 2100 non lo sarà. Le regole cercano di contenere lo scarto con il ciclo stagionale. Non servono a modificare l’orbita terrestre e non rendono ogni anno civile identico all’intervallo astronomico fra due equinozi."]}, {"title": "La notte attraversa il confine della data", "paragraphs": ["Una serata che comincia alle ventidue e prosegue dopo mezzanotte occupa due date civili. Nel diario conviene indicare chiaramente il giorno di ciascuna misura o usare un intervallo di serata ben definito. Anche il passaggio fra ora solare e legale può produrre orari locali ambigui. Per dati da confrontare a distanza aggiungi il riferimento temporale richiesto: la data scritta sul telefono non descrive da sola tutto il contesto della misura."]}, {"title": "Una pagina mensile deve restare coerente", "paragraphs": ["Quando il sito cambia mese, titolo, calendario, eventi e fotografie d’archivio devono conservare una relazione corretta. Una bella immagine non dimostra che il fenomeno avvenga in quel giorno. Le regole automatiche del calendario possono organizzare la pagina, mentre gli eventi astronomici richiedono calcoli o fonti pertinenti. Separare le due operazioni evita di trasformare un aggiornamento del titolo in un presunto aggiornamento scientifico completo di tutte le informazioni."]}], "facts": ["Il mese civile non è una lunazione", "La notte può comprendere due date differenti"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/anno/"}]}, {"id": "calibrazione", "name": "Calibrazione", "definition": "La calibrazione collega una misura alla risposta dello strumento e ai riferimenti necessari per interpretarla; nelle immagini astronomiche comprende correzioni strumentali documentate.", "example": "Calibrazione ≠ abbellimento", "source": "https://www.treccani.it/enciclopedia/taratura/", "lesson": "astrofotografia.html", "related": ["sensore", "fotometria", "vignettatura"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Separare il soggetto dalla risposta dello strumento", "paragraphs": ["Una fotografia grezza contiene il segnale del cielo insieme a contributi e variazioni prodotti dal sistema di ripresa. La calibrazione cerca di riconoscere e correggere alcuni di questi effetti con misure appropriate. Non consiste nel rendere la figura più gradevole e non coincide con una regolazione arbitraria del contrasto. Lo scopo è conservare una relazione più affidabile tra ciò che è stato raccolto e l’informazione che vogliamo ricavare."]}, {"title": "Riferimenti con funzioni diverse", "paragraphs": ["Nella pratica fotografica si incontrano fotogrammi di bias, dark e flat. I primi caratterizzano un livello elettronico di riferimento, i dark contribuiscono a descrivere il comportamento in assenza di luce durante un’esposizione e i flat aiutano a trattare variazioni della risposta e dell’illuminazione del campo. Le procedure dipendono dalla camera e dal programma. Non è corretto sottrarre o dividere immagini qualsiasi soltanto perché hanno un aspetto simile ai file di riferimento."]}, {"title": "Le condizioni fanno parte della misura", "paragraphs": ["Temperatura, impostazioni elettroniche, tempo e configurazione ottica possono influire sull’utilità dei riferimenti. Un flat acquisito dopo aver cambiato posizione di un accessorio può non descrivere più lo stesso sistema. Anche una calibrazione inappropriata può introdurre difetti. Per questo conviene conservare gli originali e annotare come sono stati prodotti i riferimenti, invece di considerare l’elaborazione una sequenza di pulsanti valida sempre nello stesso modo."]}, {"title": "Dalla fotografia alla misura scientifica", "paragraphs": ["Correggere un’immagine non significa averla già trasformata in una misura fotometrica assoluta. Per quello servono ulteriori riferimenti, controlli e valutazione dell’incertezza. Il modello del laboratorio può mostrare un difetto sintetico noto e la sua correzione, ma deve dichiarare che il difetto è stato costruito appositamente. L’esempio rende comprensibile il principio senza promettere la rimozione perfetta di ogni errore o autorizzare a cancellare strutture del soggetto che sembrano insolite."]}], "facts": ["Calibrazione ≠ abbellimento", "I riferimenti devono descrivere la configurazione effettiva"], "sources": [{"title": "Treccani · fondamento terminologico; applicazione alle immagini astronomiche spiegata nel testo", "url": "https://www.treccani.it/enciclopedia/taratura/"}]}, {"id": "campionamento", "name": "Campionamento", "definition": "Nelle immagini astronomiche il campionamento descrive come il segnale viene rappresentato da misure discrete; la scala d’immagine indica quanto angolo corrisponde a ciascun pixel.", "example": "Scala d’immagine: angolo per pixel", "source": "https://www.treccani.it/enciclopedia/campionamento/", "lesson": "astrofotografia.html", "related": ["pixel", "focale", "diffrazione"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Dal cielo continuo alla griglia", "paragraphs": ["Una camera registra la distribuzione della luce attraverso elementi discreti. La scena astronomica non è però composta da quadratini: quella griglia appartiene alla misura. La dimensione fisica dei pixel, insieme alla focale, determina la scala angolare dell’immagine. Pixel più piccoli non significano automaticamente che il telescopio abbia raccolto dettagli più fini. Prima la luce viene modificata dall’atmosfera e dall’ottica, poi viene registrata dal sensore."]}, {"title": "Una stella occupa più di un punto ideale", "paragraphs": ["Diffrazione, turbolenza, fuoco e inseguimento contribuiscono alla forma dell’immagine stellare. Se quella forma viene descritta da troppo pochi pixel, alcuni dettagli della distribuzione si perdono o diventano ambigui. Se viene distribuita su molti pixel, la rappresentazione è più fitta ma non guadagna necessariamente nuova informazione fisica. Il compromesso dipende dal tipo di ripresa e dalle condizioni, quindi una regola numerica unica non sostituisce l’analisi del sistema."]}, {"title": "Un confronto semplice", "paragraphs": ["Se una certa separazione angolare corrisponde a due pixel in una configurazione e a quattro in un’altra, la seconda la descrive con una griglia più fitta. Ciò non dimostra da solo che le due sorgenti siano risolte: l’immagine ottica può essere ancora troppo larga per separarle. Allargare un file dopo la ripresa crea più caselle di visualizzazione, ma non equivale a raccogliere nuove misure indipendenti della stessa scena."]}, {"title": "Anche il tempo viene campionato", "paragraphs": ["Una sequenza planetaria o una curva di luce registra il fenomeno a intervalli. Se gli intervalli sono troppo distanti rispetto alla variazione cercata, possiamo perdere un passaggio o interpretarne male l’andamento. Per questo frequenza delle riprese, durata delle esposizioni e risoluzione spaziale vanno distinti. Nel laboratorio si può rallentare un processo per mostrarlo chiaramente, purché non si presenti la velocità dell’animazione come una misura reale del fenomeno osservato."]}], "facts": ["Scala d’immagine: angolo per pixel", "Ingrandire il file non crea automaticamente nuovo dettaglio"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/campionamento/"}]}, {"id": "campo-apparente", "name": "Campo apparente", "definition": "Il campo apparente di un oculare è l’ampiezza angolare sotto cui si presenta il suo campo visivo all’occhio, distinta dalla porzione reale di cielo inquadrata.", "example": "Campo apparente: la vista offerta dall’oculare", "source": "https://www.treccani.it/enciclopedia/oculare/", "lesson": "lezione-7-4.html", "related": ["oculare", "ingrandimento", "campo-reale"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "La finestra che percepisci all’occhio", "paragraphs": ["Guardando in due oculari puoi avere la sensazione di osservare attraverso un’apertura più stretta o più avvolgente. Il campo apparente descrive questa estensione angolare della vista fornita dall’oculare. Non dice da solo quanto cielo entra nell’inquadratura: bisogna conoscere anche l’ingrandimento del sistema. Una finestra apparentemente molto ampia può mostrare una piccola regione celeste se viene utilizzata a un ingrandimento elevato."]}, {"title": "Un esempio con gli stessi ingrandimenti", "paragraphs": ["A parità di ingrandimento, un oculare con campo apparente maggiore offre generalmente un campo reale più ampio. Questo può aiutare a riconoscere il contesto di un oggetto o a seguirlo con una montatura manuale. Non significa però che la parte centrale contenga automaticamente più dettaglio. L’ingrandimento, la risoluzione e la correzione dell’immagine ai bordi restano proprietà da distinguere, anche quando il risultato all’occhio sembra più spettacolare."]}, {"title": "La divisione utile, con il suo limite", "paragraphs": ["Come stima introduttiva si divide il campo apparente per il numero degli ingrandimenti. Un campo apparente di 60 gradi a 40 ingrandimenti suggerisce circa 1,5 gradi di cielo reale. La divisione aiuta a progettare un’inquadratura, ma è approssimata: distorsione e progetto ottico possono modificarne l’esattezza. Per un dato più affidabile si considerano il diaframma di campo e le specifiche dell’oculare, oppure si misura direttamente il campo."]}, {"title": "Il comfort non dipende da un solo numero", "paragraphs": ["Estrazione pupillare, posizione dell’occhio, uso degli occhiali e qualità del bordo influenzano l’esperienza. Un campo molto ampio non è necessariamente tutto comodo da esplorare per chiunque. Confronta gli oculari sullo stesso strumento e sullo stesso bersaglio, senza confondere l’effetto immersivo con una misura di sensibilità. Nel laboratorio il cerchio rappresenta una finestra di osservazione: non è una regione fisica delimitata fra le stelle e non si applica invariato a ogni configurazione."]}], "facts": ["Campo apparente: la vista offerta dall’oculare", "Campo reale: la regione di cielo inquadrata"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/oculare/"}, {"title": "AAVSO · manuale italiano, oculari e campi", "url": "https://www.aavso.org/sites/default/files/publications_files/manual/italian/ItalianManual.pdf"}], "aliases": ["campi apparenti"]}, {"id": "campo-reale", "name": "Campo reale", "definition": "Il campo reale è l’estensione angolare della porzione di cielo compresa nell’inquadratura di uno strumento in una certa configurazione.", "example": "Il campo si misura in angoli", "source": "https://www.treccani.it/enciclopedia/oculare/", "lesson": "lezione-7-4.html", "related": ["campo-apparente", "focale", "sensore"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Quanto cielo entra davvero", "paragraphs": ["Il campo reale permette di capire se un ammasso, una coppia di stelle o la Luna entra interamente nella vista. È una misura angolare, espressa per esempio in gradi o primi d’arco. Non è il diametro fisico della regione nello spazio: oggetti a distanze differenti possono occupare la stessa inquadratura. Un cerchio disegnato sulla carta confronta direzioni e separazioni apparenti, non racchiude tutti i soggetti dentro un’unica sfera materiale."]}, {"title": "Con l’oculare dipende dalla configurazione", "paragraphs": ["Campo dell’oculare e focale dello strumento concorrono all’inquadratura. Un aumento dell’ingrandimento tende a ridurre la regione visibile se il campo apparente resta uguale. La stima ottenuta dividendo campo apparente per ingrandimento è utile ma approssimata. Non trasferire il cerchio di un oculare a un altro soltanto perché hanno lo stesso diametro del barilotto: quella misura riguarda l’interfaccia meccanica e non descrive da sola la porzione di cielo accessibile."]}, {"title": "Con una camera conta la dimensione del sensore", "paragraphs": ["A parità di focale, un sensore fisicamente più grande inquadra generalmente più cielo. Il numero di megapixel da solo non basta: due sensori possono avere lo stesso numero di pixel e dimensioni diverse. Anche la forma del riquadro conta, perché larghezza, altezza e diagonale non sono lo stesso campo. Nel disegno va dichiarata la direzione a cui si riferisce un valore, evitando di rappresentare ogni camera con un cerchio generico."]}, {"title": "Riconoscere prima di ingrandire", "paragraphs": ["Una vista ampia facilita il confronto fra stelle guida e carta. Una più stretta può aiutare a studiare un dettaglio, ma rende meno evidente il contesto. Nel diario puoi disegnare un bordo e segnare poche stelle riconoscibili per documentare l’inquadratura effettiva. Nei modelli interattivi lo zoom deve rispettare la geometria: avvicinare la vista non deve spostare un oggetto a un’altra declinazione o alterare arbitrariamente le distanze angolari che si stanno insegnando."]}], "facts": ["Il campo si misura in angoli", "Megapixel e dimensione fisica del sensore sono dati differenti"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/oculare/"}], "aliases": ["campi reali"]}, {"id": "catadiottrico", "name": "Catadiottrico", "definition": "Un sistema ottico catadiottrico combina superfici riflettenti e rifrangenti nella formazione o nella correzione dell’immagine.", "example": "Catadiottrico descrive l’ottica, non la montatura", "source": "https://www.treccani.it/vocabolario/catadiottrico/", "lesson": "lezione-7-3.html", "related": ["riflettore", "rifrattore", "focale"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Specchi e lenti nello stesso progetto", "paragraphs": ["Un telescopio catadiottrico impiega una combinazione di elementi: la luce viene riflessa da specchi e attraversa superfici ottiche rifrangenti progettate per il sistema. Schmidt-Cassegrain e Maksutov-Cassegrain sono esempi noti, con configurazioni e correzioni diverse. Il termine non identifica una montatura. Lo stesso tubo può essere sostenuto da una forcella, da una montatura altazimutale o da una equatoriale, secondo il modello e gli adattamenti previsti."]}, {"title": "Un tubo corto può avere una focale lunga", "paragraphs": ["Il percorso della luce viene ripiegato all’interno del sistema. Per questo la lunghezza esterna del tubo non coincide con la focale equivalente. Non si deve disegnare il fascio come se attraversasse semplicemente il tubo in linea retta da un’estremità all’altra. Una sezione didattica deve mostrare superfici, riflessioni e uscita del fascio, dichiarando le dimensioni illustrative quando gli elementi sono ingranditi o distanziati per renderli leggibili."]}, {"title": "La forma esterna non racconta tutto", "paragraphs": ["Due tubi simili possono avere diametri, rapporti focali e prestazioni differenti. Per scegliere un impiego contano campo corretto, ostacoli nel fascio, comportamento termico, accessori e qualità di lavorazione. Un sistema compatto non è necessariamente leggero o pronto appena portato fuori da un ambiente caldo. Non basta quindi riconoscere una sagoma per dedurre il tempo di acclimatamento o la facilità di ogni tipo di fotografia."]}, {"title": "Che cosa riconoscere nell’esplorazione", "paragraphs": ["Nella fotografia annotata distingui tubo ottico, lastra o menisco anteriore quando presenti, gruppo posteriore, focheggiatore e attacco alla montatura. Le parti visibili dipendono dalla configurazione e alcune sono interne. Un’immagine generativa deve rispettare questo ordine senza aggiungere oculari o specchi in posizioni impossibili. Il modello spiega il principio; la procedura per montare accessori, collimare o smontare componenti deve invece seguire le istruzioni del costruttore per quello strumento."]}], "facts": ["Catadiottrico descrive l’ottica, non la montatura", "Lunghezza del tubo e focale equivalente non coincidono"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/vocabolario/catadiottrico/"}]}, {"id": "ccd", "name": "CCD", "definition": "Un CCD è un dispositivo a trasferimento di carica; nei sensori d’immagine raccoglie segnali elettrici prodotti dalla luce e li trasferisce per la lettura.", "example": "CCD: trasferimento di carica nella lettura", "source": "https://www.treccani.it/enciclopedia/ccd/", "lesson": "astrofotografia.html", "related": ["sensore", "pixel", "cmos"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "La luce diventa un segnale misurabile", "paragraphs": ["I fotoni assorbiti nel materiale sensibile possono generare cariche che vengono raccolte durante l’esposizione. Nel CCD il trasferimento ordinato di queste cariche è una caratteristica del processo di lettura. Il risultato viene poi convertito in valori digitali attraverso l’elettronica. Non si tratta di microscopiche fotografie già complete conservate in ogni pixel: ogni elemento contribuisce alla misura della distribuzione luminosa sul piano dell’immagine."]}, {"title": "La sigla non riassume tutte le prestazioni", "paragraphs": ["Dimensione dei pixel, efficienza, rumore di lettura, capacità di accumulo, raffreddamento e formato influenzano l’uso astronomico. Due camere CCD possono essere molto diverse e una buona misura richiede informazioni sul modello concreto. Anche la quantità di segnale registrata dipende dal soggetto e dall’intera catena ottica. Non è possibile giudicare un’immagine soltanto dalla tecnologia indicata nel nome, ignorando esposizione, fuoco, atmosfera e calibrazione."]}, {"title": "Il confronto con altre tecnologie", "paragraphs": ["I sensori CMOS impiegano architetture di lettura differenti. Questo non implica una gerarchia universale in cui ogni CCD supera ogni CMOS o viceversa. Per il lettore è più utile confrontare requisiti della ripresa e dati documentati del dispositivo. Un sistema adatto a lunghe integrazioni non è automaticamente la scelta migliore per una sequenza rapida; un’elevata frequenza di lettura non descrive da sola la qualità di ogni immagine raccolta."]}, {"title": "Come riconoscerlo nella storia e nella pratica", "paragraphs": ["I CCD hanno avuto un ruolo centrale nel passaggio da lastre e pellicole alla misura elettronica astronomica. Questo valore storico non giustifica però illustrare soltanto attrezzature datate nelle lezioni operative. Le fotografie devono identificare il dispositivo effettivo, senza dedurre la tecnologia da una semplice scatola cilindrica. Nel diario tecnico scrivi camera, impostazioni e condizioni: sono questi elementi a rendere confrontabili le riprese, oltre alla sigla generale del sensore."]}], "facts": ["CCD: trasferimento di carica nella lettura", "La tecnologia non sostituisce le specifiche del modello"], "sources": [{"title": "Treccani · fondamento terminologico; applicazione alle immagini astronomiche spiegata nel testo", "url": "https://www.treccani.it/enciclopedia/ccd/"}]}, {"id": "circumpolare", "name": "Circumpolare", "definition": "Detto di un astro che, da una determinata latitudine, non scende mai sotto l’orizzonte nel moto diurno.", "example": "La proprietà dipende dal luogo. Per una costellazione estesa va verificata stella per stella.", "source": "https://www.treccani.it/vocabolario/circumpolare/", "lesson": "lezione-1-3.html", "related": ["occiduo", "polo-celeste"], "checked": "2026-10-30", "sections": [{"title": "Una stella che non tramonta", "paragraphs": ["Un astro è circumpolare per un dato luogo quando il suo percorso diurno resta sopra l’orizzonte. La condizione non è una qualità assoluta della stella: dipende dalla latitudine dell’osservatore. Nell’emisfero nord la regione circumpolare circonda il Polo Nord celeste; nell’emisfero sud il riferimento è il Polo Sud celeste. La rotazione apparente segue i poli celesti, non un punto scelto liberamente sul disegno."]}, {"title": "Perché il luogo cambia la risposta", "paragraphs": ["Spostandoti verso il Polo Nord, il polo celeste sale sopra l’orizzonte e si amplia la regione di stelle che non tramontano. Avvicinandoti all’equatore la regione si restringe. Per capire il caso concreto confronta la distanza angolare della stella dal polo con l’altezza del polo sull’orizzonte. A 45° N una stella con declinazione +60° dista 30° dal polo: il suo cerchio resta interamente sopra l’orizzonte geometrico. Una con declinazione +20° ne dista 70° e quindi sorge e tramonta."]}, {"title": "Sopra l’orizzonte non significa visibile", "paragraphs": ["La stella può trovarsi sopra l’orizzonte durante il giorno, quando il chiarore impedisce di distinguerla. Possono nasconderla anche nuvole, foschia, edifici o montagne. Circumpolare è dunque una condizione geometrica, non una promessa di osservazione in qualunque momento. Anche di notte, al suo passaggio più basso una stella può attraversare strati atmosferici e ostacoli che rendono poco favorevole la ripresa."]}, {"title": "Una cautela sulle costellazioni", "paragraphs": ["Dire per comodità “costellazioni circumpolari” può essere utile per orientarsi, ma i confini e le figure occupano un’estensione. Da una certa latitudine alcune stelle del disegno potrebbero non soddisfare la stessa condizione. Nei laboratori AD ASTRA si deve quindi indicare il luogo e, quando serve precisione, classificare stelle o porzioni effettive della figura. Il caso limite di una traiettoria tangente all’orizzonte richiede di specificare la convenzione: non va trattato come una visibilità robusta per tutta la notte."]}], "facts": ["La circumpolarità dipende dalla latitudine", "A 45° N, δ +60° è un esempio circumpolare", "Ostacoli e luce diurna restano importanti"], "sources": [{"title": "Treccani · riferimento della voce", "url": "https://www.treccani.it/vocabolario/circumpolare/"}], "editorialStatus": "scheda-estesa"}, {"id": "cmos", "name": "CMOS", "definition": "CMOS indica una tecnologia elettronica; nei sensori fotografici è associata ad architetture di raccolta e lettura del segnale luminoso differenti da quelle dei CCD.", "example": "CMOS non indica da solo qualità, formato o colore", "source": "https://www.treccani.it/enciclopedia/cmos/", "lesson": "astrofotografia.html", "related": ["ccd", "sensore", "campionamento"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Una tecnologia, molte applicazioni", "paragraphs": ["La sigla nasce dall’elettronica e non indica soltanto camere astronomiche. Nei sensori d’immagine viene impiegata per realizzare sistemi che trasformano la luce in segnali leggibili mediante circuiti integrati. Il termine da solo non specifica formato, colore, raffreddamento o destinazione d’uso. Uno smartphone e una camera dedicata possono appartenere alla stessa grande famiglia tecnologica senza produrre dati equivalenti o offrire gli stessi controlli operativi."]}, {"title": "La lettura è parte del progetto", "paragraphs": ["Nei sensori CMOS l’elettronica di lettura è organizzata diversamente dal trasferimento di carica tipico dei CCD. Esistono però molte architetture e modalità operative, quindi le prestazioni non si deducono da una sola frase. Rumore, velocità, capacità dei pixel e comportamento alle varie impostazioni vanno valutati sul dispositivo effettivo. Aumentare un controllo chiamato gain non significa aumentare fisicamente la luce raccolta dall’obiettivo durante lo stesso intervallo di esposizione."]}, {"title": "Colore e monocromia sono un’altra distinzione", "paragraphs": ["Un sensore può registrare il colore attraverso filtri distribuiti sui pixel oppure essere monocromatico e lavorare con filtri esterni, secondo il sistema. Questa distinzione non coincide con CMOS contro CCD. Anche i megapixel non indicano da soli l’inquadratura o la risoluzione effettiva sul cielo: servono dimensioni fisiche, focale e qualità dell’immagine che raggiunge il sensore. Separare queste caratteristiche aiuta a leggere le schede senza trasformare ogni numero in una classifica."]}, {"title": "Una fotografia didattica deve identificare il modello", "paragraphs": ["Per mostrare l’attrezzatura contemporanea scegli immagini chiare e specifiche documentate, non fotografie anonime della forma esterna. Le impostazioni suggerite per una camera non si trasferiscono automaticamente a tutte le altre. Anche i riferimenti di calibrazione dipendono dal comportamento del sistema. Nel laboratorio si può illustrare la raccolta dei segnali su una griglia, dichiarando la semplificazione: non è una simulazione elettronica delle prestazioni reali di un prodotto commerciale."]}], "facts": ["CMOS non indica da solo qualità, formato o colore", "Gain elettronico e fotoni raccolti sono grandezze differenti"], "sources": [{"title": "Treccani · fondamento terminologico; applicazione alle immagini astronomiche spiegata nel testo", "url": "https://www.treccani.it/enciclopedia/cmos/"}]}, {"id": "collimazione", "name": "Collimazione", "definition": "Nell’uso dei telescopi la collimazione è la regolazione dell’allineamento degli elementi ottici e dei riferimenti del sistema.", "example": "Collimazione ≠ fuoco ≠ allineamento polare", "source": "https://www.treccani.it/vocabolario/collimazione/", "lesson": "lezione-7-3.html", "related": ["riflettore", "fuoco", "seeing"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Allineare prima di giudicare", "paragraphs": ["Uno specchio o un gruppo ottico di qualità non può lavorare bene se il sistema è disallineato. La collimazione cerca una disposizione coerente degli elementi e del percorso della luce. Non è la messa a fuoco e non è l’allineamento della montatura al polo celeste. Sono operazioni che agiscono su aspetti diversi, anche se tutte possono influenzare il risultato dell’osservazione."]}, {"title": "Il caso del riflettore Newton", "paragraphs": ["Nel Newton occorre considerare focheggiatore, secondario e primario secondo la procedura appropriata. Il secondario deve portare correttamente il fascio al focheggiatore e il primario deve essere orientato in modo coerente. Una figura didattica con tre specchi o un oculare nel posto sbagliato non aiuta a capire. Anche gli strumenti di controllo richiedono corretto posizionamento e calibrazione: un laser non elimina automaticamente tutti gli errori."]}, {"title": "I sintomi possono assomigliarsi", "paragraphs": ["Una stella deformata può dipendere da collimazione, seeing, fuoco o temperatura del tubo. È utile verificare in condizioni favorevoli e distinguere la forma persistente dai cambiamenti rapidi dovuti all’aria. Le procedure variano fra Newton, Schmidt-Cassegrain, rifrattori e altri sistemi. Non si devono trasferire istruzioni di regolazione da un modello all’altro, soprattutto quando alcune parti non sono previste per interventi dell’utilizzatore."]}, {"title": "Che cosa insegnare in un laboratorio", "paragraphs": ["Un esercizio introduttivo può mostrare asse ottico, percorso del fascio e ruolo degli elementi, chiedendo di riconoscere l’allineamento. Non deve fingere di certificare la collimazione reale del proprio telescopio attraverso tre clic. Per agire sullo strumento servono il manuale e una procedura adatta. Il valore divulgativo sta nel capire quale regolazione si sta facendo e perché, evitando di attribuire ogni problema a un’ottica scadente prima di controllare le condizioni di uso."]}], "facts": ["Collimazione ≠ fuoco ≠ allineamento polare", "Seguire la procedura del proprio schema ottico"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/vocabolario/collimazione/"}]}, {"id": "cometa", "name": "Cometa", "definition": "Corpo del Sistema solare che può sviluppare una chioma e code quando la sua attività libera gas e polveri.", "example": "Una cometa non è una meteora: il suo nucleo è un corpo nello spazio, non una scia prodotta nell’atmosfera.", "source": "https://www.treccani.it/enciclopedia/cometa/", "lesson": "lezione-3-5.html", "related": ["meteora", "pianeta"], "checked": "2026-10-30", "sections": [{"title": "Un piccolo corpo che può diventare visibile", "paragraphs": ["Una cometa è un piccolo corpo del Sistema solare contenente materiali volatili, polveri e componenti rocciose. Il nucleo è il corpo materiale; la grande figura luminosa che talvolta vediamo comprende invece materiale liberato nello spazio. Avvicinandosi al Sole, alcune sostanze passano in fase gassosa e trascinano polveri, formando una chioma. Non tutte le comete sviluppano una coda spettacolare e molte richiedono strumenti per essere osservate."]}, {"title": "La coda non è una scia dietro il viaggio", "paragraphs": ["Le polveri risentono della pressione della radiazione solare e proseguono su traiettorie che possono formare una coda curva. Il plasma interagisce con il vento solare e con il campo magnetico trasportato da esso. Per questo una cometa può mostrare code diverse. La loro direzione non si ricava semplicemente mettendole dietro il nucleo, come il fumo di un treno: il riferimento essenziale è il Sole, insieme alla dinamica del materiale."]}, {"title": "Che cosa osservare in una serata", "paragraphs": ["La luminosità dichiarata per una cometa può riferirsi alla luce complessiva distribuita su un’area estesa. Una cometa di una certa magnitudine non ha quindi necessariamente la stessa facilità osservativa di una stella con quel numero. Un cielo scuro, l’altezza sull’orizzonte e la vicinanza apparente al Sole cambiano molto il risultato. Nel diario conviene annotare l’aspetto della chioma, l’eventuale coda, lo strumento, il campo e le condizioni, distinguendo ciò che si vede da ciò che mostra una fotografia elaborata."]}, {"title": "Tra ritorni e trasformazioni", "paragraphs": ["Alcune comete percorrono orbite che le riportano periodicamente nel Sistema solare interno; altre hanno periodi lunghissimi. Le interazioni gravitazionali e le emissioni di materiale possono modificarne il moto. Frammentazione e variazioni di attività rendono difficili previsioni semplicistiche della luminosità. L’immagine di una cometa è dunque il risultato di un corpo e di un ambiente che interagiscono, non di una stella con una coda permanente."]}], "facts": ["Nucleo, chioma e code sono componenti differenti", "La coda non indica semplicemente la direzione opposta al moto"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/cometa/"}, {"title": "NASA · piccoli corpi", "url": "https://science.nasa.gov/asteroids-comets-meteors/facts/"}], "editorialStatus": "scheda-estesa", "media": {"file": "assets/lezioni/cometa67p-navcam.jpg", "caption": "Il nucleo della cometa 67P osservato da vicino: la forma e l’attività non rappresentano tutte le comete.", "credit": "ESA/Rosetta/NAVCAM", "source": "https://www.esa.int/ESA_Multimedia/Images/2015/03/Comet_on_21_March_2015_NavCam", "license": "CC BY-SA IGO 3.0"}, "aliases": ["comete"]}, {"id": "condensa", "name": "Condensa", "definition": "La condensazione trasforma vapore in liquido; durante un’osservazione può formare goccioline sulle superfici ottiche raffreddate.", "example": "Temperatura della superficie e umidità contano insieme", "source": "https://www.treccani.it/enciclopedia/condensazione/", "lesson": "lezione-7-6.html", "related": ["atmosfera", "temperatura", "obiettivo"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Una superficie può raffreddarsi più dell’aria", "paragraphs": ["Durante una notte un’ottica esposta può perdere energia per irraggiamento e raggiungere una temperatura inferiore a quella dell’aria circostante. Se le condizioni lo consentono, il vapore acqueo condensa sulla superficie. Non significa che l’umidità sia diventata visibile soltanto perché il telescopio ingrandisce. La rugiada è un fenomeno fisico che coinvolge temperatura della superficie e contenuto di vapore dell’ambiente."]}, {"title": "Il segnale nell’immagine", "paragraphs": ["Un obiettivo appannato riduce il contrasto e può produrre aloni, velature o un’apparente perdita di stelle deboli. Il lettore potrebbe scambiarli per una nebulosa o per un peggioramento improvviso del fuoco. Prima di interpretare il cielo conviene quindi controllare lo stato del corredo. La condensa sul vetro è distinta da nubi alte, seeing e variazioni reali del soggetto, anche se tutti possono rendere l’immagine meno leggibile."]}, {"title": "Prevenire con il sistema adatto", "paragraphs": ["Paraluce, protezioni e dispositivi anticondensa possono ritardare o controllare l’appannamento secondo il progetto e le condizioni. Non esiste un accessorio universale che annulli il problema in ogni notte. Il riscaldamento eccessivo può introdurre altri effetti e richiede attenzione a alimentazione e compatibilità. Segui le istruzioni del costruttore invece di strofinare ripetutamente la superficie ottica o improvvisare sorgenti di calore non adatte."]}, {"title": "La serata finisce con il riponimento", "paragraphs": ["Uno strumento umido non va considerato pronto soltanto perché è stato messo nella custodia. Occorre gestire asciugatura e passaggio di temperatura secondo il tipo di strumento, evitando di intrappolare umidità e rispettando le indicazioni per elettronica e ottiche. Nel diario annotare la comparsa della rugiada aiuta a interpretare una sequenza di immagini e a preparare meglio la volta successiva. È parte dell’osservazione, non un dettaglio secondario dopo il cielo."]}], "facts": ["Temperatura della superficie e umidità contano insieme", "Un alone può essere condensa, non una nube astronomica"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/condensazione/"}]}, {"id": "congiunzione", "name": "Congiunzione", "definition": "Una congiunzione è una configurazione di coordinate apparenti: due astri condividono una coordinata specificata, senza trovarsi necessariamente vicini nello spazio.", "example": "Specificare la coordinata della congiunzione", "source": "https://www.treccani.it/enciclopedia/congiunzione_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-9-3.html", "related": ["elongazione", "opposizione", "eclittica"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Vicini sulla carta, lontani nello spazio", "paragraphs": ["Quando Luna e pianeta sembrano incontrarsi, guardiamo due direzioni che si avvicinano. Le distanze reali possono restare enormemente differenti. Nella definizione precisa si deve specificare se la congiunzione riguarda longitudine eclittica o ascensione retta. Avere la stessa coordinata non implica necessariamente la minima separazione angolare totale: l’altra coordinata può essere diversa. La data di un massimo avvicinamento e quella di una congiunzione possono quindi non coincidere."]}, {"title": "Il rapporto con il Sole", "paragraphs": ["Per i pianeti interni si distingue la congiunzione inferiore, con il pianeta dalla parte fra Terra e Sole, da quella superiore, al di là del Sole. La descrizione è una geometria generale: l’inclinazione dell’orbita può impedire l’allineamento perfetto dei dischi. Non ogni congiunzione inferiore di Mercurio o Venere produce un transito sul Sole, così come non ogni Luna nuova produce un’eclissi."]}, {"title": "La serata non è garantita dalla data", "paragraphs": ["Un evento può avvenire di giorno o sotto l’orizzonte per la città scelta. La separazione cambia nelle ore precedenti e successive e il crepuscolo può nascondere il bersaglio meno brillante. Una scheda utile indica luogo, orario, direzione e condizioni geometriche. Scrivere soltanto che due astri sono in congiunzione non dice automaticamente dove guardare e non garantisce che entrino nello stesso campo strumentale."]}, {"title": "Immagini oneste del fenomeno", "paragraphs": ["Accostare una fotografia della Luna e una di un pianeta può illustrare i protagonisti, ma non è una fotografia del loro incontro. Una simulazione calcolata può rappresentare la configurazione se conserva coordinate e istante. Una composizione artistica va dichiarata. Queste distinzioni permettono di creare una presentazione visivamente ricca senza convincere il lettore che un collage costituisca una testimonianza osservativa reale."]}], "facts": ["Specificare la coordinata della congiunzione", "Vicinanza apparente ≠ vicinanza fisica"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/congiunzione_(Dizionario-delle-Scienze-Fisiche)/"}]}, {"id": "corpo-nero", "name": "Corpo nero", "definition": "Il corpo nero è un modello ideale che assorbe tutta la radiazione incidente e, in equilibrio termico, emette uno spettro determinato dalla temperatura.", "example": "Assorbitore ideale non significa emettitore spento", "source": "https://www.treccani.it/enciclopedia/corpo-nero/", "lesson": "lezione-4-3.html", "related": ["temperatura", "spettro", "stella"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Nero non significa privo di emissione", "paragraphs": ["Il nome descrive l’assorbimento ideale, non l’obbligo di apparire sempre scuro. Un corpo nero caldo emette radiazione e può essere molto luminoso. Il modello permette di collegare temperatura e distribuzione dell’energia emessa senza dover descrivere ogni dettaglio del materiale. È uno strumento concettuale, non una nuova categoria di oggetti celesti da aggiungere accanto a stelle, pianeti e galassie."]}, {"title": "Una curva distribuita su molte lunghezze d’onda", "paragraphs": ["Lo spettro termico non è una singola riga colorata. Contiene radiazione distribuita su un intervallo ampio e presenta un massimo che si sposta verso lunghezze d’onda più corte quando la temperatura cresce. Non significa che un oggetto emetta soltanto nel colore del massimo. Per questo leggere la tonalità di una stella come se fosse una lampadina monocromatica porta a una rappresentazione sbagliata del suo spettro."]}, {"title": "Che cosa cambia aumentando la temperatura", "paragraphs": ["A parità di superficie emittente, un corpo nero più caldo emette più energia complessiva. Anche l’estensione della superficie conta: un oggetto molto grande e meno caldo può avere una luminosità totale elevata. Il confronto fra temperatura e luminosità di una stella richiede quindi di distinguere emissione per superficie e quantità totale. Le immagini del laboratorio devono conservare questa distinzione, senza far coincidere automaticamente la sfera più blu con quella di luminosità totale maggiore in ogni configurazione."]}, {"title": "Le stelle reali aggiungono informazioni", "paragraphs": ["Il continuo stellare può essere confrontato con un modello termico, ma atmosfere, righe e altri processi rendono lo spettro reale più ricco. Un adattamento di corpo nero è un’approssimazione utile, non la descrizione completa di ogni sorgente. Anche assorbimento e risposta dello strumento modificano la luce osservata. Quando usi una curva didattica, indica dunque che rappresenta un modello ideale e quali proprietà permette di capire prima di passare ai dati astronomici."]}], "facts": ["Assorbitore ideale non significa emettitore spento", "Temperatura e superficie contribuiscono alla luminosità totale"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/corpo-nero/"}]}, {"id": "costellazione", "name": "Costellazione", "definition": "Regione delimitata della sfera celeste, associata tradizionalmente a una figura apparente di stelle.", "example": "Le linee che colleghiamo fra stelle non sono fili fisici. Stelle vicine sulla carta possono essere a distanze molto diverse.", "source": "https://www.treccani.it/enciclopedia/costellazione/", "lesson": "lezione-1-4.html", "related": ["ammasso-aperto", "sfera-celeste"], "checked": "2026-10-30", "sections": [{"title": "Dal disegno alla regione del cielo", "paragraphs": ["Una costellazione moderna è una regione della sfera celeste con nome e confini convenzionali. Le figure che uniamo fra stelle sono un modo storico e pratico per riconoscerla, ma non ne costituiscono il confine ufficiale. Se un oggetto si trova nella regione di Orione, può essere descritto come “in Orione” anche quando non appartiene alle stelle del suo disegno più familiare. Le costellazioni organizzano la carta delle direzioni."]}, {"title": "La prospettiva può ingannare", "paragraphs": ["Due stelle che sul foglio sembrano vicine possono trovarsi a distanze molto diverse. I segmenti del disegno non rappresentano ponti, orbite o legami gravitazionali. Un ammasso stellare, invece, è un gruppo fisico di stelle: può anche offrire una figura apparente riconoscibile, ma il suo essere un sistema va dimostrato con informazioni aggiuntive. Costellazione e ammasso non sono quindi due nomi per la stessa cosa."]}, {"title": "Asterismi e confini", "paragraphs": ["Un asterismo è una figura riconoscibile che può occupare parte di una costellazione oppure attraversarne più di una. Il Grande Carro è una parte della figura dell’Orsa Maggiore; il Triangolo Estivo usa stelle di tre costellazioni. Le carte possono tracciare segmenti diversi a seconda dell’autore: questo non sposta le stelle né i confini adottati. Per gli esercizi conta scegliere un tracciato dichiarato e mantenere coerenti forma, orientamento e posizioni relative."]}, {"title": "Usarla per cercare, senza trasformarla in un oggetto fisico", "paragraphs": ["Quando impari il cielo, parti da poche stelle luminose e confronta distanze angolari, direzione e disposizione. Poi passa agli oggetti che occupano la stessa regione. La parte visibile cambia con luogo e ora, mentre una carta equatoriale conserva un riferimento diverso dalla vista locale dell’orizzonte. Una costellazione non “scende di declinazione” al cambiare della stagione: cambia la vista che ne abbiamo dalla Terra. Un laboratorio deve distinguere il reticolo di catalogo dal movimento apparente nel cielo dell’osservatore."]}], "facts": ["Regione del cielo ≠ gruppo fisico di stelle", "Asterismo: figura riconoscibile, anche fra più costellazioni", "Le linee sono convenzioni grafiche, non strutture nello spazio"], "sources": [{"title": "Treccani · riferimento della voce", "url": "https://www.treccani.it/enciclopedia/costellazione/"}], "editorialStatus": "scheda-estesa", "aliases": ["costellazioni"]}, {"id": "crepuscolo", "name": "Crepuscolo", "definition": "Il crepuscolo è la fase di luminosità diffusa del cielo prima del sorgere o dopo il tramonto del Sole, mentre il Sole si trova sotto l’orizzonte.", "example": "Soglie solari: −6°, −12°, −18°", "source": "https://www.treccani.it/enciclopedia/crepuscolo/", "lesson": "lezione-9-5.html", "related": ["sole", "orizzonte", "effemeridi"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il tramonto non spegne subito il cielo", "paragraphs": ["Dopo che il disco solare è scomparso, parte dell’atmosfera continua a ricevere luce e a diffonderla verso di noi. Il paesaggio e il cielo passano gradualmente a condizioni più scure. Per questo un pianeta brillante può emergere quando molte stelle sono ancora invisibili, e una nebulosa tenue può richiedere un’attesa maggiore. La comparsa dei bersagli non dipende soltanto dall’essere geometricamente sopra l’orizzonte."]}, {"title": "Tre soglie convenzionali", "paragraphs": ["Si usano le soglie del centro del Sole a 6, 12 e 18 gradi sotto l’orizzonte per distinguere i riferimenti civile, nautico e astronomico. Nella suddivisione delle fasi serali gli intervalli sono progressivamente da circa zero a meno sei, da meno sei a meno dodici e da meno dodici a meno diciotto gradi. Al mattino la sequenza è inversa. Questi numeri descrivono una geometria, non un interruttore della luminosità reale."]}, {"title": "La durata dipende dal luogo e dalla stagione", "paragraphs": ["Il Sole attraversa le direzioni sotto l’orizzonte con geometrie differenti secondo latitudine e periodo dell’anno. Non si può quindi aggiungere sempre lo stesso numero di minuti al tramonto. In alcune combinazioni di luogo e stagione una soglia può non essere raggiunta. Le effemeridi devono gestire questi casi senza inventare un orario. Anche nubi, aerosol, Luna e luci artificiali modificano poi l’aspetto effettivo della serata."]}, {"title": "Un’indicazione utile, non una promessa", "paragraphs": ["La fine del crepuscolo astronomico non assicura un cielo privo di chiarore, perché restano sorgenti naturali e artificiali. Può però aiutare a scegliere l’orario per bersagli poco contrastati. Nel planetario didattico la sfumatura dovrebbe cambiare con l’altezza solare, invece di mostrare a ogni ora lo stesso cielo nero pieno di stelle. Annotare la fase della serata rende più chiaro perché alcuni oggetti attesi sulla mappa non si distinguono ancora a occhio."]}], "facts": ["Soglie solari: −6°, −12°, −18°", "Tramonto e buio astronomico non sono lo stesso istante"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/crepuscolo/"}, {"title": "USNO · riferimenti del crepuscolo", "url": "https://aa.usno.navy.mil/data/RS_OneYear"}]}, {"id": "culminazione", "name": "Culminazione", "definition": "La culminazione è il passaggio di un astro al meridiano locale: superiore in corrispondenza del massimo della traiettoria diurna, inferiore in corrispondenza del minimo.", "example": "Massima altezza non significa zenit", "source": "https://www.treccani.it/enciclopedia/culminazione/", "lesson": "lezione-1-3.html", "related": ["altezza-angolare", "circumpolare", "angolo-orario"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il punto più alto del percorso", "paragraphs": ["Una stella cambia direzione e altezza mentre la Terra ruota. Per una traiettoria diurna a declinazione praticamente costante, la culminazione superiore corrisponde al passaggio al meridiano nella posizione di massima altezza. Non significa che tutte le stelle raggiungano lo zenit. Il massimo dipende dalla declinazione della stella e dalla latitudine dell’osservatore: alcune culminano alte, altre restano basse e altre non raggiungono affatto il cielo visibile da quel luogo."]}, {"title": "Il passaggio inferiore non scompare sotto terra", "paragraphs": ["La culminazione inferiore esiste geometricamente anche quando avviene sotto l’orizzonte. È osservabile sopra l’orizzonte per le stelle circumpolari appropriate al luogo. Dire che avviene soltanto per le circumpolari confonde esistenza del passaggio e visibilità. Nel modello una stella che sorge e tramonta continua la sua traiettoria anche quando non possiamo vederla: il bordo del panorama non interrompe il moto relativo alla sfera celeste."]}, {"title": "Perché interessa all’osservazione", "paragraphs": ["Un bersaglio vicino alla propria massima altezza può offrire un percorso atmosferico più favorevole rispetto a quando è molto basso. Questo non garantisce il seeing migliore e non elimina nubi o ostacoli. Per pianificare cerca l’orario del passaggio e confrontalo con buio, Luna e praticabilità del sito. Non basta che l’oggetto culmini: potrebbe farlo di giorno o restare troppo vicino all’orizzonte per l’attività che vuoi svolgere."]}, {"title": "Non confonderla con il mezzogiorno civile", "paragraphs": ["Per il Sole il passaggio superiore è legato al mezzogiorno solare locale, che non coincide in generale con le dodici dell’orologio. Per le stelle gli orari dipendono da data e luogo. Nelle effemeridi, la colonna transito può indicare proprio questo passaggio, non un’eclisse o un attraversamento del disco solare. Una legenda chiara deve quindi dire quale evento è calcolato e quale sistema orario viene usato."]}], "facts": ["Massima altezza non significa zenit", "Il passaggio inferiore può avvenire sotto l’orizzonte"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/culminazione/"}]}, {"id": "curva-di-luce", "name": "Curva di luce", "definition": "Una curva di luce rappresenta come varia nel tempo il segnale luminoso misurato di una sorgente, in una banda e con una scala specificate.", "example": "Gli assi e la banda fanno parte del significato", "source": "https://www.treccani.it/enciclopedia/variabile_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-10-1.html", "related": ["fotometria", "transito", "binaria-a-eclisse"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Una successione di misure diventa una figura", "paragraphs": ["Sull’asse orizzontale si dispone il tempo; su quello verticale il flusso, la magnitudine o un’altra quantità luminosa dichiarata. Ogni punto deriva da una misura, non è necessariamente un fotogramma del movimento fisico dell’oggetto. La curva permette di riconoscere andamenti che un’immagine isolata non racconta. Può mostrare un transito, una pulsazione, un’eclisse stellare o l’evoluzione di un evento esplosivo, ma il solo profilo non ne prova automaticamente la causa."]}, {"title": "Prima di interpretare, leggi gli assi", "paragraphs": ["Quando il flusso diminuisce il numero misurato scende, mentre nella scala delle magnitudini una sorgente più debole ha un numero maggiore. Nei grafici astronomici l’asse delle magnitudini può essere invertito per mostrare le sorgenti più brillanti in alto. Anche il flusso normalizzato è una scelta: uno può rappresentare un livello di riferimento, non un watt. Senza legenda, la stessa forma grafica può quindi essere letta nel verso sbagliato."]}, {"title": "Il tempo fra le misure conta", "paragraphs": ["Esposizioni lunghe possono smussare un fenomeno rapido; intervalli distanti possono lasciare vuoti importanti. Un tratto disegnato fra due punti non dimostra che il segnale abbia seguito esattamente quella linea durante la pausa. Le incertezze aiutano a distinguere variazioni significative da oscillazioni compatibili con il rumore. Anche atmosfera e strumento possono alterare la misura: confronti con riferimenti e controlli dei dati fanno parte dell’interpretazione."]}, {"title": "Dal modello al dato reale", "paragraphs": ["Nel laboratorio una stella schematica occultata da un pianeta rende visibile il legame fra posizione e calo di luce. Dimensioni accentuate e curva semplificata devono essere dichiarate. Nei dati reali occorre verificare ripetizione, stabilità dei confronti e possibili alternative. Non tutti i cali indicano un pianeta e non tutte le stelle variabili sono binarie. Il punto da ricordare è il metodo: osservare il cambiamento, misurarlo e solo dopo confrontare spiegazioni fisiche compatibili."]}], "facts": ["Gli assi e la banda fanno parte del significato", "Una forma della curva suggerisce ipotesi, non basta da sola a provarle"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/variabile_(Dizionario-delle-Scienze-Fisiche)/"}]}, {"id": "declinazione", "name": "Declinazione", "definition": "Coordinata equatoriale che misura la distanza angolare a nord o a sud dell’equatore celeste, fra −90° e +90°.", "example": "Una declinazione positiva indica il lato nord dell’equatore celeste, non l’altezza sopra il tuo orizzonte.", "source": "https://www.treccani.it/enciclopedia/coordinate/", "lesson": "lezione-1-6.html", "related": ["ascensione-retta", "equatore-celeste"], "checked": "2026-10-30", "sections": [{"title": "A nord o a sud di quale cerchio?", "paragraphs": ["La declinazione, simbolo δ, misura la distanza angolare di una direzione dall’equatore celeste. Vale zero sull’equatore, è positiva nell’emisfero celeste nord e negativa in quello sud. Raggiunge +90° al Polo Nord celeste e −90° al Polo Sud celeste. Il confronto con la latitudine geografica aiuta a immaginarla, purché si ricordi che stiamo descrivendo direzioni sulla sfera celeste e non punti sulla superficie terrestre."]}, {"title": "Un numero che non è l’altezza", "paragraphs": ["Una stella con declinazione +30° non si trova necessariamente 30° sopra il tuo orizzonte. Durante la notte può salire, transitare e scendere, mentre la sua declinazione di catalogo resta praticamente invariata alla scala della serata. L’altezza dipende dalla latitudine del luogo e dalla posizione nel moto diurno. Per esempio, al transito superiore, una stella di declinazione +30° osservata a latitudine 45° N passa a 75° di altezza geometrica: 90° meno la differenza di 15° fra latitudine e declinazione."]}, {"title": "La regione circumpolare", "paragraphs": ["Declinazione e latitudine aiutano a capire quali stelle non tramontano. A 45° N una stella di declinazione +60° mantiene il suo punto più basso a 15° sopra l’orizzonte geometrico; una di declinazione +20° attraversa invece l’orizzonte. Questi esempi ignorano rifrazione e ostacoli. La proprietà riguarda le singole direzioni stellari: assegnarla indiscriminatamente a un’intera costellazione estesa può creare errori, soprattutto quando una parte del disegno si trova vicino al limite."]}, {"title": "Non confonderla con la bussola", "paragraphs": ["La declinazione magnetica è un altro concetto: riguarda la differenza fra riferimento magnetico e geografico nel luogo di misura. Non entra come coordinata nord–sud della stella. Anche per la declinazione celeste occorre conservare il riferimento del catalogo: coordinate con equinozi o sistemi diversi non si confrontano sottraendo semplicemente i numeri. Per leggere una carta divulgativa basta iniziare dal segno e dal cerchio di riferimento; per puntamenti e misure precisi si controllano tutte le indicazioni associate."]}], "facts": ["Equatore 0° · Polo Nord +90° · Polo Sud −90°", "Declinazione celeste ≠ declinazione magnetica", "Esempio a 45° N: δ +60° → altezza minima 15°"], "sources": [{"title": "Treccani · riferimento della voce", "url": "https://www.treccani.it/enciclopedia/coordinate/"}, {"title": "USNO · coordinate e vista locale", "url": "https://aa.usno.navy.mil/faq/alt_az"}], "editorialStatus": "scheda-estesa", "aliases": ["declinazioni"]}, {"id": "declinazione-magnetica", "name": "Declinazione magnetica", "definition": "Angolo locale fra il meridiano geografico e quello magnetico.", "example": "Serve a distinguere il nord indicato dalla bussola dal nord geografico. Non è la declinazione delle coordinate stellari.", "source": "https://www.treccani.it/enciclopedia/declinazione/", "lesson": "lezione-1-2.html", "related": ["declinazione", "polo-celeste"], "checked": "2026-10-30", "sections": [{"title": "Due riferimenti diversi", "paragraphs": ["La declinazione magnetica è l’angolo fra il nord geografico e la direzione nord indicata dalla componente orizzontale del campo magnetico locale. Il nord geografico si riferisce alla rotazione terrestre; la bussola risponde invece al campo magnetico. Non sono due nomi dello stesso riferimento. La loro differenza va considerata quando si usa la bussola per orientare una carta o predisporre uno strumento astronomico."]}, {"title": "Perché il valore cambia", "paragraphs": ["Il campo terrestre non è quello di un dipolo perfetto e varia nel tempo. La declinazione dipende perciò dal luogo e dalla data: non si può applicare a tutta la Terra una correzione fissa di pochi gradi. Un modello geomagnetico fornisce una stima per le coordinate e l’epoca richieste. Disturbi locali, come masse metalliche, magneti, automobili o componenti elettriche, possono inoltre alterare la lettura senza essere rappresentati dal modello globale."]}, {"title": "Un esempio con il segno dichiarato", "paragraphs": ["Supponiamo, soltanto come esempio, che il nord magnetico si trovi 4° a est del nord vero. Una direzione indicata dalla bussola come nord non coincide allora con l’azimut geografico 0°: si trova 4° più a est. Il modo operativo di correggere la lettura dipende dal tipo di bussola e dalla convenzione usata. Prima di aggiungere o sottrarre numeri conviene disegnare i due nord e specificare il segno della declinazione."]}, {"title": "Nel lavoro dell’astrofilo", "paragraphs": ["La bussola aiuta a trovare una direzione iniziale, ma l’allineamento polare accurato richiede una procedura astronomica o strumentale appropriata. Il sensore del telefono non elimina gli errori ambientali. Questa declinazione non è quella celeste, che misura la posizione di un astro rispetto all’equatore celeste: confonderle rende impossibile interpretare correttamente una carta. Per un’attività didattica è sufficiente dichiarare la correzione adottata, la provenienza e la data del valore."]}], "facts": ["Dipende da luogo e data", "Nord geografico e riferimento magnetico sono distinti"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/declinazione/"}, {"title": "NOAA · declinazione magnetica", "url": "https://www.ngdc.noaa.gov/geomag/declination.shtml"}], "editorialStatus": "scheda-estesa"}, {"id": "densita", "name": "Densità", "definition": "La densità di massa è la massa per unità di volume; una densità media non descrive necessariamente ogni regione interna di un corpo.", "example": "Densità = massa divisa per volume", "source": "https://www.treccani.it/enciclopedia/densita/", "lesson": "lezione-3-2.html", "related": ["massa", "pianeta", "stella"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La dimensione da sola non basta", "paragraphs": ["Due sfere della stessa grandezza possono avere masse diverse se contengono materiali o strutture differenti. Due corpi della stessa massa possono occupare volumi diversi. La densità mette in relazione queste informazioni: si divide la massa per il volume. Per un corpo omogeneo la descrizione è semplice; per un pianeta differenziato occorre distinguere media globale e valori locali."]}, {"title": "Un esempio di unità", "paragraphs": ["Un campione con massa di 300 grammi e volume di 100 centimetri cubi ha densità media 3 g/cm³. Il rapporto non è un peso specifico misurato in grammi e non indica il diametro del campione. Per confrontare valori si devono usare unità coerenti. Lo stesso numero scritto con chilogrammi per metro cubo ha una scala diversa: non si possono confrontare le cifre ignorando ciò che compare accanto."]}, {"title": "Dentro un pianeta", "paragraphs": ["Crosta, mantello e nucleo possono avere composizioni, pressioni e densità diverse. La media aiuta a interpretare il mondo insieme a massa, raggio e altri dati, ma non produce da sola una sezione interna unica. Anche materiali con la stessa composizione possono avere stati differenti sotto pressioni diverse. Un’illustrazione degli strati deve quindi essere dichiarata come modello, non come una fotografia di una fetta realmente estratta."]}, {"title": "Cautela con gli oggetti compatti", "paragraphs": ["Nane bianche, stelle di neutroni e buchi neri non si descrivono tutti come sfere di materiale ordinario compresso allo stesso modo. Nel caso di un orizzonte degli eventi, usare il volume racchiuso per definire una densità media può essere un confronto matematico, ma non dice come la materia sia distribuita nell’interno. Una cifra spettacolare va accompagnata dal modello: la densità è utile quando chiarisce, non quando nasconde dietro un numero grande ciò che non è direttamente misurato."]}], "facts": ["Densità = massa divisa per volume", "Densità media ≠ densità uniforme ovunque"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/densita/"}]}, {"id": "diffrazione", "name": "Diffrazione", "definition": "La natura ondulatoria della luce fa sì che un’apertura finita produca una figura estesa anche per una sorgente puntiforme.", "example": "Una sorgente puntiforme produce un’immagine di estensione finita", "source": "https://www.treccani.it/enciclopedia/diffrazione/", "lesson": "lezione-7-3.html", "related": ["seeing", "telescopio", "riflettore"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Perché una stella non diventa un punto perfetto", "paragraphs": ["L’ottica geometrica rappresenta la luce con raggi, ma questa descrizione non racconta tutti i fenomeni. Quando un’onda attraversa un’apertura o incontra un ostacolo, la distribuzione della luce non segue soltanto l’idea di ombre nette. Nel telescopio una stella idealmente puntiforme forma una figura con una zona centrale e strutture circostanti. Non è necessariamente un difetto di lavorazione: è una conseguenza fisica della propagazione della luce."]}, {"title": "Apertura e lunghezza d’onda", "paragraphs": ["Per un’apertura circolare ideale, la scala angolare della figura diminuisce aumentando il diametro e cresce usando lunghezze d’onda maggiori. A parità di condizioni, raddoppiare il diametro dimezza la scala angolare caratteristica. Questo non significa che ogni immagine reale migliori esattamente del doppio: atmosfera, aberrazioni, sensore e movimento possono dominare. La relazione descrive un limite ottico ideale, non una promessa commerciale di prestazioni."]}, {"title": "Anelli e raggi nelle fotografie", "paragraphs": ["Una pupilla circolare libera produce una distribuzione diversa da quella di un sistema con ostruzione centrale e sostegni del secondario. I raggi attorno a stelle brillanti possono quindi dipendere dalla struttura dell’apertura, non da getti che escono materialmente dalla stella. Anche la saturazione può alterare l’aspetto. Una fotografia divulgativa deve evitare di presentare ogni struttura brillante come una proprietà fisica del corpo osservato."]}, {"title": "Distinguere i limiti per scegliere", "paragraphs": ["L’ingrandimento rende più grande la figura già prodotta, ma non ricrea dettagli assenti. Una maggiore apertura può offrire più potere risolutivo, purché le altre condizioni consentano di sfruttarlo. Il seeing deforma ulteriormente il segnale e un fuoco errato lo allarga ancora. Per capire una stella apparentemente grossa sul sensore bisogna quindi separare dimensione fisica dell’astro, figura di diffrazione e degradazioni introdotte lungo il percorso della luce."]}], "facts": ["Una sorgente puntiforme produce un’immagine di estensione finita", "Apertura doppia → scala di diffrazione circa dimezzata"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/diffrazione/"}, {"title": "OpenStax · telescopi", "url": "https://openstax.org/books/astronomy-2e/pages/6-1-telescopes"}]}, {"id": "eclissi", "name": "Eclissi", "definition": "Oscuramento totale o parziale di un astro dovuto all’interposizione di un altro corpo.", "example": "Nell’eclissi lunare la Luna attraversa l’ombra terrestre; nell’eclissi solare la Luna si interpone fra osservatore e Sole.", "source": "https://www.treccani.it/enciclopedia/eclissi/", "lesson": "lezione-2-6.html", "related": ["eclittica", "orbita"], "checked": "2026-10-30", "sections": [{"title": "Un allineamento che cambia la luce", "paragraphs": ["Un’eclissi avviene quando un corpo viene oscurato o la sua vista viene impedita per l’allineamento con altri corpi. Nel sistema Sole–Terra–Luna distinguiamo eclissi solari e lunari. Nel primo caso la Luna si interpone fra noi e il Sole; nel secondo la Luna attraversa l’ombra terrestre. Non sono fasi lunari ordinarie: la normale alternanza delle fasi dipende dalla porzione illuminata che vediamo, non dall’ombra della Terra."]}, {"title": "Ombra e penombra", "paragraphs": ["Poiché il Sole è una sorgente estesa, dietro un corpo opaco si formano zone con condizioni diverse. Nell’ombra la sorgente è completamente occultata; nella penombra soltanto una sua parte. Per le eclissi solari conta anche la dimensione apparente di Sole e Luna e la posizione dell’osservatore. Per quelle lunari si distinguono attraversamenti della penombra, dell’ombra parziale o dell’ombra con l’intero disco lunare."]}, {"title": "Perché non succede ogni mese", "paragraphs": ["L’orbita della Luna è inclinata rispetto al piano dell’orbita terrestre. A molte lune nuove o piene i tre corpi non sono allineati abbastanza: la Luna passa sopra o sotto la regione necessaria. Un’eclissi richiede la prossimità a uno dei nodi, dove i due piani si intersecano, insieme alla fase appropriata. Un disegno bidimensionale che mette sempre i tre centri su una retta nasconde questa condizione decisiva."]}, {"title": "Osservare fenomeni diversi", "paragraphs": ["Un’eclissi lunare si segue come la Luna ordinaria, mentre osservare il Sole richiede protezioni e procedure specifiche. Non si guarda il Sole attraverso binocoli o telescopi senza filtrazione solare certificata, adatta e correttamente montata davanti all’apertura. Il rossore della Luna eclissata dipende dalla luce filtrata e deviata dall’atmosfera terrestre: un disco rosso in un laboratorio è un’illustrazione del fenomeno, non una previsione della sua luminosità esatta."]}], "facts": ["Solare: Sole–Luna–Terra · lunare: Sole–Terra–Luna", "Le fasi non sono causate dall’ombra terrestre"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/eclissi/"}, {"title": "NASA · eclissi lunari e solari", "url": "https://science.nasa.gov/moon/eclipses/"}], "editorialStatus": "scheda-estesa"}, {"id": "eclittica", "name": "Eclittica", "definition": "Cerchio della sfera celeste che descrive il percorso apparente annuo del Sole e corrisponde al piano dell’orbita terrestre.", "example": "Non è l’equatore celeste: i due cerchi sono inclinati fra loro.", "source": "https://www.treccani.it/enciclopedia/eclittica_(Enciclopedia-Italiana)/", "lesson": "lezione-2-2.html", "related": ["equatore-celeste", "punto-equinoziale"], "checked": "2026-10-30", "sections": [{"title": "Il percorso annuo apparente del Sole", "paragraphs": ["L’eclittica è il cerchio massimo della sfera celeste associato al piano dell’orbita terrestre. Guardando il cielo dalla Terra, il Sole appare spostarsi durante l’anno lungo questo percorso rispetto alle stelle di sfondo. Non si tratta di un’orbita materiale del Sole attorno alla Terra: è una descrizione geometrica della sua direzione apparente, collegata alla rivoluzione terrestre."]}, {"title": "Due piani da tenere distinti", "paragraphs": ["Il piano equatoriale terrestre è inclinato rispetto a quello orbitale. Prolungandoli nel cielo otteniamo equatore celeste ed eclittica, che si incontrano nei punti equinoziali. L’angolo fra i piani è circa 23,4°. La stessa cifra descrive l’inclinazione dell’asse terrestre rispetto alla normale al piano orbitale, non rispetto al piano stesso: confondere normale e piano produce disegni con angoli complementari scambiati."]}, {"title": "Dove cercare i pianeti", "paragraphs": ["Le orbite dei pianeti principali sono relativamente vicine al piano di quella terrestre, quindi nel cielo li cerchiamo in una fascia attorno all’eclittica. Non sono però inchiodati esattamente alla linea: ciascuna orbita ha una propria inclinazione e la vista dipende dalla geometria del momento. Anche la Luna si discosta dall’eclittica. Per questo non basta un allineamento sulla carta bidimensionale per concludere che si verifichi un’eclissi o una congiunzione strettissima."]}, {"title": "Una guida utile, non un reticolo unico", "paragraphs": ["Una carta può mostrare insieme eclittica, equatore e orizzonte, ma sono riferimenti differenti. La loro posizione nella vista locale cambia con luogo e ora. Se un pianeta è vicino al Sole in direzione, può essere sopra l’orizzonte e tuttavia immerso nel chiarore. L’eclittica aiuta a comprendere la disposizione generale; le effemeridi servono a valutare l’istante e l’osservabilità. I punti equinoziali e i piani di riferimento non sono immutabili su scale storiche: nei dati precisi si dichiarano le convenzioni del calcolo."]}], "facts": ["Eclittica: riferimento legato al piano orbitale terrestre", "Circa 23,4° fra eclittica ed equatore celeste", "I pianeti si cercano vicino alla fascia, non necessariamente sulla linea"], "sources": [{"title": "Treccani · riferimento della voce", "url": "https://www.treccani.it/enciclopedia/eclittica_(Enciclopedia-Italiana)/"}], "editorialStatus": "scheda-estesa"}, {"id": "effemeridi", "name": "Effemeridi", "definition": "Le effemeridi forniscono posizioni e altri dati astronomici in funzione del tempo, entro un riferimento, un modello e condizioni dichiarate.", "example": "Ogni dato richiede tempo e riferimento", "source": "https://www.treccani.it/vocabolario/effemeride/", "lesson": "lezione-9-3.html", "related": ["ora-civile", "astrometria", "congiunzione"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Dal calendario alla geometria", "paragraphs": ["Un’effemeride non è soltanto un elenco di date interessanti. Può riportare coordinate, distanze, fasi, istanti di fenomeni e altre grandezze variabili. Il tempo è parte dell’informazione. Una tabella riferita al giorno 15 alle 22:00 non descrive automaticamente l’intero mese. Per una pagina che cambia giorno o città occorre aggiornare in modo coordinato tutti i valori che dipendono da quelle scelte."]}, {"title": "Luogo e riferimento contano", "paragraphs": ["Una posizione geocentrica si riferisce al centro della Terra, una topocentrica al sito dell’osservatore. Altezza e azimut richiedono coordinate geografiche e istante. I tempi vanno accompagnati dalla scala o dal fuso pertinente. Anche sorgere e tramonto dipendono da convenzioni, rifrazione e orizzonte adottato. La presenza di molti decimali non compensa una definizione assente del riferimento."]}, {"title": "Visibile secondo quale criterio?", "paragraphs": ["Un pianeta sopra l’orizzonte può essere nascosto da chiarore, ostacoli o atmosfera. Una finestra calcolata con Sole sotto una certa altezza e pianeta sopra un limite è un criterio operativo, non la promessa che ogni osservatore vedrà il soggetto. Se il calcolo campiona intervalli di dieci minuti, il risultato non deve essere presentato come una misura esatta al secondo. Le soglie e il metodo fanno parte della scheda."]}, {"title": "Aggiornare senza inventare cambiamenti", "paragraphs": ["Ricalcolare una pagina può restituire gli stessi valori arrotondati: non serve modificare una cifra per dimostrare che il pulsante ha funzionato. L’aggiornamento deve confermare istante e luogo. I contenuti editoriali e le fotografie d’archivio rimangono distinti dalle quantità astronomiche calcolate. Questo permette a un sito di aggiornare i dati dinamici senza attribuire alle immagini o agli articoli un’automatica validazione osservativa."]}], "facts": ["Ogni dato richiede tempo e riferimento", "Ricalcolo e variazione del valore arrotondato non sono la stessa cosa"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/vocabolario/effemeride/"}]}, {"id": "effetto-doppler", "name": "Effetto Doppler", "definition": "L’effetto Doppler collega il moto relativo fra sorgente e osservatore a una variazione della frequenza e della lunghezza d’onda ricevute.", "example": "Si confrontano caratteristiche spettrali identificate", "source": "https://www.treccani.it/enciclopedia/effetto-doppler/", "lesson": "lezione-4-3.html", "related": ["frequenza", "redshift", "velocita-radiale"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "La sirena come prima intuizione", "paragraphs": ["Il suono di una sirena che si avvicina e poi si allontana offre un esempio familiare di variazione percepita. Per la luce il fenomeno va descritto con la fisica elettromagnetica e, quando necessario, relativistica, non copiando ogni dettaglio delle onde sonore nell’aria. L’analogia aiuta a introdurre il legame con il moto relativo; non significa che lo spazio debba essere riempito di un mezzo materiale simile all’aria per trasmettere la luce."]}, {"title": "Il confronto si fa sulle righe", "paragraphs": ["In uno spettro si identificano caratteristiche note e si confrontano le loro posizioni con riferimenti. Per il semplice caso di avvicinamento lungo la linea di vista si ha uno spostamento verso lunghezze d’onda minori; per allontanamento verso maggiori. Non è necessario che l’intera stella diventi visivamente blu o rossa. Il suo colore fotografico dipende da molti contributi e da solo non è una misura affidabile della velocità."]}, {"title": "Una componente del moto", "paragraphs": ["Lo spostamento osservato fornisce informazioni sulla componente radiale, con il modello e le correzioni appropriati. Un movimento prevalentemente trasversale non si legge nello stesso modo. Anche l’osservatore si muove: rotazione e rivoluzione terrestre influiscono sui riferimenti di una misura accurata. Una velocità pubblicata deve quindi indicare a quale riferimento è stata ricondotta, anziché presentare il dato come se provenisse da un osservatore immobile in senso assoluto."]}, {"title": "Non ogni redshift ha la stessa causa", "paragraphs": ["Espansione cosmologica ed effetti gravitazionali richiedono descrizioni proprie. Il redshift è una misura dello spostamento relativo delle lunghezze d’onda; non implica sempre una velocità ricavabile con una semplice proporzione doppleriana. Nelle lezioni conviene partire dal caso vicino e a bassa velocità, dichiararne i limiti e poi distinguere gli altri fenomeni. Così la formula resta collegata a una domanda concreta e non diventa una scorciatoia sbagliata per qualsiasi sorgente lontana."]}], "facts": ["Si confrontano caratteristiche spettrali identificate", "Redshift e velocità non sono sinonimi universali"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/effetto-doppler/"}]}, {"id": "elongazione", "name": "Elongazione", "definition": "Nell’uso osservativo l’elongazione descrive la separazione apparente dal Sole; occorre distinguere la separazione angolare totale dalla differenza di longitudine usata in alcune definizioni.", "example": "Un angolo dal Sole, non chilometri", "source": "https://www.treccani.it/enciclopedia/elongazione/", "lesson": "lezione-9-3.html", "related": ["congiunzione", "opposizione", "pianeta"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Quanto lontano appare dal Sole", "paragraphs": ["Per cercare Mercurio o Venere è utile sapere quanto si separano apparentemente dal Sole. Una piccola separazione può lasciarli immersi nel chiarore o rendere impossibile osservarli in sicurezza. Il numero è angolare, non una distanza fisica in chilometri. Il riferimento deve essere dichiarato: alcune fonti usano differenze di longitudine, mentre nelle indicazioni pratiche si parla spesso della separazione angolare osservata."]}, {"title": "Est e ovest del Sole", "paragraphs": ["Un pianeta a est del Sole può essere favorevole nel cielo serale; a ovest può comparire prima dell’alba. La geometria locale dell’eclittica e l’altezza sull’orizzonte cambiano però l’effettiva comodità dell’osservazione. Non basta un valore alto di elongazione per garantire un’ottima apparizione da ogni latitudine. Anche data, condizioni atmosferiche e ostacoli incidono sul tempo in cui il bersaglio si trova in un cielo abbastanza scuro."]}, {"title": "La massima elongazione dei pianeti interni", "paragraphs": ["Mercurio e Venere non possono allontanarsi apparentemente dal Sole quanto un pianeta esterno. La loro orbita interna produce elongazioni massime. Il valore e la geometria di ciascun evento dipendono dalle orbite reali: non sono sempre identici in tutte le apparizioni. È un’occasione per collegare un diagramma visto dall’alto alla direzione osservata dalla Terra, senza disegnare pianeti tutti sulla stessa orbita."]}, {"title": "Una precauzione operativa concreta", "paragraphs": ["Un’indicazione di visibilità vicino al tramonto non autorizza a cercare il pianeta con un telescopio quando il Sole può ancora entrare nel campo. La progettazione della serata deve tenere conto di direzione solare, orizzonte e procedura sicura. Una fotografia con cielo scuro e pianeta vicino al Sole può essere un collage o una rappresentazione non realistica: la carta calcolata deve includere anche il chiarore, almeno come limite dichiarato di visibilità."]}], "facts": ["Un angolo dal Sole, non chilometri", "Est del Sole: spesso serale · ovest: spesso mattutino"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/elongazione/"}]}, {"id": "energia", "name": "Energia", "definition": "L’energia è una grandezza fisica che permette di descrivere e confrontare trasformazioni e trasferimenti; non è sinonimo di potenza o temperatura.", "example": "1 watt = 1 joule al secondo", "source": "https://www.treccani.it/enciclopedia/energia/", "lesson": "lezione-4-1.html", "related": ["luminosita", "fotone", "gravitazione"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Seguire le trasformazioni", "paragraphs": ["In astronomia osserviamo materia in movimento, radiazione emessa e sistemi che cambiano. L’energia permette di collegare questi processi in un bilancio fisico. Non è una sostanza luminosa che si vede sempre direttamente e non è una parola da aggiungere a un fenomeno per renderlo misterioso. Nel descrivere un evento occorre specificare quale forma si considera e come la quantità venga trasferita o ricostruita."]}, {"title": "Potenza significa energia nel tempo", "paragraphs": ["Se una sorgente emette 10 joule ogni secondo, la sua potenza è 10 watt. In tre secondi, mantenendo lo stesso ritmo, emette 30 joule. Il joule misura energia e il watt energia per unità di tempo. Questa distinzione chiarisce la luminosità di una stella e il funzionamento di una posa fotografica: accumulare più a lungo non significa necessariamente che la sorgente sia diventata più potente."]}, {"title": "Gravità e stelle", "paragraphs": ["La contrazione gravitazionale può liberare energia e riscaldare materiale; la fusione nucleare alimenta determinate fasi stellari. Non sono lo stesso meccanismo. La luce che riceviamo dipende inoltre da distanza, direzione e assorbimento. Una stella apparentemente debole può emettere una grande potenza totale, mentre una sorgente vicina può dominare il cielo senza essere la più energetica in assoluto."]}, {"title": "Il numero richiede un contesto", "paragraphs": ["L’energia di un singolo fotone dipende dalla frequenza, ma un fascio contiene molti fotoni. Un’esplosione va descritta distinguendo energia totale, durata, bande e altre componenti come particelle. Un’immagine molto contrastata non misura direttamente il bilancio energetico. La divulgazione può evitare passaggi matematici complessi conservando questa domanda semplice: quanta energia, in quale forma, durante quale intervallo e ricevuta da chi?"]}], "facts": ["1 watt = 1 joule al secondo", "Energia ≠ potenza ≠ temperatura"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/energia/"}]}, {"id": "equatore-celeste", "name": "Equatore celeste", "definition": "Cerchio massimo della sfera celeste ottenuto prolungando il piano dell’equatore terrestre.", "example": "La declinazione si misura rispetto a questo cerchio, non rispetto all’orizzonte locale.", "source": "https://www.treccani.it/enciclopedia/coordinate/", "lesson": "lezione-1-6.html", "related": ["declinazione", "polo-celeste"], "checked": "2026-10-30", "sections": [{"title": "Il piano terrestre prolungato nel cielo", "paragraphs": ["L’equatore celeste è il cerchio massimo che otteniamo intersecando la sfera celeste con il piano dell’equatore terrestre. Non è un anello materiale nello spazio: è un riferimento geometrico. I poli celesti sono perpendicolari a quel piano e corrispondono al prolungamento dell’asse di rotazione terrestre. Pensare insieme a piano e asse evita di orientare il sistema equatoriale rispetto a un arbitrario bordo della pagina."]}, {"title": "La linea da cui si misura la declinazione", "paragraphs": ["L’equatore celeste ha declinazione zero. Le direzioni a nord hanno declinazioni positive, quelle a sud negative. L’ascensione retta individua invece la posizione lungo questo riferimento, con le condizioni del sistema adottato. I paralleli di declinazione sono cerchi di dimensione diversa: quelli vicini ai poli sono piccoli. Una stessa differenza di ascensione retta non rappresenta perciò la stessa separazione angolare lungo tutti i paralleli."]}, {"title": "Perché non coincide con l’orizzonte", "paragraphs": ["L’orizzonte è perpendicolare alla verticale locale dell’osservatore e cambia orientamento sulla Terra. L’equatore celeste si riferisce invece al piano equatoriale terrestre. Da latitudini diverse lo vediamo inclinato diversamente rispetto al nostro paesaggio. Nel modello geometrico semplice, dall’equatore terrestre passa attraverso lo zenit; ai poli terrestri coincide con il piano dell’orizzonte. Alle latitudini intermedie i due cerchi si incontrano nei punti est e ovest."]}, {"title": "Il rapporto con l’eclittica", "paragraphs": ["Il piano dell’orbita terrestre non coincide con quello dell’equatore. Di conseguenza l’eclittica e l’equatore celeste sono inclinati fra loro di circa 23,4°. Le loro intersezioni sono i punti equinoziali. Nel disegno si deve indicare a quale piano si riferisce un’inclinazione: i 23,4° non sono l’angolo che l’asse polare di una montatura forma ovunque con il terreno. Quell’angolo, nell’emisfero nord, è legato alla latitudine del luogo. Il riferimento equatoriale preciso va associato anche al sistema e all’epoca usati."]}], "facts": ["Declinazione dell’equatore celeste: 0°", "Non coincide generalmente con l’orizzonte locale", "Equatore celeste ed eclittica: circa 23,4° fra i piani"], "sources": [{"title": "Treccani · riferimento della voce", "url": "https://www.treccani.it/enciclopedia/coordinate/"}, {"title": "USNO · riferimenti celesti", "url": "https://aa.usno.navy.mil/faq/ICRS_doc"}], "editorialStatus": "scheda-estesa"}, {"id": "equinozio", "name": "Equinozio", "definition": "Un equinozio è l’istante in cui il Sole attraversa l’equatore celeste nel suo percorso apparente annuale; il termine indica anche il corrispondente punto d’intersezione con l’eclittica.", "example": "Marzo e settembre hanno stagioni opposte nei due emisferi", "source": "https://www.treccani.it/enciclopedia/equinozio/", "lesson": "lezione-2-2.html", "related": ["punto-equinoziale", "eclittica", "solstizio"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "L’incrocio di due riferimenti", "paragraphs": ["L’equatore celeste è la proiezione del piano equatoriale terrestre, mentre l’eclittica descrive il percorso apparente annuale del Sole nel modello introduttivo. I due cerchi si intersecano in due direzioni opposte. Il passaggio del Sole da sud a nord dell’equatore celeste identifica l’equinozio di marzo; quello opposto l’equinozio di settembre. Parlare di un incrocio non significa che il Sole attraversi fisicamente una linea dipinta nello spazio."]}, {"title": "Le stagioni hanno nomi opposti nei due emisferi", "paragraphs": ["Marzo avvia la primavera astronomica boreale e l’autunno australe; settembre inverte la situazione. Non è corretto usare primavera come etichetta universale senza specificare l’emisfero. Anche data e ora dell’evento cambiano con l’anno e con il riferimento temporale scelto. Le date scolastiche sono promemoria approssimati, non sostituiscono un’effemeride quando si vuole indicare l’istante di un evento reale."]}, {"title": "Giorno e notte: una quasi uguaglianza", "paragraphs": ["Il nome richiama l’equilibrio fra luce e buio, ma nella pratica la durata fra alba e tramonto non è esattamente dodici ore ovunque al giorno dell’equinozio. Contano rifrazione atmosferica, dimensione del disco solare e convenzioni per il sorgere e il tramontare. Questo non annulla il significato geometrico dell’evento. Spiega invece perché una tabella locale possa mostrare una durata del giorno leggermente diversa dall’immagine ideale proposta nel disegno."]}, {"title": "Un punto utile anche per le coordinate", "paragraphs": ["Il punto equinoziale di marzo è l’origine tradizionale dell’ascensione retta nel sistema equatoriale classico. La precessione ne cambia lentamente la direzione rispetto alle stelle, motivo per cui riferimenti ed epoche dei cataloghi vanno dichiarati. Il collegamento fra stagioni e coordinate è quindi geometrico. Non significa che le stelle di una costellazione abbiano il compito fisico di provocare la stagione o che i segni astrologici coincidano con le regioni ufficiali del cielo."]}], "facts": ["Marzo e settembre hanno stagioni opposte nei due emisferi", "Equinozio non garantisce esattamente dodici ore fra alba e tramonto"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/equinozio/"}], "aliases": ["equinozi"]}, {"id": "fase-lunare", "name": "Fase lunare", "definition": "La fase lunare descrive la porzione dell’emisfero illuminato della Luna che vediamo dalla Terra, secondo la geometria Sole–Luna–osservatore.", "example": "Le fasi non sono causate dall’ombra terrestre", "source": "https://www.treccani.it/enciclopedia/fase/", "lesson": "lezione-2-4.html", "related": ["eclissi", "terminatore", "luna"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La Luna non si accende a pezzi", "paragraphs": ["Il Sole illumina circa metà della Luna in condizioni ordinarie. Durante il moto orbitale cambia la parte di quell’emisfero che vediamo dalla Terra. La fase riguarda quindi un aspetto prospettico dell’illuminazione, non la materia che cresce o scompare. L’ombra terrestre non produce le normali fasi: entra in gioco nelle eclissi lunari, che richiedono un allineamento particolare e non avvengono a ogni giro."]}, {"title": "Nuova, quarti e piena", "paragraphs": ["In prossimità della Luna nuova osserviamo soprattutto il lato notturno rivolto verso di noi; alla piena il disco visibile è quasi completamente illuminato. Ai quarti vediamo circa metà del disco illuminata, non un quarto della sua area. Il nome riguarda la posizione nel ciclo. Il lato che appare crescente o calante cambia orientamento nella vista locale, quindi una sagoma girata senza contesto non basta a fissare una regola universale destra–sinistra."]}, {"title": "Un ciclo da distinguere dalla rotazione", "paragraphs": ["Il ritorno alla stessa fase, o mese sinodico, dura circa 29 giorni e mezzo. Il periodo della Luna rispetto alle stelle è più breve: durante il giro anche la Terra si sposta attorno al Sole. Questi intervalli non sono identici alla durata di tutti i mesi del calendario civile. Anche l’istante della fase riportato in effemeride richiede un fuso: la data visualizzata può cambiare fra territori diversi."]}, {"title": "Osservare il rilievo", "paragraphs": ["Vicino al terminatore la luce radente mette in risalto crateri e montagne attraverso le ombre. Alla piena si vedono bene differenze di riflettività e strutture come raggi chiari, ma il rilievo può apparire meno contrastato. Non esiste quindi un’unica fase migliore per ogni osservazione. Nel diario registra fase, ora e regione studiata, distinguendo l’immagine geometrica della fase dai dettagli reali della superficie."]}], "facts": ["Le fasi non sono causate dall’ombra terrestre", "Quarto: circa metà del disco illuminata"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/fase/"}]}, {"id": "focale", "name": "Focale", "definition": "La lunghezza focale è una proprietà del sistema ottico che determina la scala dell’immagine e, con oculare o sensore, il modo in cui la osserviamo.", "example": "800 mm / 20 mm = 40×", "source": "https://www.treccani.it/enciclopedia/focale/", "lesson": "lezione-7-4.html", "related": ["fuoco", "ingrandimento", "obiettivo"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Una distanza ottica, non sempre la lunghezza del tubo", "paragraphs": ["La focale collega la geometria del sistema alla formazione dell’immagine. Per una lente sottile si può immaginare come la distanza dalla lente al fuoco per raggi paralleli. In sistemi composti il riferimento corretto coinvolge i punti principali, perciò non coincide necessariamente con la misura del tubo. Un telescopio compatto può avere una focale molto più lunga del suo ingombro."]}, {"title": "Con un oculare", "paragraphs": ["L’ingrandimento visuale si ottiene dividendo la focale del telescopio per quella dell’oculare. Con 800 mm e un oculare da 20 mm si hanno 40 volte; con 10 mm se ne hanno 80. Le unità devono essere le stesse e si cancellano nel rapporto. Cambia la dimensione angolare apparente dell’immagine, non l’apertura che raccoglie luce. Un ingrandimento maggiore può essere poco utile se l’immagine è già limitata da seeing o qualità ottica."]}, {"title": "Con un sensore", "paragraphs": ["A parità di sensore, una focale più lunga inquadra una porzione più piccola di cielo e rende più evidente il movimento angolare nell’immagine. Il campo dipende però anche dalle dimensioni del sensore, non dalla sola focale. Dire che un’ottica è grandangolare senza indicare il formato può risultare ambiguo. Riduttori e moltiplicatori cambiano la focale effettiva e richiedono distanze e compatibilità previste dal progetto."]}, {"title": "Rapporto focale e obiettivo della ripresa", "paragraphs": ["Dividendo focale per apertura si ottiene il rapporto focale: 600 mm su 100 mm dà f/6. Questo numero non è l’ingrandimento visuale. Nella fotografia di soggetti estesi entra nella raccolta del segnale per unità di area sul sensore, ma non riassume da solo tutte le prestazioni. Campo, campionamento, trasmissione e stabilità devono restare nella descrizione. Scegliere una focale significa scegliere anche una scala di lavoro e le difficoltà che la accompagnano."]}], "facts": ["800 mm / 20 mm = 40×", "Focale del sistema ≠ necessariamente lunghezza del tubo"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/focale/"}, {"title": "OpenStax · telescopi", "url": "https://openstax.org/books/astronomy-2e/pages/6-1-telescopes"}], "aliases": ["lunghezza focale", "distanza focale"]}, {"id": "fotometria", "name": "Fotometria astronomica", "definition": "La fotometria astronomica misura la radiazione ricevuta dalle sorgenti in bande e condizioni definite, per confrontarne flusso e variazioni.", "example": "Banda e calibrazione fanno parte della misura", "source": "https://www.treccani.it/enciclopedia/fotometria/", "lesson": "lezione-4-2.html", "related": ["magnitudine-apparente", "luminosita", "spettro"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Misurare quanta luce arriva", "paragraphs": ["Una fotografia può essere usata per raccontare una scena oppure per misurare un segnale. La fotometria pone al centro la seconda domanda: quanto flusso arriva e come varia? Il risultato richiede una banda definita e una procedura calibrata. In fisica il termine include anche grandezze legate alla sensibilità visiva umana; nell’astronomia il contesto e il sistema fotometrico devono quindi essere chiari."]}, {"title": "Non si contano soltanto i pixel più bianchi", "paragraphs": ["Il segnale di una sorgente va distinto dal fondo cielo e dalle risposte dello strumento. Saturazione, esposizione, sensibilità, pixel difettosi e variazioni atmosferiche influenzano la misura. Una stella può apparire più grande perché più brillante senza avere un diametro angolare risolto. Per il confronto si considera il segnale raccolto con una procedura coerente, non il numero di pixel che sembrano accesi dopo un’elaborazione estetica."]}, {"title": "Confronti nella stessa immagine", "paragraphs": ["Con sorgenti di confronto adeguate si possono seguire variazioni relative, controllando i limiti del metodo. Una curva di luce riporta il segnale nel tempo e aiuta a studiare variabili, eclissi o possibili transiti. Un calo singolo non identifica automaticamente un pianeta: nubi, errori di misura o altri fenomeni possono produrre variazioni. Servono ripetibilità, controlli e interpretazione fisica."]}, {"title": "La banda fa parte del dato", "paragraphs": ["Due stelle possono avere un rapporto di brillantezza diverso in filtri differenti perché i loro spettri non sono uguali. Una magnitudine senza banda può essere insufficiente per un confronto preciso. Anche trasformare una foto a colori in bianco e nero non crea automaticamente una misura in una banda standard. Per una prima esperienza divulgativa basta distinguere immagine illustrativa, conteggio di segnale e misura calibrata: sono livelli diversi, tutti utili se dichiarati correttamente."]}], "facts": ["Banda e calibrazione fanno parte della misura", "Curva di luce: segnale misurato in funzione del tempo"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/fotometria/"}]}, {"id": "fotone", "name": "Fotone", "definition": "Il fotone è il quanto della radiazione elettromagnetica: l’energia di un singolo fotone è legata alla frequenza della radiazione.", "example": "Fotone blu: energia individuale maggiore di un fotone rosso", "source": "https://www.treccani.it/enciclopedia/fotone/", "lesson": "lezione-4-3.html", "related": ["spettro", "radiazione", "temperatura"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un modo necessario di descrivere la luce", "paragraphs": ["La luce presenta fenomeni spiegati dalla descrizione ondulatoria e interazioni che richiedono una descrizione quantistica. Il fotone non è semplicemente una pallina colorata con una superficie. È il quanto del campo elettromagnetico. Nei disegni i puntini che viaggiano verso il sensore rappresentano eventi o pacchetti di energia per aiutare la comprensione; non sono una fotografia ingrandita della forma fisica di un fotone."]}, {"title": "Energia e colore", "paragraphs": ["La frequenza indica quante oscillazioni corrispondono a un intervallo di tempo. Un fotone a frequenza maggiore ha energia maggiore. Nel visibile, un fotone blu porta più energia di uno rosso, ma un fascio rosso può trasportare più potenza complessiva se contiene un numero sufficientemente maggiore di fotoni. Non si può quindi dedurre l’energia totale ricevuta dal solo colore senza considerare anche il numero di eventi e l’intervallo temporale."]}, {"title": "Perché contare conta in fotografia", "paragraphs": ["Un sensore converte una parte dei fotoni incidenti in un segnale misurabile. Quando il flusso è debole, il numero di eventi registrati fluttua statisticamente. Esposizioni e integrazione permettono di accumulare informazione, ma restano fondo cielo, rumore strumentale e limiti del dispositivo. Moltiplicare digitalmente i valori di una fotografia già registrata non equivale a raccogliere nuovi fotoni dal bersaglio."]}, {"title": "Il legame con lo spettro", "paragraphs": ["Atomi e molecole possono assorbire o emettere radiazione in corrispondenza di differenze energetiche specifiche. Le righe spettrali diventano così indizi sulla materia. I fotoni che arrivano possono aver attraversato gas, polveri e campi gravitazionali; il segnale va interpretato nel suo percorso. L’idea del messaggero è evocativa, purché non suggerisca un cartellino individuale che contenga già nome, distanza e temperatura della sorgente senza bisogno di misure."]}], "facts": ["Fotone blu: energia individuale maggiore di un fotone rosso", "Amplificare i pixel non significa raccogliere altri fotoni"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/fotone/"}]}, {"id": "frequenza", "name": "Frequenza", "definition": "La frequenza indica quanti cicli di un fenomeno periodico si ripetono nell’unità di tempo; si misura in hertz, cioè cicli al secondo.", "example": "Hertz = cicli al secondo", "source": "https://www.treccani.it/enciclopedia/frequenza/", "lesson": "lezione-4-3.html", "related": ["lunghezza-d-onda", "spettro", "fotone"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Contare ripetizioni, non misurare una distanza", "paragraphs": ["Un’oscillazione che si ripete due volte in un secondo ha frequenza di due hertz. Una che si ripete una volta ogni due secondi ha frequenza di mezzo hertz. Il periodo è invece il tempo necessario per un ciclo. Le due grandezze sono collegate ma non intercambiabili: una frequenza più alta corrisponde a un periodo più breve. Questo linguaggio descrive onde e molti fenomeni variabili, non soltanto il suono."]}, {"title": "La relazione con la lunghezza d’onda", "paragraphs": ["Per un’onda che si propaga con una certa velocità, frequenza e lunghezza d’onda sono collegate: la velocità è il prodotto fra le due. Nel vuoto la luce mantiene la stessa velocità, quindi lunghezze d’onda più corte corrispondono a frequenze maggiori. La relazione non dice che la luce blu raggiunga prima il telescopio perché oscilla più rapidamente. Occorre distinguere velocità di propagazione e ritmo delle oscillazioni."]}, {"title": "L’energia del fotone è un’altra informazione", "paragraphs": ["Nella descrizione quantistica l’energia di un singolo fotone cresce con la frequenza. Questo non significa che una sorgente blu sia sempre più luminosa in totale di una rossa. L’energia complessiva ricevuta dipende anche da quanti fotoni arrivano e dalla loro distribuzione nello spettro. Una figura corretta deve quindi separare frequenza, energia per fotone e quantità totale di radiazione, invece di usare un unico cursore chiamato genericamente potenza."]}, {"title": "Leggere uno spettro", "paragraphs": ["Un grafico può usare frequenza o lunghezza d’onda sull’asse orizzontale. Passare dall’una all’altra non è soltanto cambiare il nome dell’asse, perché le scale e le densità spettrali vanno trasformate coerentemente. Per una prima lettura identifica unità e direzione di crescita. Una riga spostata verso frequenze minori corrisponde a lunghezze d’onda maggiori, nel confronto appropriato. Imparare questo collegamento rende più comprensibile il redshift senza introdurre subito calcoli avanzati."]}], "facts": ["Hertz = cicli al secondo", "Nel vuoto, frequenza maggiore significa lunghezza d’onda minore"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/frequenza/"}], "aliases": ["frequenze"]}, {"id": "fuoco", "name": "Fuoco ottico", "definition": "Il fuoco e il piano focale descrivono dove un sistema ottico forma l’immagine di sorgenti lontane.", "example": "Mettere a fuoco non significa aumentare l’ingrandimento", "source": "https://www.treccani.it/enciclopedia/fuoco_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-7-3.html", "related": ["focale", "obiettivo", "seeing"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il luogo in cui l’immagine prende forma", "paragraphs": ["In un sistema convergente ideale, raggi paralleli all’asse vengono raccolti nel fuoco. Per una scena estesa come un campo stellare, ogni direzione forma la propria immagine: si parla quindi di piano o superficie focale, non di tutte le stelle ammassate in un unico punto. Mettere a fuoco significa far coincidere il rivelatore, o la condizione corretta per l’osservazione con oculare, con l’immagine prodotta dal sistema."]}, {"title": "Che cosa muove il focheggiatore", "paragraphs": ["Girando la manopola si modifica la posizione di un elemento o del gruppo che riceve l’immagine, secondo il progetto del telescopio. Una stella fuori fuoco appare allargata; in certi strumenti può mostrare anche l’ombra del secondario. Non stiamo vedendo crescere il diametro reale della stella. Il controllo pratico consiste nel cercare l’immagine più concentrata compatibile con atmosfera e ottica, senza scambiare ogni fluttuazione per un errore del focheggiatore."]}, {"title": "Perché il controllo va ripetuto", "paragraphs": ["Temperatura, variazioni meccaniche, filtri e cambiamenti del corredo possono modificare il punto ottimale. Un’immagine a fuoco all’inizio non garantisce che resti tale per tutta la notte. Per la fotografia conviene controllare il risultato sul sensore e non soltanto sul mirino. Una maschera di messa a fuoco può fornire un riferimento, ma richiede interpretazione e va rimossa prima delle riprese scientifiche o estetiche."]}, {"title": "Quello che il fuoco non può correggere", "paragraphs": ["Una regolazione accurata non elimina turbolenza, aberrazioni, mosso o disallineamento ottico. Se il centro del campo è nitido ma i bordi non lo sono, il problema può riguardare la superficie focale o altri aspetti del sistema. Se tutto si muove rapidamente, può dominare il seeing. Distinguere i sintomi evita di inseguire continuamente la manopola quando la causa dell’immagine instabile si trova invece nell’aria, nel supporto o nel progetto ottico."]}], "facts": ["Mettere a fuoco non significa aumentare l’ingrandimento", "Fuoco corretto e atmosfera stabile sono condizioni differenti"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/fuoco_(Dizionario-delle-Scienze-Fisiche)/"}], "archiveReferences": ["Fulvio Mete, pagina PDF 54: distinzione fra seeing, adattamento termico e allineamento; non sono riprodotte istruzioni di intervento meccanico."], "aliases": ["fuoco"]}, {"id": "galassia", "name": "Galassia", "definition": "Grande sistema gravitazionale di stelle, generalmente accompagnate da gas e polveri.", "example": "La Via Lattea è la galassia di cui fa parte il Sole. Una nebulosa è un oggetto di natura e scala differenti.", "source": "https://www.treccani.it/enciclopedia/galassia/", "lesson": "lezione-6-1.html", "related": ["nebulosa", "stella"], "checked": "2026-10-30", "sections": [{"title": "Un ambiente di stelle, gas e polveri", "paragraphs": ["Una galassia è un grande sistema gravitazionale che comprende stelle e, in misura variabile, gas e polveri. Il Sole appartiene alla Via Lattea. Una galassia non è una costellazione: la costellazione organizza le direzioni del nostro cielo, mentre la galassia è un sistema fisico. Guardare Andromeda significa osservare un’altra galassia, non un ammasso di stelle della Via Lattea che si trova casualmente nella regione omonima."]}, {"title": "Forme diverse, senza una scala evolutiva automatica", "paragraphs": ["Le classificazioni morfologiche distinguono, fra gli altri tipi, galassie ellittiche, lenticolari, spirali, spirali barrate e irregolari. Un disco visto di taglio può nascondere le proprie braccia; una stessa struttura osservata con un’altra inclinazione cambia molto aspetto. La sequenza grafica dei tipi non deve essere letta come il percorso obbligatorio che ogni galassia compie crescendo: descrizione della forma e ricostruzione dell’evoluzione sono problemi differenti."]}, {"title": "Perché la fotografia non mostra tutto", "paragraphs": ["Una ripresa in luce visibile mette in evidenza alcune componenti; infrarosso, ultravioletto, radio e raggi X possono raccontarne altre. Polveri, stelle giovani, gas caldo e nuclei attivi non emergono nello stesso modo. Anche il colore può dipendere dai filtri e dalla composizione dell’immagine. Quando il soggetto è debole, la brillantezza distribuita su una grande superficie conta per l’osservazione: la magnitudine totale da sola non dice quanto facilmente distinguerai le parti diffuse."]}, {"title": "La dinamica aggiunge la profondità fisica", "paragraphs": ["Per comprendere una galassia si misurano anche distanze, velocità e distribuzione della materia. I moti non si ricavano facendo ruotare arbitrariamente una fotografia come fosse un disco rigido. Le regioni possono avere comportamenti differenti, e una simulazione divulgativa deve dichiarare il modello usato. La gravità collega i componenti, ma una figura statica non dimostra da sola quali stelle siano legate o quanta materia sia presente. Le immagini aprono la domanda; dati e confronti permettono di costruire la spiegazione."]}], "facts": ["La Via Lattea è la nostra galassia", "Morfologia, orientamento e storia sono aspetti distinti", "Una galassia non è una costellazione né una nebulosa"], "sources": [{"title": "Treccani · riferimento della voce", "url": "https://www.treccani.it/enciclopedia/galassia/"}, {"title": "NASA · tipi di galassie", "url": "https://science.nasa.gov/universe/galaxies/types/"}, {"title": "NASA · lettura delle galassie", "url": "https://science.nasa.gov/universe/galaxies/"}], "editorialStatus": "scheda-estesa", "media": {"file": "assets/lezioni/m51-struttura-galassia.jpg", "caption": "M51: una galassia a spirale. La foto contiene strutture e popolazioni stellari, non una singola nube interstellare.", "credit": "NASA, ESA, S. Beckwith (STScI), Hubble Heritage Team (STScI/AURA)", "source": "https://esahubble.org/images/heic0506a/", "license": "CC BY 4.0"}, "aliases": ["galassie"]}, {"id": "giorno-siderale", "name": "Giorno siderale", "definition": "Il giorno siderale medio dura circa 23 ore, 56 minuti e 4 secondi di tempo solare medio: usa un riferimento celeste diverso dal Sole.", "example": "Circa 23 h 56 min 4 s", "source": "https://www.treccani.it/enciclopedia/tempo_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-2-1.html", "related": ["angolo-orario", "ora-civile", "sfera-celeste"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Due ritorni che non coincidono", "paragraphs": ["Possiamo seguire la rotazione terrestre rispetto al riferimento stellare oppure rispetto al Sole. Nel linguaggio introduttivo il giorno siderale descrive il ritorno del cielo stellato, mentre la definizione classica precisa usa il passaggio del punto equinoziale al meridiano. La durata media è circa 23 h 56 min 4 s di tempo solare medio, un poco meno delle 24 ore della giornata ordinaria."]}, {"title": "Da dove vengono i quattro minuti", "paragraphs": ["Mentre ruota, la Terra si sposta anche lungo l’orbita attorno al Sole. Dopo un giro rispetto alle stelle deve ruotare ancora un poco perché il Sole torni sullo stesso meridiano. Una piccola differenza angolare corrisponde quindi a una differenza di tempo. Non significa che un orologio perda quattro minuti ogni giorno: abbiamo scelto due riferimenti differenti per descrivere il ritorno. Il confronto deve mantenere costanti le convenzioni temporali."]}, {"title": "Una stella ritorna prima", "paragraphs": ["Se una stella attraversa una certa direzione alle 22:00, il giorno successivo torna approssimativamente nella stessa posizione alle 21:56, ignorando correzioni piccole e cambi di ora legale. Alla stessa ora civile apparirà quindi un poco più avanzata nel proprio percorso. Durante una singola notte il cambiamento avviene invece continuamente ora dopo ora. Sono due confronti diversi: intervalli nella stessa notte e ritorni da una sera alla successiva."]}, {"title": "Perché serve nella pratica", "paragraphs": ["Il moto siderale è il riferimento usuale per l’inseguimento delle stelle. Luna e Sole hanno moti propri apparenti diversi e possono richiedere velocità specifiche. Nel leggere valori molto precisi occorre distinguere tempo siderale medio, apparente e altri riferimenti della rotazione terrestre. Per la divulgazione bastano le durate arrotondate e il motivo della differenza, senza trasformare l’approssimazione dei quattro minuti in una legge esatta per ogni corpo e per ogni orologio."]}], "facts": ["Circa 23 h 56 min 4 s", "Il cielo stellato anticipa di circa quattro minuti per giorno"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/tempo_(Dizionario-delle-Scienze-Fisiche)/"}, {"title": "Treccani · lezione sulla Terra, confronto dei riferimenti", "url": "https://static.treccani.it/export/sites/default/Portale/resources/multimedia/Lezioni_Astrofisica/Terra/LEZIONE_Terra.pdf"}], "archiveReferences": ["Marco Monaci, pagina PDF 21, confrontata con SAIt, Bignamino, pagina PDF 57. La frase sul giorno solare vero esattamente di 24 ore non è stata adottata."]}, {"id": "grado-angolare", "name": "Grado angolare", "definition": "Il grado sessagesimale è un’unità di angolo: un giro completo ne contiene 360 e un angolo retto 90.", "example": "1 giro = 360°", "source": "https://www.treccani.it/enciclopedia/grado/", "lesson": "lezione-1-1.html", "related": ["secondo-d-arco", "altezza-angolare", "azimut"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Misurare una direzione, non una lunghezza", "paragraphs": ["Due stelle possono essere separate da alcuni gradi nel cielo anche se le loro distanze dalla Terra sono molto diverse. L’angolo descrive quanto dobbiamo ruotare lo sguardo fra le due direzioni. Non dice quanti chilometri ci siano fra gli oggetti. Anche un piccolo corpo vicino e uno enorme ma lontano possono occupare lo stesso angolo apparente: per ricavare una dimensione fisica serve un’informazione aggiuntiva sulla distanza."]}, {"title": "Il cielo come confronto di ampiezze", "paragraphs": ["Dall’orizzonte geometrico allo zenit ci sono novanta gradi lungo un cerchio verticale. Un giro completo di azimut ne comprende 360. Il disco della Luna occupa all’incirca mezzo grado, con variazioni della dimensione apparente. Questi esempi aiutano a costruire una scala mentale. Le misure fatte con la mano a braccio disteso sono stime personali utili, ma non devono essere presentate come strumenti angolari di precisione identici per ogni osservatore."]}, {"title": "Primi, secondi e decimali", "paragraphs": ["Un grado contiene sessanta primi d’arco e ciascun primo sessanta secondi d’arco. Quindi un grado contiene 3.600 secondi d’arco. Nella scrittura decimale mezzo grado è 0,5 gradi; nella scrittura sessagesimale è trenta primi. Non si deve leggere trenta primi come trenta centesimi di grado. Le unità accanto ai numeri evitano errori quando si passa da una carta a un’applicazione o si copiano coordinate nel diario."]}, {"title": "Le ore dell’ascensione retta sono un’altra notazione", "paragraphs": ["Nel sistema equatoriale, ventiquattro ore di ascensione retta coprono un giro completo, quindi un’ora corrisponde a quindici gradi. Si tratta di una misura angolare espressa in unità orarie, non del tempo necessario per raggiungere una stella. Le formule e le interfacce devono distinguere ore di coordinate e ore civili. Nel disegno, etichette e colori vicino agli archi rendono visibile quale angolo stiamo leggendo e da dove viene contato."]}], "facts": ["1 giro = 360°", "1° = 60′ = 3.600″"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/grado/"}]}, {"id": "gravitazione", "name": "Gravitazione", "definition": "La gravitazione governa l’interazione fra masse nella descrizione newtoniana; in relatività generale viene descritta attraverso la geometria dello spaziotempo.", "example": "Distanza doppia → forza gravitazionale un quarto", "source": "https://www.treccani.it/enciclopedia/gravitazione/", "lesson": "lezione-3-6.html", "related": ["massa", "orbita", "buco-nero"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La stessa domanda dalla Terra al cielo", "paragraphs": ["Un oggetto lasciato libero cade verso il suolo e la Luna percorre un’orbita attorno alla Terra. La gravitazione collega fenomeni che sembrano molto diversi. Nella descrizione newtoniana due masse si attraggono lungo la direzione che le congiunge. La Terra non è un riferimento privilegiato di questa legge: la stessa idea permette di studiare sistemi planetari e moti stellari, entro le condizioni in cui l’approssimazione è adeguata."]}, {"title": "La legge spiegata nei suoi rapporti", "paragraphs": ["La forza cresce con ciascuna massa e diminuisce con il quadrato della distanza fra i centri, nel caso di corpi sferici separati o masse puntiformi. Tenendo ferme le altre condizioni, raddoppiare una massa raddoppia la forza. Raddoppiare la distanza la riduce a un quarto, perché due per due fa quattro. La costante G rende coerenti quantità e unità; non è il valore locale g dell’accelerazione di gravità al suolo."]}, {"title": "Perché un corpo in orbita non cade diritto", "paragraphs": ["La gravità modifica la velocità, ma la traiettoria dipende anche dalla velocità iniziale. Una componente laterale può far sì che il corpo continui a cadere attorno al corpo centrale senza urtarlo, nel modello ideale. Non occorre immaginare una spinta costante del motore che lo sorregga. La gravità non scompare nello spazio: l’assenza apparente di peso degli astronauti in orbita si collega alla caduta libera comune di persone e veicolo."]}, {"title": "Dove serve una descrizione più ampia", "paragraphs": ["La relatività generale estende il quadro e diventa essenziale per campi intensi, precisioni elevate e fenomeni come la deviazione della luce. Un modello elementare può essere utilissimo senza descrivere ogni regime. La correttezza sta anche nel dichiarare i limiti. Un telo elastico può evocare una geometria curva, ma non è una prova fisica completa né spiega da solo perché i corpi si muovano: è un’analogia da interpretare."]}], "facts": ["Distanza doppia → forza gravitazionale un quarto", "G universale ≠ g locale"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/gravitazione/"}]}, {"id": "ingrandimento", "name": "Ingrandimento", "definition": "L’ingrandimento angolare indica quanto aumenta l’angolo sotto cui osserviamo un soggetto attraverso lo strumento.", "example": "Ingrandimento visuale = focale telescopio / focale oculare", "source": "https://www.treccani.it/enciclopedia/ingrandimento/", "lesson": "lezione-7-4.html", "related": ["focale", "telescopio", "diffrazione"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Rendere grande non significa aggiungere informazione", "paragraphs": ["Quando un telescopio mostra la Luna a 50 ingrandimenti, la dimensione angolare osservata attraverso l’oculare è circa cinquanta volte quella a occhio nudo, nel modello appropriato. Non siamo cinquanta volte più vicini fisicamente. L’immagine viene presentata su una scala maggiore, ma i dettagli disponibili dipendono prima di tutto dall’apertura, dalla qualità del sistema e dalle condizioni atmosferiche."]}, {"title": "La divisione utile", "paragraphs": ["Per il consueto telescopio con oculare, dividi la focale del telescopio per quella dell’oculare. Un tubo da 1.200 mm con un oculare da 24 mm offre 50×; con uno da 12 mm offre 100×. Si usano le stesse unità per entrambe le focali. Un moltiplicatore o un diverso treno ottico possono modificare il valore effettivo, che va quindi ricavato dalla configurazione realmente impiegata."]}, {"title": "La prova davanti a un pianeta", "paragraphs": ["Aumentando l’ingrandimento Giove diventa più grande, ma può apparire più debole e meno stabile. Se la turbolenza cancella i dettagli, la scala maggiore ingrandisce anche il disturbo. Il valore migliore non è sempre il massimo disponibile: conviene partire moderatamente e aumentare finché l’immagine conserva informazione utile. Il campo reale inquadrato può restringersi, rendendo più difficile mantenere il bersaglio con un supporto manuale."]}, {"title": "Non confonderlo con lo zoom sullo schermo", "paragraphs": ["In una fotografia l’aspetto dipende da focale, pixel, dimensione dell’immagine e distanza di osservazione dello schermo. Un generico “ingrandimento della foto” non è una proprietà unica del telescopio. Lo zoom digitale mostra gli stessi campioni più grandi, senza creare automaticamente nuovi dettagli. Per confrontare riprese è più informativo specificare scala angolare per pixel e campo, mentre per l’osservazione visuale resta utile il rapporto fra le focali."]}], "facts": ["Ingrandimento visuale = focale telescopio / focale oculare", "Zoom digitale ≠ nuova risoluzione"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/ingrandimento/"}]}, {"id": "isotropia", "name": "Isotropia", "definition": "L’isotropia è l’indipendenza di una proprietà dalla direzione considerata; bisogna specificare quale proprietà e quale modello si stanno descrivendo.", "example": "Isotropo: nessuna direzione privilegiata per la proprietà considerata", "source": "https://www.treccani.it/enciclopedia/isotropia/", "lesson": "lezione-4-2.html", "related": ["luminosita", "radiazione", "universo"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "La domanda è: cambia se guardo in un’altra direzione?", "paragraphs": ["Una sorgente ideale che emette la stessa potenza per angolo solido in tutte le direzioni è detta isotropa. Non privilegia un fascio o un lato. È un’ipotesi utile per collegare energia emessa e luce ricevuta, ma va dichiarata. Un getto, un disco o un sistema con oscuramenti possono emettere o apparire in modo molto diverso secondo la direzione. La parola isotropia non può essere attribuita automaticamente a ogni oggetto luminoso."]}, {"title": "Perché compare nella legge della distanza", "paragraphs": ["Per una sorgente isotropa in spazio trasparente, l’energia si distribuisce su superfici sferiche sempre più grandi. Raddoppiando la distanza, l’area della sfera diventa quattro volte maggiore e il flusso per unità di area diventa un quarto. Triplicando la distanza diventa un nono. L’esempio spiega la proporzione senza richiedere logaritmi, ma conserva le ipotesi: stessa sorgente, nessun assorbimento aggiuntivo e geometria adatta al modello usato."]}, {"title": "Non significa essere uguali in ogni punto", "paragraphs": ["Isotropia riguarda le direzioni; omogeneità riguarda la posizione. Sono concetti differenti. Un ambiente può avere proprietà che non cambiano orientando una misura in un certo punto, ma cambiano spostandosi altrove. In cosmologia i due termini vengono applicati su scale e con criteri specifici, non al dettaglio di ogni stella. La presenza di strutture locali non si valuta semplicemente confrontando due fotografie scelte a caso nel cielo."]}, {"title": "Come usarla in una spiegazione divulgativa", "paragraphs": ["Accanto alla formula del flusso scrivi che cosa si suppone e quale grandezza viene distribuita. Il disegno di sfere concentriche serve a mostrare aree crescenti, non gusci materiali che trattengono la luce. I valori devono stare accanto alle distanze o alle superfici corrispondenti. Il lettore può così ricostruire il ragionamento: stessa energia totale, area maggiore, meno energia ricevuta da ogni metro quadrato. Una parola tecnica diventa allora una condizione comprensibile del modello."]}], "facts": ["Isotropo: nessuna direzione privilegiata per la proprietà considerata", "Distanza doppia → flusso un quarto, nelle ipotesi del modello"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/isotropia/"}], "aliases": ["isotropa", "isotropo"]}, {"id": "kelvin", "name": "Kelvin", "definition": "Il kelvin, simbolo K, è l’unità del Sistema Internazionale per la temperatura termodinamica.", "example": "20 °C = 293,15 K", "source": "https://www.treccani.it/enciclopedia/kelvin_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-4-3.html", "related": ["temperatura", "stella", "radiazione"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La scala assoluta usata in astrofisica", "paragraphs": ["Quando una stella viene descritta con una temperatura in migliaia di kelvin, il numero non è scritto in gradi Celsius. Il simbolo corretto è K, senza il segno °. La temperatura assoluta rende coerenti molte relazioni fisiche della radiazione e della materia. Non misura direttamente quanta energia totale contiene un oggetto e non elimina la necessità di specificare quale regione della sorgente si stia descrivendo."]}, {"title": "La conversione accessibile", "paragraphs": ["Per ottenere kelvin da gradi Celsius si aggiunge 273,15. Una temperatura di 20 °C corrisponde quindi a 293,15 K. La dimensione dell’intervallo è uguale: un aumento di 10 °C equivale a un aumento di 10 K. I valori di partenza sono però diversi. Dire che 20 °C sia il doppio di 10 °C non esprime un rapporto fisico di temperatura assoluta uguale a quello fra 20 K e 10 K."]}, {"title": "La definizione è stata aggiornata", "paragraphs": ["La definizione moderna del kelvin si basa sul valore fissato della costante di Boltzmann nel Sistema Internazionale riveduto. Le descrizioni storiche riferite alla frazione della temperatura del punto triplo dell’acqua appartengono alla definizione precedente. Rimangono utili per capire la storia della metrologia, ma non vanno presentate come formulazione normativa corrente. Il riferimento attuale in questa scheda è il BIPM."]}, {"title": "Leggere bene un numero stellare", "paragraphs": ["Temperatura efficace, temperatura del gas e temperatura del nucleo non sono la stessa grandezza operativa, anche se tutte possono essere espresse in kelvin. Una fotografia a falsi colori non costituisce da sola una mappa termica calibrata. Il vantaggio dell’unità sta nella coerenza delle relazioni: prima di inserire un numero in una formula occorre sapere sia quale scala usa sia come la temperatura sia stata ricavata."]}], "facts": ["20 °C = 293,15 K", "Simbolo K, senza il segno dei gradi"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/kelvin_(Dizionario-delle-Scienze-Fisiche)/"}, {"title": "BIPM · unità di base SI e ridefinizione", "url": "https://www.bipm.org/en/measurement-units/si-base-units"}]}, {"id": "latitudine", "name": "Latitudine", "definition": "La latitudine geografica indica quanto un luogo si trova a nord o a sud dell’equatore; nel modello terrestre sferico è un angolo compreso fra −90° e +90°.", "example": "Latitudine: nord/sud rispetto all’equatore", "source": "https://www.treccani.it/enciclopedia/latitudine/", "lesson": "lezione-1-2.html", "related": ["longitudine", "polo-celeste", "circumpolare"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un numero per riconoscere la posizione sulla Terra", "paragraphs": ["All’equatore la latitudine è zero; ai poli raggiunge novanta gradi nord o sud. Nelle coordinate con segno si usa generalmente positivo verso nord e negativo verso sud. La misura non dice quanto siamo a est o a ovest: quella è l’altra coordinata, la longitudine. Due località sullo stesso parallelo possono essere molto lontane e avere lo stesso valore di latitudine, pur osservando in orari locali e condizioni ambientali differenti."]}, {"title": "Il collegamento con il polo celeste", "paragraphs": ["Nel modello geometrico introduttivo, l’altezza del polo celeste sull’orizzonte corrisponde al valore della latitudine nell’emisfero pertinente. A circa quarantacinque gradi nord il polo nord celeste è quindi circa quarantacinque gradi sopra il nord dell’orizzonte. La Polare gli è vicina ma non coincide esattamente con esso. Questa relazione spiega perché il cielo circumpolare cambia spostandosi verso nord o verso sud, senza che le costellazioni cambino arbitrariamente declinazione."]}, {"title": "Perché la carta deve conoscere il luogo", "paragraphs": ["La stessa stella può sorgere e tramontare da una località ed essere circumpolare da un’altra. Cambia l’orientamento dell’orizzonte dell’osservatore rispetto all’asse terrestre. Non è necessario che la stella si sposti fisicamente tra una fascia equatoriale e una polare della sfera celeste. Nel laboratorio, variando la latitudine si deve quindi ricalcolare il rapporto tra traiettoria e orizzonte, lasciando coerenti le coordinate del soggetto nel riferimento adottato."]}, {"title": "La precisione oltre il modello sferico", "paragraphs": ["La Terra reale è schiacciata e la geodesia distingue definizioni più accurate, come latitudine geodetica e geocentrica. Per un primo esercizio la sfera è un modello comprensibile, purché dichiarato. Le coordinate fornite da un dispositivo o da un catalogo devono essere usate secondo la documentazione del calcolo. Non aggiungere decimali inventati per dare un’impressione di precisione: indica luogo, convenzione e limiti con un dettaglio proporzionato all’attività proposta."]}], "facts": ["Latitudine: nord/sud rispetto all’equatore", "L’altezza geometrica del polo collega luogo e cielo"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/latitudine/"}], "aliases": ["latitudini"]}, {"id": "librazione", "name": "Librazione", "definition": "La librazione fa variare la parte della superficie lunare visibile dalla Terra, pur restando la Luna in rotazione sincrona in media.", "example": "Circa 59% della superficie accessibile nel tempo", "source": "https://www.treccani.it/enciclopedia/librazione/", "lesson": "lezione-2-5.html", "related": ["luna", "orbita", "fase-lunare"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La stessa faccia, ma non una fotografia immobile", "paragraphs": ["La Luna mostra verso la Terra approssimativamente lo stesso emisfero perché rotazione e rivoluzione sono sincronizzate. Nel tempo possiamo però vedere un poco oltre i bordi normalmente rivolti verso di noi. L’insieme di queste variazioni prende il nome di librazione. Non implica che la Luna smetta improvvisamente di ruotare o si ribalti per mostrare a turno due metà completamente opposte."]}, {"title": "Una geometria che cambia", "paragraphs": ["La velocità orbitale varia lungo la traiettoria, mentre la rotazione non segue esattamente la stessa variazione istantanea. Anche l’orientamento dell’asse e il punto di osservazione terrestre contribuiscono alla vista. Si distinguono componenti ottiche, cioè geometriche, e componenti fisiche. Per un’introduzione basta capire che il bordo accessibile si sposta: non tutto il fenomeno è una vera oscillazione materiale della Luna come un pendolo."]}, {"title": "Più della metà nel corso del tempo", "paragraphs": ["Combinando osservazioni in momenti differenti possiamo accedere a circa il 59% della superficie lunare, non tutto insieme da un singolo punto in una singola notte. Questa distinzione temporale è essenziale. Una fotografia resta una vista di una porzione, con illuminazione e geometria proprie. Comporre regioni osservate in epoche diverse può essere utile, purché la composizione sia dichiarata e non venga presentata come una ripresa istantanea."]}, {"title": "Una possibilità per il diario", "paragraphs": ["Confronta regioni vicine al bordo in date diverse e annota fase e ora. Una formazione può diventare più favorevole senza che sia cambiata fisicamente. È un esempio efficace di come il punto di vista influenzi ciò che possiamo osservare. Per un confronto preciso si consultano dati di librazione, mentre l’esperienza visiva introduce il principio: posizione apparente del dettaglio, illuminazione e struttura reale non sono la stessa informazione."]}], "facts": ["Circa 59% della superficie accessibile nel tempo", "Non tutto visibile insieme in una sola fotografia"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/librazione/"}]}, {"id": "longitudine", "name": "Longitudine", "definition": "La longitudine geografica misura la posizione angolare di un luogo a est o a ovest di un meridiano di riferimento, convenzionalmente Greenwich.", "example": "Controlla sempre la convenzione est/ovest", "source": "https://www.treccani.it/enciclopedia/longitudine/", "lesson": "lezione-9-3.html", "related": ["latitudine", "meridiano", "ora-civile"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "L’altra metà dell’indirizzo terrestre", "paragraphs": ["Latitudine e longitudine servono insieme per individuare un luogo sulla superficie nel modello adottato. La longitudine distingue posizioni lungo il giro est–ovest. Un programma può richiederla con segni positivi a est e negativi a ovest, oppure con indicazioni separate. Controllare questa convenzione è essenziale: inserire il segno opposto colloca l’osservatore da un’altra parte e altera gli orari e le direzioni calcolate."]}, {"title": "Un legame con il passaggio del cielo", "paragraphs": ["La Terra compie una rotazione completa attraverso tutti i meridiani. A parità di istante, osservatori a longitudini differenti non hanno lo stesso meridiano celeste orientato verso le stelle. Come relazione angolare, quindici gradi corrispondono a un’ora di rotazione e un grado a quattro minuti. Questa equivalenza aiuta a capire gli scarti locali, ma non significa che i fusi civili seguano sempre confini geografici regolari larghi quindici gradi."]}, {"title": "Il fuso orario è una decisione civile", "paragraphs": ["Due città italiane possono usare la stessa ora dell’orologio pur avendo il Sole al meridiano in istanti diversi. Il fuso e l’eventuale ora legale non cancellano la differenza di longitudine. Per questo un’applicazione astronomica deve conoscere sia coordinate sia riferimento temporale. Correggere una carta soltanto aggiungendo l’ora legale, senza aver gestito luogo e scala del tempo, non basta a ricostruire correttamente il cielo osservato."]}, {"title": "Leggere e registrare il dato", "paragraphs": ["Gradi decimali e gradi con primi e secondi sono rappresentazioni differenti della stessa quantità. Non trattare una scrittura con separatori come se fosse un numero decimale già pronto. Nel diario è sufficiente una precisione adatta al fenomeno: trovare una costellazione e cronometrare un’occultazione non richiedono lo stesso dettaglio. La longitudine resta una coordinata terrestre; non va confusa con ascensione retta o azimut, che descrivono riferimenti e direzioni celesti differenti."]}], "facts": ["Controlla sempre la convenzione est/ovest", "Ora civile comune non significa stesso mezzogiorno solare"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/longitudine/"}], "aliases": ["longitudini"]}, {"id": "luce", "name": "Luce", "definition": "Nel senso ottico la luce è la radiazione elettromagnetica visibile; in astronomia il termine viene talvolta esteso a bande che l’occhio non percepisce.", "example": "Nel vuoto c = 299.792.458 m/s", "source": "https://www.treccani.it/enciclopedia/luce/", "lesson": "lezione-4-3.html", "related": ["radiazione", "fotone", "anno-luce"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il messaggero che ci raggiunge", "paragraphs": ["Osservare il cielo significa ricevere segnali. La luce può provenire direttamente da una stella oppure essere riflessa, diffusa o trasformata attraverso interazioni con altra materia. Non tutto ciò che brilla produce energia allo stesso modo: la Luna riflette principalmente luce solare, mentre il Sole irradia energia alimentata dalla sua evoluzione interna. Separare questi casi è il primo passo per interpretare una fotografia senza limitarsi alla sua bellezza."]}, {"title": "Una velocità e un tempo di viaggio", "paragraphs": ["Nel vuoto la velocità della luce è esattamente 299.792.458 metri al secondo. Per raggiungere oggetti e osservatori percorre distanze che richiedono tempo. Un anno luce è una lunghezza costruita usando quel cammino, non un intervallo da leggere su un orologio. Ricevere oggi una luce partita prima non equivale a conoscere automaticamente lo stato attuale simultaneo di una sorgente lontana."]}, {"title": "Direzione, colore e quantità", "paragraphs": ["La posizione apparente ci dice dove guardare; il flusso quanto segnale arriva per area e tempo; lo spettro come si distribuisce fra lunghezze d’onda. Nessuna di queste misure, da sola, riassume tutto l’oggetto. Gas e polveri lungo il percorso possono attenuare e modificare il segnale. Anche telescopio, sensore e trattamento dell’immagine contribuiscono a ciò che infine vediamo sullo schermo."]}, {"title": "La fotografia è una traduzione controllata", "paragraphs": ["Un’immagine a colori assegnati può rendere comprensibili bande invisibili o differenze molto deboli. Non è per questo falsa, purché si spieghi quali dati rappresenta. È invece fuorviante presentarla come la vista naturale di un occhio umano o come prova di dettagli non misurati. Una didascalia con banda, fonte e principali trasformazioni permette di conservare il potere evocativo della luce e allo stesso tempo di capire come sia diventata informazione."]}], "facts": ["Nel vuoto c = 299.792.458 m/s", "Direzione, flusso e spettro raccontano informazioni differenti"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/luce/"}, {"title": "JPL · velocità e tempi della luce", "url": "https://ssd.jpl.nasa.gov/astro_par.html"}]}, {"id": "luminosita", "name": "Luminosità intrinseca", "definition": "In astronomia la luminosità intrinseca è la potenza radiativa emessa da una sorgente, nell’intero spettro o in una banda specificata.", "example": "Luminosità = energia emessa per unità di tempo", "source": "https://www.treccani.it/enciclopedia/luminosita/", "lesson": "lezione-4-2.html", "related": ["magnitudine-assoluta", "magnitudine-apparente", "stella"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Quello che la sorgente emette", "paragraphs": ["La luminosità intrinseca descrive energia emessa per unità di tempo. Nel Sistema Internazionale si misura in watt, come ogni potenza, oppure si esprime rispetto alla luminosità solare. Non è la quantità di luce che entra nel nostro telescopio. Una sorgente può essere molto potente e apparire debole perché lontana; una meno potente può dominare il cielo perché vicina."]}, {"title": "Il flusso che riceviamo", "paragraphs": ["Nel modello di emissione uguale in tutte le direzioni, la stessa potenza si distribuisce su superfici sferiche sempre più grandi. A distanza doppia, la superficie è quattro volte maggiore e il flusso ricevuto per unità di area si riduce a un quarto. L’ipotesi si chiama isotropia. Non è appropriata automaticamente per getti o emissioni molto direzionali. Polveri e gas fra sorgente e osservatore possono inoltre sottrarre o redistribuire radiazione."]}, {"title": "Un esempio che non richiede logaritmi", "paragraphs": ["Immagina due stelle ideali senza assorbimento: una emette quattro volte la potenza dell’altra ma si trova a distanza doppia. Il fattore quattro della potenza e il fattore quattro della diluizione si compensano, così il flusso ricevuto è uguale. Dalla sola brillantezza apparente non potremmo scegliere quale sia la più potente. Occorre conoscere la distanza o disporre di altri indizi fisici."]}, {"title": "Bande e parole comuni", "paragraphs": ["Luminosità bolometrica significa potenza integrata su tutto lo spettro; una luminosità in una certa banda riguarda soltanto quell’intervallo. La magnitudine assoluta è una scala legata alla brillantezza a distanza convenzionale e richiede anch’essa una banda. Nel linguaggio quotidiano chiamiamo luminoso ciò che vediamo brillante: nelle spiegazioni astronomiche conviene specificare ogni volta se stiamo parlando di emissione della sorgente, flusso ricevuto o percezione visiva."]}], "facts": ["Luminosità = energia emessa per unità di tempo", "Isotropia: stessa emissione nelle diverse direzioni", "Distanza doppia → flusso un quarto, nelle ipotesi dichiarate"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/luminosita/"}]}, {"id": "luna", "name": "Luna", "definition": "La Luna è il satellite naturale della Terra; luce riflessa, moto orbitale e superficie producono fenomeni diversi che vanno distinti.", "example": "La Luna ruota: rotazione sincrona non significa assenza di rotazione", "source": "https://www.treccani.it/enciclopedia/luna/", "lesson": "lezione-2-4.html", "related": ["fase-lunare", "librazione", "terminatore"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un mondo vicino, non una lampada", "paragraphs": ["La Luna brilla principalmente perché riflette luce solare. La sua superficie presenta regioni di riflettività e rilievo differenti: mari basaltici, altopiani, crateri e altre strutture raccontano una storia geologica. Il nome mare è storico e non indica grandi distese attuali di acqua liquida. Una regione più chiara non è automaticamente più alta, mentre una zona scura può dipendere da materiale o illuminazione."]}, {"title": "La faccia rivolta verso la Terra", "paragraphs": ["La rotazione lunare è sincronizzata in media con la rivoluzione attorno alla Terra: la Luna compie un giro su se stessa mentre percorre l’orbita. Non è quindi un corpo che non ruota. La librazione permette nel tempo di vedere un poco oltre i bordi, senza mostrarci in una notte tutta la superficie. Nei diagrammi un dettaglio di riferimento va mantenuto rivolto verso la Terra per spiegare correttamente la sincronizzazione."]}, {"title": "Fasi e ombre", "paragraphs": ["La fase dipende dalla parte illuminata visibile, mentre il terminatore separa giorno e notte sulla superficie. L’eclissi lunare richiede invece il passaggio nell’ombra della Terra. Sono tre descrizioni collegate ma diverse. Una fotografia della Luna parzialmente illuminata non è di per sé un’eclissi. L’orientamento della fase sullo schermo può inoltre variare con punto di vista e strumento: non va trasformato in una regola universale senza contesto."]}, {"title": "Un bersaglio da tornare a osservare", "paragraphs": ["Le ombre cambiano rapidamente nelle regioni vicine al terminatore e rivelano dettagli diversi da una serata all’altra. Non serve aspettare soltanto la piena. Un diario con ora, fase, zona e disegno permette di confrontare il rilievo percepito e la riflettività. La distanza orbitale varia e il diametro apparente ne risente, ma l’illusione della Luna enorme sull’orizzonte appartiene anche alla percezione: non è una misura diretta della sua distanza."]}], "facts": ["La Luna ruota: rotazione sincrona non significa assenza di rotazione", "Mari lunari: nome storico, non oceani attuali"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/luna/"}]}, {"id": "lunghezza-d-onda", "name": "Lunghezza d’onda", "definition": "La lunghezza d’onda è la distanza fra due punti consecutivi nella stessa fase di un’onda, per esempio due creste; si indica spesso con la lettera greca lambda, λ.", "example": "λ si legge lambda e indica una lunghezza", "source": "https://www.treccani.it/enciclopedia/frequenza/", "lesson": "lezione-4-3.html", "related": ["frequenza", "redshift", "spettro"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Una distanza nella forma dell’onda", "paragraphs": ["Le creste disegnate su una linea aiutano a visualizzare la ripetizione spaziale. La distanza fra una cresta e la successiva è una lunghezza d’onda. Non coincide con la distanza della sorgente e non misura il diametro di una stella. Nell’onda elettromagnetica il disegno rappresenta variazioni dei campi, non una corda materiale che si snoda nello spazio. L’analogia serve a introdurre una grandezza misurabile, non a descrivere ogni proprietà della luce."]}, {"title": "Le unità rendono leggibile il numero", "paragraphs": ["Per la luce visibile si usano spesso nanometri: un nanometro è un miliardesimo di metro. Le onde radio possono essere descritte con lunghezze molto maggiori, mentre altre bande hanno lunghezze molto minori. Un numero senza unità non consente di riconoscere la regione dello spettro. Anche il simbolo lambda deve essere spiegato alla prima comparsa, altrimenti una formula semplice diventa inutilmente opaca per chi non ha familiarità con la notazione scientifica."]}, {"title": "Il confronto fra emissione e osservazione", "paragraphs": ["Nello studio del redshift si confronta la posizione osservata di una caratteristica spettrale con quella di riferimento. Se la lunghezza d’onda osservata è maggiore, lo spostamento è verso il rosso. Non basta vedere una fotografia dai toni rossi: servono caratteristiche identificate e misure. Un’illustrazione deve mostrare le stesse righe confrontabili, non sostituire arbitrariamente il loro numero o la loro disposizione per ottenere un effetto grafico più evidente."]}, {"title": "Collegarla alla frequenza", "paragraphs": ["Nel vuoto, lunghezza d’onda moltiplicata per frequenza dà la velocità della luce. Per capire il verso del legame non servono radici o logaritmi: se il prodotto resta uguale, una grandezza aumenta mentre l’altra diminuisce. In un mezzo materiale la propagazione richiede altre precisazioni. Le didascalie devono perciò dichiarare il contesto, soprattutto quando si passa da uno spettro astronomico a un esperimento con vetro, acqua o altri materiali sul banco."]}], "facts": ["λ si legge lambda e indica una lunghezza", "La lunghezza d’onda non è la distanza della sorgente"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/frequenza/"}], "aliases": ["lunghezza d’onda", "lunghezze d’onda", "lunghezze d'onda"]}, {"id": "magnitudine-apparente", "name": "Magnitudine apparente", "definition": "Numero che descrive quanto un astro appare brillante in una determinata banda: valori più piccoli indicano maggiore brillantezza.", "example": "Una stella di magnitudine 1 appare più brillante di una di magnitudine 4. Non ne deduci da solo la distanza.", "source": "https://www.treccani.it/enciclopedia/magnitudine_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-4-2.html", "related": ["magnitudine-assoluta", "stella"], "checked": "2026-10-30", "sections": [{"title": "Quanto arriva, non quanto viene emesso", "paragraphs": ["La magnitudine apparente è un numero che descrive la brillantezza ricevuta da un oggetto in una banda osservativa specificata. Dipende dalla luce emessa, dalla distanza e da ciò che la luce attraversa. Non misura direttamente massa, diametro o età. Due stelle con la stessa magnitudine apparente possono essere fisicamente molto diverse: una poco luminosa e vicina può apparire come una sorgente più potente ma lontana."]}, {"title": "Una scala che procede al contrario", "paragraphs": ["Nella convenzione astronomica, numeri minori indicano sorgenti più brillanti. Sono possibili valori zero e negativi: non rappresentano luce negativa. Fra magnitudine 1 e magnitudine 4, la prima sorgente è più brillante. Cinque magnitudini di differenza corrispondono a un rapporto di cento fra i flussi nella medesima banda. Per leggere il concetto non serve svolgere logaritmi: basta ricordare verso della scala e significato del confronto."]}, {"title": "La banda fa parte del dato", "paragraphs": ["Un valore misurato in una banda blu non si confronta indiscriminatamente con uno ottenuto nell’infrarosso. Le sorgenti distribuiscono energia in modi diversi lungo lo spettro; i sensori e i filtri selezionano parti di quella distribuzione. In un catalogo occorre quindi leggere anche il sistema fotometrico. Una fotografia elaborata per evidenziare dettagli non è una scala automatica di magnitudini: stretching, saturazione e filtri cambiano l’aspetto dei pixel."]}, {"title": "Un oggetto diffuso pone una domanda in più", "paragraphs": ["La luce di una galassia o di una nebulosa è distribuita su un’area. Una magnitudine totale favorevole non garantisce che le zone esterne si stacchino dal fondo del cielo. Contano brillantezza superficiale, dimensione angolare, trasparenza e luce artificiale. È il motivo per cui un piccolo punto e una grande nube con lo stesso flusso complessivo non hanno la stessa facilità di osservazione. Per confrontare la potenza intrinseca delle stelle si introduce invece la magnitudine assoluta, riferita a una distanza convenzionale."]}], "facts": ["Valori più piccoli → maggiore brillantezza", "Differenza di 5 magnitudini → rapporto di flusso 100", "La banda e il tipo di magnitudine vanno specificati"], "sources": [{"title": "Treccani · riferimento della voce", "url": "https://www.treccani.it/enciclopedia/magnitudine_(Dizionario-delle-Scienze-Fisiche)/"}], "editorialStatus": "scheda-estesa"}, {"id": "magnitudine-assoluta", "name": "Magnitudine assoluta", "definition": "Magnitudine che un oggetto avrebbe se fosse osservato dalla distanza convenzionale di 10 parsec, nella banda specificata.", "example": "Mettere idealmente le stelle alla stessa distanza permette un confronto diverso da quello del cielo a occhio nudo.", "source": "https://www.treccani.it/enciclopedia/magnitudine_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-4-2.html", "related": ["magnitudine-apparente", "parsec"], "checked": "2026-10-30", "sections": [{"title": "Un confronto a distanza comune", "paragraphs": ["Per confrontare la brillantezza intrinseca di stelle lontane a distanze differenti immaginiamo di osservarle tutte da una stessa distanza. La magnitudine assoluta è quella che una sorgente avrebbe a 10 parsec, nella banda specificata e con le convenzioni del confronto. Non cambia fisicamente la stella: è un modo di separare il ruolo della distanza dalla misura ricevuta. Dieci parsec equivalgono a circa 32,6 anni luce."]}, {"title": "Una sorgente debole in apparenza può essere potente", "paragraphs": ["Una stella molto lontana può avere una magnitudine apparente modesta pur emettendo molta energia. La sua magnitudine assoluta permette un confronto diverso da quello delle stelle che dominano la serata a occhio nudo. Come nella scala apparente, valori numerici più bassi indicano maggiore brillantezza. Un valore negativo non rappresenta un errore né una quantità di luce sotto zero: è una posizione nella scala convenzionale."]}, {"title": "Che cosa occorre conoscere", "paragraphs": ["Ricavare la magnitudine assoluta dalla misura apparente richiede una distanza e una valutazione dell’assorbimento lungo la linea di vista. Polveri interstellari possono attenuare e modificare il colore della luce. Senza una correzione adeguata si può attribuire alla sorgente una debolezza che dipende invece dal percorso dei fotoni. La distanza può provenire, per esempio, dalla parallasse per gli oggetti per cui il metodo è utilizzabile con precisione sufficiente."]}, {"title": "Non è un numero universale di potenza", "paragraphs": ["La magnitudine assoluta in una banda misura il confronto in quella parte dello spettro. La magnitudine bolometrica cerca invece di considerare l’emissione complessiva: non va scambiata con un valore visuale senza le correzioni appropriate. Anche l’interpretazione in termini di raggio e temperatura richiede informazioni ulteriori. Il vantaggio divulgativo è chiaro: “se fossero alla stessa distanza, quale apparirebbe più brillante?” è una domanda precisa, diversa da “quale punto vedo meglio stasera?”."]}], "facts": ["Distanza convenzionale: 10 parsec ≈ 32,6 anni luce", "Si specifica la banda fotometrica", "Distanza e assorbimento entrano nella ricostruzione"], "sources": [{"title": "Treccani · riferimento della voce", "url": "https://www.treccani.it/enciclopedia/magnitudine_(Dizionario-delle-Scienze-Fisiche)/"}], "editorialStatus": "scheda-estesa"}, {"id": "massa", "name": "Massa", "definition": "La massa caratterizza la risposta di un corpo alle forze e il suo ruolo gravitazionale; non coincide con il peso né con il volume.", "example": "Massa ≠ peso ≠ volume", "source": "https://www.treccani.it/enciclopedia/massa/", "lesson": "lezione-4-1.html", "related": ["gravitazione", "stella", "buco-nero"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Tre parole da separare", "paragraphs": ["Un corpo può essere grande ma poco denso, oppure piccolo e molto denso. Il volume descrive lo spazio occupato; la massa non si ricava dal solo diametro. Il peso è invece una forza legata all’ambiente gravitazionale e al riferimento. Portando un campione dalla Terra alla Luna il suo peso cambia, mentre la sua massa resta sostanzialmente la stessa, se non perde o acquista materiale."]}, {"title": "L’inerzia rende la definizione concreta", "paragraphs": ["Nella meccanica ordinaria, a parità di forza, un corpo di massa maggiore cambia velocità meno rapidamente. La massa misura quindi anche l’inerzia. In ambito gravitazionale contribuisce all’attrazione e ai moti del sistema. Dire soltanto quantità di materia può servire come prima intuizione, ma lascia aperta la domanda di come misurarla. Per l’astronomia, osservare un moto orbitale è spesso più utile che immaginare una bilancia accanto alla stella."]}, {"title": "Il caso delle stelle", "paragraphs": ["La massa influenza il percorso evolutivo, ma non va confusa con la luminosità apparente. Una stella molto brillante nel nostro cielo può essere relativamente vicina. Una relazione massa–luminosità è un’approssimazione utile per determinate stelle della sequenza principale, non una legge da applicare senza condizioni a giganti, protostelle o nane bianche. Anche la storia di interazioni e trasferimenti in un sistema binario può complicare il quadro."]}, {"title": "Le unità del cielo", "paragraphs": ["Le masse stellari vengono spesso espresse rispetto a quella del Sole. Dire dieci masse solari significa un rapporto, non dieci diametri del Sole. Nei buchi neri non rotanti la dimensione dell’orizzonte cresce linearmente con la massa, ma quel confine non è una superficie materiale da cui ricavare la densità come per una palla ordinaria. Specificare massa, raggio del riferimento e modello evita confronti spettacolari ma ambigui."]}], "facts": ["Massa ≠ peso ≠ volume", "Massa solare indica un’unità di massa, non una dimensione"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/massa/"}]}, {"id": "meridiano", "name": "Meridiano", "definition": "Il meridiano celeste locale è il grande cerchio che passa per i poli celesti e lo zenit dell’osservatore; sulla Terra i meridiani servono a definire le longitudini.", "example": "Il meridiano locale passa per zenit e poli celesti", "source": "https://www.treccani.it/enciclopedia/meridiano/", "lesson": "lezione-1-3.html", "related": ["zenit", "culminazione", "longitudine"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un riferimento sopra la testa", "paragraphs": ["Immagina un arco che attraversa lo zenit e collega le direzioni nord e sud dell’orizzonte. È la parte visibile del meridiano celeste locale. Il cerchio completo prosegue anche sotto l’orizzonte e contiene i poli celesti. Non è una linea materiale disegnata fra le stelle: dipende dalla posizione dell’osservatore e serve a descrivere passaggi e direzioni in modo ordinato."]}, {"title": "Il passaggio di una stella", "paragraphs": ["Durante il moto diurno una stella attraversa il meridiano. Il passaggio superiore corrisponde alla parte più alta della traiettoria a declinazione quasi costante; quello inferiore alla più bassa. Quest’ultimo può avvenire sotto l’orizzonte. Una mappa deve quindi distinguere il riferimento geometrico dal cielo effettivamente visibile. Anche la parola transito nelle tabelle può indicare il passaggio al meridiano e non un corpo che si proietta sul disco di un altro."]}, {"title": "Terra e cielo sono collegati", "paragraphs": ["Il meridiano geografico di un luogo attraversa i poli terrestri. Il piano meridiano mette in relazione il riferimento terrestre con quello celeste. La longitudine individua quale meridiano è associato al luogo rispetto a quello convenzionale di partenza. Nei disegni introduttivi si usa spesso una Terra sferica; per la geodesia reale entrano definizioni più accurate, che non vanno confuse con la semplice semicirconferenza del mappamondo scolastico."]}, {"title": "Un uso pratico senza equivoci", "paragraphs": ["Conoscere il meridiano aiuta a programmare un’osservazione vicino alla massima altezza del bersaglio. Non implica che il bersaglio passi sempre a sud per ogni osservatore: le traiettorie dipendono da declinazione e latitudine. Per il Sole il passaggio definisce il mezzogiorno solare locale, non necessariamente le dodici civili. Nel laboratorio orientare correttamente nord, zenit e polo rende il concetto più comprensibile di una linea verticale anonima che non dichiara il proprio piano."]}], "facts": ["Il meridiano locale passa per zenit e poli celesti", "Un passaggio al meridiano non è necessariamente un transito davanti a un disco"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/meridiano/"}], "aliases": ["meridiani"]}, {"id": "meteora", "name": "Meteora", "definition": "Fenomeno luminoso atmosferico provocato dall’ingresso di un meteoroide.", "example": "La “stella cadente” non è una stella che precipita.", "source": "https://www.treccani.it/enciclopedia/meteora/", "lesson": "lezione-8-1.html", "related": ["meteorite", "meteoroide"], "checked": "2026-10-30", "sections": [{"title": "Una luce, non una stella che cade", "paragraphs": ["La meteora è il fenomeno luminoso prodotto dall’ingresso rapido di materiale naturale nell’atmosfera. La chiamiamo comunemente stella cadente, ma non è una stella che si stacca dalla volta celeste. Il corpo iniziale è un meteoroide; l’interazione con il gas atmosferico causa riscaldamento, perdita di materiale e luce. Parlare soltanto di sfregamento, come per due superfici solide, non rende bene la fisica del fenomeno."]}, {"title": "Riconoscere il passaggio", "paragraphs": ["Una meteora attraversa normalmente una parte del cielo in un tempo breve e non segue per minuti il moto regolare di un satellite. Può variare molto di luminosità, lasciare una traccia persistente o frammentarsi. Durata e direzione aiutano a interpretare l’osservazione, ma un singolo indizio non basta sempre. Un filmato riprodotto a velocità alterata o una lunga esposizione possono cambiare profondamente l’impressione rispetto a ciò che vedrebbe l’occhio."]}, {"title": "Il disegno di uno sciame", "paragraphs": ["Le meteore di uno sciame, prolungate all’indietro sulla carta, sembrano convergere verso un radiante. La somiglianza deriva da traiettorie sostanzialmente parallele viste in prospettiva. Per osservarle non occorre fissare soltanto il radiante: un campo ampio e comodo permette di seguire scie anche lontane da esso. La Luna, le luci locali, le nubi e il tempo effettivo di osservazione influenzano il numero contato."]}, {"title": "Una registrazione utile", "paragraphs": ["Scrivi l’ora con il fuso, il luogo, la direzione iniziale e finale e l’eventuale persistenza della traccia. Non assegnare automaticamente una meteora allo sciame più noto della stagione: esistono meteore sporadiche e sciami contemporanei. Non chiamare meteorite la luce osservata. La distinzione fra corpo, fenomeno e residuo evita equivoci e rende il diario confrontabile con altre osservazioni, anche se non si dispone di una strumentazione dedicata."]}], "facts": ["La stella cadente non è una stella", "Il radiante è un effetto prospettico", "Una traccia fotografica non coincide con la visione istantanea"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/meteora/"}, {"title": "NASA · meteore e meteoriti", "url": "https://science.nasa.gov/solar-system/meteors-meteorites/facts/"}], "editorialStatus": "scheda-estesa", "media": {"file": "assets/lezioni/perseide-vlt-2010.jpg", "caption": "Una scia registrata fotograficamente. L’esposizione raccoglie un percorso che l’occhio segue nel tempo.", "credit": "ESO/S. Guisard", "source": "https://www.eso.org/public/images/potw1033a/", "license": "CC BY 4.0"}, "aliases": ["meteore"]}, {"id": "meteorite", "name": "Meteorite", "definition": "Materiale di origine cosmica che raggiunge la superficie di un pianeta o satellite.", "example": "Una scia osservata in cielo è una meteora; un frammento sopravvissuto e arrivato al suolo è una meteorite.", "source": "https://www.treccani.it/enciclopedia/meteorite/", "lesson": "lezione-8-1.html", "related": ["meteora", "meteoroide"], "checked": "2026-10-30", "sections": [{"title": "Il materiale che raggiunge la superficie", "paragraphs": ["Una meteorite è un frammento naturale di origine extraterrestre che raggiunge la superficie dopo il passaggio atmosferico. Il nome riguarda il campione materiale, non il lampo visto in cielo. Il corpo nello spazio è un meteoroide, mentre la fase luminosa è una meteora. Questa distinzione permette di parlare separatamente di traiettoria, interazione atmosferica e analisi del materiale recuperato."]}, {"title": "Un archivio molto più antico del ritrovamento", "paragraphs": ["Molte meteoriti conservano informazioni sui primi materiali del Sistema solare, sulle trasformazioni dei corpi progenitori e sugli urti che li hanno frammentati. Non sono tutte identiche: esistono campioni prevalentemente rocciosi, metallici e misti. Alcuni materiali hanno subito fusione e differenziazione, altri conservano strutture più primitive. La data del ritrovamento non è l’età della roccia e neppure, necessariamente, il giorno della sua caduta."]}, {"title": "Riconoscere richiede più di un colore", "paragraphs": ["Una crosta scura o la risposta a una calamita non bastano a certificare una meteorite. Rocce terrestri, scorie e materiali industriali possono somigliare a campioni extraterrestri. Un’identificazione seria richiede contesto, esame competente e talvolta analisi di laboratorio. Anche l’idea di un frammento sempre incandescente al suolo è fuorviante: il passaggio atmosferico non implica che tutto il volume interno raggiunga temperature elevate."]}, {"title": "Dalla curiosità al documento", "paragraphs": ["Se trovi un oggetto sospetto, registra posizione e circostanze senza attribuirgli subito un’origine. La documentazione del luogo e la corretta gestione del campione possono essere importanti per l’interpretazione scientifica. Rivolgiti a un museo o a un ente competente per il riconoscimento e verifica le regole applicabili alla raccolta. Una fotografia sui social può suggerire un approfondimento, ma non sostituisce l’analisi di una meteorite reale."]}], "facts": ["Meteorite = campione materiale, non scia luminosa", "Aspetto scuro e magnetismo non sono prove sufficienti"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/meteorite/"}, {"title": "NASA · meteore e meteoriti", "url": "https://science.nasa.gov/solar-system/meteors-meteorites/facts/"}], "editorialStatus": "scheda-estesa", "media": {"file": "assets/lezioni/meteorite-hoba.jpg", "caption": "Hoba: un campione materiale sulla superficie terrestre, distinto dalla meteora luminosa.", "credit": "Olga Ernst", "source": "https://commons.wikimedia.org/wiki/File:Hoba_meteorite,_Namibia_(2014).jpg", "license": "CC BY-SA 4.0"}, "aliases": ["meteoriti"]}, {"id": "meteoroide", "name": "Meteoroide", "definition": "Piccolo corpo solido nello spazio interplanetario che può produrre una meteora entrando nell’atmosfera.", "example": "Distingui corpo nello spazio, fenomeno luminoso e residuo al suolo.", "source": "https://www.treccani.it/enciclopedia/meteora/", "lesson": "lezione-8-1.html", "related": ["meteora", "meteorite"], "checked": "2026-10-30", "sections": [{"title": "Il frammento prima del fenomeno luminoso", "paragraphs": ["Un meteoroide è un piccolo corpo naturale solido nello spazio interplanetario. Il termine descrive il materiale prima dell’eventuale ingresso atmosferico: non la scia luminosa e non il frammento raccolto al suolo. Può provenire dalla frammentazione di corpi più grandi o dal materiale disperso da una cometa. Nella nomenclatura le soglie dimensionali dipendono dalle convenzioni adottate; non serve inventare un limite rigido per riconoscere la distinzione fondamentale."]}, {"title": "Tre nomi per tre aspetti", "paragraphs": ["Quando un meteoroide entra nell’atmosfera ad alta velocità può produrre una meteora, il fenomeno luminoso che chiamiamo stella cadente. Se una parte del materiale raggiunge la superficie, quel residuo è una meteorite. Non tutti i meteoroidi incontrano la Terra e non tutte le meteore lasciano meteoriti recuperabili. La sequenza è utile per capire il vocabolario, ma non va trasformata nella promessa che ogni scia abbia un sasso ancora caldo da cercare sotto di essa."]}, {"title": "Perché gli sciami ritornano", "paragraphs": ["Lungo certe orbite si distribuiscono particelle liberate nel tempo da un corpo progenitore. Se la Terra attraversa una di queste popolazioni, osserviamo un aumento delle meteore con traiettorie che sembrano provenire da una stessa zona prospettica, il radiante. I frammenti non partono materialmente da quel punto della volta celeste. Sono il moto relativo e la prospettiva a produrre il disegno, come accade alle linee parallele di una strada viste in lontananza."]}, {"title": "Che cosa possiamo dedurre", "paragraphs": ["Dalla sola impressione visiva di una scia non ricaviamo con certezza massa, composizione o provenienza del corpo. Osservazioni coordinate, fotografie calibrate e misure della traiettoria possono fornire informazioni più solide. Durante una serata amatoriale è già utile registrare ora, direzione, durata e luminosità approssimata. Il valore dell’appunto cresce se separiamo i dati osservati dall’interpretazione proposta dopo."]}], "facts": ["Meteoroide: corpo nello spazio", "Meteora: fenomeno atmosferico · meteorite: residuo al suolo"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/meteora/"}, {"title": "NASA · terminologia dei meteoroidi", "url": "https://ntrs.nasa.gov/api/citations/20200000049/downloads/20200000049.pdf?attachment=true"}], "editorialStatus": "scheda-estesa", "aliases": ["meteoroidi"]}, {"id": "montatura-altazimutale", "name": "Montatura altazimutale", "definition": "Un supporto altazimutale orienta lo strumento con un movimento in azimut e uno in altezza rispetto all’orizzonte locale.", "example": "Movimenti: azimut e altezza", "source": "https://www.treccani.it/enciclopedia/montatura/", "lesson": "lezione-7-3.html", "related": ["azimut", "altezza-angolare", "montatura-equatoriale"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Due movimenti intuitivi", "paragraphs": ["Uno dei movimenti fa girare lo strumento attorno alla verticale; l’altro lo alza o lo abbassa. Il primo cambia l’azimut, il secondo l’altezza. I riferimenti dipendono dal luogo in cui il supporto è installato. Una testa fotografica adatta, una montatura a forcella e un supporto Dobson possono realizzare questa logica con forme meccaniche molto differenti, senza diventare per questo schemi ottici differenti."]}, {"title": "Seguire il cielo", "paragraphs": ["Per mantenere una stella al centro durante il moto diurno occorre normalmente regolare entrambi i movimenti. Un controllo motorizzato può farlo automaticamente. Tuttavia il campo ruota rispetto al sistema locale: mantenere il centro non equivale a conservare immobile l’orientamento di tutta l’immagine sul sensore. Questo punto spiega un limite importante nelle esposizioni lunghe, senza rendere il supporto inutile per l’osservazione visuale o per molte riprese brevi."]}, {"title": "Vicino allo zenit", "paragraphs": ["Allo zenit l’azimut è geometricamente indefinito. Nei dintorni di quel punto il movimento azimutale richiesto per inseguire un oggetto può diventare molto rapido. Il comportamento dipende dal sistema e dalle procedure disponibili. Un simulatore non dovrebbe mostrare una rotazione arbitraria degli assi come se fosse una legge fisica universale, né confondere il problema di coordinate con una stella che cambia improvvisamente posizione reale."]}, {"title": "Scegliere senza gerarchie assolute", "paragraphs": ["Stabilità, semplicità, ingombro e uso previsto contano più di una classifica unica. Una soluzione altazimutale ben progettata può essere eccellente per osservare e puntare rapidamente. Per fotografia prolungata si valutano rotazione di campo, posa, derotazione o eventuale configurazione equatoriale prevista dal costruttore. Il nome della montatura non garantisce la portata reale: tubo, accessori, leva e vento concorrono alle condizioni di impiego."]}], "facts": ["Movimenti: azimut e altezza", "Inseguire il centro non annulla la rotazione del campo"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/montatura/"}], "aliases": ["montature altazimutali"]}, {"id": "montatura-equatoriale", "name": "Montatura equatoriale", "definition": "Una montatura equatoriale dispone l’asse polare parallelamente all’asse terrestre e un secondo asse, di declinazione, perpendicolare al primo.", "example": "Asse polare parallelo all’asse terrestre", "source": "https://www.treccani.it/enciclopedia/montatura/", "lesson": "lezione-7-3.html", "related": ["polo-celeste", "ascensione-retta", "montatura-altazimutale"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La geometria prima della forma", "paragraphs": ["La caratteristica decisiva non è il colore, la presenza del contrappeso o il numero di motori. È l’orientamento dell’asse polare verso il polo celeste appropriato. L’asse di declinazione è perpendicolare a esso e consente di scegliere il cerchio celeste su cui puntare. Montature tedesche e sistemi a forcella inclinata possono condividere questa geometria pur avendo strutture molto diverse."]}, {"title": "Quale inclinazione impostare", "paragraphs": ["Nell’emisfero nord l’asse polare forma con l’orizzonte un angolo pari alla latitudine geografica. A 45° N va quindi inclinato di circa 45°, non di un valore fisso di 23,4°. L’obliquità terrestre si riferisce alla perpendicolare al piano orbitale e riguarda un altro confronto. Orientare l’asse richiede anche la direzione nord vera: una bussola non corretta può fornire soltanto un’approssimazione iniziale."]}, {"title": "Allineamento e puntamento sono operazioni diverse", "paragraphs": ["Dopo avere disposto l’asse polare, lo strumento viene puntato mediante i movimenti della montatura. Non si deve perdere l’allineamento spostando tutta la base per cercare ogni nuovo oggetto. Nell’idealizzazione di una stella fissa, una rotazione appropriata attorno all’asse polare compensa il moto diurno. In fotografia reale restano errori meccanici, flessioni, rifrazione e requisiti di precisione che possono richiedere ulteriori correzioni."]}, {"title": "Preparare un sistema stabile", "paragraphs": ["Un buon montaggio include fissaggi, equilibrio e libertà di movimento per tubi e cavi. La capacità dichiarata non è una garanzia identica per ogni configurazione fotografica. Le montature tedesche possono richiedere procedure al passaggio del meridiano secondo il progetto e il controllo impiegato. Un laboratorio introduttivo deve spiegare prima che cosa si allinea e che cosa si muove, poi introdurre queste operazioni pratiche senza fingere che un unico pulsante elimini ogni limite."]}], "facts": ["Asse polare parallelo all’asse terrestre", "Allineare la base ≠ puntare il tubo"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/montatura/"}], "aliases": ["montature equatoriali"]}, {"id": "nebulosa", "name": "Nebulosa", "definition": "Concentrazione di gas e polveri dall’aspetto diffuso, luminosa oppure scura sul fondo del cielo.", "example": "Il colore di una fotografia dipende anche da filtri ed elaborazione: non basta per classificare la nube.", "source": "https://www.treccani.it/enciclopedia/nebulosa/", "lesson": "lezione-5-4.html", "related": ["nebulosa-a-emissione", "nebulosa-a-riflessione"], "checked": "2026-10-30", "sections": [{"title": "Materia diffusa fra le stelle", "paragraphs": ["Una nebulosa è una regione di gas e polveri interstellari riconoscibile per come emette, diffonde o assorbe la radiazione. Non tutte le nebulose sono culle stellari e non tutte sono luminose. Il termine comprende ambienti molto diversi: nubi associate alla nascita delle stelle, involucri espulsi da stelle evolute e resti di esplosioni. La somiglianza di una fotografia non basta a stabilire che due oggetti abbiano la stessa origine."]}, {"title": "Tre modi di apparire", "paragraphs": ["Una nebulosa a emissione produce radiazione attraverso processi fisici nel gas; una nebulosa a riflessione rende visibile luce stellare diffusa dalle polveri; una nebulosa oscura si riconosce perché attenua lo sfondo. Le categorie possono convivere nella stessa regione. Un colore blu o rosso in una fotografia non è da solo una classificazione: filtri, sensibilità del sensore e trattamento dei dati modificano la rappresentazione."]}, {"title": "Perché l’occhio vede meno della fotografia", "paragraphs": ["La luce può essere distribuita su un’area estesa e avere basso contrasto rispetto al cielo. Una fotografia accumula segnale e può registrare bande che l’occhio percepisce poco. Perciò una nube dai colori brillanti in un’immagine d’archivio può apparire all’oculare come una tenue zona grigia. Contano apertura, trasparenza, buio e adattamento visivo. Un filtro appropriato può aiutare alcuni oggetti a emissione, ma non produce luce e non migliora allo stesso modo ogni nebulosa."]}, {"title": "Una parola storica da interpretare", "paragraphs": ["Nei testi antichi “nebulosa” poteva indicare oggetti dall’aspetto indistinto che oggi sappiamo essere galassie. La galassia di Andromeda non è una nube interstellare della Via Lattea. Anche “nebulosa planetaria” non significa un sistema di pianeti: è il nome storico di un involucro gassoso di origine stellare. Identificare il processo fisico e la scala dell’oggetto è più utile che fermarsi alla forma evocativa suggerita dal soprannome."]}], "facts": ["Emissione, riflessione e oscuramento sono processi diversi", "Nebulosa planetaria non significa sistema planetario"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/nebulosa/"}], "editorialStatus": "scheda-estesa", "media": {"file": "assets/lezioni/trifida-emissione-polveri.jpg", "caption": "La Trifida combina regioni a emissione, riflessione e filamenti di polveri che oscurano lo sfondo.", "credit": "ESO", "source": "https://www.eso.org/public/images/eso0930a/", "license": "CC BY 4.0"}, "aliases": ["nebulose"]}, {"id": "nebulosa-a-emissione", "name": "Nebulosa a emissione", "definition": "Nube il cui gas emette radiazione dopo essere stato eccitato o ionizzato.", "example": "Le stelle calde possono fornire l’energia che rende luminoso il gas circostante.", "source": "https://www.treccani.it/enciclopedia/nebulosa/", "lesson": "lezione-5-4.html", "related": ["nebulosa-a-riflessione", "spettro"], "checked": "2026-10-30", "sections": [{"title": "Quando il gas diventa una sorgente di luce", "paragraphs": ["Una nebulosa a emissione è una regione di gas che emette radiazione dopo aver ricevuto energia. Il nome descrive un meccanismo fisico, non una forma geometrica: la nube può mostrare archi, filamenti, cavità o una distribuzione irregolare. Non va identificata soltanto perché una fotografia appare rossa. Nello stesso complesso possono coesistere gas luminoso, polveri che diffondono la luce e zone scure.", "Un caso molto importante è la regione H II. L’idrogeno è l’elemento dominante del gas e la radiazione ultravioletta di stelle calde può separare gli elettroni dai suoi atomi: è la ionizzazione. Il simbolo H II indica idrogeno ionizzato; non significa una molecola composta da due atomi. Il gas continua a interagire con la radiazione e a perdere energia emettendo luce."]}, {"title": "Da energia invisibile a righe osservabili", "paragraphs": ["Quando un elettrone viene catturato da uno ione, l’atomo può trovarsi in uno stato energetico eccitato. I successivi passaggi fra livelli liberano fotoni con energie determinate. Nel gas agiscono anche urti fra particelle e altri processi: l’emissione non si riduce a un solo percorso identico per ogni atomo. Lo spettro consente di riconoscere alcune delle componenti del fenomeno.", "Una riga ben nota è H-alfa, intorno a 656,3 nanometri, nella regione rossa della luce visibile. La sua presenza spiega perché molte immagini di regioni ricche di idrogeno mostrino strutture rossastre. Ma il gas emette anche altre righe, e la fotografia può combinare filtri e bande con una mappatura dei colori scelta per rendere distinguibili i contributi. Rosso nell’immagine non equivale automaticamente a temperatura più alta."]}, {"title": "L’esempio di Orione e la formazione stellare", "paragraphs": ["La nebulosa di Orione è un esempio vicino e osservativamente importante di regione di formazione stellare. Le stelle giovani più calde forniscono radiazione capace di rendere luminoso parte del gas circostante. Non è però corretto immaginare che ogni porzione visibile sia una stella pronta a nascere: densità, radiazione e geometria cambiano attraverso la nube.", "La stessa parola “emissione” compare anche quando si descrivono nebulose planetarie e resti di supernova, ma la loro storia è differente da quella di una nube in cui stanno nascendo stelle. Una nebulosa planetaria deriva dall’evoluzione di una stella che ha espulso i propri strati esterni; nei resti di supernova possono contribuire anche onde d’urto. Il meccanismo luminoso e l’origine dell’oggetto sono due livelli di classificazione da tenere distinti."]}, {"title": "Che cosa aspettarsi all’oculare e nelle immagini", "paragraphs": ["Nell’osservazione visuale un oggetto diffuso può mostrare meno colore e meno dettaglio di una fotografia a lunga integrazione. Con poca luce la visione umana non riproduce la sensibilità cromatica di un sensore che accumula segnale per molti minuti. Il contrasto dipende da trasparenza, chiarore del cielo, altezza del soggetto e strumento; una bella immagine d’archivio non è una promessa di ciò che apparirà nell’oculare.", "Per leggere una fotografia controlla soggetto, strumento, filtri e legenda dei colori. Chiediti poi quale componente stai guardando: gas che emette, polvere che diffonde o materiale che oscura lo sfondo. Una nebulosa a riflessione si illumina soprattutto diffondendo la luce stellare; una nube oscura viene riconosciuta perché attenua ciò che sta dietro. Le distinzioni aiutano a trasformare una macchia suggestiva in un ambiente fisico comprensibile."]}], "facts": ["Emissione: il gas produce radiazione dopo aver ricevuto energia", "H II = idrogeno ionizzato, non idrogeno molecolare", "H-alfa: circa 656,3 nm; i colori fotografici richiedono una legenda"], "sources": [{"title": "Treccani · nebulose e classificazione", "url": "https://www.treccani.it/enciclopedia/nebulosa/"}, {"title": "NASA/Hubble · processi nelle nebulose", "url": "https://science.nasa.gov/mission/hubble/science/universe-uncovered/hubble-nebulae/"}, {"title": "ESO · una regione H II", "url": "https://www.eso.org/public/images/potw2003a/"}, {"title": "ESO · gas ionizzato in NGC 6357", "url": "https://www.eso.org/public/images/potw1334a/"}], "archiveReferences": ["Daniele Gasparri, Vent’anni sotto il cielo stellato, pagina PDF 161: formazione stellare e distinzione fra nebulose di diversa origine. Lettura del passaggio, non revisione integrale del volume."], "editorialStatus": "scheda-estesa", "media": {"file": "assets/lezioni/orione-fotografico.jpg", "caption": "Regione di Orione: la fotografia registra molta più luce e dettaglio di quanto si percepisca normalmente all’oculare.", "credit": "Martinbernardi", "source": "https://commons.wikimedia.org/wiki/File:Orion_wide_field.jpg", "license": "CC BY 4.0"}}, {"id": "nebulosa-a-riflessione", "name": "Nebulosa a riflessione", "definition": "Nube le cui polveri diffondono la luce di stelle vicine.", "example": "Non è una galassia a riflessione: l’espressione classifica un meccanismo luminoso della nebulosa.", "source": "https://www.treccani.it/enciclopedia/nebulosa/", "lesson": "lezione-5-4.html", "related": ["nebulosa-a-emissione", "nebulosa-oscura"], "checked": "2026-10-30", "sections": [{"title": "Luce prestata da una stella", "paragraphs": ["Una nebulosa a riflessione è una nube in cui le polveri diffondono verso di noi parte della luce di stelle vicine. Il nome non indica uno specchio liscio: la luce interagisce con grani distribuiti nello spazio e viene deviata in direzioni differenti. La nube diventa visibile grazie a un’illuminazione esterna, anziché per lo stesso meccanismo di una regione di gas ionizzato a emissione."]}, {"title": "Perché viene spesso mostrata blu", "paragraphs": ["La diffusione dipende dalle proprietà e dalle dimensioni dei grani e dalla lunghezza d’onda. Molte nebulose a riflessione risultano azzurre nelle immagini nel visibile, ma il colore osservato dipende anche dalla sorgente illuminante, dalla geometria e dall’estinzione lungo la linea di vista. Non esiste una regola che consenta di classificare qualsiasi macchia blu come nebulosa a riflessione, soprattutto in immagini a falsi colori."]}, {"title": "Il caso delle Pleiadi", "paragraphs": ["Nelle fotografie profonde delle Pleiadi compaiono veli di polvere illuminati dalle stelle dell’ammasso. L’ammasso e la nebulosità non sono la stessa cosa: uno è un insieme di stelle, l’altra è materia diffusa resa visibile dalla loro luce. L’immagine invita a distinguere la posizione apparente dal legame evolutivo. Non si deve supporre automaticamente che ogni polvere visibile attorno a stelle giovani sia il residuo della nube che le ha generate."]}, {"title": "Come leggerla nell’osservazione", "paragraphs": ["Una nebulosità diffusa richiede contrasto, un cielo adatto e attenzione a riflessi e condensa. Un alone prodotto dall’ottica o da una superficie appannata può imitare una nube. I filtri pensati per selezionare righe di emissione non offrono lo stesso vantaggio su una sorgente che diffonde luce stellare continua. Nel diario specifica se hai osservato il velo luminoso o soltanto le stelle che lo illuminano: entrambe sono osservazioni valide, ma raccontano elementi diversi."]}], "facts": ["La polvere diffonde luce stellare", "Un alone ottico non certifica una nebulosa", "Ammasso e nube sono componenti differenti"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/nebulosa/"}], "editorialStatus": "scheda-estesa"}, {"id": "nebulosa-oscura", "name": "Nebulosa oscura", "definition": "Nube che attenua la luce delle sorgenti retrostanti e appare scura rispetto allo sfondo.", "example": "Una zona scura può contenere materia che nasconde stelle, anziché essere uno spazio vuoto.", "source": "https://www.treccani.it/enciclopedia/nebulosa/", "lesson": "lezione-5-4.html", "related": ["nebulosa", "galassia"], "checked": "2026-10-30", "sections": [{"title": "Una nube vista per ciò che nasconde", "paragraphs": ["Una nebulosa oscura è una nube interstellare ricca di polveri che attenua la luce di sorgenti poste dietro di essa. Può apparire come una sagoma scura contro un campo stellare o una regione luminosa. Non è necessariamente uno spazio vuoto. Il contrasto nasce proprio dalla presenza di materiale lungo la linea di vista: il cielo apparentemente più povero di stelle può contenere una nube che ne impedisce la visione."]}, {"title": "Luce assorbita e diffusa", "paragraphs": ["I grani interstellari assorbono e diffondono la radiazione. L’attenuazione dipende dalla lunghezza d’onda: una regione molto opaca nel visibile può risultare più penetrabile nell’infrarosso. Osservazioni in bande differenti permettono quindi di scoprire stelle nascoste e di studiare la materia della nube. Non significa che ogni immagine infrarossa mostri automaticamente tutto ciò che sta dietro: contano densità, banda e sensibilità."]}, {"title": "Il contesto rende riconoscibile la forma", "paragraphs": ["Una sagoma famosa si distingue perché davanti a essa e dietro di essa esistono condizioni favorevoli al contrasto. Senza uno sfondo luminoso adeguato, la stessa nube sarebbe meno evidente. Nelle fotografie la forma può essere accentuata dal trattamento, mentre all’oculare resta tenue. Il soprannome di un oggetto aiuta a ricordarlo, ma non ne descrive né la composizione né la tridimensionalità."]}, {"title": "Il rapporto con la nascita stellare", "paragraphs": ["Nubi fredde e dense possono ospitare regioni in cui la gravità favorisce la formazione di stelle. Tuttavia “oscura” descrive anzitutto l’aspetto nel visibile, non garantisce che in ogni sua parte stiano nascendo stelle. Le osservazioni di gas, polveri e sorgenti giovani vanno combinate. La lezione da conservare è che l’assenza di luce ricevuta non equivale sempre all’assenza di materia: talvolta il primo indizio è proprio un’ombra sullo sfondo."]}], "facts": ["Una zona scura può contenere materia, non essere un vuoto", "Il contrasto dipende dallo sfondo e dalla banda osservata"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/nebulosa/"}], "editorialStatus": "scheda-estesa"}, {"id": "nutazione", "name": "Nutazione", "definition": "La nutazione terrestre è l’insieme di piccole variazioni periodiche dell’orientamento dell’asse, sovrapposte al cambiamento più lento descritto dalla precessione.", "example": "Una componente principale ha periodo di circa 18,6 anni", "source": "https://www.treccani.it/enciclopedia/nutazione/", "lesson": "lezione-1-6.html", "related": ["precessione", "polo-celeste", "eclittica"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Una variazione dentro un movimento più lento", "paragraphs": ["Per introdurre la precessione disegniamo spesso un percorso regolare del polo. Nella realtà il movimento è più articolato. La nutazione aggiunge piccole componenti periodiche rispetto a quel quadro medio. La figura di una linea ondulata su un percorso più ampio aiuta a distinguere le scale, ma le ondulazioni devono essere accentuate per risultare visibili: non rappresentano un grande dondolio del paesaggio percepibile durante la notte."]}, {"title": "Il ruolo della geometria lunare", "paragraphs": ["La variazione delle azioni gravitazionali dipende anche dall’evoluzione dell’orbita lunare. Una componente principale ha un periodo di circa 18,6 anni, collegato al moto dei nodi dell’orbita della Luna. Non va confuso con il Saros delle eclissi, che è un altro intervallo e un’altra combinazione di cicli. Condividere un numero di anni vicino non significa descrivere lo stesso fenomeno, né autorizza a scambiare i due nomi in una lezione."]}, {"title": "Quanto conta per il principiante", "paragraphs": ["Per riconoscere una costellazione stasera non serve calcolare a mano la nutazione. Nella costruzione di riferimenti e posizioni di precisione, invece, la distinzione fra grandezze medie e apparenti diventa importante. Il concetto serve a capire perché una coordinata non sia soltanto un numero privo di contesto. Un’applicazione può gestire trasformazioni accurate internamente mantenendo un’interfaccia semplice, purché non dichiari una precisione superiore a quella del modello effettivamente usato."]}, {"title": "Una rappresentazione onesta", "paragraphs": ["Se il laboratorio mostra insieme precessione e nutazione, deve indicare scale temporali differenti e ampiezze illustrative. Far oscillare il polo a ogni cambio di stagione sarebbe scientificamente fuorviante. Il cielo stagionale cambia soprattutto per la geometria della rivoluzione terrestre e per l’orario osservato, non perché la nutazione trasporti le costellazioni da una regione all’altra. Separare questi fenomeni evita un’animazione spettacolare ma incapace di spiegare quale cambiamento l’utente sta realmente osservando."]}], "facts": ["Una componente principale ha periodo di circa 18,6 anni", "Nutazione e Saros non sono sinonimi"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/nutazione/"}]}, {"id": "obiettivo", "name": "Obiettivo", "definition": "Sistema ottico che raccoglie la luce e forma l’immagine dell’oggetto osservato. Può utilizzare lenti, specchi o entrambi.", "example": "La parola non indica soltanto l’ottica di una macchina fotografica: si usa anche per altri strumenti.", "source": "https://www.treccani.it/vocabolario/obiettivo/", "lesson": "lezione-7-3.html", "related": ["telescopio", "rifrattore", "riflettore"], "checked": "2026-10-30", "sections": [{"title": "La parte che raccoglie e forma l’immagine", "paragraphs": ["In uno strumento ottico l’obiettivo è il sistema che raccoglie la luce della scena e ne forma un’immagine. In un rifrattore è costituito da lenti; in senso funzionale, nei telescopi a riflessione il ruolo principale di raccolta spetta allo specchio primario. Non è l’oculare, che permette all’occhio di osservare l’immagine formata dallo strumento, e non è il sensore che la registra."]}, {"title": "Diametro e focale raccontano cose diverse", "paragraphs": ["Il diametro utile dell’apertura influisce sulla quantità di luce raccolta e sul limite teorico di risoluzione. La lunghezza focale determina la scala dell’immagine sul piano focale. Due obiettivi con la stessa focale possono avere aperture e prestazioni diverse. Il rapporto focale si ottiene dividendo focale per diametro: 500 mm diviso 100 mm dà f/5. È un rapporto senza unità, non un ingrandimento."]}, {"title": "Che cosa cambia nella fotografia", "paragraphs": ["Per una fotocamera, focale e dimensioni del sensore determinano il campo inquadrato. La messa a fuoco porta il piano dell’immagine sul sensore, ma non elimina automaticamente aberrazioni o vibrazioni. La luce delle stelle rende evidenti difetti che possono passare inosservati nella fotografia diurna. Forma delle stelle ai bordi, precisione del fuoco e stabilità del sistema vanno valutate insieme, senza ridurre la qualità al solo numero di millimetri."]}, {"title": "Maneggiarlo durante la serata", "paragraphs": ["L’obiettivo deve essere protetto da urti e condensa, evitando di toccare inutilmente le superfici ottiche. Un paraluce può limitare luce laterale e ritardare l’appannamento in certe condizioni, ma non sostituisce ogni sistema anticondensa. Nel descrivere un corredo specifica separatamente obiettivo, supporto, fotocamera e inseguitore: conoscere il ruolo di ogni pezzo aiuta a capire dove nasce un problema e quale intervento può davvero migliorare l’immagine."]}], "facts": ["Obiettivo ≠ oculare ≠ sensore", "Rapporto focale = focale divisa per apertura"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/vocabolario/obiettivo/"}, {"title": "OpenStax · telescopi", "url": "https://openstax.org/books/astronomy-2e/pages/6-1-telescopes"}], "editorialStatus": "scheda-estesa"}, {"id": "occiduo", "name": "Occiduo", "definition": "Nel contesto del moto diurno, astro che sorge e tramonta rispetto all’orizzonte del luogo.", "example": "Non è una proprietà universale di una stella: cambia con la latitudine di osservazione.", "source": "https://www.treccani.it/vocabolario/occiduo_(Sinonimi-e-Contrari)/", "lesson": "lezione-1-3.html", "related": ["circumpolare", "orizzonte"], "checked": "2026-10-30", "sections": [{"title": "Un astro che attraversa l’orizzonte", "paragraphs": ["In astronomia si dice occiduo un astro che, per il luogo considerato, sorge e tramonta nel moto diurno. La parola non significa semplicemente “a ovest” e non indica una fase evolutiva della stella. Descrive il rapporto geometrico fra il suo percorso apparente e l’orizzonte dell’osservatore. È quindi una proprietà relativa al luogo, come la circumpolarità."]}, {"title": "Tre condizioni da distinguere", "paragraphs": ["Una stella può restare sempre sopra l’orizzonte geometrico, attraversarlo oppure rimanere sempre sotto. Nel primo caso è circumpolare, nel secondo occidua, nel terzo non sorge da quel luogo. Latitudine e declinazione determinano la condizione nell’approssimazione di stelle fisse e orizzonte ideale. A 45° N, per esempio, una stella di declinazione +20° sorge e tramonta, mentre una a +60° rimane sopra il piano dell’orizzonte."]}, {"title": "Una stessa stella, luoghi diversi", "paragraphs": ["Avvicinandosi al polo geografico, la regione circumpolare si allarga; avvicinandosi all’equatore si restringe. Una stella occidua per un osservatore può quindi risultare circumpolare per un altro. La costellazione è una regione estesa e non un punto: alcune sue stelle possono trovarsi ai lati di un limite di visibilità. Dire che un intero disegno è sempre circumpolare in tutta Italia può essere scorretto."]}, {"title": "La geometria non è la serata reale", "paragraphs": ["Sorgere non equivale a diventare immediatamente visibile. La luce del giorno, il crepuscolo, le nubi e gli ostacoli possono impedire l’osservazione. Anche la rifrazione modifica la posizione apparente vicino all’orizzonte. Quando un laboratorio usa il termine occiduo deve dichiarare le semplificazioni e conservare la declinazione della stella mentre ne fa cambiare l’angolo orario, senza spostarla arbitrariamente verso l’equatore celeste."]}], "facts": ["Occiduo = sorge e tramonta per quel luogo", "La condizione dipende da latitudine e declinazione"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/vocabolario/occiduo_(Sinonimi-e-Contrari)/"}, {"title": "USNO · vista locale degli astri", "url": "https://aa.usno.navy.mil/faq/alt_az"}], "editorialStatus": "scheda-estesa"}, {"id": "occultazione", "name": "Occultazione", "definition": "Un’occultazione avviene quando un corpo celeste passa davanti a un altro lungo la linea di vista dell’osservatore e ne nasconde tutta o parte della luce.", "example": "Allineamento apparente non significa vicinanza fisica", "source": "https://www.treccani.it/enciclopedia/occultazione/", "lesson": "lezione-9-3.html", "related": ["luna", "transito", "eclissi"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un incontro prospettico", "paragraphs": ["La Luna può nascondere una stella pur trovandosi enormemente più vicina a noi. Non è necessario che i due corpi siano fisicamente vicini nello spazio: devono allinearsi nella direzione osservata. Lo stesso evento può essere visibile da una zona della Terra e non da un’altra. Per questo una previsione deve specificare luogo e ora, invece di limitarsi a indicare che due oggetti appaiono vicini su una carta generale."]}, {"title": "Scomparsa e ricomparsa", "paragraphs": ["L’istante in cui il bersaglio scompare viene chiamato immersione; quello in cui riappare emersione. Per una stella dietro il bordo lunare il cambiamento può essere molto rapido, mentre dimensioni apparenti e atmosfere possono produrre comportamenti differenti in altri sistemi. Il bordo illuminato o scuro della Luna influisce anche sulla facilità osservativa. Non bisogna però trasformare una regola illustrativa sull’aspetto del bordo in una previsione locale senza verificare la geometria effettiva dell’evento."]}, {"title": "Il valore della misura coordinata", "paragraphs": ["Cronometrare occultazioni da luoghi differenti può fornire informazioni su forma, dimensioni o ambiente del corpo che nasconde il bersaglio. Le misure devono avere riferimenti temporali e posizioni affidabili, con incertezze dichiarate. Un filmato con un orologio non verificato non diventa automaticamente un dato preciso. L’attività divulgativa può prima insegnare il principio con una simulazione, poi distinguere i requisiti di una vera campagna osservativa senza confondere esercizio e risultato scientifico."]}, {"title": "Nomi che dipendono dal contesto", "paragraphs": ["Transito, occultazione ed eclisse si incontrano in geometrie collegate, ma vengono usati secondo convenzioni e fenomeni specifici. In un’eclissi lunare interessa l’ombra terrestre sulla Luna; in un’occultazione stellare interessa il blocco della linea di vista da parte del corpo davanti. Nella figura mostra quindi osservatore, oggetti e direzione della luce. Tre cerchi senza queste informazioni non permettono di capire che cosa viene nascosto e per quale ragione."]}], "facts": ["Allineamento apparente non significa vicinanza fisica", "La visibilità dell’evento dipende anche dal luogo"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/occultazione/"}], "aliases": ["occultazioni"]}, {"id": "oculare", "name": "Oculare", "definition": "L’oculare è il gruppo ottico attraverso cui l’occhio osserva l’immagine formata dal telescopio; non è l’elemento principale che raccoglie luce.", "example": "Oculare da 18 mm su 900 mm → 50×", "source": "https://www.treccani.it/enciclopedia/oculare/", "lesson": "lezione-7-4.html", "related": ["obiettivo", "focale", "ingrandimento"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "L’immagine prima dello sguardo", "paragraphs": ["L’obiettivo del telescopio forma un’immagine e l’oculare la presenta all’occhio con una determinata scala angolare. Non si deve confondere l’oculare con lo specchio primario o con la lente frontale. Cambiandolo si modifica il modo di osservare l’immagine, ma non l’apertura utile del telescopio. Una scatola con molti oculari non equivale quindi a possedere molti diametri diversi di strumento."]}, {"title": "Scegliere l’ingrandimento", "paragraphs": ["Dividi la focale del telescopio per quella dell’oculare: con 900 mm e 18 mm ottieni 50×; con 9 mm ottieni 100×. Sono rapporti fra lunghezze espresse nelle stesse unità. Il maggiore ingrandimento restringe spesso il campo reale e richiede condizioni adeguate per conservare dettaglio. Il campo apparente dichiarato per l’oculare è un’altra proprietà e non coincide con il campo di cielo realmente inquadrato."]}, {"title": "Comodità e posizione dell’occhio", "paragraphs": ["Distanza dell’occhio dalla lente, regolazione delle conchiglie e pupilla d’uscita influenzano l’esperienza. Un posizionamento scorretto può far comparire oscuramenti e rendere difficile vedere tutto il campo. L’estrazione pupillare riguarda la distanza utile dell’occhio, non la lunghezza focale del telescopio. Chi usa occhiali può avere esigenze specifiche, da provare invece di dedurre la comodità dal solo diametro del barilotto."]}, {"title": "Un oggetto adatto al bersaglio", "paragraphs": ["Per cercare una regione estesa è utile partire con un campo ampio e una scala moderata. Per dettagli lunari o planetari si può aumentare gradualmente, finché atmosfera e immagine lo consentono. Un oculare sporco, un fuoco errato o un supporto instabile non si risolvono scegliendo il valore più spinto. Il miglior oculare per una serata è quello che rende accessibile informazione utile nel proprio sistema, non quello che ingrandisce di più sulla confezione."]}], "facts": ["Oculare da 18 mm su 900 mm → 50×", "Campo apparente e campo reale non coincidono"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/oculare/"}], "aliases": ["oculari"]}, {"id": "opposizione", "name": "Opposizione", "definition": "Nella convenzione eclittica geocentrica, l’opposizione al Sole corrisponde a una differenza di 180° di longitudine celeste.", "example": "Opposizione e minima distanza non sono sempre simultanee", "source": "https://www.treccani.it/enciclopedia/opposizione/", "lesson": "lezione-9-3.html", "related": ["congiunzione", "elongazione", "orbita"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Dalla parte opposta rispetto al Sole", "paragraphs": ["Un pianeta esterno all’orbita terrestre può trovarsi in opposizione al Sole. La Terra occupa allora una posizione intermedia nella geometria generale del sistema. La definizione precisa usa una coordinata, normalmente la longitudine eclittica geocentrica. Non implica che i tre centri siano sempre perfettamente collineari nello spazio: le orbite possiedono inclinazioni e l’altra coordinata può introdurre uno scostamento."]}, {"title": "Perché favorisce l’osservazione", "paragraphs": ["Intorno all’opposizione un pianeta esterno è generalmente disponibile per gran parte della notte, sorge circa al tramonto e passa alto nella parte notturna del percorso, secondo declinazione e luogo. La sua distanza dalla Terra è relativamente favorevole e il disco può offrire buone opportunità. Ma la massima altezza locale dipende anche dalla stagione e dalla latitudine: opposizione non significa automaticamente pianeta allo zenit."]}, {"title": "Gli istanti non sono sempre identici", "paragraphs": ["Per orbite reali eccentriche, l’istante della minima distanza non deve coincidere esattamente con quello dell’opposizione. Un’affermazione scolastica che li renda sempre identici è una semplificazione da correggere. Le condizioni utili si estendono inoltre su un intervallo: non tutto si esaurisce in un minuto. Per il lavoro osservativo conviene confrontare altezza, diametro apparente e finestre temporali mediante effemeridi appropriate."]}, {"title": "Il limite dei pianeti interni", "paragraphs": ["Mercurio e Venere, osservati dalla Terra, rimangono legati alla regione apparente del Sole e non raggiungono una normale opposizione come Marte o Giove. Per essi sono importanti le elongazioni. Questa differenza nasce dalle orbite relative, non dal fatto che siano semplicemente più piccoli o meno luminosi. La configurazione è quindi un modo per collegare geometria del Sistema solare e possibilità concrete della serata."]}], "facts": ["Opposizione e minima distanza non sono sempre simultanee", "Mercurio e Venere non raggiungono l’opposizione alla vista terrestre"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/opposizione/"}]}, {"id": "ora-civile", "name": "Ora civile", "definition": "L’ora civile è l’ora adottata per la vita quotidiana in un territorio: nei dati astronomici va specificata insieme a data e fuso.", "example": "CET = UTC +1 · CEST = UTC +2", "source": "https://www.treccani.it/enciclopedia/tempo_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-9-3.html", "related": ["giorno-siderale", "angolo-orario", "anno-luce"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "L’ora dell’orologio non è una coordinata stellare", "paragraphs": ["Quando programmi un’uscita per le 22:00 stai usando un orario civile, non l’ascensione retta di un oggetto e non il tempo siderale locale. L’ora civile permette di coordinare attività nello stesso territorio. Per convertire quel numero nella posizione degli astri servono anche data e luogo. Due località possono condividere l’ora dell’orologio ma avere tramonto e meridiano astronomico in istanti differenti."]}, {"title": "CET e CEST senza mistero", "paragraphs": ["Le sigle distinguono due regimi orari dell’Europa centrale. CET indica l’ora standard, un’ora avanti rispetto a UTC. CEST indica l’ora legale, due ore avanti rispetto a UTC. Per un istante indicato come 20:00 UTC, la lettura è 21:00 in CET oppure 22:00 in CEST. La regola da applicare a una data concreta dipende dal territorio e dalle disposizioni in vigore: non si sceglie la sigla semplicemente in base al caldo o al freddo."]}, {"title": "La correzione si applica una volta", "paragraphs": ["Se un planisfero usa la scala dell’ora standard e l’orologio mostra le 22:00 in ora legale, si imposta l’equivalente delle 21:00 sulla scala standard. Se esiste già una scala dedicata all’ora legale, si usa quella senza sottrarre di nuovo un’ora. Anche il software può aver già eseguito la conversione. Ripeterla sposta il cielo e crea un errore che sembra astronomico ma nasce dal calendario."]}, {"title": "Un diario confrontabile", "paragraphs": ["Scrivi data completa, ora e fuso. Se osservi dopo mezzanotte, annota il giorno effettivo invece di affidarti alla sola espressione “serata del venerdì”. Durante i cambi di ora alcune letture locali possono essere assenti o ripetersi: UTC aiuta a rendere univoco l’istante. La mezzanotte civile non è il mezzogiorno solare, né il passaggio di una particolare stella. Un buon dato temporale chiarisce sempre a quale convenzione si riferisce."]}], "facts": ["CET = UTC +1 · CEST = UTC +2", "Data, ora e fuso vanno conservati insieme"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/tempo_(Dizionario-delle-Scienze-Fisiche)/"}, {"title": "INAF · tempo locale medio e tempo civile", "url": "https://moodle.olimpiadi.inaf.it/mod/page/view.php?id=1063"}], "aliases": ["CET", "CEST"]}, {"id": "orbita", "name": "Orbita", "definition": "Traiettoria percorsa da un corpo attorno a un altro sotto l’azione della gravità.", "example": "Le orbite del puzzle mostrano l’ordine dei pianeti: dimensioni, distanze e posizioni istantanee sono semplificate.", "source": "https://www.treccani.it/enciclopedia/pianeta/", "lesson": "lezione-3-1.html", "related": ["pianeta", "eclittica"], "checked": "2026-10-30", "sections": [{"title": "Una traiettoria sotto l’azione della gravità", "paragraphs": ["L’orbita descrive il moto di un corpo nello spazio sotto l’azione gravitazionale. Non è una rotaia materiale né un cerchio tracciato nel vuoto. Nel modello ideale di due corpi isolati, una traiettoria legata è un’ellisse; il cerchio ne è un caso particolare. Nel Sistema solare reale gli altri corpi esercitano perturbazioni e la traiettoria non si ripete come un disegno rigido immutabile."]}, {"title": "La distanza non resta necessariamente uguale", "paragraphs": ["In un’ellisse il corpo centrale si trova in un fuoco, non al centro geometrico. Il semiasse maggiore descrive la scala dell’orbita, mentre l’eccentricità ne esprime l’allungamento. Per un pianeta intorno al Sole, il perielio è il punto più vicino e l’afelio il più lontano. La velocità varia: il pianeta si muove più rapidamente vicino al perielio e più lentamente vicino all’afelio."]}, {"title": "Tempo e dimensione sono collegati", "paragraphs": ["Per pianeti la cui massa è piccola rispetto a quella solare, il quadrato del periodo in anni è circa uguale al cubo del semiasse maggiore in unità astronomiche. Per esempio, con un semiasse di 4 UA il cubo è 64; il periodo è circa 8 anni perché 8 per 8 dà 64. Non si inserisce nella relazione la distanza istantanea misurata in un punto qualsiasi della traiettoria."]}, {"title": "Leggere un disegno senza farsi ingannare", "paragraphs": ["Nei diagrammi le dimensioni dei pianeti e del Sole sono spesso ingrandite rispetto alle distanze. Anche l’eccentricità può essere accentuata per rendere visibile la differenza fra fuoco e centro. Va dichiarato: altrimenti un’orbita didattica molto allungata può suggerire erroneamente che le stagioni terrestri derivino da grandi variazioni di distanza. Per le stagioni il ruolo fondamentale è invece l’inclinazione dell’asse rispetto al piano orbitale."]}], "facts": ["Orbita ≠ rotaia materiale", "Semiasse maggiore ≠ distanza istantanea", "Un’ellisse ha il corpo centrale in un fuoco"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/pianeta/"}], "editorialStatus": "scheda-estesa"}, {"id": "orizzonte", "name": "Orizzonte", "definition": "Il piano astronomico locale perpendicolare alla verticale dell’osservatore. Il profilo visibile di monti e case è un riferimento diverso.", "example": "Un astro può avere altezza positiva ma essere nascosto da una collina.", "source": "https://www.treccani.it/enciclopedia/orizzonte/", "lesson": "lezione-1-1.html", "related": ["altezza-angolare", "zenit"], "checked": "2026-10-30", "sections": [{"title": "Il piano da cui comincia il cielo locale", "paragraphs": ["Nelle coordinate astronomiche locali l’orizzonte è il piano perpendicolare alla verticale dell’osservatore. La sua intersezione con la sfera celeste forma un cerchio massimo. È il riferimento per misurare l’altezza degli astri: zero su quel piano, valori positivi sopra e negativi sotto. La definizione usa una geometria ideale, non il contorno irregolare che vediamo fra tetti, alberi e montagne."]}, {"title": "Il profilo visibile è un’altra informazione", "paragraphs": ["Da una valle, una montagna può nascondere una stella già sopra l’orizzonte geometrico. Sul mare il limite visibile dipende anche dalla quota dell’osservatore e dalla rifrazione. Una carta che mostra un oggetto a +5° non garantisce quindi che sia libero dagli ostacoli del luogo. Per pianificare bene occorre affiancare alla posizione calcolata la conoscenza reale del sito, soprattutto per bersagli bassi."]}, {"title": "Perché cambia da città a città", "paragraphs": ["La verticale locale segue la posizione dell’osservatore sulla Terra: spostandoci sulla sua superficie, cambia l’orientamento del piano dell’orizzonte rispetto alle stelle. La rotazione terrestre modifica inoltre, durante la notte, le direzioni del cielo rispetto al nostro piano locale. Ecco perché altezza e azimut richiedono luogo e ora, mentre le coordinate equatoriali di catalogo di una stella lontana possono essere condivise fra osservatori."]}, {"title": "Leggere una mappa del cielo", "paragraphs": ["In una carta altazimutale a tutto cielo il bordo rappresenta spesso l’orizzonte e il centro lo zenit. I cerchi interni possono indicare altezze, non distanze in chilometri. Una stella al centro è sopra la testa; una sul bordo è verso l’orizzonte. La carta non è una fotografia della superficie terrestre e il suo orientamento va letto secondo la legenda, in particolare per capire perché l’est possa trovarsi a sinistra quando si guarda verso l’alto."]}], "facts": ["Orizzonte geometrico ≠ profilo degli ostacoli", "Altezza 0° sul piano dell’orizzonte"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/orizzonte/"}, {"title": "USNO · coordinate locali", "url": "https://aa.usno.navy.mil/faq/alt_az"}], "editorialStatus": "scheda-estesa"}, {"id": "parallasse", "name": "Parallasse", "definition": "Variazione apparente della direzione di un oggetto quando cambia il punto di osservazione.", "example": "Guardando un dito prima con un occhio e poi con l’altro lo vedi spostarsi rispetto allo sfondo: è un’analogia di prospettiva.", "source": "https://www.treccani.it/enciclopedia/parallasse/", "lesson": "lezione-6-3.html", "related": ["parsec", "anno-luce"], "checked": "2026-10-30", "sections": [{"title": "Due punti di vista, un piccolo spostamento", "paragraphs": ["La parallasse è una differenza nella direzione apparente di un oggetto osservato da posizioni differenti. Distendi un braccio e guarda un dito, prima con un occhio e poi con l’altro: rispetto allo sfondo sembra spostarsi. Il dito non sta saltando lateralmente. Hai cambiato il punto da cui lo guardi. L’esperienza introduce il principio, ma non riproduce le dimensioni né la precisione di una misura stellare."]}, {"title": "La base della misura stellare", "paragraphs": ["Per la parallasse annua si sfrutta il movimento della Terra lungo l’orbita. Le osservazioni distribuite nell’anno permettono di ricostruire il piccolo moto apparente della stella rispetto a riferimenti più lontani. Il parametro p corrisponde alla parallasse riferita al raggio convenzionale di una unità astronomica. Nella geometria favorevole, fra due posizioni opposte dell’orbita, l’escursione massima è circa 2p. Usare questa escursione come se fosse p dimezzerebbe erroneamente la distanza."]}, {"title": "Il calcolo, senza passaggi nascosti", "paragraphs": ["Se p è espresso in secondi d’arco, la distanza in parsec si ottiene dividendo 1 per p. Con p = 0,1 secondi d’arco: 1 diviso 0,1 dà 10 parsec. Con p = 0,01: 1 diviso 0,01 dà 100 parsec. L’angolo diventa più piccolo quando l’oggetto è più lontano. Il secondo d’arco è un’unità angolare, pari a un tremilaseicentesimo di grado; non è un secondo di tempo."]}, {"title": "Dal principio alla misura reale", "paragraphs": ["Le stelle hanno anche moti propri e possono appartenere a sistemi multipli. Una soluzione astrometrica deve distinguere questi contributi, considerare il riferimento e quantificare le incertezze. Non basta confrontare a occhio due fotografie qualunque. Una parallasse molto incerta non produce una distanza affidabile applicando meccanicamente il reciproco; valori misurati negativi possono derivare dagli errori statistici e non indicano distanze fisiche negative. La qualità del dato viene prima della formula."]}], "facts": ["d in parsec = 1 diviso p in secondi d’arco", "Escursione massima fra posizioni opposte ≈ 2p", "Una misura richiede un’incertezza"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/parallasse/"}, {"title": "NASA · distanze cosmiche", "url": "https://science.nasa.gov/universe/cosmic-distances/"}], "editorialStatus": "scheda-estesa"}, {"id": "parsec", "name": "Parsec", "definition": "Unità di distanza definita attraverso una parallasse annua di un secondo d’arco; equivale a circa 3,26 anni luce.", "example": "È una distanza: non è un tempo di viaggio e non coincide con l’anno luce.", "source": "https://www.treccani.it/enciclopedia/parsec/", "lesson": "lezione-6-3.html", "related": ["parallasse", "anno-luce"], "checked": "2026-10-30", "sections": [{"title": "Un’unità costruita da un angolo", "paragraphs": ["Il parsec è un’unità di lunghezza nata dalla misura della parallasse stellare. Il nome unisce parallasse e secondo d’arco. Un oggetto alla distanza di un parsec presenta una parallasse annua di un secondo d’arco, nella convenzione astronomica. È quindi una distanza, non la durata di un viaggio, una velocità o il tempo necessario alla luce per compiere un percorso."]}, {"title": "Quanto è lungo", "paragraphs": ["Un parsec equivale a circa 3,086 × 10¹³ chilometri, cioè 30.860 miliardi di chilometri, e a circa 3,262 anni luce. Le approssimazioni sono adatte alla divulgazione: non vanno scambiate per uguaglianze esatte. A una stella a 10 parsec attribuiamo perciò una distanza di circa 32,6 anni luce. Il numero in parsec e quello in anni luce descrivono la stessa lunghezza con unità diverse, come metri e chilometri."]}, {"title": "Perché compare nei cataloghi", "paragraphs": ["Con la parallasse p in secondi d’arco, la distanza in parsec è 1 diviso p. A 0,2 secondi d’arco corrispondono 5 parsec; a 0,05 corrispondono 20 parsec. Il vantaggio dell’unità sta nella relazione immediata con una misura angolare. Per distanze più grandi si usano multipli: un kiloparsec vale mille parsec e un megaparsec un milione. Il prefisso modifica l’unità, non il tipo di fenomeno osservato."]}, {"title": "Dove la semplicità non basta", "paragraphs": ["Il reciproco della parallasse è utile quando il dato è adeguatamente preciso. L’incertezza della misura, le correzioni del catalogo e la selezione del campione contano nelle applicazioni reali. Inoltre in cosmologia esistono diverse definizioni operative di distanza: una distanza di luminosità e una distanza comovente non sono intercambiabili soltanto perché entrambe sono espresse in megaparsec. Specificare che cosa è stato misurato resta indispensabile anche quando l’unità è familiare."]}], "facts": ["1 pc ≈ 3,262 anni luce", "1 kpc = 1.000 pc · 1 Mpc = 1.000.000 pc", "1 pc ≈ 30.860 miliardi di km"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/parsec/"}, {"title": "NASA · distanze cosmiche", "url": "https://science.nasa.gov/universe/cosmic-distances/"}], "editorialStatus": "scheda-estesa"}, {"id": "perielio", "name": "Perielio", "definition": "Il perielio è il punto di un’orbita attorno al Sole in cui la distanza dal Sole è minima.", "example": "Perielio: minima distanza dal Sole", "source": "https://www.treccani.it/enciclopedia/perielio_(Enciclopedia-Italiana)/", "lesson": "lezione-3-6.html", "related": ["afelio", "orbita", "cometa"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un riferimento dell’orbita solare", "paragraphs": ["Il nome unisce l’idea di vicinanza a quella del Sole. In un’ellisse il perielio è un estremo dell’asse maggiore dalla parte del fuoco occupato dal Sole. Non è il punto in cui il corpo entra necessariamente nella corona solare, né un luogo identico per tutti i pianeti. Ogni orbita possiede i propri parametri e quindi una propria distanza minima."]}, {"title": "Il moto accelera", "paragraphs": ["Nel modello a due corpi il pianeta o la cometa raggiunge vicino al perielio una velocità maggiore che vicino all’afelio. La gravità modifica continuamente direzione e intensità della velocità. Un corpo non si ferma nel punto più lontano per poi cadere lungo una retta: conserva un moto orbitale. Nei diagrammi il Sole va collocato in un fuoco e le frecce non dovrebbero suggerire una velocità uniforme su un’ellisse allungata."]}, {"title": "Le comete e l’attività", "paragraphs": ["L’avvicinamento al Sole può aumentare l’attività di una cometa, liberando gas e polveri e modificandone l’aspetto. Il massimo di luminosità osservata non coincide però obbligatoriamente con l’istante del perielio: contano distanza dalla Terra, geometria, ritardi fisici e comportamento del nucleo. L’osservabilità dipende anche dall’allontanamento apparente dal Sole, che può rendere difficile o impossibile seguirla dal suolo proprio nel periodo interessante."]}, {"title": "Non è il calendario delle stagioni", "paragraphs": ["Per la Terra il passaggio al perielio avviene nel periodo invernale dell’emisfero nord. La data precisa varia e non va sostituita da un giorno fisso universale. Le stagioni opposte nei due emisferi derivano soprattutto dall’obliquità dell’asse terrestre. Per descrivere un evento concreto serve un’effemeride aggiornata; per capire il concetto bastano la geometria dell’orbita e la distinzione fra distanza dal Sole e inclinazione della luce sul luogo di osservazione."]}], "facts": ["Perielio: minima distanza dal Sole", "Massima attività osservata e perielio non coincidono necessariamente"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/perielio_(Enciclopedia-Italiana)/"}]}, {"id": "perigeo", "name": "Perigeo", "definition": "Il perigeo è il punto di un’orbita attorno alla Terra in cui la distanza dalla Terra è minima.", "example": "Perigeo: minima distanza dalla Terra", "source": "https://www.treccani.it/enciclopedia/apogeo/", "lesson": "lezione-2-4.html", "related": ["apogeo", "orbita", "eclissi"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "L’estremo vicino di un’orbita terrestre", "paragraphs": ["Perigeo e apogeo sono i due riferimenti di distanza estrema per un’orbita geocentrica: minimo e massimo. Il nome non va scambiato con perielio, che riguarda la distanza dal Sole. La Luna attraversa posizioni di distanza terrestre differente e la sua orbita reale non è un’ellisse isolata perfettamente immutabile. Per stabilire l’istante e la distanza di un passaggio concreto servono effemeridi."]}, {"title": "Che cosa cambia nell’immagine", "paragraphs": ["A distanza minore un corpo di dimensione fissa sottende un angolo maggiore. La Luna vicina al perigeo può quindi mostrare un diametro apparente maggiore rispetto a quando è vicina all’apogeo. Questa variazione non significa che la Luna si gonfi fisicamente. Il confronto fotografico richiede stessa scala e condizioni documentate: ritagliare ogni disco per farlo entrare nello stesso cerchio cancella proprio la differenza che si vorrebbe mostrare."]}, {"title": "La parola superluna", "paragraphs": ["Nel linguaggio mediatico si usa spesso questo nome per una Luna piena relativamente vicina al perigeo, con criteri non sempre identici. Non è una nuova fase né un fenomeno che renda automaticamente il cielo diverso da ogni altra luna piena. La luminosità e la percezione dipendono anche da atmosfera, altezza e contesto. Una data divulgativa deve precisare che cosa intende, evitando di trasformare un confronto graduale in un confine fisico improvviso."]}, {"title": "Eclissi e geometria completa", "paragraphs": ["La dimensione apparente della Luna contribuisce alle condizioni di un’eclissi solare, ma la sola vicinanza non produce l’allineamento. Occorrono fase nuova, posizione rispetto ai nodi e luogo dell’osservatore. Una Luna grande all’orizzonte può inoltre essere un’illusione percettiva, distinta dalla variazione orbitale. Separare queste cause aiuta a leggere immagini e notizie: distanza dalla Terra, altezza nel cielo e forma della fase raccontano informazioni diverse."]}], "facts": ["Perigeo: minima distanza dalla Terra", "Diametro apparente maggiore non significa Luna fisicamente più grande"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/apogeo/"}]}, {"id": "pianeta", "name": "Pianeta", "definition": "Nel Sistema solare: corpo in orbita intorno al Sole, quasi sferico per la propria gravità e dinamicamente dominante nella sua zona orbitale.", "example": "La classificazione IAU del 2006 distingue gli otto pianeti dai pianeti nani, fra cui Plutone.", "source": "https://www.treccani.it/enciclopedia/pianeta/", "lesson": "lezione-3-1.html", "related": ["orbita", "stella"], "checked": "2026-10-30", "sections": [{"title": "Una categoria di corpi, non un tipo di paesaggio", "paragraphs": ["Un pianeta è un corpo celeste la cui classificazione dipende dalle proprietà fisiche e dinamiche, non dall’avere oceani, una superficie abitabile o un colore particolare. Nel Sistema solare la definizione IAU del 2006 richiede che orbiti attorno al Sole, abbia massa sufficiente a raggiungere una forma prossima all’equilibrio sotto la propria gravità e abbia ripulito la zona circostante la propria orbita. Non deve essere un satellite."]}, {"title": "Che cosa significa ripulire", "paragraphs": ["Il requisito dinamico non dice che lungo l’orbita non possa esistere alcun granello o asteroide. Indica il ruolo dominante del corpo nella propria regione orbitale. I pianeti nani soddisfano i requisiti legati all’orbita solare e alla forma, ma non quello della dominanza dinamica. Plutone non è stato cancellato dal Sistema solare: è stato classificato diversamente. Le pagine storiche che elencano nove pianeti vanno lette nel loro contesto temporale."]}, {"title": "Mondi molto differenti", "paragraphs": ["Gli otto pianeti del Sistema solare comprendono corpi rocciosi e giganti con strutture e atmosfere diverse. La dimensione apparente in cielo non misura direttamente quella reale: dipende anche dalla distanza. Inoltre un pianeta può brillare intensamente perché riflette luce solare, senza produrre come una stella l’energia della propria luminosità visibile attraverso la fusione nucleare. L’aspetto al telescopio dipende da diametro angolare, fase, atmosfera e condizioni osservative."]}, {"title": "Oltre il Sistema solare", "paragraphs": ["Gli esopianeti orbitano attorno ad altre stelle o ad altri oggetti secondo criteri di classificazione specifici. La formulazione del 2006 riguarda espressamente il Sistema solare e non va estesa parola per parola a ogni scoperta extrasolare. Massa, raggio, orbita e metodi di rilevazione contribuiscono alla descrizione dei nuovi mondi. “Pianeta simile alla Terra” richiede sempre di precisare in quale proprietà avvenga la somiglianza."]}], "facts": ["Otto pianeti nel Sistema solare", "La definizione IAU 2006 riguarda il Sistema solare"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/pianeta/"}, {"title": "IAU · risoluzione definitiva B5/B6", "url": "https://www.iau.org/static/resolutions/Resolution_GA26-5-6.pdf"}], "editorialStatus": "scheda-estesa"}, {"id": "pixel", "name": "Pixel", "definition": "Il pixel è un elemento di un’immagine digitale; nel contesto del sensore va distinto dal modo in cui l’immagine viene visualizzata o ricampionata.", "example": "Più pixel nel file non garantiscono più dettagli reali", "source": "https://www.treccani.it/enciclopedia/pixel/", "lesson": "astrofotografia.html", "related": ["sensore", "focale", "fotometria"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un campione, non un piccolo astro", "paragraphs": ["Un’immagine digitale è rappresentata da valori disposti su una griglia. Ogni elemento contribuisce alla descrizione della scena. Una stella copre normalmente più campioni attraverso la figura ottica, il seeing e le altre trasformazioni del sistema. Non è corretto identificare ogni punto chiaro con una stella distinta o ricavare direttamente la grandezza fisica di un astro dal numero di pixel luminosi dopo l’elaborazione."]}, {"title": "Dimensione fisica e dimensione sullo schermo", "paragraphs": ["I siti sensibili di un rivelatore hanno una scala fisica, mentre i pixel visualizzati possono essere ingranditi, ridotti o interpolati. Aumentare le dimensioni del file con un ricampionamento non produce automaticamente nuovi dettagli osservati. La risoluzione numerica dell’immagine e il contenuto informativo sono concetti collegati ma differenti. Una foto molto grande può restare sfocata; una figura vettoriale può essere nitida senza contenere una misura fotografica."]}, {"title": "La scala angolare", "paragraphs": ["Focale e dimensione fisica dei campioni determinano quale porzione di cielo corrisponde a un pixel, secondo il sistema. Una focale maggiore distribuisce lo stesso angolo su una scala più ampia. La scelta deve confrontarsi con seeing, ottica e precisione di inseguimento: campionare molto finemente non recupera dettagli che non arrivano sul rivelatore. Anche il campo totale dipende dal numero e dalla dimensione dei campioni."]}, {"title": "Valori che richiedono interpretazione", "paragraphs": ["Un pixel può contenere contributi di sorgente, cielo e rumore strumentale. Saturazione e difetti alterano il risultato. Nei sensori a colori, la matrice di filtri e la ricostruzione aggiungono passaggi prima dell’immagine finale. Per questo contare semplicemente pixel rossi o bianchi non equivale a una misura fisica. Calibrazione, metadati e descrizione dell’elaborazione rendono leggibile il rapporto fra griglia digitale e fenomeno osservato."]}], "facts": ["Più pixel nel file non garantiscono più dettagli reali", "Pixel del sensore e pixel visualizzato non sono la stessa scala"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/pixel/"}]}, {"id": "plasma", "name": "Plasma", "definition": "In fisica un plasma è un insieme di particelle con una componente significativa di cariche libere, capace di comportamenti collettivi elettromagnetici.", "example": "Plasma fisico ≠ plasma sanguigno", "source": "https://www.treccani.it/enciclopedia/plasma/", "lesson": "lezione-4-1.html", "related": ["stella", "spettro", "nebulosa-a-emissione"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Materia che risponde ai campi", "paragraphs": ["Un gas neutro contiene atomi o molecole senza carica complessiva. Se alcuni elettroni vengono separati dagli atomi, compaiono elettroni liberi e ioni. In condizioni appropriate il loro insieme costituisce un plasma. Il termine in astronomia non riguarda il plasma sanguigno. Le cariche possono rispondere a campi elettrici e magnetici e influenzarsi collettivamente: non basta immaginare un gas ordinario semplicemente dipinto di un colore luminoso."]}, {"title": "Dove lo incontriamo nel cielo", "paragraphs": ["Stelle, corona solare, vento solare e molte regioni di gas interstellare coinvolgono materia ionizzata. Temperatura, densità e grado di ionizzazione possono però differire enormemente. Non tutti questi ambienti hanno le stesse condizioni del nucleo solare e non ogni nube interstellare è completamente ionizzata. Occorre specificare il processo che produce e mantiene le cariche libere, per esempio riscaldamento o radiazione energetica."]}, {"title": "Perché può emettere luce", "paragraphs": ["Particelle cariche ed atomi interagiscono in modi che possono produrre radiazione. Le righe spettrali raccontano transizioni e condizioni fisiche, mentre altre emissioni possono avere un andamento continuo. Il colore di una fotografia dipende dalle bande registrate e dalla loro rappresentazione. Una spirale luminosa in un’illustrazione non dimostra direttamente la forma di un campo magnetico: per ricostruirlo si usano osservazioni e modelli appropriati."]}, {"title": "Un concetto che collega fenomeni diversi", "paragraphs": ["Il plasma aiuta a comprendere il collegamento fra attività solare e ambiente terrestre, ma non riduce l’aurora a luce solare riflessa. Particelle energetiche e atmosfera interagiscono, con il campo magnetico che organizza una parte della dinamica. Nel Sole, a sua volta, il movimento della materia e i campi magnetici contribuiscono alla complessità delle strutture visibili. Il vocabolo è utile proprio quando permette di passare dalla semplice apparenza luminosa al comportamento fisico della materia."]}], "facts": ["Plasma fisico ≠ plasma sanguigno", "Temperatura, densità e ionizzazione vanno distinte"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/plasma/"}]}, {"id": "polo-celeste", "name": "Polo celeste", "definition": "Uno dei due punti in cui il prolungamento dell’asse di rotazione terrestre incontra la sfera celeste.", "example": "La Polare è prossima al Polo Nord celeste, ma non coincide esattamente con esso.", "source": "https://www.treccani.it/enciclopedia/polo_(Enciclopedia-Italiana)/", "lesson": "lezione-1-2.html", "related": ["equatore-celeste", "circumpolare"], "checked": "2026-10-30", "sections": [{"title": "Dove punta l’asse terrestre", "paragraphs": ["I poli celesti sono le direzioni in cui l’asse di rotazione terrestre, prolungato idealmente, incontra la sfera celeste. Sono due punti opposti: Polo Nord celeste e Polo Sud celeste. Non sono corpi materiali, né coincidono esattamente con stelle. La Polare si trova vicino al Polo Nord celeste e offre un riferimento pratico approssimato, ma i due nomi non sono sinonimi."]}, {"title": "Il cielo gira attorno a queste direzioni", "paragraphs": ["A causa della rotazione terrestre, le stelle sembrano descrivere cerchi attorno ai poli celesti. La loro distanza angolare dal polo è collegata alla declinazione. Una fotografia di scie stellari mostra bene questa struttura: vicino al polo le tracce sono archi piccoli, più lontano diventano più ampi. Il centro delle scie non è lo zenit dell’osservatore, salvo il caso particolare del polo geografico."]}, {"title": "L’altezza dipende dalla latitudine", "paragraphs": ["Nell’emisfero nord l’altezza geometrica del Polo Nord celeste sull’orizzonte è uguale alla latitudine geografica del luogo. A Roma è circa 42°, non 23,4°. Quest’ultimo angolo riguarda invece l’obliquità dell’asse rispetto alla perpendicolare al piano orbitale. Mescolare i due riferimenti produce schemi sbagliati: un disegno deve sempre specificare rispetto a quale piano sta misurando l’inclinazione."]}, {"title": "Che cosa si allinea in una montatura", "paragraphs": ["L’asse polare di una montatura equatoriale va disposto parallelamente all’asse terrestre, rivolto al polo celeste appropriato. La rotazione intorno a quell’asse permette di compensare il moto diurno. L’asse di declinazione è perpendicolare a quello polare. Non si inclina tutto il sistema di un valore fisso universale: l’orientamento rispetto all’orizzonte cambia con il luogo. Anche la direzione del polo rispetto alle stelle varia lentamente per la precessione."]}], "facts": ["Polo celeste = direzione dell’asse terrestre", "A 42° N il polo è alto circa 42°", "Obliquità e latitudine sono angoli diversi"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/polo_(Enciclopedia-Italiana)/"}, {"title": "USNO · sistemi di riferimento", "url": "https://aa.usno.navy.mil/faq/ICRS_doc"}], "editorialStatus": "scheda-estesa", "aliases": ["poli celesti", "PNC"]}, {"id": "precessione", "name": "Precessione", "definition": "In astronomia la precessione comprende cambiamenti lenti dell’orientamento dei riferimenti terrestri e orbitali; la precessione dell’asse terrestre modifica nel tempo le direzioni dei poli celesti.", "example": "La Polare non è sempre stata né sarà sempre la stella più vicina al polo", "source": "https://www.treccani.it/enciclopedia/nutazione/", "lesson": "lezione-1-6.html", "related": ["polo-celeste", "punto-equinoziale", "nutazione"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "L’asse non punta sempre alla stessa stella", "paragraphs": ["La rotazione quotidiana della Terra non esaurisce i suoi movimenti. L’orientamento dell’asse varia lentamente e il polo celeste descrive un percorso rispetto alle stelle. La Polare è vicina al polo nord celeste nella nostra epoca, ma non è un perno eterno fissato all’Universo. Il ciclo principale è dell’ordine di ventiseimila anni, una scala molto più lunga di una stagione o di una serata osservativa."]}, {"title": "L’analogia della trottola ha un limite", "paragraphs": ["Una trottola inclinata può aiutare a immaginare un asse che cambia direzione. La Terra non è però una trottola appoggiata su un pavimento: i meccanismi e le forze vanno descritti nel contesto gravitazionale del sistema. Sole e Luna agiscono sul rigonfiamento equatoriale terrestre. Il disegno del cono riassume un movimento, ma non dimostra che il polo celeste sia un oggetto materiale o che tutte le stelle ruotino fisicamente insieme lungo quel cono."]}, {"title": "I cataloghi richiedono riferimenti dichiarati", "paragraphs": ["Se cambia l’orientamento dell’equatore celeste rispetto alle stelle, cambiano le coordinate equatoriali espresse rispetto a riferimenti diversi. Per confrontare dati di epoche o sistemi differenti servono trasformazioni coerenti. Questo non contraddice l’utilità delle coordinate di catalogo da luoghi diversi della Terra: indica un’altra dipendenza, quella dal riferimento e dal tempo. L’aggiornamento corretto non consiste nello spostare arbitrariamente le costellazioni fra zone della sfera celeste."]}, {"title": "Non confonderla con altri cambiamenti", "paragraphs": ["Il moto proprio di una stella, la nutazione e la rivoluzione annuale hanno significati differenti. In una figura introduttiva conviene separarli prima di sovrapporli. Anche l’orientamento delle orbite può subire precessioni: bisogna dire quale asse o linea sta cambiando. Una parola generica senza il riferimento porta il lettore a immaginare un unico grande movimento indistinto; una spiegazione precisa permette invece di collegare la mappa attuale alla storia dei riferimenti celesti."]}], "facts": ["La Polare non è sempre stata né sarà sempre la stella più vicina al polo", "Dichiara quale asse o riferimento subisce precessione"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/nutazione/"}]}, {"id": "pulsar", "name": "Pulsar", "definition": "Una pulsar è una stella di neutroni dalla quale riceviamo impulsi periodici legati alla rotazione e alla geometria dell’emissione.", "example": "Pulsar ≠ Cefeide", "source": "https://www.treccani.it/enciclopedia/pulsar/", "lesson": "lezione-10-3.html", "related": ["stella", "supernova", "spettro"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un faro come analogia", "paragraphs": ["L’analogia del faro aiuta a capire il segnale: una sorgente rotante invia emissione in direzioni privilegiate e noi riceviamo impulsi se la geometria porta quella regione verso l’osservatore. Non significa che la stella si accenda e si spenga tutta a ogni impulso. Anche il termine pulsar, nato dalle prime osservazioni radio, non limita il fenomeno a un unico intervallo dello spettro."]}, {"title": "Un oggetto compatto, non una stella ordinaria pulsante", "paragraphs": ["Le pulsar sono associate a stelle di neutroni, residui estremamente compatti di percorsi evolutivi particolari. Il loro comportamento non è quello di una Cefeide che varia raggio e luminosità attraverso pulsazioni. Il periodo può essere molto breve e viene studiato con strumenti e procedure temporali precise. La frequenza degli impulsi e la sua evoluzione permettono di ricostruire proprietà del sistema, con modelli che distinguono i contributi diversi."]}, {"title": "La precisione non elimina i cambiamenti", "paragraphs": ["Molte pulsar sono riferimenti temporali straordinariamente regolari, ma non sono orologi ideali immutabili. Il rallentamento della rotazione, variazioni improvvise e l’eventuale moto in un sistema binario possono influenzare i tempi di arrivo. Anche la propagazione nel mezzo interstellare lascia effetti che vanno corretti. Non si interpreta un singolo ritardo come prova automatica di un pianeta compagno o di un fenomeno gravitazionale."]}, {"title": "Cosa mostra una fotografia", "paragraphs": ["Un’immagine di una nebulosa può contenere la regione alimentata da una pulsar, ma non mostrare impulsi visibili a occhio. Una riproduzione animata del faro è un modello esplicativo, non un filmato ripreso da vicino. Le vecchie cifre sul numero di pulsar note in alcune enciclopedie sono datate e non vengono riportate qui come inventario attuale. Il nucleo del concetto è il rapporto fra oggetto compatto, rotazione, emissione e tempi misurati."]}], "facts": ["Pulsar ≠ Cefeide", "L’impulso dipende anche dalla geometria verso l’osservatore"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/pulsar/"}]}, {"id": "punto-equinoziale", "name": "Punto equinoziale", "definition": "Intersezione fra eclittica ed equatore celeste. Quello di primavera è l’origine convenzionale dell’ascensione retta.", "example": "Il riferimento è una direzione del sistema di coordinate, non una stella fissata per sempre nel cielo.", "source": "https://www.treccani.it/enciclopedia/equinozi_(Enciclopedia-Italiana)/", "lesson": "lezione-1-6.html", "related": ["ascensione-retta", "eclittica"], "checked": "2026-10-30", "sections": [{"title": "L’origine di una coordinata", "paragraphs": ["Nel sistema equatoriale classico il punto equinoziale di primavera è la direzione in cui l’eclittica incontra l’equatore celeste al passaggio del Sole dall’emisfero celeste sud a quello nord. Si chiama anche punto vernale o punto gamma. È un riferimento geometrico, non una stella e non il punto dell’orizzonte da cui il Sole sorge in una particolare città."]}, {"title": "Perché equatore ed eclittica si incontrano", "paragraphs": ["L’equatore celeste è il prolungamento del piano equatoriale terrestre. L’eclittica descrive il percorso annuo apparente del Sole sullo sfondo stellare, legato al piano dell’orbita terrestre. I due piani sono inclinati di circa 23,4° e si intersecano lungo una linea che individua due direzioni opposte. Una corrisponde all’equinozio di primavera, l’altra a quello d’autunno, usando i nomi stagionali convenzionali dell’emisfero nord."]}, {"title": "Da quel punto si misura l’ascensione retta", "paragraphs": ["L’origine dell’ascensione retta classica vale 0 h nel punto vernale. Da lì si misura verso est lungo l’equatore celeste fino al cerchio orario dell’astro. Un giro vale 24 h, equivalenti a 360°. La declinazione misura invece lo scostamento nord–sud dall’equatore. Le ore indicano qui una coordinata angolare: un oggetto a 6 h di ascensione retta non è per questo osservabile alle sei dell’orologio."]}, {"title": "Un riferimento con una storia", "paragraphs": ["La precessione modifica lentamente l’orientamento dell’asse e del riferimento equinoziale rispetto alle stelle. Perciò coordinate classiche riferite a equinozi diversi non si confrontano ignorando questa informazione. Nei cataloghi moderni esistono riferimenti come ICRS che richiedono una descrizione più precisa di quella scolastica. Il punto equinoziale resta essenziale per capire l’origine del sistema, ma non autorizza a trattare ogni catalogo come se usasse automaticamente lo stesso equinozio."]}], "facts": ["Punto vernale: origine classica AR = 0 h", "Eclittica ed equatore celeste si intersecano in due punti"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/equinozi_(Enciclopedia-Italiana)/"}, {"title": "USNO · ICRS", "url": "https://aa.usno.navy.mil/faq/ICRS_doc"}], "editorialStatus": "scheda-estesa"}, {"id": "quasar", "name": "Quasar", "definition": "Un quasar è un nucleo galattico attivo molto luminoso, alimentato dall’accrescimento di materia attorno a un buco nero supermassiccio.", "example": "Aspetto quasi stellare ≠ stella", "source": "https://www.treccani.it/enciclopedia/quasar/", "lesson": "lezione-6-2.html", "related": ["buco-nero", "galassia", "redshift"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Sembra un punto, ma non è una stella", "paragraphs": ["Il nome deriva dall’aspetto quasi stellare che rese difficili le prime identificazioni. Un quasar non è una stella enorme isolata: è l’attività di una regione centrale di una galassia. La luce può dominare quella delle stelle circostanti e rendere difficile distinguere la galassia ospite. L’apparenza puntiforme dipende dalla distanza e dalla risoluzione, non da una dimensione realmente uguale a quella di una stella ordinaria."]}, {"title": "Da dove arriva l’energia", "paragraphs": ["Materia che cade verso un buco nero può formare strutture di accrescimento e liberare energia prima di attraversare l’orizzonte. Non stiamo ricevendo luce che esce dall’interno del buco nero. Gas, disco e altre componenti contribuiscono a uno spettro complesso. Alcuni sistemi mostrano getti potenti, ma il nome quasar non impone che ogni oggetto abbia la stessa radioemissione o lo stesso orientamento verso di noi."]}, {"title": "Spettri e grandi distanze", "paragraphs": ["Le righe spettrali, identificate e confrontate con valori di laboratorio, permettono di misurare il redshift. Per sorgenti cosmologiche la traduzione in distanza ed epoca richiede un modello dell’espansione. Non basta che il punto appaia rosso nella fotografia. Guardare molto lontano significa ricevere luce emessa in un Universo più giovane; ciò non rende però tutti i quasar oggetti identici o tutti situati alla stessa distanza."]}, {"title": "Il caso di un nome celebre", "paragraphs": ["TON 618 è un esempio spesso citato nelle discussioni sui buchi neri molto massicci. Le stime dipendono da metodi, calibrazioni e incertezze: non si deve usare un numero popolare come primato eterno o diametro direttamente fotografato. La lezione generale è più importante della classifica: una piccola sorgente sul cielo può testimoniare un processo estremamente energetico su scala galattica, ricostruito attraverso luce, variabilità e dinamica del materiale."]}], "facts": ["Aspetto quasi stellare ≠ stella", "La luce proviene dal materiale esterno all’orizzonte"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/quasar/"}]}, {"id": "radiazione", "name": "Radiazione elettromagnetica", "definition": "La radiazione elettromagnetica trasporta energia e comprende onde radio, microonde, infrarosso, luce visibile, ultravioletto, raggi X e gamma.", "example": "Visibile = una parte dello spettro elettromagnetico", "source": "https://www.treccani.it/enciclopedia/radiazione/", "lesson": "lezione-4-3.html", "related": ["fotone", "spettro", "redshift"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La luce è una parte della storia", "paragraphs": ["L’occhio registra soltanto una porzione dello spettro elettromagnetico. Molti fenomeni astronomici emettono anche in bande invisibili per noi, osservate con strumenti adatti. Radio, infrarosso e raggi X non sono decorazioni aggiunte a una fotografia: sono modi differenti di raccogliere informazione fisica. Il termine radiazione è più generale e può comprendere anche particelle; qui specifichiamo il caso elettromagnetico."]}, {"title": "Lunghezza d’onda e frequenza", "paragraphs": ["La lunghezza d’onda è la distanza fra fasi equivalenti dell’onda, mentre la frequenza riguarda il numero di oscillazioni per unità di tempo. Nel vuoto, a lunghezza d’onda maggiore corrisponde frequenza minore. Le due descrizioni parlano dello stesso segnale. Non si tratta della dimensione dell’oggetto emittente: una galassia può essere studiata a lunghezze d’onda radio senza avere un diametro pari alla lunghezza di quell’onda."]}, {"title": "L’atmosfera seleziona quello che arriva", "paragraphs": ["Alcune bande attraversano bene l’atmosfera terrestre, altre vengono fortemente assorbite. Questo contribuisce a spiegare perché esistano telescopi spaziali e osservatori situati in ambienti particolari. Un telescopio al suolo non diventa sensibile a tutte le radiazioni soltanto aumentando il diametro. Rivelatore, ottiche, trasmissione atmosferica e disturbi devono essere adatti alla misura scelta."]}, {"title": "Leggere immagini oltre il visibile", "paragraphs": ["Per mostrare dati invisibili si assegnano colori alle bande registrate. Una composizione può rivelare strutture che l’occhio non vedrebbe direttamente e restare scientificamente informativa, purché la legenda chiarisca il significato. Colore rappresentato e colore naturale non sono automaticamente equivalenti. Confrontare la stessa regione in bande diverse permette di distinguere gas caldo, polveri, stelle e processi energetici, evitando di ridurre tutta l’astronomia a ciò che appare in una sola fotografia."]}], "facts": ["Visibile = una parte dello spettro elettromagnetico", "Colore assegnato ai dati ≠ necessariamente colore visto dall’occhio"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/radiazione/"}]}, {"id": "redshift", "name": "Redshift", "definition": "Lo spostamento verso il rosso indica un aumento della lunghezza d’onda osservata rispetto al valore a riposo della stessa caratteristica spettrale.", "example": "Esempio: (550 − 500) / 500 = 0,1", "source": "https://www.treccani.it/enciclopedia/redshift/", "lesson": "lezione-6-5.html", "related": ["spettro", "galassia", "parallasse"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il confronto deve riguardare la stessa riga", "paragraphs": ["Per misurare uno spostamento si identifica una caratteristica dello spettro e la si confronta con il suo valore di laboratorio. Non basta che una galassia appaia rossa in fotografia: popolazione stellare, polveri e filtri possono modificarne il colore. La misura richiede una corrispondenza fra righe e una calibrazione della scala delle lunghezze d’onda. Il segno positivo indica lunghezze d’onda osservate maggiori del riferimento."]}, {"title": "Il significato di z e di lambda", "paragraphs": ["La lettera greca λ indica la lunghezza d’onda. Il numero z si ottiene sottraendo il valore a riposo da quello osservato e dividendo la differenza per il valore a riposo. Se una riga che vale 500 unità viene misurata a 550 nelle stesse unità, la differenza è 50 e 50 diviso 500 dà z = 0,1. È un rapporto senza unità: non è una distanza di 0,1 anni luce."]}, {"title": "Cause differenti", "paragraphs": ["Il moto relativo può produrre uno spostamento Doppler. Un campo gravitazionale può modificare le frequenze ricevute. Per sorgenti cosmologiche l’espansione dello spazio durante il viaggio della luce contribuisce ad allungare le lunghezze d’onda. Questi fenomeni non si descrivono sempre con la stessa formula semplice. In particolare non è corretto moltiplicare indiscriminatamente qualsiasi z per la velocità della luce e chiamare il risultato velocità ordinaria di allontanamento."]}, {"title": "Dalla misura alla storia cosmica", "paragraphs": ["Per oggetti abbastanza vicini, con le opportune cautele, la relazione di Hubble–Lemaître collega la tendenza dell’allontanamento alla distanza. Alle grandi distanze la conversione fra redshift, epoca e tipi di distanza richiede un modello cosmologico e i suoi parametri. I moti locali introducono ulteriori contributi. Il redshift è quindi un dato prezioso, ma non un metro universale che restituisce ogni distanza con una sola moltiplicazione."]}], "facts": ["Esempio: (550 − 500) / 500 = 0,1", "z è un rapporto senza unità; λ è una lunghezza d’onda"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/redshift/"}]}, {"id": "riflessione", "name": "Riflessione", "definition": "In ottica la riflessione rinvia parte della luce nel mezzo da cui proviene quando incontra una superficie; è il principio usato dagli specchi dei telescopi.", "example": "Gli angoli si misurano dalla normale alla superficie", "source": "https://www.treccani.it/enciclopedia/riflessione/", "lesson": "lezione-7-3.html", "related": ["riflettore", "rifrazione", "catadiottrico"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il raggio cambia direzione alla superficie", "paragraphs": ["Nella rappresentazione geometrica si disegna il raggio incidente, la normale alla superficie e il raggio riflesso. Per la riflessione speculare l’angolo d’incidenza e quello di riflessione sono uguali, misurati rispetto alla normale. Quest’ultima è la perpendicolare locale alla superficie, non il bordo del foglio. Se un diagramma misura gli angoli rispetto a linee differenti senza dirlo, anche una legge semplice diventa apparentemente contraddittoria."]}, {"title": "Uno specchio curvo raccoglie luce", "paragraphs": ["Le direzioni delle normali cambiano da punto a punto su una superficie curva. Un profilo ottico opportuno permette di far convergere verso una regione focale raggi provenienti da una sorgente lontana. Non basta però disegnare un arco qualsiasi: forma, lavorazione e geometria del sistema determinano l’immagine. Nei riflettori astronomici gli specchi devono quindi rispettare un progetto preciso, non la sola somiglianza esterna con una superficie lucida."]}, {"title": "La riflessione non riguarda soltanto gli specchi", "paragraphs": ["Una superficie ruvida può distribuire la luce in molte direzioni e contribuire a ciò che vediamo di un oggetto illuminato. Luna e pianeti sono visibili anche grazie alla luce solare diffusa o riflessa dal loro ambiente e dalle superfici. Non per questo producono lo stesso tipo di immagine di uno specchio piano. Nelle nebulose a riflessione interviene la diffusione della luce stellare sulle particelle: l’etichetta non va interpretata come un enorme specchio levigato nello spazio."]}, {"title": "Distinguere gli altri processi", "paragraphs": ["Rifrazione, assorbimento ed emissione descrivono fenomeni differenti che possono convivere in un sistema. Un vetro può trasmettere e rifrangere parte della luce e rifletterne un’altra parte. I trattamenti ottici cercano di gestire questi contributi secondo lo scopo. Nel laboratorio del telescopio, frecce coerenti e superfici riconoscibili aiutano a capire il percorso; non bisogna far passare un raggio attraverso uno specchio opaco soltanto per collegare graficamente due componenti."]}], "facts": ["Gli angoli si misurano dalla normale alla superficie", "Speculare, diffuso e rifratto non sono sinonimi"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/riflessione/"}]}, {"id": "riflettore", "name": "Riflettore", "definition": "Telescopio che usa uno specchio come elemento principale per raccogliere e focalizzare la luce.", "example": "Nel Newtoniano uno specchio secondario devia la luce verso il lato del tubo.", "source": "https://www.treccani.it/enciclopedia/telescopio_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-7-3.html", "related": ["rifrattore", "obiettivo"], "checked": "2026-10-30", "sections": [{"title": "Raccogliere la luce con uno specchio", "paragraphs": ["Un telescopio riflettore usa uno specchio primario come elemento principale di raccolta della luce. La superficie curva devia i raggi verso un fuoco; altri elementi possono condurli all’oculare o a un sensore. Non è semplicemente un tubo più corto o più largo di un rifrattore. La distinzione riguarda il principio ottico e la disposizione delle superfici che formano l’immagine."]}, {"title": "Il caso del Newton", "paragraphs": ["Nel telescopio newtoniano uno specchio primario concavo raccoglie la luce e uno specchio secondario piano, inclinato, la devia lateralmente verso il focheggiatore. Il secondario non è un oculare e non si trova arbitrariamente nel percorso. La geometria deve far coincidere il fascio con il piano focale. Per questo la collimazione, cioè il corretto allineamento degli elementi ottici, è importante per sfruttare le prestazioni dello strumento."]}, {"title": "Vantaggi e compromessi", "paragraphs": ["Lo specchio evita l’aberrazione cromatica propria della rifrazione semplice, ma non rende l’immagine priva di difetti. Coma, ostruzione centrale, qualità delle superfici, temperatura e supporti meccanici possono influenzare il risultato. Un Newton veloce può richiedere un correttore di coma per la fotografia a largo campo. Il diametro non basta: occorrono montatura adeguata, equilibrio e condizioni atmosferiche favorevoli."]}, {"title": "Non confondere schema e montatura", "paragraphs": ["Un riflettore può stare su supporti altazimutali o equatoriali. “Dobson” indica una soluzione di montaggio pratica, frequentemente associata a un tubo Newton, non una terza legge ottica. Un assemblaggio didattico deve mostrare tubo, punti di fissaggio, supporto e accessori riconoscibili. Le parti non si possono sovrapporre come blocchi intercambiabili: asse ottico, baricentro e collegamenti reali determinano il funzionamento."]}], "facts": ["Specchio primario: raccolta · secondario: deviazione del fascio", "Newton è uno schema ottico; Dobson un tipo di supporto"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/telescopio_(Dizionario-delle-Scienze-Fisiche)/"}, {"title": "OpenStax · telescopi", "url": "https://openstax.org/books/astronomy-2e/pages/6-1-telescopes"}], "editorialStatus": "scheda-estesa", "aliases": ["riflettori"]}, {"id": "rifrattore", "name": "Rifrattore", "definition": "Telescopio il cui obiettivo principale è costituito da lenti.", "example": "Rifrattore e montatura equatoriale non sono sinonimi: uno descrive l’ottica, l’altra il supporto.", "source": "https://www.treccani.it/enciclopedia/telescopio_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-7-3.html", "related": ["riflettore", "telescopio"], "checked": "2026-10-30", "sections": [{"title": "Il nome racconta il percorso della luce", "paragraphs": ["Un rifrattore è un telescopio il cui elemento ottico principale è un obiettivo a lenti. La luce attraversa i vetri e cambia direzione per rifrazione; il sistema viene progettato per far convergere i raggi e formare un’immagine. Questa definizione distingue l’ottica del tubo, non il tipo di montatura: lo stesso rifrattore può essere sostenuto da una montatura altazimutale oppure equatoriale.", "Guardando lo strumento riconosci generalmente l’obiettivo nella parte anteriore, il tubo che mantiene distanze e allineamenti, e il focheggiatore nella parte posteriore. Per uso visuale si inserisce un oculare; in molte configurazioni si aggiunge un diagonale che rende più comoda la posizione dell’osservatore. Per fotografare, il sensore può essere collocato sul percorso dell’immagine senza usare un oculare."]}, {"title": "Raccogliere luce e ingrandire non sono la stessa operazione", "paragraphs": ["L’apertura è il diametro utile dell’obiettivo. Influenza la quantità di luce raccolta e la capacità teorica di distinguere dettagli angolari, insieme alle condizioni reali di osservazione. La lunghezza focale descrive invece la scala con cui il sistema forma l’immagine. Non basta leggere un ingrandimento molto elevato sulla confezione per conoscere la qualità o l’utilità del telescopio.", "Nell’uso visuale ordinario l’ingrandimento si ricava dividendo la focale del telescopio per quella dell’oculare, espresse nella stessa unità. Un esempio: tubo da 600 mm e oculare da 20 mm danno 30 ingrandimenti; con un oculare da 10 mm diventano 60. L’operazione non crea nuova luce e non garantisce che l’atmosfera o l’ottica rendano visibili dettagli sempre più fini. Un’immagine più grande può anche diventare più difficile da leggere."]}, {"title": "Perché servono più lenti", "paragraphs": ["Il vetro non devia tutte le lunghezze d’onda nello stesso modo. Un obiettivo semplice può portare i colori a fuoco in posizioni differenti, producendo aloni e perdita di nitidezza: è l’aberrazione cromatica. Combinare lenti con caratteristiche opportune permette di correggerla. Le denominazioni acromatico e apocromatico descrivono differenti criteri di correzione; non sono una garanzia assoluta di prestazioni indipendenti da progetto, lavorazione e controllo.", "Anche la fotografia introduce esigenze particolari. Un’immagine nitida al centro non assicura stelle puntiformi su tutto un sensore ampio; per alcune configurazioni servono accessori correttivi e distanze di lavoro specifiche. Un riduttore o spianatore non si sceglie soltanto perché entra nel focheggiatore: occorre verificare compatibilità e istruzioni del costruttore."]}, {"title": "Il tubo fa parte di un sistema", "paragraphs": ["Un piccolo rifrattore può essere trasportabile, ma montatura, treppiede, alimentazione e camera contribuiscono all’ingombro dell’intero corredo. Le vibrazioni del supporto possono compromettere un’ottica buona; in fotografia l’inseguimento e l’allineamento diventano parte del risultato. Inoltre “rifrattore” non significa automaticamente “strumento per principianti” o “strumento solo per i pianeti”: diametro, focale, sensore e obiettivo osservativo cambiano l’impiego.", "Per orientarti fra i componenti segui il percorso: luce dall’astro, obiettivo, immagine al fuoco, oculare oppure sensore. Poi osserva separatamente il sostegno: montatura, collegamento al tubo e treppiede. Capire questi due percorsi — quello della luce e quello dei carichi — permette di leggere una fotografia dello strumento e di preparare domande precise sul montaggio, senza affidarsi soltanto alla sua somiglianza con un disegno."]}], "facts": ["Rifrattore: obiettivo principale a lenti", "Esempio: focale 600 mm / oculare 20 mm = 30×", "Ottica e montatura descrivono parti diverse del sistema"], "sources": [{"title": "Treccani · telescopio, Dizionario delle Scienze Fisiche", "url": "https://www.treccani.it/enciclopedia/telescopio_(Dizionario-delle-Scienze-Fisiche)/"}, {"title": "NASA · Telescopes 101", "url": "https://science.nasa.gov/universe/telescopes-101/"}, {"title": "OpenStax · telescopi e formazione dell’immagine", "url": "https://openstax.org/books/astronomy-2e/pages/6-1-telescopes"}, {"title": "OpenStax · aberrazioni ottiche", "url": "https://openstax.org/books/college-physics/pages/26-6-aberrations"}], "archiveReferences": [], "editorialStatus": "scheda-estesa", "aliases": ["rifrattori"]}, {"id": "rifrazione", "name": "Rifrazione", "definition": "La rifrazione modifica la propagazione della luce attraverso mezzi con proprietà ottiche differenti e contribuisce sia al funzionamento delle lenti sia alla vista atmosferica degli astri.", "example": "Altezza geometrica e apparente possono differire", "source": "https://www.treccani.it/enciclopedia/rifrazione/", "lesson": "lezione-8-4.html", "related": ["rifrattore", "orizzonte", "aberrazione-cromatica"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La direzione può cambiare", "paragraphs": ["Quando la luce attraversa mezzi con indici di rifrazione differenti, il percorso può deviare secondo la geometria dell’interfaccia. Un oggetto parzialmente immerso nell’acqua può apparire spostato o spezzato senza essersi deformato materialmente. Le lenti usano superfici e materiali appropriati per guidare i raggi e formare un’immagine. La rifrazione non è riflessione: il segnale non torna semplicemente indietro dalla stessa superficie."]}, {"title": "L’atmosfera non è un blocco uniforme", "paragraphs": ["L’indice cambia gradualmente con le condizioni dell’aria, così il percorso atmosferico non equivale a quello attraverso il vuoto. Una stella può apparire a un’altezza diversa da quella geometrica. L’effetto è particolarmente importante vicino all’orizzonte e dipende dalle condizioni atmosferiche. Un valore standard è un modello utile, non la misura del profilo d’aria di ogni sera e di ogni città."]}, {"title": "I colori non seguono esattamente lo stesso cammino", "paragraphs": ["La dipendenza dalla lunghezza d’onda può produrre dispersione. Su un pianeta basso si possono notare bordi di colori differenti anche usando un riflettore. Non si deve quindi diagnosticare automaticamente un obiettivo difettoso. L’atmosfera può inoltre alterare la forma apparente del Sole o della Luna vicino all’orizzonte: non è il corpo che diventa improvvisamente schiacciato nella propria struttura."]}, {"title": "Geometrico e apparente nelle carte", "paragraphs": ["Un programma deve dichiarare se riporta altezze geometriche oppure corrette per un modello di rifrazione. Per sorgere e tramonto entrano anche dimensione del disco e definizione dell’evento. Una semplice carta didattica può ignorare la rifrazione se lo dice e non promette precisioni eccessive. Questa distinzione mantiene utile il modello e impedisce di attribuire un errore delle stelle a una differenza di convenzione o di condizioni atmosferiche."]}], "facts": ["Altezza geometrica e apparente possono differire", "Rifrazione ≠ riflessione"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/rifrazione/"}]}, {"id": "rotazione", "name": "Rotazione", "definition": "La rotazione descrive un cambiamento di orientamento attorno a un asse; in astronomia va distinta dalla rivoluzione orbitale.", "example": "Rotazione ≠ rivoluzione", "source": "https://www.treccani.it/enciclopedia/rotazione/", "lesson": "lezione-2-1.html", "related": ["terra", "giorno-siderale", "luna"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Girare su se stessi e orbitare", "paragraphs": ["Per la Terra distinguiamo la rotazione attorno al proprio asse e la rivoluzione attorno al Sole. Una persona che ruota su se stessa cambia direzione dello sguardo senza dover percorrere un’orbita attorno a un oggetto. I due movimenti possono convivere, come accade alla Luna: rotazione sincrona significa che compie un giro su se stessa nello stesso tempo medio della rivoluzione pertinente, non che rimanga priva di rotazione."]}, {"title": "L’asse è un riferimento geometrico", "paragraphs": ["L’asse di rotazione ideale attraversa il corpo e individua due poli. Non è un’asta materiale interna. Il suo orientamento va descritto rispetto a un riferimento: per l’obliquità terrestre si confronta con la perpendicolare al piano orbitale, mentre l’altezza del polo nel cielo dipende dal luogo. Un disegno con un’asta inclinata senza indicare il piano di misura lascia il lettore davanti a un angolo ambiguo."]}, {"title": "Il cielo sembra muoversi", "paragraphs": ["La rotazione terrestre fa cambiare la nostra linea di vista verso stelle lontane e produce gran parte del moto diurno apparente. Non occorre che le stelle compiano un giro attorno alla casa ogni notte. Conservando la declinazione, una stella percorre il proprio parallelo celeste. Il periodo di ritorno dipende dal riferimento: rispetto al Sole e rispetto al riferimento siderale non si ottiene lo stesso intervallo."]}, {"title": "La realtà può essere più complessa", "paragraphs": ["Un corpo esteso non deve ruotare in modo perfettamente rigido. Nel Sole e nei pianeti fluidi o gassosi si studiano movimenti e periodi che dipendono dalla regione e dalla definizione adottata. Un numero unico può essere una convenzione utile, ma non la descrizione di ogni nube o strato. Questa cautela aiuta a leggere animazioni delle tempeste: far ruotare una texture intera a velocità uniforme è un modello grafico, non una misura completa della dinamica atmosferica."]}], "facts": ["Rotazione ≠ rivoluzione", "Rotazione sincrona non significa assenza di rotazione"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/rotazione/"}]}, {"id": "secondo-d-arco", "name": "Secondo d’arco", "definition": "Il secondo d’arco è un’unità angolare pari a un sessantesimo di primo d’arco, cioè a un tremilaseicentesimo di grado; si indica con ″.", "example": "1″ = 1/3.600 di grado", "source": "https://www.treccani.it/enciclopedia/grado/", "lesson": "lezione-6-3.html", "related": ["grado-angolare", "parallasse", "parsec"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un piccolo angolo, non un istante", "paragraphs": ["Il simbolo del secondo d’arco ricorda quello usato per i secondi in altri contesti, ma qui misura un angolo. Se una scheda riporta una separazione di due secondi d’arco, non sta descrivendo due secondi di durata. La parola arco serve proprio a evitare l’equivoco. Anche il secondo d’ascensione retta appartiene a una notazione diversa: sul cerchio equatoriale corrisponde a quindici secondi d’arco, non a uno."]}, {"title": "Dalla Luna ai dettagli più fini", "paragraphs": ["La Luna occupa grossomodo mezzo grado, cioè circa trenta primi o 1.800 secondi d’arco. Un secondo d’arco è dunque una piccolissima frazione del suo diametro apparente. Il confronto offre una scala intuitiva senza promettere che ogni telescopio distingua agevolmente strutture di quell’ampiezza. Apertura, contrasto, seeing e qualità dell’immagine limitano il dettaglio accessibile e vanno separati dalla precisione con cui possiamo scrivere un numero sulla scheda."]}, {"title": "Perché compare nella parallasse", "paragraphs": ["Gli spostamenti parallattici stellari sono molto piccoli e si esprimono spesso in secondi d’arco o loro frazioni. Il parsec è legato a un angolo parallattico di un secondo d’arco nella definizione geometrica pertinente. Non si usa automaticamente lo spostamento totale fra due osservazioni come se fosse quel singolo angolo. Il disegno deve indicare quale metà della geometria viene chiamata parallasse, soprattutto quando la separazione fra le posizioni è accentuata per renderla visibile."]}, {"title": "Come leggere una precisione dichiarata", "paragraphs": ["Seeing, separazione stellare, dimensione apparente e incertezza astrometrica possono essere espressi con la stessa unità ma non sono la stessa grandezza. Una camera che campiona un secondo d’arco per pixel non garantisce un’immagine risolta fino a un secondo d’arco. Leggi quindi sempre il nome della quantità oltre all’unità. Nel laboratorio il numero deve accompagnare l’arco o la misura corretta, evitando simboli isolati che sembrano formule da memorizzare senza significato."]}], "facts": ["1″ = 1/3.600 di grado", "Secondo d’arco ≠ secondo di tempo"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/grado/"}], "aliases": ["secondo d’arco", "secondi d’arco", "secondi d'arco"]}, {"id": "seeing", "name": "Seeing", "definition": "La turbolenza atmosferica altera e allarga l’immagine degli astri: il seeing descrive questo effetto sulla qualità osservativa.", "example": "Seeing ≠ trasparenza ≠ messa a fuoco", "source": "https://www.treccani.it/enciclopedia/seeing/", "lesson": "lezione-7-5.html", "related": ["diffrazione", "fuoco", "telescopio"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "L’immagine attraversa aria in movimento", "paragraphs": ["Anche con un telescopio ben regolato una stella può tremare, allargarsi e cambiare forma. L’atmosfera non è una lastra uniforme: differenze di temperatura e densità modificano il cammino della luce. La turbolenza produce variazioni rapide del fronte d’onda che lo strumento raccoglie. Il seeing riguarda questo disturbo, non la semplice presenza di nubi e non il numero di stelle visibili a occhio nudo."]}, {"title": "Una misura angolare, con condizioni dichiarate", "paragraphs": ["Nelle misure professionali il seeing viene spesso espresso in secondi d’arco attraverso la larghezza di un’immagine stellare in condizioni standardizzate. Un valore minore indica generalmente una minore degradazione atmosferica. Il confronto richiede però di conoscere metodo, lunghezza d’onda e direzione di misura. Il diametro della macchia stellare in una propria fotografia contiene anche contributi dell’ottica, del fuoco, del campionamento e dell’inseguimento: non è automaticamente una misura pura del seeing."]}, {"title": "Un esempio da riconoscere", "paragraphs": ["Se il bordo di Giove sembra ondeggiare e i dettagli compaiono per brevi istanti, aumentare l’ingrandimento non stabilizza l’aria. Un pianeta più alto sull’orizzonte può offrire un percorso atmosferico più favorevole. Anche un tetto caldo o uno strumento non acclimatato possono peggiorare l’immagine localmente. Annotare altezza del bersaglio e comportamento visivo è più utile che descrivere ogni notte soltanto come limpida o nuvolosa."]}, {"title": "Non confonderlo con trasparenza e fuoco", "paragraphs": ["Una notte molto scura e trasparente può avere immagini planetarie instabili; una notte meno trasparente può offrire dettagli abbastanza fermi. La messa a fuoco cerca il piano corretto dell’immagine, ma non cancella la turbolenza. Brevi esposizioni e selezione dei fotogrammi possono sfruttare istanti migliori nell’imaging planetario, senza garantire risultati identici in ogni situazione. Nel diario separa quindi buio, trasparenza, stabilità atmosferica e regolazione dello strumento."]}], "facts": ["Seeing ≠ trasparenza ≠ messa a fuoco", "Il secondo d’arco misura un angolo"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/seeing/"}, {"title": "ESO · condizioni osservative", "url": "https://www.eso.org/sci/observing/phase2/ObsConditions.html"}], "archiveReferences": ["Fulvio Mete, Cenni di astronomia pratica per neofiti, pagina PDF 48: effetti locali; le generalizzazioni stagionali non sono adottate come previsione universale."]}, {"id": "sensore", "name": "Sensore fotografico", "definition": "Un sensore fotografico converte una parte della radiazione ricevuta in un segnale misurabile, con una risposta e limiti propri.", "example": "Sensore ≠ obiettivo", "source": "https://www.treccani.it/enciclopedia/sensore/", "lesson": "astrofotografia.html", "related": ["pixel", "fotone", "obiettivo"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il punto in cui la luce diventa dato", "paragraphs": ["L’obiettivo forma l’immagine e il sensore registra il segnale. Non sono la stessa funzione. Il rivelatore risponde alla radiazione con una conversione fisica che porta a quantità leggibili dall’elettronica. Non ogni fotone incidente viene convertito in un evento utile. La risposta dipende da lunghezza d’onda, struttura, impostazioni e caratteristiche del dispositivo, che vanno distinte dalla luminosità reale della sorgente."]}, {"title": "Dimensione e campo", "paragraphs": ["A parità di focale, un sensore più esteso inquadra una porzione maggiore di cielo, se il sistema ottico la copre in modo utile. Il numero di megapixel non descrive da solo questa estensione né la sensibilità. Anche dimensione dei campioni, rumore e gamma del segnale contano. Un sensore grande dietro un collegamento troppo stretto può registrare bordi fortemente attenuati invece di una porzione di campo realmente utilizzabile."]}, {"title": "Segnale, fondo e saturazione", "paragraphs": ["L’esposizione accumula contributi della sorgente e del cielo, insieme a effetti del dispositivo. Un valore elevato non è automaticamente un dettaglio prezioso: può essere saturato e aver perso informazione. Impostazioni elettroniche o amplificazione non equivalgono a raccogliere nuovi fotoni. Per soggetti deboli occorre ragionare sul rapporto fra segnale e disturbi, non soltanto sul fatto che l’anteprima diventi più chiara."]}, {"title": "Un sistema, non un accessorio isolato", "paragraphs": ["Ottica, fuoco, supporto, inseguimento e calibrazione devono lavorare insieme. Una camera moderna non corregge da sola un asse polare orientato male o una lente appannata. I dati originali e le impostazioni permettono di capire che cosa sia stato misurato e che cosa aggiunto dall’elaborazione. Il progresso didattico sta nel collegare il sensore alla catena completa, evitando di trasformare il suo prezzo o i megapixel in una garanzia automatica di qualità."]}], "facts": ["Sensore ≠ obiettivo", "Megapixel, dimensione fisica e risposta sono proprietà differenti"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/sensore/"}]}, {"id": "sfera-celeste", "name": "Sfera celeste", "definition": "Superficie immaginaria sulla quale rappresentiamo le direzioni degli astri, senza collocarli tutti alla stessa distanza reale.", "example": "È una mappa delle direzioni: non un guscio materiale attorno alla Terra.", "source": "https://www.treccani.it/enciclopedia/sfera-celeste/", "lesson": "lezione-1-1.html", "related": ["costellazione", "polo-celeste"], "checked": "2026-10-30", "sections": [{"title": "Una superficie immaginaria per le direzioni", "paragraphs": ["La sfera celeste è un modello geometrico sul quale rappresentiamo le direzioni degli astri. Immaginiamo di prolungare le linee di vista fino a una superficie sferica. Non stiamo dicendo che le stelle siano incollate a un guscio o che si trovino tutte alla stessa distanza. La sfera ci aiuta a ordinare gli angoli, come una carta geografica aiuta a ordinare luoghi senza riprodurre tutte le loro proprietà fisiche."]}, {"title": "Chi sta al centro?", "paragraphs": ["In una rappresentazione geocentrica il centro è la Terra; in una descrizione locale possiamo porre l’osservatore al centro. Per stelle lontane la differenza fra i due punti è trascurabile in molte attività introduttive, ma per oggetti vicini e misure precise non lo è. Nei disegni la persona deve quindi essere collocata coerentemente con il modello scelto, non fuori da una cupola che dovrebbe rappresentare il cielo visto dal suo interno."]}, {"title": "Cerchi diversi, riferimenti diversi", "paragraphs": ["Equatore e poli celesti si collegano alla rotazione terrestre. Orizzonte e zenit si collegano invece alla posizione dell’osservatore. Questi riferimenti possono essere disegnati sulla stessa sfera, ma non si sostituiscono a vicenda. Le coordinate equatoriali usano ascensione retta e declinazione; quelle locali usano azimut e altezza. Per confrontarle occorrono luogo e tempo, oltre a convenzioni e sistema di riferimento."]}, {"title": "Il limite utile del modello", "paragraphs": ["Due stelle vicine sul disegno possono essere separate nello spazio da enormi distanze. Le linee di una costellazione esprimono un riconoscimento prospettico, non legami materiali. Per raccontare una struttura tridimensionale serve aggiungere le distanze. La sfera celeste rimane però uno strumento potente: permette di cercare un oggetto, descriverne il percorso e costruire carte senza confondere la direzione in cui guardiamo con la distanza che ci separa da ciò che vediamo."]}], "facts": ["La sfera rappresenta direzioni, non un guscio materiale", "Orizzonte locale ed equatore celeste non coincidono normalmente"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/sfera-celeste/"}], "editorialStatus": "scheda-estesa"}, {"id": "sistema-solare", "name": "Sistema solare", "definition": "Il Sistema solare comprende il Sole e i corpi e materiali legati al suo ambiente gravitazionale, non soltanto gli otto pianeti.", "example": "Otto pianeti, ma molti altri corpi", "source": "https://www.treccani.it/enciclopedia/sistema-solare/", "lesson": "lezione-3-1.html", "related": ["sole", "pianeta", "asteroide"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La stella e molti mondi differenti", "paragraphs": ["Il Sole contiene la maggior parte della massa del sistema. Attorno a esso si muovono pianeti, pianeti nani, piccoli corpi e popolazioni diffuse, mentre i pianeti possono avere satelliti e anelli. Gli otto pianeti principali non esauriscono quindi il contenuto del Sistema solare. Un atlante che mostri soltanto otto grandi sfere racconta l’ordine più noto, ma deve lasciare spazio alla varietà dei corpi minori e dei materiali."]}, {"title": "Un ordine che non è una scala uniforme", "paragraphs": ["Mercurio, Venere, Terra, Marte, Giove, Saturno, Urano e Nettuno si succedono nell’ordine consueto delle orbite principali. Le distanze non sono però equidistanti e le dimensioni non sono proporzionali agli spazi mostrati in molte infografiche. Le orbite sono inoltre tridimensionali e non cerchi perfetti sullo stesso foglio. Un puzzle può insegnare l’ordine senza fingere di rappresentare anche le distanze reali."]}, {"title": "Una storia ricostruita", "paragraphs": ["Il sistema si è formato attraverso l’evoluzione di materiale attorno al giovane Sole, con accrescimento, collisioni e successivi cambiamenti. Non possediamo una fotografia del nostro sistema durante la nascita. Osservazioni di dischi attorno ad altre stelle, meteoriti, superfici planetarie e modelli contribuiscono alla ricostruzione. Un’animazione protoplanetaria è quindi una rappresentazione di processi, non un filmato storico del passato terrestre."]}, {"title": "Confini diversi per domande diverse", "paragraphs": ["L’ambiente dominato dal vento solare e l’insieme dei corpi gravitazionalmente legati non hanno un unico bordo materiale identico. Parlare del confine del Sistema solare richiede di dire quale fenomeno si considera. Anche l’estremo di una mappa non è una barriera fisica. La lezione importante è collegare stella, corpi e ambiente, senza trasformare un diagramma comodo in una pianta completa e in scala dell’intero sistema."]}], "facts": ["Otto pianeti, ma molti altri corpi", "Ordine delle orbite ≠ distanze uguali"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/sistema-solare/"}]}, {"id": "sole", "name": "Sole", "definition": "Il Sole è la stella del nostro Sistema solare: la sua radiazione, gravità e attività determinano gran parte dell’ambiente dei pianeti.", "example": "Il Sole è una stella, non una palla in combustione chimica", "source": "https://www.treccani.it/enciclopedia/sole/", "lesson": "lezione-2-3.html", "related": ["stella", "vento-solare", "sistema-solare"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Una stella che possiamo studiare da vicino", "paragraphs": ["Il Sole non è un corpo fondamentalmente diverso dalle stelle soltanto perché lo vediamo come un disco. La vicinanza permette di risolvere strutture che negli altri astri sono molto più difficili da osservare. È composto soprattutto da idrogeno ed elio e presenta regioni con condizioni differenti. La superficie apparente nel visibile è una regione da cui emerge molta radiazione, non una crosta solida sulla quale appoggiare uno strumento."]}, {"title": "L’energia nasce in profondità", "paragraphs": ["Nella fase attuale la fusione dell’idrogeno nel nucleo alimenta la produzione di energia. Questa viene trasportata attraverso l’interno prima di essere irradiata all’esterno. Non è una combustione chimica che richiede ossigeno atmosferico. La temperatura efficace della superficie non va sostituita a quella del nucleo: descrivono regioni e significati diversi. Un’immagine in una certa banda mostra soltanto alcuni strati e processi, non una radiografia completa di tutto il volume."]}, {"title": "Una sorgente variabile nei fenomeni", "paragraphs": ["Macchie, regioni attive, brillamenti ed espulsioni di materiale testimoniano una dinamica complessa, fortemente collegata ai campi magnetici. Non sono tutti lo stesso fenomeno. La presenza di una macchia non basta a prevedere da sola un evento diretto verso la Terra. Anche l’immagine arancione del Sole può essere una scelta di rappresentazione di dati: colore assegnato e banda osservata devono restare nella didascalia."]}, {"title": "Osservazione consapevole", "paragraphs": ["La vicinanza non rende il Sole un bersaglio da cercare con strumenti ordinari senza protezioni appropriate. Un telescopio o binocolo concentra radiazione e richiede una configurazione solare correttamente filtrata davanti alle aperture, secondo istruzioni adatte. Una fotografia sullo schermo può essere esplorata in sicurezza, ma non sostituisce queste procedure sul campo. Il suo valore didattico cresce quando permette di identificare una struttura e capire in quale banda sia stata registrata."]}], "facts": ["Il Sole è una stella, non una palla in combustione chimica", "La foto deve dichiarare banda e rappresentazione cromatica"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/sole/"}]}, {"id": "solstizio", "name": "Solstizio", "definition": "Un solstizio è l’istante in cui il Sole raggiunge uno degli estremi annuali della sua declinazione, verso nord o verso sud dell’equatore celeste.", "example": "Giugno: estate boreale, inverno australe", "source": "https://www.treccani.it/enciclopedia/solstizio/", "lesson": "lezione-2-2.html", "related": ["declinazione", "equinozio", "anno-tropico"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Gli estremi del percorso annuale", "paragraphs": ["Nel corso dell’anno la declinazione del Sole varia fra valori boreali e australi. Ai solstizi raggiunge i due estremi, di circa ventitré gradi e mezzo in valore assoluto nell’epoca attuale. Non è un cambiamento improvviso di traiettoria: attorno all’estremo la variazione giornaliera è lenta. Il termine richiama proprio l’impressione che il Sole indugi vicino alla posizione limite prima di tornare verso declinazioni meno estreme."]}, {"title": "La durata del giorno cambia secondo l’emisfero", "paragraphs": ["Al solstizio di giugno l’emisfero nord ha il massimo stagionale della durata diurna e quello sud il minimo; a dicembre avviene il contrario. Nei pressi delle regioni polari entrano anche giorno e notte polari. Non bisogna immaginare la stessa scena in ogni città. Il collegamento nasce dall’inclinazione dell’asse terrestre rispetto al piano orbitale, non dalla maggiore o minore vicinanza al Sole lungo l’orbita."]}, {"title": "Un istante, non un mese meteorologico", "paragraphs": ["Il solstizio ha un orario calcolabile e non cade necessariamente sempre nella stessa data civile. Le stagioni meteorologiche e quelle astronomiche seguono criteri differenti. Anche il periodo più caldo o più freddo non deve coincidere esattamente con il solstizio, perché suolo, aria e acqua rispondono con tempi propri. Una pagina divulgativa deve distinguere l’evento geometrico dalle condizioni meteorologiche generali, senza trasformare un calendario stagionale in una previsione locale."]}, {"title": "Un’esperienza con le ombre", "paragraphs": ["Con un’asta verticale stabile si possono confrontare direzione e lunghezza dell’ombra in momenti definiti del giorno e dell’anno. Per capire la variazione occorre mantenere chiaro il riferimento orario e l’orizzonte del luogo. Un’ombra più corta indica un Sole più alto nel confronto appropriato, ma da sola non identifica automaticamente la data del solstizio. Il laboratorio aiuta a collegare misura e geometria senza richiedere di guardare direttamente il Sole o di puntarlo con strumenti non protetti."]}], "facts": ["Giugno: estate boreale, inverno australe", "Le stagioni dipendono soprattutto dall’obliquità, non dalla distanza Terra–Sole"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/solstizio/"}], "aliases": ["solstizi"]}, {"id": "spettro", "name": "Spettro", "definition": "Distribuzione della radiazione nelle sue componenti, per esempio secondo la lunghezza d’onda.", "example": "Le righe possono fornire indizi sulla materia che emette o assorbe la luce. Non sono semplici strisce decorative.", "source": "https://www.treccani.it/enciclopedia/spettro/", "lesson": "lezione-4-3.html", "related": ["stella", "nebulosa-a-emissione"], "checked": "2026-10-30", "sections": [{"title": "Separare la luce per leggerne le tracce", "paragraphs": ["Uno spettro mostra come la radiazione di una sorgente si distribuisce nelle diverse lunghezze d’onda, o nelle frequenze corrispondenti. Nel visibile possiamo immaginarlo come una sequenza di colori, ma lo studio spettroscopico si estende anche oltre quelli percepibili dall’occhio. Un prisma o un reticolo può separare la luce; il grafico dello spettro misura quantitativamente quanto segnale arriva in ciascuna regione."]}, {"title": "Continui e righe", "paragraphs": ["Uno spettro può presentare un andamento continuo con righe più scure o più luminose. Atomi, ioni e molecole interagiscono con la radiazione a energie caratteristiche, lasciando tracce che aiutano a riconoscere la materia. La posizione di una riga non basta però a descrivere tutta la sorgente: intensità, larghezza e combinazione delle righe dipendono dalle condizioni fisiche e dalla geometria del materiale osservato."]}, {"title": "Dallo spostamento al significato", "paragraphs": ["Confrontando una riga identificata con il suo valore di laboratorio possiamo misurarne lo spostamento. Se la lunghezza d’onda osservata è maggiore, si parla di spostamento verso il rosso. Il simbolo λ indica la lunghezza d’onda; z esprime la differenza relativa rispetto al valore a riposo. Le cause possono comprendere moto relativo, gravità ed espansione cosmica: non è corretto tradurre ogni spostamento in una velocità usando indiscriminatamente la stessa approssimazione."]}, {"title": "Una fotografia non è uno spettro", "paragraphs": ["Il colore complessivo di una stella o di una galassia è un’informazione integrata, modificata anche da filtri, sensore e assorbimento. Non sostituisce l’identificazione delle righe. La spettroscopia richiede calibrazione e controllo degli effetti atmosferici e strumentali. La sua forza divulgativa sta nel rendere concreta una possibilità sorprendente: dalla luce ricevuta possiamo ricostruire proprietà di materia che non possiamo prelevare direttamente, distinguendo sempre misura e interpretazione."]}], "facts": ["λ indica una lunghezza d’onda", "Colore fotografico e spettro non sono la stessa misura"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/spettro/"}], "editorialStatus": "scheda-estesa"}, {"id": "stella", "name": "Stella", "definition": "Oggetto astrofisico che, durante parte della propria evoluzione, produce energia attraverso la fusione nucleare.", "example": "Il Sole è una stella. La brillantezza apparente di una stella dipende anche dalla distanza e dall’assorbimento.", "source": "https://www.treccani.it/enciclopedia/stella/", "lesson": "lezione-4-1.html", "related": ["magnitudine-apparente", "galassia"], "checked": "2026-10-30", "sections": [{"title": "Un corpo che produce energia", "paragraphs": ["Una stella è un corpo autogravitante di gas e plasma la cui storia è governata dalla gravità, dalla pressione e dalla produzione e dal trasporto dell’energia. Durante la sequenza principale la fusione dell’idrogeno nel nucleo alimenta la luminosità. Non è una palla che brucia come un combustibile nell’aria. Il Sole è la stella vicina che ci consente di studiare direttamente molti fenomeni altrimenti osservati soltanto come punti luminosi."]}, {"title": "Un punto apparente nasconde un mondo", "paragraphs": ["La maggior parte delle stelle rimane puntiforme negli strumenti amatoriali a causa della grande distanza. La dimensione della macchia nell’immagine dipende da diffrazione, atmosfera, messa a fuoco, sensore e trattamento. Non è normalmente il diametro fisico della stella ingrandito sulla fotografia. Per questo una stella più brillante può apparire più larga in una ripresa senza essere necessariamente più grande nella realtà."]}, {"title": "Massa, temperatura e luminosità", "paragraphs": ["La massa iniziale influenza profondamente l’evoluzione e la durata della vita stellare. Temperatura superficiale e raggio concorrono alla luminosità intrinseca; la luce ricevuta dipende anche dalla distanza e dall’assorbimento. Il colore fornisce indizi, ma la fotografia può modificarlo. Non tutte le stelle seguono la stessa traiettoria evolutiva e una relazione approssimata fra massa e luminosità non va applicata indistintamente a giganti, nane bianche e protostelle."]}, {"title": "Nascita, trasformazione e residui", "paragraphs": ["Le stelle si formano in regioni di nubi che collassano e si frammentano. Dopo le fasi di fusione la loro evoluzione dipende dalla massa e dalle interazioni con eventuali compagne. Una stella simile al Sole può lasciare una nana bianca; percorsi di stelle più massicce possono produrre stelle di neutroni o buchi neri. Un diagramma didattico deve ramificarsi dove i destini differiscono, senza presentare una singola fila di immagini come il futuro inevitabile di tutte le stelle."]}], "facts": ["Il Sole è una stella", "Brillantezza apparente ≠ luminosità intrinseca", "La massa influenza durata e destino"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/stella/"}, {"title": "NASA · stelle", "url": "https://science.nasa.gov/universe/stars/"}], "editorialStatus": "scheda-estesa", "media": {"file": "assets/laboratorio-editoriale/sole-hmi.jpg", "caption": "Il Sole nel continuum HMI colorato: copia d’archivio del 30 ottobre 2026, non una finestra aggiornata in diretta.", "credit": "NASA/SDO/HMI", "source": "https://sdo.gsfc.nasa.gov/data/", "license": "NASA media usage guidelines; continuum colorato, copia d’archivio del 30 ottobre 2026"}}, {"id": "supernova", "name": "Supernova", "definition": "Una supernova è un evento esplosivo stellare; esistono meccanismi differenti e non è il destino ordinario di ogni stella.", "example": "Supernova ≠ nascita di una nuova stella", "source": "https://www.treccani.it/enciclopedia/supernova/", "lesson": "lezione-10-4.html", "related": ["stella", "buco-nero", "nebulosa"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un’apparizione che racconta una trasformazione", "paragraphs": ["Una sorgente può diventare improvvisamente molto luminosa dove prima non era evidente. Il nome storico non significa che sia appena nata una nuova stella. La supernova è una fase esplosiva che coinvolge trasformazioni profonde e materiale espulso. La luminosità evolve nel tempo: per studiarla servono osservazioni ripetute, non soltanto una fotografia al massimo. Anche lo spettro cambia e contribuisce alla classificazione."]}, {"title": "Due famiglie da non confondere", "paragraphs": ["In un percorso, il nucleo di una stella massiccia collassa al termine di determinate fasi evolutive e l’evento può espellere gli strati esterni. In un altro, una nana bianca in un sistema appropriato può essere coinvolta in un’esplosione termonucleare. Le condizioni e gli esiti non sono identici. Non si deve quindi disegnare ogni supernova come una stella simile al Sole che invecchia e poi diventa necessariamente un buco nero."]}, {"title": "La luce dell’evento e il resto", "paragraphs": ["L’esplosione e il resto di supernova sono fasi osservative differenti. Un’immagine di filamenti espansi può mostrare materiale e onde d’urto molto tempo dopo il lampo iniziale. Il resto non va confuso con una nebulosa planetaria, che nasce attraverso un altro processo. La formazione di una stella di neutroni o di un buco nero dipende dal percorso: l’etichetta supernova, da sola, non determina sempre un residuo compatto uguale."]}, {"title": "Perché contano per l’Universo", "paragraphs": ["Questi eventi disperdono materiale, modificano l’ambiente interstellare e offrono strumenti per ricostruire processi fisici e distanze, con specifiche calibrazioni. Non ogni supernova è una candela di luminosità perfettamente identica. Nell’osservazione amatoriale una segnalazione richiede confronto con immagini precedenti, posizione e controlli per escludere altri transitori o artefatti. Un punto luminoso nuovo è un indizio interessante: la classificazione viene dopo le verifiche."]}], "facts": ["Supernova ≠ nascita di una nuova stella", "Esplosione e resto di supernova sono fasi differenti"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/supernova/"}], "media": {"file": "assets/lezioni/velo-resto-supernova.jpg", "caption": "Filamenti del Velo: un resto di supernova, non il lampo iniziale dell’esplosione.", "credit": "NASA, ESA, Hubble Heritage Team", "source": "https://esahubble.org/images/heic1520a/", "license": "CC BY 4.0"}, "aliases": ["supernove"]}, {"id": "telescopio", "name": "Telescopio", "definition": "Strumento che raccoglie radiazione da sorgenti lontane per formarne immagini o misurarne proprietà.", "example": "In questa didattica distinguiamo l’ottica, il supporto e il sistema di acquisizione: hanno compiti diversi.", "source": "https://www.treccani.it/enciclopedia/telescopio_(Dizionario-delle-Scienze-Fisiche)/", "lesson": "lezione-7-3.html", "related": ["obiettivo", "riflettore", "rifrattore"], "checked": "2026-10-30", "sections": [{"title": "Più luce, più dettagli accessibili", "paragraphs": ["Un telescopio raccoglie radiazione e forma un’immagine o alimenta uno strumento di misura. Nell’osservazione amatoriale permette di vedere oggetti più deboli e dettagli più fini rispetto all’occhio nudo, entro i limiti dell’ottica e dell’atmosfera. Non serve soltanto a ingrandire: un’immagine enorme, ma sfocata e instabile, non contiene necessariamente più informazioni di una piccola immagine nitida."]}, {"title": "Le grandezze da leggere", "paragraphs": ["L’apertura utile riguarda il diametro che raccoglie luce. La focale determina la scala dell’immagine. Con un oculare, l’ingrandimento si ottiene dividendo la focale del telescopio per quella dell’oculare: 1.000 mm diviso 20 mm dà 50 volte. Cambiare oculare non modifica il diametro del telescopio. Un ingrandimento elevato non garantisce dettagli se seeing, fuoco, collimazione o stabilità non lo permettono."]}, {"title": "Ottica e supporto lavorano insieme", "paragraphs": ["Rifrattori, riflettori e sistemi misti conducono la luce con geometrie differenti. La montatura sostiene e orienta lo strumento: può essere altazimutale o equatoriale, manuale o motorizzata. Un sistema automatico può trovare bersagli e registrare immagini, ma non annulla condensa, ostacoli, luce diffusa o errori di preparazione. La compatibilità del carico comprende anche accessori e leve, non soltanto il peso dichiarato del tubo."]}, {"title": "Che cosa aspettarsi all’oculare", "paragraphs": ["Pianeti e Luna possono mostrare dettagli su un disco esteso; molte stelle restano immagini puntiformi allargate da diffrazione e atmosfera. Le galassie e le nebulose possono apparire molto più tenui delle fotografie. Imparare a mettere a fuoco, scegliere l’ingrandimento e osservare con pazienza rende più utile lo strumento. Per il Sole occorre invece un equipaggiamento specifico e correttamente filtrato: un telescopio ordinario non è pronto per l’osservazione solare soltanto perché è piccolo."]}], "facts": ["Ingrandimento = focale telescopio divisa per focale oculare", "L’apertura non cambia sostituendo l’oculare"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/telescopio_(Dizionario-delle-Scienze-Fisiche)/"}, {"title": "OpenStax · principi dei telescopi", "url": "https://openstax.org/books/astronomy-2e/pages/6-1-telescopes"}], "editorialStatus": "scheda-estesa", "aliases": ["telescopi"]}, {"id": "temperatura", "name": "Temperatura", "definition": "La temperatura descrive uno stato termico e il verso degli scambi spontanei di calore; in astronomia occorre precisare quale regione o quale temperatura equivalente si intende.", "example": "0 °C = 273,15 K", "source": "https://www.treccani.it/enciclopedia/temperatura/", "lesson": "lezione-4-3.html", "related": ["stella", "spettro", "luminosita"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Non è la quantità totale di calore", "paragraphs": ["La temperatura aiuta a descrivere lo stato termico, ma non coincide con l’energia totale contenuta in un corpo. Una piccola quantità di materia molto calda e un grande corpo più freddo non si confrontano contando soltanto i gradi. Nelle osservazioni astronomiche non appoggiamo normalmente un termometro sulla sorgente: ricostruiamo proprietà attraverso radiazione, modelli e condizioni fisiche."]}, {"title": "La scala kelvin", "paragraphs": ["In astrofisica si usa spesso il kelvin, simbolo K, senza il segno dei gradi. Per passare dai gradi Celsius ai kelvin si aggiunge 273,15: 0 °C corrisponde a 273,15 K. Non si deve applicare una relazione fisica che richiede temperatura assoluta inserendo direttamente una lettura Celsius. Un rapporto fra temperature ha significato soltanto se le scale e le definizioni impiegate sono coerenti."]}, {"title": "Una stella non ha una sola temperatura", "paragraphs": ["Il nucleo, l’atmosfera e le diverse regioni di una stella non si trovano alla stessa temperatura. La temperatura efficace è definita attraverso la potenza emessa per unità di superficie confrontata con un modello ideale. Non è una misura del nucleo. In generale stelle con temperatura superficiale maggiore tendono a colori più blu e quelle più fredde a colori più rossi, ma polveri e strumenti possono modificare il colore osservato."]}, {"title": "Dai colori alle condizioni fisiche", "paragraphs": ["Lo spettro contiene più informazioni di una tinta fotografica. Le righe rispondono anche a ionizzazione, densità e composizione. Una nube tenue molto calda non si comporta come una superficie stellare opaca alla stessa temperatura. Nei testi divulgativi bisogna quindi dire temperatura di che cosa e ricavata come. Questa precisazione evita di leggere ogni colore artificiale di un’immagine astronomica come una scala termica naturale."]}], "facts": ["0 °C = 273,15 K", "Temperatura efficace ≠ temperatura del nucleo"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/temperatura/"}]}, {"id": "terminatore", "name": "Terminatore", "definition": "Il terminatore separa la regione illuminata da quella in ombra su un corpo: la sua forma apparente dipende dalla geometria e dal rilievo.", "example": "Sfera ideale: piano del terminatore perpendicolare ai raggi", "source": "https://www.treccani.it/enciclopedia/terminatore/", "lesson": "lezione-2-5.html", "related": ["fase-lunare", "luna", "orizzonte"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il confine fra giorno e notte", "paragraphs": ["Su una sfera ideale illuminata da raggi paralleli, il piano che separa gli emisferi diurni e notturni passa per il centro ed è perpendicolare alla direzione della luce. Il terminatore è l’intersezione con la superficie. Non deve essere necessariamente verticale sul foglio: la sua inclinazione apparente dipende dall’orientamento del corpo e dalla vista. È il riferimento luminoso, non il bordo della sfera."]}, {"title": "Perché lo vediamo curvo", "paragraphs": ["Una linea circolare su una sfera, proiettata nell’immagine, può apparire come un’ellisse o ridursi a una retta in una geometria particolare. Nelle fasi lunari la curva separa la parte del disco illuminata da quella notturna visibile. Non è un’ombra rettangolare stesa sopra una fotografia. Un disegno deve far coincidere illuminazione, posizione del Sole e forma della superficie, evitando geometrie scelte soltanto per riempire lo spazio."]}, {"title": "La superficie reale aggiunge dettagli", "paragraphs": ["Crateri e montagne producono ombre locali e zone illuminate oltre la separazione ideale. Alcune cime ricevono il Sole prima dei terreni circostanti, altre rimangono nell’ombra. Questo rende il terminatore lunare ricco di dettagli variabili e interessante da seguire. Le ombre non indicano automaticamente la profondità di un cratere senza conoscere angolo di illuminazione e geometria del terreno."]}, {"title": "Sulla Terra e nei modelli", "paragraphs": ["L’atmosfera terrestre introduce crepuscoli e rifrazione, quindi il passaggio percepito fra giorno e notte non è una lama perfettamente netta. In un mappamondo illuminato da una sorgente si riproduce una geometria semplificata. La sorgente vicina può avere raggi sensibilmente divergenti e va distinta dal Sole lontano. Chiarire queste ipotesi permette di usare un esperimento concreto senza presentarlo come una copia esatta dell’illuminazione planetaria."]}], "facts": ["Sfera ideale: piano del terminatore perpendicolare ai raggi", "Curva apparente e ombre del rilievo sono aspetti distinti"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/terminatore/"}]}, {"id": "terra", "name": "Terra", "definition": "La Terra è il terzo pianeta dal Sole e il punto di osservazione da cui descriviamo il cielo locale.", "example": "Obliquità orbitale e altezza del polo sono angoli diversi", "source": "https://www.treccani.it/enciclopedia/terra/", "lesson": "lezione-2-1.html", "related": ["pianeta", "rotazione", "orizzonte"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il luogo da cui guardiamo", "paragraphs": ["Il nostro pianeta è un corpo roccioso con una struttura interna differenziata, oceani e atmosfera. La sua superficie non è il centro di un guscio materiale di stelle. Per orientarci usiamo però un modello locale, nel quale la verticale e l’orizzonte dipendono dal punto di osservazione. Cambiando luogo cambiano questi riferimenti rispetto al cielo: non sono le coordinate di una stella a essere spostate a piacere per adattarle alla città."]}, {"title": "Rotazione e rivoluzione", "paragraphs": ["La rotazione terrestre produce gran parte del moto apparente diurno degli astri. La rivoluzione attorno al Sole modifica la direzione verso cui guardiamo di notte durante l’anno. Sono due movimenti da distinguere, non due modi di dire che il cielo cambia. Anche gli assi e i periodi di riferimento devono essere dichiarati: il giorno siderale e quello solare medio non hanno la stessa durata."]}, {"title": "L’inclinazione richiede un piano", "paragraphs": ["L’obliquità di circa 23,4° si misura rispetto alla perpendicolare al piano orbitale. L’altezza del polo celeste sull’orizzonte, invece, dipende dalla latitudine del luogo. A 45° N il polo è alto circa 45°. Confondere questi angoli genera modelli di montature e mappamondi sbagliati. Una figura scientifica deve mostrare la normale al piano oppure nominare esplicitamente il riferimento dell’angolo."]}, {"title": "Il cielo è anche un’esperienza terrestre", "paragraphs": ["Atmosfera, rilievo, illuminazione e meteo influenzano ciò che vediamo, senza modificare arbitrariamente la posizione fisica degli oggetti lontani. Un mappamondo orientato aiuta a collegare locale e globale se la propria posizione viene portata in alto e l’asse rimane parallelo a quello terrestre. La sorgente che illumina il modello deve essere descritta con i suoi limiti: una lampada vicina non riproduce esattamente i raggi quasi paralleli del Sole."]}], "facts": ["Obliquità orbitale e altezza del polo sono angoli diversi", "L’orizzonte dipende dal luogo di osservazione"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/terra/"}]}, {"id": "transito", "name": "Transito", "definition": "Un transito può indicare il passaggio apparente di un corpo davanti al disco di un altro; nel contesto delle effemeridi può anche riferirsi al passaggio al meridiano.", "example": "Transito sul disco e transito al meridiano sono accezioni differenti", "source": "https://www.treccani.it/enciclopedia/transito/", "lesson": "lezione-10-1.html", "related": ["pianeta", "fotometria", "congiunzione"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La geometria lungo la linea di vista", "paragraphs": ["Un pianeta può apparire davanti alla superficie luminosa di una stella se la geometria orbitale e il punto di osservazione sono favorevoli. Nel Sistema solare, dalla Terra vediamo transiti di Mercurio o Venere davanti al Sole in occasioni specifiche. Non ogni congiunzione inferiore è un transito, perché l’inclinazione dell’orbita può portare il pianeta sopra o sotto il disco apparente."]}, {"title": "Un indizio nella luce totale", "paragraphs": ["Per un esopianeta non risolto, il passaggio può produrre una piccola diminuzione del flusso stellare. Profondità, durata e ripetizione contengono informazioni, ma dipendono dalla geometria e dalle proprietà del sistema. Una curva rettangolare in un laboratorio introduce l’idea, non riproduce tutte le forme reali. Una singola diminuzione non prova automaticamente un pianeta: altri sistemi o difetti dei dati possono produrre segnali simili."]}, {"title": "La verifica oltre il disegno", "paragraphs": ["Osservazioni ripetute, confronto con stelle di riferimento e controlli strumentali aiutano a distinguere il segnale. Il periodo può collegarsi all’orbita, ma il transito non fornisce da solo ogni proprietà fisica senza ipotesi e dati aggiuntivi. La rappresentazione di un grande pianeta scuro su una stella deve dichiarare dimensioni accentuate quando serve a rendere l’esercizio leggibile. La visibilità grafica non equivale alla facilità della misura reale."]}, {"title": "Un’altra accezione da riconoscere", "paragraphs": ["Nelle tabelle locali, transito può significare attraversamento del meridiano, spesso collegato alla culminazione superiore. Non implica un passaggio davanti a un disco. La parola va quindi letta insieme alla colonna e alla legenda. Per i transiti solari reali resta inoltre indispensabile un equipaggiamento solare adeguatamente filtrato: il modello sullo schermo non costituisce una procedura sicura per puntare il Sole con strumenti ordinari."]}], "facts": ["Transito sul disco e transito al meridiano sono accezioni differenti", "Un calo di luce richiede verifiche prima della classificazione"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/transito/"}]}, {"id": "ultravioletto", "name": "Ultravioletto", "definition": "La radiazione ultravioletta ha lunghezze d’onda più corte del violetto visibile e non viene percepita direttamente come un colore dall’occhio.", "example": "UV: invisibile direttamente all’occhio", "source": "https://www.treccani.it/enciclopedia/ultravioletto/", "lesson": "lezione-4-3.html", "related": ["radiazione", "fotone", "atmosfera"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Oltre il limite visibile", "paragraphs": ["L’ultravioletto, spesso indicato con UV, è una regione dello spettro elettromagnetico. Non è un viola particolarmente intenso che l’occhio riesce a vedere aumentando la luminosità. Per registrarlo occorrono rivelatori e sistemi adatti. Le suddivisioni in bande dipendono dalle convenzioni del settore, perciò una tabella deve specificare quali limiti adotta invece di mescolare definizioni mediche, atmosferiche e astronomiche."]}, {"title": "Una finestra sui processi energetici", "paragraphs": ["Stelle calde, gas e fenomeni legati all’attività stellare possono essere studiati nell’ultravioletto. Un’immagine UV mette in evidenza componenti diverse da una fotografia nel visibile. Non significa che tutto ciò che appare brillante nella composizione abbia la stessa temperatura o lo stesso meccanismo di emissione. Spettri, bande e contesto aiutano a separare i contributi. Il colore assegnato per visualizzare i dati è una scelta di rappresentazione."]}, {"title": "Il filtro dell’atmosfera", "paragraphs": ["L’atmosfera terrestre assorbe una parte importante di questa radiazione, con trasmissione molto diversa nelle varie bande. L’osservazione spaziale permette di accedere a regioni dello spettro difficili o impossibili da studiare dal suolo. Aumentare il diametro di un telescopio terrestre non elimina l’assorbimento atmosferico. Anche materiali ottici e rivelatori possono avere risposte insufficienti fuori dal visibile: lo strumento va progettato per il segnale che vuole misurare."]}, {"title": "Leggere correttamente una fotografia", "paragraphs": ["Una ripresa della corona solare in una banda estrema non è la vista che si avrebbe guardando il Sole a occhio nudo. Deve essere descritta come dato in una banda invisibile, eventualmente con colori assegnati. Il fatto che il risultato sembri familiare non autorizza a usare strumenti ordinari per l’osservazione solare: la protezione dipende dalla configurazione completa e dalla filtrazione adatta, non dal colore finale mostrato sullo schermo."]}], "facts": ["UV: invisibile direttamente all’occhio", "Colore della composizione e banda misurata sono distinti"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/ultravioletto/"}]}, {"id": "unita-astronomica", "name": "Unità astronomica", "definition": "L’unità astronomica è una lunghezza convenzionale esatta di 149.597.870.700 metri, usata soprattutto per le distanze nel Sistema solare.", "example": "1 UA = 149.597.870,7 km esatti", "source": "https://www.treccani.it/enciclopedia/distanza/", "lesson": "lezione-6-3.html", "related": ["anno-luce", "parsec", "orbita"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Una scala vicina all’esperienza del Sistema solare", "paragraphs": ["L’unità astronomica, abbreviata spesso UA nei testi italiani e au nella convenzione internazionale, nasce dal riferimento alla scala dell’orbita terrestre. Dal 2012 è fissata a un numero esatto di metri: 149.597.870.700 m, equivalenti a 149.597.870,7 km. Non varia ogni volta che la Terra si avvicina o si allontana dal Sole. La distanza istantanea Terra–Sole può quindi essere espressa con un numero un poco diverso da una UA."]}, {"title": "Perché non basta dire distanza media", "paragraphs": ["La descrizione storica come distanza media Terra–Sole aiuta a immaginarne l’ordine di grandezza, ma non sostituisce la definizione convenzionale moderna. La misura dell’orbita e l’unità che usiamo per esprimerla sono concetti distinti. Un testo datato può riportare valori o definizioni precedenti: qui il riferimento numerico è JPL con la risoluzione IAU, non una cifra trasferita senza controllo da una vecchia dispensa."]}, {"title": "Il tempo della luce", "paragraphs": ["Dividendo la lunghezza per la velocità della luce nel vuoto si ottiene circa 499 secondi, cioè 8 minuti e 19 secondi. È il tempo necessario a percorrere una UA, non una seconda definizione dell’unità come durata. La luce del Sole impiega un intervallo vicino a questo valore per raggiungerci, con la variazione dovuta alla distanza reale. Anche in questo caso chilometri e secondi descrivono grandezze differenti."]}, {"title": "Leggere numeri e disegni", "paragraphs": ["Un semiasse maggiore di 5 UA indica cinque volte quella lunghezza, non cinque raggi del Sole. Nei diagrammi le orbite possono essere compresse per farle entrare nella pagina, mentre i pianeti vengono ingranditi. La didascalia deve precisarlo. L’unità astronomica rende maneggevoli i numeri del Sistema solare; per le stelle si preferiscono spesso anni luce e parsec, senza che cambi la natura fisica della distanza misurata."]}], "facts": ["1 UA = 149.597.870,7 km esatti", "Tempo della luce per 1 UA ≈ 8 min 19 s"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/distanza/"}, {"title": "JPL · parametri e definizione IAU", "url": "https://ssd.jpl.nasa.gov/astro_par.html"}, {"title": "INAF · definizione del 2012", "url": "https://www.media.inaf.it/2012/09/17/nuova-vita-per-lunita-astronomica/"}], "aliases": ["unità astronomiche", "UA"]}, {"id": "universo", "name": "Universo", "definition": "In cosmologia l’Universo comprende spazio, tempo, materia, radiazione e le strutture fisiche che studiamo; l’Universo osservabile non coincide necessariamente con il tutto.", "example": "Universo osservabile ≠ necessariamente tutto l’Universo", "source": "https://www.treccani.it/enciclopedia/universo/", "lesson": "lezione-6-5.html", "related": ["galassia", "redshift", "radiazione"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "La parte che possiamo osservare", "paragraphs": ["La luce e altri segnali impiegano tempo a propagarsi. Osservare più lontano significa ricevere informazione da epoche precedenti. Esiste quindi un limite a ciò che può averci inviato segnali nella storia cosmica. Questo definisce il concetto di Universo osservabile, non un muro materiale posto attorno alla Terra. La sua dimensione non si ottiene moltiplicando ingenuamente l’età cosmica per la velocità della luce senza considerare l’espansione."]}, {"title": "Una struttura su molte scale", "paragraphs": ["Stelle, sistemi planetari, galassie, ammassi e strutture su larga scala appartengono a livelli diversi. Una fotografia profonda mescola oggetti a distanze ed epoche differenti lungo la stessa linea di vista. Non è una sezione sottile in cui ogni punto giace sullo stesso piano. Per ricostruire la distribuzione spaziale servono dati e modelli oltre alla sola immagine, come distanze e spettri."]}, {"title": "Espansione non significa esplosione da un luogo della mappa", "paragraphs": ["Nel modello cosmologico l’espansione riguarda l’evoluzione delle distanze fra regioni appropriate su grande scala. Non implica che ogni oggetto legato, come un pianeta o un sistema stellare, debba gonfiarsi insieme allo spazio. Non esiste nella descrizione omogenea un centro privilegiato rappresentato dalla Terra. Le analogie con palloncini e impasti aiutano soltanto se chiariscono quali proprietà imitano e quali, come la presenza di un ambiente esterno visibile, non vanno trasferite."]}, {"title": "Conoscere attraverso modelli confrontabili", "paragraphs": ["La cosmologia combina osservazioni e fisica per costruire scenari verificabili. Età, distanze e composizione cosmica vengono inferite in un quadro con parametri e incertezze. Le immagini evocative dell’Universo giovane non sono fotografie ordinarie di ogni fase. Una divulgazione seria mantiene aperta la meraviglia e precisa che cosa è misurato, che cosa è ricostruito e quali domande restano senza risposta definitiva."]}], "facts": ["Universo osservabile ≠ necessariamente tutto l’Universo", "L’espansione non fa gonfiare ogni sistema legato"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/universo/"}]}, {"id": "velocita-radiale", "name": "Velocità radiale", "definition": "La velocità radiale è la componente del moto relativo lungo la linea di vista, distinta dal movimento trasversale sul piano del cielo.", "example": "Componente radiale ≠ velocità totale", "source": "https://www.treccani.it/enciclopedia/effetto-doppler/", "lesson": "lezione-4-1.html", "related": ["effetto-doppler", "astrometria", "binaria-a-eclisse"], "checked": "2026-10-31", "editorialStatus": "scheda-estesa", "sections": [{"title": "Un movimento scomposto in direzioni", "paragraphs": ["Un oggetto può avvicinarsi, allontanarsi e spostarsi lateralmente rispetto all’osservatore. La velocità radiale descrive soltanto la componente lungo la congiungente. Non è automaticamente la velocità totale nello spazio. Immagina una persona che attraversa diagonalmente un campo: il suo avvicinamento verso di te e il suo spostamento laterale sono aspetti dello stesso cammino, ma misurarne uno non determina da solo l’altro."]}, {"title": "L’informazione nello spettro", "paragraphs": ["Gli spostamenti Doppler delle righe permettono di studiare la componente radiale, secondo un modello e riferimenti dichiarati. Nella convenzione astronomica comune una velocità radiale positiva indica allontanamento e una negativa avvicinamento. Il valore deve essere associato a un sistema di riferimento: la misura dalla Terra comprende anche il moto dell’osservatore. Non si deve confrontare senza correzioni un dato topocentrico con uno riferito al baricentro del Sistema solare."]}, {"title": "Le stelle doppie lasciano una firma", "paragraphs": ["In un sistema binario le componenti possono mostrare variazioni periodiche della velocità radiale mentre orbitano attorno al centro di massa. Le righe possono alternare spostamenti anche quando il telescopio non separa visivamente le stelle. L’ampiezza osservata dipende dall’orientamento: guardare il sistema quasi lungo l’asse orbitale non produce lo stesso segnale di una vista quasi di taglio. Non basta quindi osservare un’oscillazione per ricavare ogni proprietà senza ulteriori dati."]}, {"title": "Che cosa non dedurre troppo in fretta", "paragraphs": ["Il moto proprio misura una variazione angolare di posizione, mentre la velocità radiale usa una componente lungo la vista. Per ricostruire un moto spaziale servono collegamenti fra più misure, compresa la distanza quando pertinente. In cosmologia il rapporto fra redshift, distanza e velocità richiede inoltre un quadro diverso dal semplice problema locale. Nella scheda didattica indica sempre quale componente è mostrata dalle frecce, evitando di rappresentare ogni spostamento spettrale come un movimento laterale nella fotografia."]}], "facts": ["Componente radiale ≠ velocità totale", "Il riferimento dell’osservatore fa parte del dato"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/effetto-doppler/"}]}, {"id": "vento-solare", "name": "Vento solare", "definition": "Il vento solare è un flusso di plasma proveniente dall’atmosfera esterna del Sole e diffuso nello spazio interplanetario.", "example": "Vento solare: particelle e campo, non aria", "source": "https://www.treccani.it/enciclopedia/vento-solare/", "lesson": "lezione-8-3.html", "related": ["plasma", "aurora-polare", "cometa"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Non è un vento di aria", "paragraphs": ["Protoni, elettroni e altre componenti cariche si muovono nell’ambiente solare e interplanetario. Il nome vento richiama un flusso, non una corrente di aria terrestre. Non coincide con la luce solare: radiazione elettromagnetica e particelle hanno proprietà e tempi di propagazione differenti. Anche un’emissione luminosa improvvisa del Sole non descrive da sola l’arrivo del plasma alla Terra."]}, {"title": "Un ambiente variabile", "paragraphs": ["Velocità, densità e campo magnetico trasportato possono cambiare. Il Sole non emette un flusso identico in ogni direzione e in ogni istante. Regioni e fenomeni differenti contribuiscono alle condizioni che raggiungono lo spazio vicino alla Terra. I modelli di previsione devono quindi considerare geometria e propagazione, non soltanto l’esistenza di un’attività osservata sul disco. Una foto spettacolare non basta a prevedere gli effetti locali."]}, {"title": "Il collegamento con le aurore", "paragraphs": ["L’interazione con la magnetosfera può trasferire energia e modificare la dinamica delle particelle, contribuendo alle condizioni aurorali. Non tutto il vento solare cade direttamente sull’atmosfera come pioggia uniforme. Il campo magnetico organizza parte del processo e gli effetti variano. Gli indici di attività sono strumenti di contesto: non garantiscono che una persona in una certa città vedrà colori intensi in una certa ora."]}, {"title": "Le comete come indicatori", "paragraphs": ["La coda ionica di una cometa risponde all’ambiente del vento solare e ai campi magnetici. La coda di polveri risente invece anche della pressione della radiazione e delle traiettorie dei grani. Presentarle entrambe come fumo lasciato dietro il nucleo cancella questa distinzione. Il termine vento solare collega quindi fenomeni diversi, dal Sole alle comete e alla Terra, ma richiede di separare particelle, luce e risposta dell’ambiente."]}], "facts": ["Vento solare: particelle e campo, non aria", "Luce solare e plasma non hanno gli stessi tempi di arrivo"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/vento-solare/"}]}, {"id": "via-lattea", "name": "Via Lattea", "definition": "La Via Lattea è la galassia a cui appartiene il Sole; la fascia chiara nel cielo è una vista interna della sua struttura stellare e diffusa.", "example": "Il Sole è dentro la Via Lattea", "source": "https://www.treccani.it/enciclopedia/via-lattea/", "lesson": "lezione-6-1.html", "related": ["galassia", "nebulosa-oscura", "stella"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Abitiamo dentro la figura", "paragraphs": ["La fascia lattiginosa visibile da un luogo scuro non è una nube isolata davanti a tutte le stelle: guardiamo attraverso regioni della nostra galassia. Moltissime stelle non risolte dall’occhio contribuiscono al chiarore e le polveri introducono bande oscure. Il Sole fa parte del sistema. Una fotografia della Via Lattea vista dall’esterno non può essere una normale ripresa ottenuta viaggiando fuori dalla galassia: le immagini esterne sono modelli o galassie analoghe da dichiarare."]}, {"title": "Una struttura su più componenti", "paragraphs": ["Disco, regioni centrali e alone contengono popolazioni e materiale differenti. Il disegno di una spirale ordinata è una ricostruzione utile, non la semplice proiezione di una fotografia scattata da sopra. La distribuzione delle stelle, il gas, le distanze e i moti contribuiscono a ricostruire la struttura. Anche l’estensione del sistema cambia significato secondo la componente che si considera, quindi un unico diametro senza definizione può essere ambiguo."]}, {"title": "Il cielo stagionale cambia la vista", "paragraphs": ["Durante l’anno osserviamo di notte verso regioni diverse. La visibilità della fascia e delle regioni centrali dipende da stagione, latitudine, ora, ostacoli e luce. Una fotografia estiva molto contrastata non rappresenta l’aspetto di ogni notte da ogni luogo. Nubi interstellari possono nascondere stelle e fondo luminoso: una zona scura non è necessariamente uno spazio vuoto privo di materia."]}, {"title": "Occhio e sensore raccontano diversamente", "paragraphs": ["Una lunga esposizione accumula segnale e l’elaborazione può accentuare dettagli e colori. A occhio nudo la Via Lattea può essere più tenue, ma rimane un riferimento potente per percepire la struttura del cielo. Nel diario specifica se descrivi la vista diretta o una ripresa elaborata. Evitare numeri storici trasferiti come conteggi esatti di stelle permette di conservare l’idea fondamentale senza trasformare stime complesse in un inventario apparentemente definitivo."]}], "facts": ["Il Sole è dentro la Via Lattea", "Le immagini della galassia dall’esterno sono ricostruzioni, non riprese da un viaggio esterno"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/via-lattea/"}]}, {"id": "vignettatura", "name": "Vignettatura", "definition": "Nella ripresa fotografica la vignettatura è una diminuzione dell’illuminazione verso i bordi del campo, dovuta alla geometria e alla trasmissione del sistema.", "example": "Vignettatura ≠ qualsiasi gradiente del cielo", "source": "https://www.treccani.it/vocabolario/vignettatura/", "lesson": "astrofotografia.html", "related": ["obiettivo", "focale", "fotometria"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Il fondo non è illuminato uniformemente", "paragraphs": ["Un campo ripreso può risultare più chiaro al centro e più scuro agli angoli anche quando la scena non possiede quella distribuzione. La geometria ottica, le aperture e gli accessori possono contribuire. In altri contesti la parola indica una scelta estetica deliberata, ma qui parliamo di risposta del sistema. Non ogni gradiente è vignettatura: luce artificiale, chiarore naturale e riflessi possono produrre strutture differenti."]}, {"title": "Il corredo conta", "paragraphs": ["Un adattatore troppo stretto, un filtro, un paraluce o un accoppiamento non adatto al sensore possono limitare parte del fascio. Un obiettivo progettato per un formato non copre necessariamente in modo utile un sensore più grande. Il problema non si risolve sempre cambiando esposizione: aumentarla moltiplica anche il segnale centrale. Occorre prima capire dove la luce viene attenuata e se l’assetto sia meccanicamente e otticamente appropriato."]}, {"title": "La calibrazione con i flat", "paragraphs": ["Una serie di flat acquisita correttamente può descrivere variazioni di risposta e illuminazione del sistema. La calibrazione richiede coerenza con la configurazione e una gestione adeguata dei segnali di riferimento. Non è semplicemente la sovrapposizione di un’immagine bianca. Se una regione non riceve luce utile, l’elaborazione non ricrea informazione assente. Anche il rumore può diventare più evidente nelle aree fortemente attenuate dopo la correzione."]}, {"title": "Un controllo per interpretare la fotografia", "paragraphs": ["Prima di attribuire una zona scura a una nube interstellare, confronta riprese e calibrazione. Una struttura che rimane legata al sensore anziché al cielo può suggerire un’origine strumentale. Per finalità estetiche si può scegliere un ritaglio, ma una misura fotometrica richiede attenzione più rigorosa alla risposta. Distinguere cielo reale, difetto del sistema e scelta di elaborazione rende l’immagine più leggibile e la spiegazione più onesta."]}], "facts": ["Vignettatura ≠ qualsiasi gradiente del cielo", "I flat non ricreano luce mai registrata"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/vocabolario/vignettatura/"}]}, {"id": "zenit", "name": "Zenit", "definition": "Direzione della verticale locale rivolta verso l’alto, sulla sfera celeste.", "example": "È sopra la tua testa: non è necessariamente il Polo Nord celeste.", "source": "https://www.treccani.it/enciclopedia/zenit/", "lesson": "lezione-1-1.html", "related": ["altezza-angolare", "orizzonte"], "checked": "2026-10-30", "sections": [{"title": "Il punto esattamente sopra di te", "paragraphs": ["Lo zenit è la direzione individuata dalla verticale locale verso l’alto, prolungata fino alla sfera celeste. Non è una stella né un polo astronomico. Se immagini una linea che attraversa il luogo in cui ti trovi e continua sopra la tua testa, il suo incontro ideale con la volta celeste è lo zenit. Nella direzione opposta, sotto l’osservatore, si trova il nadir."]}, {"title": "Un riferimento personale, non universale", "paragraphs": ["Lo zenit dipende dalla posizione sulla Terra. Due osservatori in città differenti non hanno generalmente lo stesso zenit nello stesso istante. Anche dal medesimo luogo, con la rotazione terrestre, cambia la regione stellare che passa in quella direzione. Non si può perciò identificare permanentemente lo zenit con la Polare o con una costellazione. Il polo celeste coincide con lo zenit soltanto al corrispondente polo geografico, nell’idealizzazione geometrica."]}, {"title": "La coordinata al limite", "paragraphs": ["L’altezza dello zenit è +90°. A quel punto l’azimut non è definito in modo univoco: tutte le direzioni orizzontali conducono alla stessa verticale quando si alza lo sguardo fino in cima. Un simulatore non dovrebbe quindi inventare un azimut fisicamente significativo per l’oggetto esattamente allo zenit. Molto vicino a questo punto una montatura altazimutale può richiedere rapide variazioni della direzione orizzontale per seguire il bersaglio."]}, {"title": "Riconoscerlo nella carta", "paragraphs": ["In molte mappe circolari a tutto cielo lo zenit è al centro, mentre l’orizzonte è sul bordo. È una scelta di rappresentazione da dichiarare, non una caratteristica di tutte le carte astronomiche: in un atlante equatoriale il centro può essere una direzione completamente diversa. Scrivere discretamente “zenit” al centro aiuta il lettore a collegare il foglio alla posizione del proprio corpo e a non interpretarlo come una mappa vista dall’esterno."]}], "facts": ["Altezza +90°", "Allo zenit l’azimut è indefinito", "Il polo celeste non è normalmente sopra la testa"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/zenit/"}, {"title": "USNO · altezza e azimut", "url": "https://aa.usno.navy.mil/faq/alt_az"}], "editorialStatus": "scheda-estesa"}, {"id": "zodiaco", "name": "Zodiaco", "definition": "Lo zodiaco astronomico è la fascia del cielo attorno all’eclittica, distinta dai dodici settori convenzionali dei segni astrologici.", "example": "Costellazioni di estensione diversa ≠ segni di 30°", "source": "https://www.treccani.it/enciclopedia/zodiaco/", "lesson": "lezione-1-6.html", "related": ["eclittica", "costellazione", "pianeta"], "checked": "2026-10-30", "editorialStatus": "scheda-estesa", "sections": [{"title": "Una fascia legata al moto apparente", "paragraphs": ["Il Sole percorre durante l’anno una linea apparente chiamata eclittica. Luna e pianeti si osservano generalmente nella regione circostante, perché le loro orbite hanno relazioni geometriche con quel piano. Questa fascia è il riferimento astronomico dello zodiaco. Non è una cintura materiale nello spazio e non significa che le stelle appartengano tutte allo stesso sistema fisico o si trovino alla medesima distanza."]}, {"title": "Costellazioni e segni non coincidono", "paragraphs": ["Le costellazioni astronomiche sono regioni con confini definiti e dimensioni diverse. I dodici segni tradizionali sono invece settori convenzionali uguali di 30°. L’eclittica attraversa anche la regione di Ofiuco, che non compare fra i dodici segni usuali. Non si è appena scoperta una nuova stella per cambiare un elenco: sono sistemi di classificazione differenti. I nomi in comune non autorizzano a usare gli stessi confini o tempi di attraversamento."]}, {"title": "La precessione cambia il riferimento storico", "paragraphs": ["L’orientamento dell’equatore e del punto equinoziale varia lentamente rispetto allo sfondo stellare. Le corrispondenze storiche fra settori e costellazioni non restano quindi identiche nei secoli. Per una carta astronomica si usano coordinate, epoca e confini appropriati. Una tabella di segni zodiacali non sostituisce l’effemeride della posizione del Sole e non indica automaticamente dove cercare un pianeta durante una notte concreta."]}, {"title": "Un aiuto per orientare lo sguardo", "paragraphs": ["Conoscere l’eclittica e alcune costellazioni vicine aiuta a immaginare la zona attraversata da Luna e pianeti. Servono comunque data, luogo e ora per la posizione effettiva. Il quadro astronomico descrive direzioni e moti osservabili; non fornisce prove di influenze sul carattere o sul destino individuale. Distinguere questi piani permette di valorizzare storia e immaginario senza confonderli con risultati della ricerca fisica."]}], "facts": ["Costellazioni di estensione diversa ≠ segni di 30°", "L’eclittica attraversa anche Ofiuco"], "sources": [{"title": "Treccani · riferimento terminologico", "url": "https://www.treccani.it/enciclopedia/zodiaco/"}, {"title": "IAU · FAQ su costellazioni e zodiaco", "url": "https://www.iau.org/IAU/IAU/Astronomy-FAQs/FAQs.aspx"}]}];
